window.__D("text/zohar/c005",{"p":[[9520011226,"<p>בְגִין כָּךְ וַיְיָ אָמָר הַמְכַסֶּה אֲנִי מֵאַבְרָהָם אֲשֶׁר אֲנִי עוֹשֶׂה. רַבִּי חִיָּיא פָּתַח (עמוס ג׳:ז׳) כִּי לא יַעֲשֶׂה יְיָ אֱלהִים דָּבָר כִּי אִם גָּלָה סוֹדוֹ אֶל עֲבָדָיו הַנְּבִיאִים. זַכָּאִין אִנּוּן זַכָּאֵי עָלְמָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ, בְּכָל מַה דְּאִיהוּ עָבִיד בָּרְקִיעָא וְזַמִּין לְמֶעְבַּד בְּעָלְמָא, עַל יְדֵי דְּזַכָּאִין עֲבִיד לֵיהּ, וְלָא כַּסֵּי מִנַּיְיהוּ לְעָלְמִין כְּלוּם.</p>\n<p>בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְשַׁתָּפָא בַּהֲדֵיהּ (לצדיקיא דלא תהא פתחון פה לרשיעייא בכל מה דאיהו עביד. תא חזי, כלא גלי קודשא בריך הוא) לְצַדִּיקַיָא בְּגִין דְּאִנּוּן אַתְיָין וּמַזְהִירִין לִבְנֵי נָשָׁא לְאֲתָבַא מֵחוֹבַיְיהוּ וְלָא יִתְעַנְשׁוּן מִגּוֹ דִּינָא עִלָּאָה וְלָא יְהֵא לוֹן פִּתְחָא דְפוּמָא לְגַבֵּיהּ. בְּגִינֵי כָךְ קוּדְשָׁא בְּרִיךְ הוּא אוֹדַע לוֹן רָזָא דְּאִיהוּ עָבִיד בְּהוּ דִינָא. תּוּ בְּגִין דְּלָא יֵימְרוּן דְּהָא בְּלָא דִינָא עֲבִיד בְּהוּ דִּינָא.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר וַוי לוֹן לְחַיָּיבַיָא דְּלָא יָדְעִין וְלָא מַשְׁגִּיחִין וְלָא יָדְעִין לְאִסְתַּמְּרָא מֵחוֹבַיְיהוּ. וּמַה קוּדְשָׁא בְּרִיךְ הוּא דִּי כָּל עוֹבָדוֹהִי קְשׁוֹט וְאוֹרְחָתֵיהּ דִּין. לָא עָבִיד כָּל מַה דְּעֲבִיד בְּעָלְמָא עַד דְּגָלֵי לְהוּ לְצַדִּיקַיָיא בְּגִין דְלָא יְהֵא לוֹן פִּתְחָא דְפוּמָא לִבְנֵי נָשָׁא. (כאן שייך מה שבסוף הספר סימן ח\"י, עי' לקמן דף ק\"ו ע\"א ותמצאנו שם) גַּבֵּי בְּנֵי נָשָׁא לא כָל שֶׁכֵּן דְּאִית לוֹן לְמֶעְבַּד מִלַּיְיהוּ דְּלָא יְמַלְּלוּן בְּנֵי נָשָׁא סִטְיָא עֲלֵיהוֹן. וְכֵן כְּתִיב, (במדבר ל״ב:כ״ב) וִהְיִיתֶם נְקִיִּים מֵיְיָ וּמִיִּשְׂרָאֵל.</p>\n<p>וְאִית לוֹן לְמֶעְבַּד דְּלָא יְהֵא לוֹן פִּתְחוֹן פֶּה לִבְנֵי נָשָׁא, וְיִתְרוּן בְּהוֹן אִי אִנּוּן חָטָאן וְלָא מַשְׁגְּחֵי לְאִסְתַּמָּרָא, דְּלָא יְהֵא לֵיהּ לְמִדַּת דִּינָא דְּקוּדְשָׁא בְּרִיךְ הוּא פִּתְחָא דְפוּמָא לְגַבַּיְיהוּ. וּבְמָּה, בִּתְשׁוּבָה וְעוֹבָדִין דְּכַשְׁרָן.</p>\n<p>תָּא חֲזֵי, וַיְיָ אָמָר הַמְכַסֶּה אֲנִי מֵאַבְרָהָם. אָמַר רַבִּי יְהוּדָה, קוּדְשָׁא בְּרִיךְ הוּא יָהַב כָּל אַרְעָא לְאַבְרָהָם <Nonei></i>לְמֶהֱוֵי לֵיהּ אַחְסָנַת יְרוּתָא לְעָלְמִין, דִּכְתִיב כִּי אֶת כָּל הָאָרֶץ אֲשֶׁר אַתָּה רֹאֶה לְךָ אֶתְּנֶנָּה וְגו'. וּכְתִיב שָׂא נָא עֵינֶיךָ וּרְאֵה. וּלְבָתַר קוּדְשָׁא בְּרִיךְ הוּא אִצְטְרִיךְ לְאַעֲקָרָא אַתְרִין אִלֵּין. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, כְּבָר יַהֲבִית יַת אַרְעָא לְאַבְרָהָם, וְהוּא אַבָּא לְכֹלָּא, דִּכְתִיב כִּי אַב הֲמוֹן גּוֹיִם נְתַתִּיךָ. וְלָא יָאוֹת לִי לְמִמְחֵי בְּנִין וְלָא אוֹדַע לַאֲבוּהוֹן דְּקָרִית לֵיהּ אַבְרָהָם אוֹהֲבִי. וּבְגִין כָּךְ אִצְטְרִיךְ לְאוֹדַע לֵיהּ, בְגִין כָּךְ (אמר) וַיְיָ אָמָר הַמְכַסֶּה אֲנִי מֵאַבְרָהָם אֲשֶׁר אֲנִי עוֹשֶׂה.</p>\n<p>אָמַר רַבִּי אַבָּא תָּא חֲזֵי (קיא א) עִנְוְתָנוּתָא דְּאַבְרָהָם, דְּאַף עַל גַּב דְּאָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא זַעֲקַת סְדוֹם וַעֲמוֹרָה כִּי רַבָּה. וְעִם כָּל דָּא דְּאוֹרִיךְ עִמֵּיהּ וְאוֹדַע לֵיהּ דְּבָעֵי לְמֶעְבַּד דִּינָא בִּסְדוֹם, לָא בָּעָא קַמֵיהּ לְשֵׁזָבָא לֵיהּ לְלוֹט וְלָא יַעֲבִיד בֵּיהּ דִּינָא. מַאי טַעְמָא בְּגִין דְּלָא לְמִתְבַּע אַגְרָא מִן עוֹבָדוֹי.</p>\n<p>וְעַל דָּא שָׁלַח קוּדְשָׁא בְּרִיךְ הוּא לְלוֹט וְשֵׁזִיב לֵיהּ בְּגִינֵיהּ דְּאַבְרָהָם. דִּכְתִיב וַיִּזְכֹּר אֱלהִים אֶת אַבְרָהָם וַיְשַׁלַּח אֶת לוֹט מִתּוֹךְ הַהֲפֵכָה וְגו'.</p>\n<p>מַאי אֲשֶׁר יָשַׁב בָּהֵן לוֹט הָא אִתְּמָר. אֲבָל בְּגִין דְּכֻלְהוּ חַיָּיבִין וְלָא אִשְׁתְּכַח (בינייהו), מִכֻּלְהוּ דְּאִית לֵיהּ מִידִי דִּזְכוּ, בַּר לוֹט. מִכָּאן אוֹלִיפְנָא בְּכָל אֲתַר דְּדָיְירִין בֵּיהּ חַיָּיבִין חָרִיב אִיהוּ.</p>\n<p>אֲשֶׁר יָשַׁב בָּהֵן לוֹט. (קח א) וְכִי בְּכֻלְהוּ הֲוָה יָתִיב לוֹט, אֶלָא בְּגִינֵיהּ הֲווּ יַתְבֵי דְּלָא אִתְחָרְבוּ. וְאִי תֵימָא בִּזְכוּתֵיהּ, לָא. אֶלָּא בִּזְכוּתֵיהּ דְּאַבְרָהָם.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן תָּא חֲזֵי, דְּשִׁמּוּשָׁא דְּעֲבִיד בַּר נָשׁ לְזַכָּאָה, הַהוּא שִׁמּוּשָׁא אָגִין עֲלֵיהּ בְּעָלְמָא. וְלָא עוֹד אֶלָּא דְּאַף עַל גַּב דְּאִיהוּ חַיָּיבָא, אוֹלִיף מֵאָרְחוֹי וְעֲבִיד לוֹן.</p>\n<p>תָּא חֲזֵי דְּהָא בְּגִין דְּאִתְחַבַּר לוֹט בַּהֲדֵיהּ דְּאַבְרָהָם אַף עַל גַּב דְּלָא אוֹלִיף כָּל עוֹבָדוֹי, אוֹלִיף לְמֶעְבַּד טִיבוּ עִם בִּרְיָין כְּמָה דְּהֲוָה עָבִיד אַבְרָהָם, וְדָא הוּא דְּאוֹתִיב לְכָל אִנּוּן קַרְתֵּי כָּל הַהוּא זִמְנָא דְּיָתְבוּ בָּתַר דְּעָאל לוֹט בֵּינַיְיהוּ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן תָּא חֲזֵי, דִּשְׁכִינְתָּא לָא אַעֲדֵי מִנֵּיהּ דְּאַבְרָהָם בְּהַהִיא שַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ (בההוא זמנא דקודשא בריך הוא עמיה), אָמַר לֵיהּ רַבִּי אֶלְעָזָר וְהָא שְׁכִינְתָּא הֲוָה מַלִּיל עִמֵּיהּ דְּהָא (בדרגא) דָא אִתְגְּלִי עֲלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא דִּכְתִיב, (שמות ו׳:ג׳) וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי. אָמַר לֵיהּ הָכִי הוּא וַדַּאי.</p>\n<p>וְתָּא חֲזֵי מַה כְּתִיב וַיֹּאמֶר יְיָ זַעֲקַת סְדוֹם וַעֲמֹרָה כִּי רָבָּה. בְּקַדְמִיתָא וַיְיָ אָמַר. וּלְבַסּוֹף וַיֹּאמֶר יְיָ זַעֲקַת סְדוֹם וַעֲמוֹרָה וְגו'. דָּא אִיהוּ דַּרְגָא עִלָּאָה דְּאִתְגְּלֵי לֵיהּ עַל דַּרְגָּא תַּתָּאָה,</p>\n<p><Noneb>מִדְרָשׁ הַנֶּעֱלָם</b> <Nonei></i>וַיְיָ אָמָר הַמְכַסֶּה אֲנִי מֵאַבְרָהָם וְגו' מַה כְּתִיב לְמַעְלָה וַיָּקוּמוּ מִשָּׁם הָאֲנָשִׁים וַיַּשְׁקִיפוּ עַל פְּנִי סְדוֹם לַעֲשׂוֹת דִּין בָּרְשָׁעִים. מַה כְּתִיב אַחֲרָיו הַמְכַסֶּה אֲנִי מֵאַבְרָהָם.</p>\n<p>אָמַר רַב חַסְדָא אֵין הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה דִּין בָּרְשָׁעִים עַד שֶׁנִּמְלַךְ בְּנִשְׁמָתָן שֶׁל צַּדִּיקִים הֲדָא הוּא דִכְתִיב, (איוב ד׳:ט׳) מִנִּשְׁמַת אֱלוֹהַּ יֹאבֵדוּ. וּכְתִיב הַמְכַסֶּה אֲנִי מֵאַבְרָהָם. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא כְּלוּם יֵשׁ לִי לַעֲשׂוֹת דִּין בָּרְשָׁעִים עַד שֶׁאֱמָלֵךְ בְּנִשְׁמוֹת הַצַּדִּיקִים, וְאוֹמֵר לָהֶם, הָרְשָׁעִים חָטְאוּ לְפָנַי, אֶעֱשֶׂה בָּהֶם דִּין, דִּכְתִיב וַיֹּאמֶר יְיָ זַעֲקַת סְדוֹם וַעֲמוֹרָה כִּי רָבָּה וחַטָאתָם וְגו'.</p>\n<p>אָמַר רַבִּי אַבְהוּ הַנְּשָׁמָה עוֹמֶדֶת בִּמְקוֹמָהּ וְהִיא יְרֵאָה לְהִתְקָרֵב אֵלָיו וְלוֹמַר לְפָנָיו כְּלוּם, עַד שֶׁיֹּאמַר לְמטטרו\"ן שֶׁיַּגִּישֶׁנָּה לְפָנָיו וְתֹאמַר מַה שֶׁרָצְּתָה, הֲדָא הוּא דִכְתִיב ויִּגַּשׁ אַבְרָהָם, וַיֹּאמֶר הַאַף תִּסְפֶּה צַּדִּיק עִם רָשָׁע חָלִילָה לְךָ וגו'.</p>\n<p>אוּלַי יֵשׁ חֲמִשִּׁים צַּדִּיקִים וְגו'. הַנְּשָׁמָה פּוֹתַחַת וְאוֹמֶרֶת רִבּוֹנוֹ שֶׁל עוֹלָם שֶׁמָּא נִתְעַסְּקוּ בְּנ' פָּרָשִׁיּוֹת שֶׁל תּוֹרָה, וְאַף עַל פִּי שֶׁלא נִתְעַסְּקוּ לִשְׁמָהּ, שָׂכָר יִשׁ לָהֶם לָעוֹלָם הַבָּא וְלֹא יִכָּנְסוּ לַגֵּיהִנֹּם. מַה כְּתִיב בַּתְרֵיהּ וַיֹּאמֶר יְיָ אִם אֶמְצָּא בִּסְדוֹם חֲמִשִּׁים צַּדִּיקִים וְגו'.</p>\n<p>והָא (תנינן) יַתִּיר אִנּוּן פָּרָשִׁיּוֹת נ\"ג הֲווּ. אֶלָּא אָמַר רַבִּי אַבָּהוּ חֲמִשָּׁה סְפָרִים הֵם בַּתּוֹרָה וּבְכָל אֶחָד וְאֶחָד נִכְלָלִים עֲשֶׂרֶת הַדִּבְּרוֹת עֲשָׂרָה מַאֲמָרוֹת שֶׁבָּהֶם נִבְרָא הָעוֹלָם חֲשׁוֹב עֲשָׂרָה בְּכָל חַד מִנְּהוֹן הוּא חֲמִשִּׁים.</p>\n<p>עוֹד פּוֹתַחַת הַנְּשָׁמָה וְאוֹמֶרֶת רִבּוֹנוֹ שֶׁל עוֹלָם אַף עַל פִּי שֶׁלא נִתְעַסְּקוּ בַּתּוֹרָה שֶׁמָּא קִבְּלוּ עוֹנְשָׁם עַל מַה שֶּׁחָטְאוּ בְּבֵּית דִּין וְנִתְכַּפֵּר לָהֶם שֶׁנֶּאֱמַר (דברים כ״ה:ג׳) אַרְבָּעִים יַכֶּנּוּ לֹא יוֹסִיף. וּמִמַּה שֶּׁנִּתְבַּיְישׁוּ לִפְנֵיהֶם דַּיָּים לְהִתְכַּפֵּר (לפניהם) לָהֶם שֶׁלֹּא יִכָּנְסוּ לַגֵּיהִנֹּם. מַה כְּתִיב אַחֲרָיו לֹא אֶעֱשֶׂה בַּעֲבוּר הָאַרְבָּעִים.</p>\n<p>עוֹד פּוֹתַחַת ואוֹמֶרֶת אוּלַי יִשׁ שָׁם שְׁלשִׁים, אוּלַי יִשׁ בֵּינֵיהֶם צַּדִּיקִים שֶׁהִשִּׂיגוּ שְׁלשִׁים מַעֲלוֹת הָרְמוּזִים בַּפָּסוּק (יחזקאל א׳:א׳) וַיְהִי בִּשְׁלשִׁים שָׁנָה וְהֵם כְּלוּלִים בְּל\"ב נְתִיבוֹת שֶׁהֵם כ\"ב אוֹתִיּוֹת וי' סְפִירוֹת לִפְעָמִים הֵם כְּלוּלִים לִשְׁמוֹנָה.</p>\n<p>עוֹד פּוֹתַחַת ואוֹמֶרֶת אוּלַי יִמָּצְּאוּן שָׁם עֶשְׂרִים, שֶׁמָּא יְגָדְּלוּ בָּנִים לְתַלְמוּד תּוֹרָה ויִשׁ לָהֶם שָׂכָר לַעֲשֶׂרֶת הַדִּבְּרוֹת שְׁתֵּי פְּעָמִים בְּכָל יוֹם, דְּאָמַר רַבִּי יִצְּחָק <Nonei></i>כָּל הַמְגַדֵּל בְּנוֹ לְתַלְמוּד תּוֹרָה וּמוֹלִיכוֹ לְבֵית רַבּוֹ בַּבֹּקֶר וּבָעֶרֶב מַעֲלֶה עָלָיו הַכָּתוּב כְּאִלּוּ קִיֵּים (עליו) הַתּוֹרָה ב' פְּעָמִים בְּכָל יוֹם. מַה כְּתִיב וַיֹּאמֶר לא אַשְׁחִית בַּעֲבוּר הָעֶשְׂרִים.</p>\n<p>עוֹד פּוֹתַחַת וְאוֹמֶרֶת אוּלַי יִמָּצְּאוּן שָׁם עֲשָׂרָה. אוֹמֶרֶת רִבּוֹנוֹ שֶׁל עוֹלָם שֶׁמָא הָיוּ מֵאוֹתָם הָעֲשָׂרָה הָרִאשׁוֹנִים שֶׁל בֵּית הַכְּנֶסֶת שֶׁנּוֹטֵל שָׂכָר כְּנֶגֶד כֻּלָּם שֶׁבָּאִים אַחֲרֵיהֶם, מַה כְּתִיב (ביה) וַיֹּאמֶר לֹא אַשְׁחִית בַּעֲבוּר הָעֲשָׂרָה.</p>\n<p>כָּל זֶה יִשׁ לְנִשְׁמַת הַצַּדִּיק לוֹמַר עַל הָרְשָׁעִים, כֵּיוָן שֶׁלֹּא נִמְצָּא בְּיָדָם כְּלוּם, מַה כְּתִיב וַיֵּלֶךְ יְיָ כַּאֲשֶׁר כִּלָּה לְדַבֵּר אֶל אַבְרָהָם וְאַבְרָהָם שָׁב לִמְקוֹמוֹ. מַהוּ לִמְקוֹמוֹ. לִמְקוֹם מַעֲלָתוֹ הַיְדוּעָה.</p>\n<p>אָמַר רַבִּי מִצְּוָה לוֹ לָאָדָם לְהִתְפַּלֵּל עַל הָרְשָׁעִים כְּדֵי שֶׁיַּחְזְרוּ לְמוּטָב וְלא יִכָּנְסוּ לַגֵּיהִנֹּם. דִּכְתִיב, (תהילים ל״ה:י״ג) וַאֲנִי בַּחֲלוֹתָם לְבוּשִׁי שָׂק וְגו'. ואָמַר רַבִּי אָסוּר לוֹ לָאָדָם לְהִתְפַּלֵּל עַל הָרְשָׁעִים שֶׁיִּסְתַּלְּקוּ מִן הָעוֹלָם, שֶׁאִלְמָלֵא סִלְּקוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְתֶרַח מִן הָעוֹלָם כְּשֶׁהָיָה עוֹבֵד עֲבוֹדָה זָרָה, לֹא בָּא אַבְרָהָם אָבִינוּ לָעוֹלָם, וְשִׁבְטֵי יִשְׂרָאֵל לא הָיוּ, וְהַמֶּלֶךְ דָּוִד וּמֶלֶךְ הַמָּשִׁיחַ, וְהַתּוֹרָה לֹא נִתְּנָה, וְכָל אוֹתָם הַצַּדִּיקִים וְהַחֲסִידִים והַנְּבִיאִים לא הָיוּ בָּעוֹלָם. אָמַר רַבִּי יְהוּדָה כֵּיוָן שֶׁרוֹאֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלא נִמְצָּא בָּרְשָׁעִים כְּלוּם מִכָּל אוֹתָם הָעִנְיָינִים, מַה כְּתִיב ויָּבֹאוּ שְׁנִי הַמַּלְאָכִים סְדוֹמָה וגו', (עד כאן מדרש הנעלם)</p>"],[9520011227,"<p><Nonei></i>אֵרְדָה נָא וְאֶרְאֶה הַכְּצַעֲקָתָהּ הַבָּאָה אֵלַי עָשׂוּ כָּלָה. לְמַאן קָאֲמַר. אִי תֵימָא לְאִנּוּן מַלְאָכִין. מַאן חָמָא מַלִּיל עִם דָּא וּפַקִּיד לְדָא. אֶלָּא לְאַבְרָהָם קָאֲמַר דְּבִרְשׁוּתֵיהּ קָיְימִין אִנּוּן אַתְרֵי. דָּבָר אַחֵר לְאִנּוּן מַלְאָכִין.</p>\n<p>מַה דְּאִתְּמָר לְאַבְרָהָם מַה טַעֲמָא עָשׂוּ. עָשָׂה מִבָּעֵי לֵיהּ. מַאי עָשׂוּ. (אלא) דָּא אַבְרָהָם וּשְׁכִינְתָּא דְּלָא אַעֲדֵי מִנֵּיהּ. (דבר אחר) עָשׂוּ מַה דְּאִתְּמָר לַמַּלְאָכִין, בְּגִין דְּהֲווּ זְמִינִין תַּמָּן וְהֲווּ מִשְׁתַּכְּחִין לְמֶעְבַּד דִּינָא, וְעַל דָּא עָשׂוּ.</p>\n<p>דָּבָר אַחֵר עָשׂוּ (למעבד) כְּתַרְגּוּמוֹ עֲבְדוּ. וְכִי לָא הֲוָה יָדַע קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ אָמַר אֵרְדָה נָא וְאֶרְאֶה, וְהָא כֹּלָּא אִתְגְּלִי קַמֵּיהּ. אֶלָּא אֵרְדָה נָא מִדַּרְגָּא דְּרַחֲמֵי לְדַרְגָּא דְדִינָא, וְהַיְינוּ (האי) יְרִידָה. וְאֶרְאֶה, רְאִיָּיה דָּא הִיא לְאַשְׁגָּחָא עֲלֵיהוֹן בְּמַאן דִּינָא יָדִין לוֹן.</p>\n<p>אַשְׁכְּחָן רְאִיָּיה לְטַב וְאַשְׁכְּחָן רְאִיָּיה לְבִישׁ. רְאִיָּיה לְטַב, דִּכְתִיב, (שמות ב׳:כ״ה) וַיַּרְא אֱלֹהִים אֶת בְּנִי יִשְׂרָאֵל וַיֵּדַע. רְאִיָּיה לְבִישׁ, דִּכְתִיב אֵרְדָה נָא וְאֶרְאֶה (נ\"א אשכחן ירידה לטב ואשכחן ירידה לביש. לטב דכתיב, (שמות י״ט:כ׳) וירד יי על הר סיני. (במדבר י״א:י״ז) וירדתי ודברתי עמך שם. ירידה לביש ארדה נא בגין) לְאַשְׁגָּחָא עֲלַיְיהוּ בְּדִינָא, וְעַל דָּא אָמַר קוּדְשָׁא בְּרִיךְ הוּא הַמְכַסֶּה אֲנִי מֵאַבְרָהָם:</p>"],[9520011228,"<p>וְאַבְרָהָם הָיוֹ יִהְיֶה לְגוֹי גָּדוֹל וְעָצוּם. מַאי טַעְמָא בְּרָכָה דָא הָכָא. אֶלָא בְּגִין לְאוֹדָעָא דְּאָפִילּוּ בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא יָתִיב בְּדִינָא עַל עָלְמָא לָא אִשְׁתַּנִּי. דְּהָא יָתִיב בְּדִינָא עַל דָּא (ד\"א ל\"ג ויתיב) וּבְרַחֲמֵי עַל דָּא וְכֹלָּא בְּרִגְעָא חָדָא וּבְשַׁעֲתָא חָדָא.</p>\n<p>אָמַר רַבִּי יְהוּדָה וְהָא כְּתִיב, (תהילים ס״ט:י״ד) וַאֲנִי תְפִלָּתִי לְךָ יְיָ עֵת רָצוֹן. זִמְנִין דְּאִיהוּ עֵת רָצוֹן וְזִמְנִין דְּלָאו אִיהוּ עֵת רָצוֹן. זִמְנִין דְּשָׁמַע וְזִמְנִין דְּלָא שָׁמַע. זִמְנִין דְּאִשְׁתְּכַח וְזִמְנִין דְּלָא אִשְׁתְּכַח דִּכְתִיב, (ישעיהו נ״ה:ו׳) דִּרְשׁוּ יְיָ בְּהִמָּצְאוֹ קְרָאוּהוּ בִּהְיוֹתוֹ קָרוֹב.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר כָּאן לְיָחִיד כָּאן לְצִבּוּר. כָּאן לְאֲתַר חָד וְכָאן לְכוּלֵי עָלְמָא. בְּגִינִי כָךְ בָּרִיךְ לֵיהּ לְאַבְרָהָם דְּאִיהוּ שָׁקִיל כְּכָל עָלְמָא דִּכְתִיב, (בראשית ב׳:ד׳) אֵלֶּה תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם (וכתיב) וְתָנִינָן בְּאַבְרָהָם.</p>\n<p>יִהְיֶה בְּגִימַטְרִיָּא שְׁלשִׁים. הָכִי תָּנִינָן תְּלָתִין צַדִּיקִים אַזְמִין קוּדְשָׁא בְּרִיךְ הוּא בְּכָל דָּרָא וְדָרָא לְעָלְמָא. כְּמָה דְּאַזְמִין לְאַבְרָהָם.</p>\n<p>פָּתַח וְאָמַר, (שמואל ב כ״ג:כ״ג) מִן הַשְּׁלשִׁים הֲכִי נִכְבָּד וְאֶל הַשְּׁלשָׁה לֹא בָא וְגו'. מִן הַשְּׁלשִׁים הֲכִי נִכְבָּד, אִלֵּין אִנּוּן תְּלָתִין צַדִּיקִים דְּאַזְמִין קוּדְשָׁא בְּרִיךְ הוּא לְעָלְמָא וְלָא יְבַטֵּל לוֹן מִנֵּיהּ. וּבְנָיָהוּ בֶּן יְהוֹיָדָע כְּתִיב בֵּיהּ מִן הַשְּׁלשִׁים הֲכִי נִכְבָּד אִיהוּ חַד מִנַּיְיהוּ. וְאֶל הַשְּׁלשָׁה לא בָא. דְּלָא שָׁקִיל לִתְלָתָא אָחֳרָנִין דְּעָלְמָא קָאִים עֲלַיְיהוּ.</p>\n<p>וְאֶל הַשְּׁלשָׁה לֹא בָא. לְמֶהוֵי בְּמִנְיָינָא כְּחַד מִנַּיְיהוּ. בְּאִנּוּן תְּלָתִין זַכָּאִין זָכָה לְמֵיעַל בְּחוּשְׁבְּנָא, אֲבָל וְאֶל הַשְּׁלשָׁה לֹא בָא, דְּלָא זָכָה לְאִתְחַבְּרָא בְּהוּ וּלְמֶהֱוֵי עִמְּהוֹן בְּחוּלָקָא חָדָא. יִהְיֶ\"ה, כְּמָה דְּתָנִינָן תְּלָתִין הֲוָה. וּבְגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא בָּרְכֵיהּ בְּאִנּוּן תְּלָתִין צַדִּיקִים.</p>"],[9520011229,"<p>תָּא חֲזֵי, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְאַבְרָהָם זַעֲקַת סְדוֹם וַעֲמוֹרָה כִּי רָבָּה, דְּהָא סְלִיקַת קֳדָמַי מַה דְּאִנּוּן עָבְדִין לְכָל עָלְמָא, דְּכָל עָלְמָא מָנְעֵי רַגְלַיְיהוּ דְּלָא לְמֵיעַל בִּסְדוֹם וַעֲמוֹרָה דִּכְתִיב, (איוב כ״ח:ד׳) פָּרַץ נַחַל מֵעִם גָּר הַנִּשְׁכָּחִים מִנִּי רָגֶל דַּלּוּ מֵאֱנוֹשׁ נָעוּ. פָּרַץ נַחַל מֵעִם גָּר, פִּרְצָה הֲוָה פָּרִיץ נַחַל לְאִנּוּן בְּנֵי עָלְמָא דְּעָאלוּ לְתַמָּן. דְּכֻלְהוּ דְּחָמָאן לְמַאן דְּהֲווּ יַהֲבֵי לְמֵיכַל וּלְמִשְׁתֵּי לְבַר נָשׁ אָחֳרָא, שַׁדְיָין לֵיהּ (בנוקבי דנקרי) בְּעוּמְקָא דְּנַהֲרָא, וְאִיהוּ דְּנָטִיל לֵיהּ הָכִי נָמֵי.</p>\n<p>וְעַל דָּא כֻּלְהוּ בְּנֵי עָלְמָא הֲווּ נִשְׁכָּחִים מִנִּי רָגֶל. דְּמָנְעֵי רַגְלַיְיהוּ דְּלָא לְמֵיעַל תַּמָּן. וּמַאן דְּעָאל, דַּלּוּ מֵאֱנוֹשׁ נָעוּ, דְּהֲווּ דָּלֵי גוּפָא בְּכַפְנָא לָא הֲווּ יַהֲבֵי לֵיהּ לְמֵיכַל וּלְמִשְׁתֵּי וְאִשְׁתַּנֵּי דִּיוּקְנֵיהּ מִשְּׁאָר בְּנֵי עָלְמָא, דִּכְתִיב דַּלּוּ מֵאֱנוֹשׁ, נָעוּ. כְּתִיב הָכָא נָעוּ. וּכְתִיב הָתָם (משלי ה׳:ו׳) נָעוּ מַעְגְּלוֹתֶיהָ. הָכִי נָמֵי הֲווּ סָטָאן מַעֲגָלִין וְאָרְחִין דְּלָא לְמֵיעַל תַּמָּן. וְאֲפִילּוּ עוֹפֵי שְׁמַיָא הֲווּ מָנְעֵי <Nonei></i>לְמֵיעַל תַּמָּן דִּכְתִיב, (איוב כ״ח:ז׳) נְתִיב לֹא יְדָעוֹ עַיִט וְגו'. וּבְגִינֵי כָךְ כֻּלֵּי עָלְמָא הֲווּ צָוְוחִין עַל סְדוֹם וְעַל עֲמוֹרָה וְעַל כֻּלְהוּ קַרְתֵּי. דְּכֻלְהוּ כְּגַוְונָא חָדָא הֲווּ.</p>\n<p>זַעֲקַת סְדוֹם וַעֲמוֹרָה כִּי רָבָּה. אָמַר לֵיהּ אַבְרָהָם. אַמַּאי. אָמַר לֵיהּ וְחַטָּאתָם כִּי כָבְדָה מְאֹד. בְּגִינֵי כָךְ אֵרְדָה נָא וְאֶרְאֶה, הַכְּצַעֲקָתָהּ. הַכְּצַעֲקָתָם מִבָּעֵי לֵיהּ, דְּהָא כְּתִיב זַעֲקַת סְדוֹם וַעֲמוֹרָה וּתְרֵי קַרְתֵּי הֲווּ, אַמַּאי הַכְּצַעֲקָתָהּ. אֶלָּא הָא אוּקְמוּהָ.</p>\n<p>תָּא חֲזֵי, בְּסִטְרָא דְּתוּתֵי קָלָא דְּבַרְדָּא סָלְקִין קוּטְרֵי כֻּלְהוּ בְּכַתְּפָא מִתְכַּנְשֵׁי בְּחַד טִיף וְעָאלִין בְּגוֹ נוּקְבֵי דִּתְהוֹמָא רַבָּא, אִתְעֲבִידוּ חָמֵשׁ בְּחַד. חַד אִיהוּ כַּד (צלילן קלין) אִיכָּא צְלִילִין קָלִין דְּכֻלְהוּ אִתְעֲבִידוּ חַד. קָלָא דְּסָלִיק מִתַּתָּא עָאל בֵּינַיְיהוּ וְאִתְמַשְׁכוּ כְּחַד.</p>\n<p>וְהַהוּא קָלָא סָלְקָא וְנַחֲתָא תָּבְעָא דִינָא לְאִתְמַשְׁכָא לְתַתָּא. כַּד הַאי קָלָא סָלְקָא לְמִתְבַּע דִּינָא כְּדֵין אִתְגְּלִי לְאַשְׁגָחָא קוּדְשָׁא בְּרִיךְ הוּא בְּדִינָא.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, הַכְּצַעֲקָתָהּ. מַאן הַכְּצַעֲקָתָהּ, דָּא גְּזֵרַת דִּינָא דְּתָבְעָא דִינָא כָּל יוֹמָא. דְּהָכִי תָּנִינָן כַּמָּה שְׁנִין קָיְימָא גְּזֵרַת דִּינָא וְתָבְעָא מִקַּמֵּי קוּדְשָׁא בְּרִיךְ הוּא עַל דְּזַבִּינוּ אֲחוּי דְיוֹסֵף לְיוֹסֵף. בְּגִין דִּגְזֵרַת דִּינָא צָוְוחַת עַל דִּינָא, וְעַל דָּא הַכְּצַעֲקָתָהּ, הַבָּאָה אֵלַי.</p>\n<p>מַאי (קז א) הַבָּאָה אֵלַי. דָּא הוּא רָזָא כְּמָא דְאַתְּ אָמֵר, (אסתר ב׳:י״ד) בָּעֶרֶב הִיא בָאָה וּבַבֹּקֶר הִיא שָׁבָה. וְדָא הוּא הַבָּאָה אֵלַי תָּדִיר. כְּגַוְונָא דָא קֵץ כָּל בָּשָׂר בָּא לְפָנַי וְהָא אִתְּמָר. עָשׂוּ כָּלָה הָא אִתְּמָר:</p>"],[9520011230,"<p>וַיִּגַשׁ אַבְרָהָם וַיֹּאמַר הַאַף תִּסְפֶּה צַדִּיק עִם רָשָׁע. אָמַר רַבִּי יְהוּדָה מַאן חָמָא אַבָּא דְּרַחְמָנוּתָא כְּאַבְרָהָם. תָּא חֲזֵי, בְּנֹחַ כְּתִיב וַיֹּאמֶר אֱלֹהִים לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי וְגו' עֲשֵׂה לְךָ תֵּבַת עֲצֵי גֹפֶר. וְאִשְׁתִּיק וְלָא אָמַר לֵיהּ מִידִי. וְלָא בָעָא רַחֲמֵי. אֲבָל אַבְרָהָם בְּשַׁעֲתָא דְּאָמַר לֵיה קוּדְשָׁא בְּרִיךְ הוּא, זַעֲקַת סְדוֹם וַעֲמוֹרָה כִּי רָבָּה וְגו'. אֵרַדָה נָא וְאֶרְאֶה וְגו'. מִיָּד כְּתִיב וַיִּגַּשׁ אַבְרָהָם וַיֹּאמַר הַאַף תִּסְפֶּה צַדִּיק עִם רָשָׁע.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אוּף אַבְרָהָם לָא עָבַד שְׁלִימוּ כְּדְקָא יְאוּת. נֹחַ לָא עֲבִיד מִידִי, לָא הַאי וְלָא הַאי. אַבְרָהָם תָּבַע דִּינָא כְּדְקָא יְאוּת דְּלָא יְמוּת זַכָּאָה עִם חַיָּיבָא. וְשָׁארֵי מֵחֲמִשִּׁים עַד עֲשָׂרָה, עָבַד וְלָא אַשְׁלִים, דְּלָא בָּעָא רַחֲמֵי בֵּין כָּךְ וּבֵין כָּךְ, דְּאָמַר אַבְרָהָם לָא בָּעִינָא לְמִתְבַּע אֲגַר עוֹבָדוֹי.</p>\n<p>אֲבָל מַאן עָבַד שְׁלִימוּ כְּדְקָא יְאוּת, דָּא משֶׁה. דְּכֵיוָן דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא (שמות ל״ב:ח׳) סָרוּ מַהֵר מִן הַדֶּרֶךְ וְגו'. עָשׂוּ לָהֶם עֵגֶל מַסֵּכָה וַיִּשְׁתַּחֲווּ לוֹ. מִיָּד מַה כְּתִיב וַיְחַל משֶׁה אֶת פְּנֵי יְיָ אֱלהָיו וְגו'. עַד דְּאָמַר וְעַתָּה אִם תִּשָּׂא חַטָּאתָם וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךָ אֲשֶׁר כָּתָבְתָּ. וְאַף עַל גַּב דְּכֻלְהוּ חָטוּ, לָא זָז מִתַּמָּן עַד דְּאָמַר לֵיהּ סָלַחְתִּי כִּדְבָרֶךָ.</p>\n<p>אֲבָל אַבְרָהָם לָא אַשְׁגַּח אֶלָּא אִי אִשְׁתְּכַח בְּהוּ זַּכַּאי וְאִם לָאו לָא. וְעַל דָּא לָא הֲוָה בְּעָלְמָא בַּר נָשׁ דְּיָגִין עַל דָּרֵיהּ כְּמשֶׁה דְּאִיהוּ רַעֲיָא מְהֵימְנָא.</p>\n<p>וַיִּגַּשׁ אַבְרָהָם וַיֹּאמַר, אַתְקִין גַּרְמֵיהּ לְמִתְבַּע דָּא. אוּלַי יִמָּצְאוּ שָׁם חֲמִשִּׁים. שָׁרָא מֵחֲמִשִּׁים דְּאִיהוּ שֵׁירוּתָא לְמִנְדַע, עַד עֲשָׂרָה דְּאִיהוּ עֲשִׂירָאָה סוֹפָא דְּכָל דַּרְגִּין.</p>\n<p>אָמַר רַבִּי יִצְחָק עַד עֲשָׂרָה, אִלֵּין עֲשָׂרָה יוֹמִין דְּבֵין רֹאשׁ הַשָּׁנָה לְיוֹם הַכִּפּוּרִים. בְּגִין כָּךְ שָׁרָא מֵחֲמִשִּׁים עַד עֲשָׂרָה. וְכֵיוָן דְּמָטָא לַעֲשָׂרָה, אָמַר מִכָּאן וּלְתַתָּא לָאו הוּא אֲתַר דְּקָיְימָא בִּתְשׁוּבָה, בְּגִינֵי כָךְ לָא נָחַת לְתַתָּא מֵעֲשָׂרָה:</p>"],[9520011231,"<p>וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדוֹמָה בָּעֶרֶב וְגו'. אָמַר רַבִּי יוֹסֵי תָּא חֲזֵי מַה כְּתִיב לְעֵילָא וַיֵּלֶךְ יְיָ כַּאֲשֶׁר <Nonei></i>כִּלָּה לְדַבֵּר אֶל אַבְרָהָם. דְּהָא כֵּיוָן דְּאִתְפְּרַשׁ שְׁכִינְתָּא מֵאַבְרָהָם, וְאַבְרָהָם תָּב לְאַתְרֵיהּ, כְּדֵין וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדוֹמָה בָּעֶרֶב, דְּהָא חַד אִסְתַּלַּק בִּשְׁכִינְתָּא, וְאִשְׁתָּאֲרוּ אִנּוּן תְּרֵין.</p>\n<p>כֵּיוָן דְּחָמָא לוֹט לוֹן, רָהַט בַּתְרַיְיהוּ. מַאי טַעְמָא, וְכִי כָּל אִנּוּן דְּהֲווּ אַתְיָין אִיהוּ אָעִיל לוֹן לְבֵיתֵיהּ וְיָהִיב לוֹן לְמֵיכַל וּלְמִשְׁתֵּי וּבְנִי מָתָא הֵיךְ לָא קָטְלִין לֵיהּ, דְּהָא לִבְרַתֵּיהּ עֲבְדוּ דִינָא.</p>\n<p>וּמַאי הוּא. דִּבְרַתֵּיהּ דְּלוֹט יַהֲבַת פִּתָּא דְּנַהֲמָא לְחַד עַנְיָא, יָדְעוּ בָּהּ, שָׁפוּהָ דוּבְשָׁא וְאוֹתְבוּהָ בְּרִישׁ אִיגְרָא עַד דְּאֲכְלוּהָ צִרְעֵי.</p>\n<p>אֶלָּא בְּגִין דְּהֲוָה בְּלֵילְיָא חָשִׁיב דְּלָא יִסְתַּכְּלוּן לֵיהּ בְּנֵי מָתָא, וְעִם כָּל דָּא כֵּיוָן דַּאֲעָלוּ לְבֵיתָא אִתְכְּנָשׁוּ כֻּלְהוּ וְאַסְחָרוּ לְבֵיתָא.</p>\n<p>אָמַר רַבִּי יִצְחָק אַמַּאי רָהַט לוֹט אֲבַּתְרַיְיהוּ, (אלא בגין) דִּכְתִיב וַיַּרְא לוֹט וַיָּרָץ לִקְרָאתָם. רַבִּי חִזְקִיָּה וְרַבִּי יֵיסָא. חַד אָמַר דִּיוּקְנָא דְּאַבְרָהָם חָמָא עִמְהוֹן. וְחַד אָמַר שְׁכִינְתָּא אַתְיָא עֲלַיְיהוּ. כְּתִיב הָכָא וַיַּרְא לוֹט וַיָּרָץ לִקְרָאתָם, וּכְתִיב הָתָם וַיָּרָץ לִקְרָאתָם מִפֶּתַח הָאֹהֶל. מַה לְהַלָּן חָמָא שְׁכִינְתָּא, אוּף הָכָא חָמָא שְׁכִינְתָּא.</p>\n<p>וַיַּרְא לוֹט וַיָּרָץ לִקְרָאתָם וַיֹּאמֶר הִנֶּה נָּא אֲדֹנַי בָּאָלֶ\"ף דָלֶ\"ת נוּ\"ן יוּ\"ד. סוּרוּ נָא, גְּשׁוּ נָא מִבָּעֵי לֵיהּ, מַאי סוּרוּ נָא. אֶלָּא לְאַהֲדָרָא לוֹן סַחֲרָנֵיהּ דְּבֵיתָא בְּגִין דְּלָא יֶחמוּן לוֹן בְּנֵי מָתָא, וְלָא יֵעֲלוּן בְּאוֹרַח מֵישָׁר לְבֵיתָא, וּבְגִין כָּךְ סוּרוּ נָא.</p>\n<p>רַבִּי חִזְקִיָּה פָּתַח (איוב כ״ח:כ״ד) כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט תַּחַת כָּל הַשָּׁמַיִם יִרְאֶה. כַּמָּה אִית לוֹן לִבְנֵי נָשָׁא לְאִסְתַּכָּלָא בְּעוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְאִשְׁתַּדָּלָא בְּאוֹרַיְיתָא יְמָמָא וְלֵילֵי, דְּכָל מָאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, קוּדְשָׁא בְּרִיךְ הוּא אִשְׁתַּבַּח בֵּיהּ לְעֵילָא, וְאִשְׁתַּבַּח בֵּיהּ לְתַתָּא, בְּגִין דְּאוֹרַיְיתָא אִילָנָא דְחַיֵּי אִיהִי לְכָל אִנּוּן דְּעָסְקִין בָּהּ לְמֵיהַב לוֹן חַיִּין בְּעָלְמָא דֵין <Nonei></i>וּלְמֵיהַב לוֹן חַיִּין בְּעָלְמָא דְּאָתֵי.</p>\n<p>תָּא חֲזֵי, כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט. לְמֵיהַב לוֹן מְזוֹנָא וּלְסַפָּקָא לוֹן מִכָּל מַה דְּאִצְטְרִיכוּ, בְּגִין דְּאִיהוּ אַשְׁגַּח בָּהּ תָּדִיר, דִּכְתִיב, (דברים י״א:י״ב) תָּמִיד עֵינֵי יְיָ אֱלוֹהֶיךָ בָּהּ מֵרִשִׁית הַשָּׁנָה וְעַד אַחֲרִית שָׁנָה.</p>\n<p>בְּגִין דְּאֶרֶץ דָּא מַה כְּתִיב בָּהּ (משלי ל״א:י״ד) מִמֶּרְחָק תָּבִיא לַחְמָהּ, וּלְבָתַר אִיהִי יְהַבְתְּ מְזוֹנָא וְטַרְפָא לְכָל אִנּוּן חֵיוָן בְּרָא דִּכְתִיב (משלי ל״א:ט״ו) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ.</p>\n<p>וְעַל דָּא כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט תַּחַת כָּל הַשָּׁמַיִם יִרְאֶה. לְכֻלְהוּ בְּנֵי עָלְמָא לְמֵיהַב לוֹן מְזוֹנָא וְסִפּוּקָא לְכָל מַה דְּאִצְטְרִיךְ כָּל חַד וְחַד דִּכְתִיב (תהילים קמ״ה:ט״ז) פּוֹתֵחַ אֶת יָדֶךָ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן.</p>\n<p>דָּבָר אַחֵר כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט. לְאִסְתַּכָּלָא עוֹבָדוֹי דְּבַר נָשׁ וּלְאַשְׁגָּחָא בְּכָל מַה דְּעַבְדֵי בְּנֵי נָשָׁא בְּעָלְמָא. תַּחַת כָּל הַשָּׁמַיִם יִרְאֶה. מִסְתַּכֵּל וְחָמֵי לְכָל חַד וְחַד.</p>\n<p>תָּא חֲזֵי, כֵּיוָן דְּחָמָא קוּדְשָׁא בְּרִיךְ הוּא עוֹבָדִין דִּסְדוֹם וַעֲמוֹרָה, שַׁדַּר לוֹן לְאִנּוּן מַלְאָכִין לְחַבָּלָא לִסְדוֹם. מַה כְּתִיב וַיַּרְא לוֹט חָמָא לִשְׁכִינְתָּא. וְכִי מַאן יָכִיל לְמֶחמֵי שְׁכִינְתָּא, אֶלָא חָמָא זָהֲרָא חַד דְּנָהִיר דְּקָא סָלְקָא עַל רֵישַׁיְיהוּ. וּכְדֵין וַיֹּאמֶר הִנֶּה נָּא אֲדֹנַי בְּאָלֶ\"ף דָלֶ\"ת כְּמָה דְּאִתְּמָר, וּבְגִין שְׁכִינְתָּא הַהוּא נְהִירוּ דְּנָהִיר קָאֲמַר, סוּרוּ נָא אֶל בֵּית עַבְדְּכֶם וְלִינוּ וְרַחֲצוּ רַגְלֵיכֶם.</p>\n<p>לָא עֲבַד הָכִי אַבְרָהָם, אֶלָּא בְּקַדְמִיתָא אָמַר וְרַחֲצוּ רַגְלֵיכֶם וּלְבָתַר וְאֶקְחָה פַּת לֶחֶם וְגו'. אֲבָל לוֹט אָמַר סוּרוּ נָא אֶל בֵּית עַבְדְּכֶם וְלִינוּ. וּלְבָתַר וְרַחֲצוּ רַגְלֵיכֶם וְהִשְׁכַּמְתֶּם וַהֲלַכְתֶּם לְדַרְכְּכֶם. בְּגִין דְּלָא יִשְׁתְּמוֹדְעוּן בְּהוּ בְּנֵי נָשָׁא.</p>\n<p>וַיֹּאמְרוּ לֹא כִּי בָרְחוֹב נָלִין. בְּגִין דְּכָךְ הֲווּ עָבְדֵי אוֹרְחִין דְּעָאלִין תַּמָּן לָא הֲוָה בַּר נָשׁ דְּיִכְנוֹשׁ לוֹן לְבֵיתָא, וְעַל דָּא אָמְרוּ לא כִּי בָרְחוֹב נָלִין. מַה כְּתִיב וַיִּפְצַר בָּם מְאֹד וְגו'.</p>\n<p>תָּא חֲזֵי כַּד קוּדְשָׁא בְּרִיךְ הוּא עֲבִיד דִּינָא בְּעָלְמָא, שְׁלִיחָא חָדָא עֲבִיד לֵיהּ, וְהַשְׁתָּא חָמֵינָן תְּרֵי שְׁלוּחֵי, אַמַּאי וְכִי לָא סַגֵּי בְּחַד. אֶלָא חַד הֲוָה, וּמַה דְּאָמַר תְּרֵי (הכי הוא ודאי בגין דחד) חַד הֲוָה לְאַפָּקָא לֵיהּ לְלוֹט וּלְשֵׁזָבָא לֵיהּ, וְחַד לְמֶהְפַּךְ לְקַרְתָּא וּלְחַבָּלָא אַרְעָא, וּבְגִין כָּךְ אִשְׁתָּאַר חַד:</p>"],[9520011232,"<p><Nonei></i><Noneb>מִדְרָשׁ הַנֶּעֱלָם</b> רַבִּי פָּתַח בְּהַאי קְרָא (שופטים ג׳:א׳) וְאֵלֶּה הַגּוֹיִם אֲשֶׁר הִנִּיחַ יְיָ לְנַסּוֹת בָּם אֶת יִשְׂרָאֵל. אָמַר רַבִּי חָזֵי הֲוִית בְּהַהוּא עָלְמָא (ולית עלמא) קָאִים (ד\"א ולית מעלה) אֶלָּא בְּאִנּוּן <Nonei></i>דְּשַׁלִּיטִין עַל רְעוּתָא דְּלִבְּהוֹן שֶׁנֶּאֱמַר (תהילים פ״א:ו׳) עֵדוּת בִּיהוֹסֵף שָׂמוֹ וְגו'. אָמַר רַב יְהוּדָה לָמָּה זָכָה יוֹסֵף לְאוֹתָהּ הַמַּעֲלָה וְהַמַּלְכוּת, בִּשְׁבִיל שֶׁכָּבַשׁ יִצְּרוֹ. דְּתָנִינָן כָּל הַכּוֹבֵשׁ אֶת יִצְּרוֹ מַלְכוּתָא דִּשְׁמַיָא אָחִיל עֲלֵיהּ.</p>\n<p>דְּאָמַר רַב אַחָא לֹא בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לַיֵּצֶּר הָרָע אֶלָּא לְנַסּוֹת בּוֹ בְּנֵי אָדָם. וּמִי בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְנַסּוּתָא בִּבְנֵי נָשָׁא. אִין. דְּאָמַר רַב אַחָא מְנָא לָן מִדִּכְתִיב, (דברים י״ג:ד׳) כִּי יָקוּם בְּקִרְבְּךָ נָבִיא וגו' וּבָא הָאוֹת וְהַמּוֹפֵת וגו' כִּי מְנַסֶה יְיָ אֱלהֵיכֶם וגו'. וְלָמָה בָּעֵי נַסוּתָא דְּהָא כָּל עוֹבָדוֹי דְּבַר נָשׁ אִתְגְּלִי קַמֵּיהּ, אֶלָּא שֶׁלא לָתֵת פִּתְחוֹן פֶּה לִבְנֵי אָדָם. רְאֵה מַה כְּתִיב וְלוֹט יוֹשֵׁב בְּשַׁעַר סְדוֹם, דְּהֲוָה יָתִיב לְנַסּוּתָא לִבְרִיָּיתָא.</p>\n<p>אָמַר רַבִּי יִצְּחָק מַאי דִּכְתִיב (ישעיהו נ״ז:כ׳) וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ וְגו'. אֲפִלּוּ בִּשְׁעַת דִּינוֹ שֶׁל רָשָׁע הוּא מֵעִיז פָּנָיו ואֲזַי הוּא בְּרִשְׁעָתוֹ קַיָּים, רְאֵה מַה כְּתִיב טֶרֶם יִשְׁכָּבוּ וגו'. אָמַר רַבִּי יִצְּחָק כְּשֵׁם שֶׁבָּרָא קוּדְשָׁא בְּרִיךְ הוּא גַּן עֵדֶן בָּאָרֶץ כָּךְ בָּרָא גֵּיהִנֹּם בָּאָרֶץ. וּכְשֵׁם שֶׁבָּרָא גַּן עֵדֶן לְמַעְלָה כָּךְ בָּרָא גֵּיהִנֹּם לְמַעְלָה.</p>\n<p>גַּן עֵדֶן בָּאָרֶץ דִּכְתִיב, (בראשית ב׳:ח׳) וַיִּטַע יְיָ אֱלֹהִים גַּן בְּעֵדֶן וגו'. גֵּיהִנֹּם בָּאָרֶץ דִּכְתִיב, (איוב י׳:כ״ב) אֶרֶץ עֵיפָתָה כְּמוֹ אוֹפֶל וגו'. גַּן עֵדֶן לְמַעְלָה דִּכְתִיב, (שמואל א כ״ה:כ״ט) וְהָיְתָה נֶפֶשׁ אֲדוֹנִי צְּרוּרָה בִּצְּרוֹר הַחַיִּים אֶת ה' אֱלֹהֶיךָ וּכְתִיב, (קהלת י״ב:ז׳) וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ.</p>\n<p>גֵּיהִנֹּם לְמַעְלָה דִּכְתִיב וְאֵת נֶפֶשׁ אֹיְבֶיךָ יְקַלְּעֶנָּה בְּתוֹךְ כַּף הַקָּלַע. גַּן עֵדֶן לְמַטָה כִּדְקָאֲמָרָן. גַּן עֵדֶן לְמַעְלָה לְנִשְׁמָתָן שֶׁל צַּדִּיקִים גְּמוּרִים לִהְיוֹת נִזּוֹנִין מֵאוֹר הַגָּדוֹל שֶׁל מַעְלָה.</p>\n<p>גֵּיהִנִֹּם לְמַטָה לְאוֹתָם הָרְשָׁעִים (דישראל) שֶׁלֹּא קִבְּלוּ בְּרִית מִילָה וְלֹא הֶאֱמִינוּ בְּהַקָּדוֹשׁ בָּרוּךְ הוּא וְדָתוֹ ולֹא שָׁמְרוּ שַׁבָּת, וְאֵלּוּ הֵם עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁנִּדּוֹנִים בָּאֵשׁ, שֶׁנְּאֱמַר (יחזקאל ט״ו:ז׳) מֵהָאֵשׁ יָצָּאוּ וְהָאֵשׁ תֹּאכְלֵם וגו'. וּכְתִיב (ישעיהו ס״ו:כ״ד) וְיָצְּאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים וְגו'.</p>\n<p>גֵּיהִנֹּם לְמַעְלָה לְאוֹתָם פּוֹשְׁעֵי יִשְׂרָאֵל שֶׁעָבְרוּ עַל מִצְּווֹת הַתּוֹרָה וְלֹא חָזְרוּ בִּתְשׁוּבָה שֶׁדּוֹחִים אוֹתָם לַחוּץ עַד שֶׁיְקַבְּלוּ עָנְשָׁם. וְהוֹלְכִים וְסוֹבְבִים כָּל הָעוֹלָם שֶׁנֶּאֱמַר (תהילים י״ב:ט׳) סָבִיב רְשָׁעִים יִתְהַלָּכוּן.</p>\n<p>וְשָׁם נִדּוֹנִים שְׁנֵים עָשָׂר חֹדֶשׁ, לְאַחַר כֵּן מָדוֹרָם עִם אוֹתָם שֶׁקִּבְּלוּ עָנְשָׁם בְּמוֹתָם <Nonei></i>כָּל אֶחָד ואֶחָד כְּפִי הַמָּקוֹם הָרָאוּי לוֹ. וְהָרְשָׁעִים שֶׁל הַעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת נִדּוֹנִים תָּמִיד בָּאֵשׁ וּבַמַּיִם וְשׁוּב אֵינָם עוֹלִים שֶׁנְּאֱמַר וְאִשָּׁם לא תִכְבֶּה.</p>\n<p>מִשְׁפַּט הָרְשָׁעִים בַּגֵּיהִנָּם כְּמָה דִּכְתִיב וַיְיָ הִמְטִיר עַל סְדוֹם וְעַל עֲמוֹרָה גָּפְרִית וָאֵשׁ וְגו' ושׁוּב אֵינָם עוֹלִים ולֹא יָקוּמוּ לְיוֹם הַדִּין שֶׁנֶּאֱמַר (דברים כ״ט:כ״ב) אֲשֶׁר הָפַךְ יְיָ בְּאַפּוֹ וּבַחֲמָתוֹ, בְּאַפּוֹ בָּעוֹלָם הַזְּה. וּבַחֲמָתוֹ בָּעוֹלָם הַבָּא.</p>\n<p>אָמַר רַבִּי יִצְּחָק לְהַאי גַּוְונָא אִית גַּן עֵדֶן לְמַעְלָה וְאִית גַּן עֵדֶן לְמַטָה. אִית גֵּיהִנֹּם לְמַטָה ואִית גֵּיהִנֹּם לְמַעְלָה. אָמַר רַבִּי יַעֲקֹב הָרְשָׁעִים שֶׁקִּלְקְלוּ בְּרִית מִילָה שֶׁבָּהֶם וְחִלְּלוּ שַׁבָּת בְּפַרְהֶסְיָא וְחִלְּלוּ אֶת הַמּוֹעֲדוֹת וְשֶׁכָּפְרוּ בַּתּוֹרָה וְשֶׁכָּפְרוּ בִּתְחִיַּת הַמֵּתִים וְכַדּוֹמֶה לָהֶם יוֹרְדִים לַגֵּיהִנֹּם שֶׁלְּמַטָה וְנִדּוֹנִים שָׁם וְשׁוּב אֵינָם עוֹלִים.</p>\n<p>אֲבָל יָקוּמוּ לְיוֹם הַדִּין וְיָקוּמוּ לִתְחִיַּת הַמֵּתִים, וַעֲלֵיהֶם נֶאֱמַר (דניאל י״ב:ב׳) וְרַבִּים מִישֵׁנִי אַדְמָת עָפָר יָקִיצּוּ אֵלֶּה לְחַיֵּי עוֹלָם וְגו'. וַעֲלֵיהֶם נְאֱמַר (ישעיהו ס״ו:כ״ד) וְהָיוּ דֵּרָאוֹן לְכָל בָּשָׂר. מַה דֵּרָאוֹן, דַּיי רָאוֹן, שֶׁהַכֹּל יֹאמְרוּ דַּיי בִּרְאִיָּיתָם. וְעַל הַצַּדִּיקִים שֶׁבְּיִשְׂרָאֵל נֶאֱמַר (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַּדִּיקִים וגו', (ע\"כ מדרש הנעלם)</p>"],[9520011233,"<p>וַיְיָ הִמְטִיר עַל סְדוֹם וְעַל עֲמוֹרָה וְגו'. רַבִּי חִיָּיא פָּתַח (ישעיהו י״ג:ט׳) הִנֵּה יוֹם יְיָ בָּא אַכְזָרִי וְגו'. הִנִּה יוֹם יְיָ בָּא, דָּא בֵּי דִינָא לְתַתָּא. בָּא כְּמָה דְּאִתְּמָר. (קו א) הַבָּאָה אֵלַי (עשו). בְּגִין דְּלָא עֲבִיד דִּינָא עַד דְעָאל וְנָטִיל רְשׁוּ, כְּגַוְונָא דָּא קֵץ כָּל בָּשָׂר בָּא לְפָנַי.</p>\n<p>דָּבָר אַחֵר הִנֵּה יוֹם יְיָ בָּא. דָּא הוּא מְחַבְּלָא לְתַתָּא כַּד נָטִיל נִשְׁמָתָא, בְּגִינֵי כָּךְ אַכְזָרִי וְעֶבְרָה. לָשׂוּם הָאָרֶץ לְשַׁמָּה, דָּא סְדוֹם וַעֲמוֹרָה. וְחַטָּאֶיהָ <Nonei></i>יַשְׁמִיד מִמֶּנָּהּ. אִלֵּין יַתְבֵי אַרְעָא.</p>\n<p>מַה כְּתִיב בַּתְרֵיהּ כִּי כּוֹכְבֵי הַשָּׁמַיִם וּכְסִילֵיהֶם וְגו'. דְּהָא מִן שְׁמַיָא אַמְטָר עֲלֵיהוֹן אֶשָׁא, וְאַעֲבַר לוֹן מִן עָלְמָא. לְבָתַר מַה כְּתִיב אוֹקִיר אֱנוֹשׁ מִפָּז וְגו'. דָּא אַבְרָהָם דְּקוּדְשָׁא בְּרִיךְ הוּא סָלִיק לֵיהּ עַל כָּל בְּנֵי עָלְמָא.</p>\n<p>רַבִּי יְהוּדָה אוֹקִים לוֹן לְהַנֵּי קְרָאֵי בְּיוֹמָא דְּאִתְחָרַב בֵּי מַקְדְּשָׁא, דִּבְהַהוּא יוֹמָא אִתְחַשְׁכוּ עִלָּאֵי וְתַתָּאֵי, וְאִתְחַשְׁכָן שְׁמַיָא וְכוֹכְבַיָא. רַבִּי אֶלְעָזָר מוֹקִים לְהַנֵּי קְרָאֵי בְּיוֹמָא דְּיוֹקִים קוּדְשָׁא בְּרִיךְ הוּא לִכְנְסֶת יִשְׂרָאֵל מֵעַפְרָא, וְהַהוּא יוֹמָא יִתְיְדַע לְעֵילָא וְתַתָּא, דִּכְתִיב, (זכריה י״ד:ז׳) וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַיְיָ. וְהַהוּא יוֹמָא יוֹמָא דְּנוֹקְמָא אִיהוּ, דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְנָקְמָא מִשְּׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת.</p>\n<p>וְכַד קוּדְשָׁא בְּרִיךְ הוּא יַעֲבִיד נוּקְמִין בִּשְׁאָר עַמִין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, כְּדֵין אוֹקִיר אֱנוֹשׁ מִּפָּז דָּא מַלְכָּא מְשִׁיחָא דְּיִסְתָּלַּק וְיִתְיָיקַר עַל כָּל בְּנִי עָלְמָא, וְכָל בְּנֵי עָלְמָא יִפְלְחוּן וְיִסְגְּדוּן קַמֵּיהּ דִּכְתִיב, (תהילים ע״ב:ט׳) לְפָנָיו יִכְרְעוּ צִיִּים וְגו' מַלְכֵי תַרְשִׁישׁ וְגו'.</p>\n<p>תָּא חֲזֵי, אַף עַל גַּב דִּנְבוּאָה דָא אִתְּמָר עַל בָּבֶל, בְּכוֹלָּא אִתְּמָר. דְּהָא חָמֵינָן בְּהַאי פַּרְשָׁתָא דִּכְתִיב (ר\"ל סמוך לפ' שלמעלה שכ' בה אוקיר אנוש וגו' ואולי לדעת הזוה\"ק חד פר' היא) כִּי יְרַחֵם יְיָ אֶת יַעֲקֹב. וּכְתִיב וּלְקָחוּם עַמִּים וְהֱבִיאוּם אֶל מְקוֹמָם.</p>\n<p>וַיְיָ הִמְטִיר עַל סְדוֹם. דָּא דַּרְגָא דְּבֵי דִינָא לְתַתָּא דְּנָטִיל רְשׁוּ מֵעֵילָא. רַבִּי יִצְחָק אָמַר דְּעֲבִיד דִּינָא בְּרַחֲמֵי. דִּכְתִיב מֵאֵת יְיָ מִן הַשָּׁמָיִם. בְּגִין לְאִשְׁתַּכָּחָא דִּינָא בְּרַחֲמֵי. וְאִי תֵימָא מַאי רַחֲמֵי הָכָא דִּכְתִיב וַיְהִי בְּשַׁחֵת אֱלֹהִים אֶת עָרֵי הַכִּכָּר וַיִּזְכֹּר אֱלֹהִים אֶת אַבְרָהָם וְגו'. וּלְבָתַר נָפְקוּ מִנֵּיהּ תְּרֵין אוּמִין שְׁלֵמִין, וְזָכָה דְּנָפִיק מִנֵּיהּ דָּוִד וּשְׁלֹמֹה מַלְכָּא.</p>\n<p>חֲמֵי מַה כְּתִיב וַיְהִי כְּהוֹצִיאָם אוֹתָם הַחוּצָה וַיֹּאמֶר וְגו'. תָּא חֲזֵי (סג א) בְּשַׁעֲתָא דְּדִינָא שָׁרֵי בְּעָלְמָא, הָא אִתְּמָר דְּלָא לִיבָּעֵי לְבַּר נָשׁ לְאִשְׁתַּכָּחָא בְּשׁוּקָא, בְּגִין דְּכֵיוָן דְּשָׁרְיָא דִינָא לָא אַשְׁגַּח בֵּין זַכָּאָה וְחַיָּיבָא, וְלָא בָעֵי (לאסתכלא) לְאִשְׁתַּכָּחָא תַּמָּן. וְהָא אִתְּמָר דִּבְגִין כָּךְ אִסְתִּים נֹחַ בַּתֵּיבָה וְלָא יִשְׁגַּח בְּעָלְמָא בְּשַׁעֲתָא דְּדִינָא יִתְעֲבִיד. וּכְתִיב (שמות י״ב:כ״ב) וְאַתֶּם לֹא תֵצְאוּ אִישׁ מִפֶּתַח בֵּיתוֹ עַד בֹּקֶר עַד דְּיִתְעֲבִיד דִּינָא. וּבְגִין כָּךְ וַיֹּאמֶר הִמָּלֵט עַל נַפְשְׁךָ אַל תַּבִּיט אַחֲרֶיךָ וְגו'.</p>\n<p>רַבִּי יִצְחָק וְרַבִּי יְהוּדָה הֲווּ אָזְלֵי בְּאָרְחָא. אָמַר רַבִּי יְהוּדָה לְרַבִּי יִצְחָק דִּינָא דְּעֲבִיד קוּדְשָׁא בְּרִיךְ הוּא בַּמַּבּוּל וְדִינָא דִּסְדוֹם, תַּרְוַויְיהוּ דִּינִין דְּגֵיהִנֹּם הֲווּ בְּגִין דְּחַיָּיבֵי גֵּיהִנֹּם אִתְדָּנוּ בְּמַיָא וּבְאֶשָׁא.</p>\n<p>אָמַר רַבִּי יִצְחָק סְדוֹם בְּדִינָא דְּגֵיהִנֹּם אִתְדָּן, דִּכְתִיב וַיְיָ הִמְטִיר עַל סְדוֹם וְעַל עֲמוֹרָה גָּפְרִית וָאֵשׁ מֵאֵת יְיָ מִן הַשָּׁמָיִם. דָּא מִסִּטְרָא דְּמַיָיא וְדָא (עיין סוף הספר סימן ב) מִסִּטְרָא דְאֶשָׁא. דָּא וְדָא הוּא דִּינָא דְּגֵיהִנֹּם, וְחַיָּיבִין דְּגֵיהִנֹּם בִּתְרֵין דִּינִין אִלֵּין אִתְדָנוּ.</p>\n<p>אָמַר לֵיהּ דִּינָא דְּחַיָּיבֵי דְּגֵיהִנֹּם תְּרֵיסַר יַרְחֵי, וְקוּדְשָׁא בְּרִיךְ הוּא סָלִיק לוֹן מִגֵּיהִנֹּם, וְתַמָּן מִתְלַבְּנִין וְיָתְבִין לְתַרְעָא דְּגֵיהִנֹּם, וְחָמָאן אִנּוּן חַיָּיבִין דְּעָאלִין וְדָנִין לוֹן תַּמָּן, וְאִנּוּן תָּבְעֵי רַחֲמֵי עֲלַיְיהוּ. וּלְבָתַר קוּדְשָׁא בְּרִיךְ הוּא חַיִּיס עֲלַיְיהוּ וְאָעִיל לוֹן לְדוּכְתָּא דְּאִצְטְרִיךְ לוֹן. מֵהַהוּא יוֹמָא וּלְהָלְאָה גּוּפָא אִשְׁתְּכַךְ בְּעַפְרָא וְנִשְׁמָתָא יַרְתָא <Nonei></i>אַתְרָהּ כִּדְחָזֵי לָהּ. (נח סט א).</p>\n<p>תָּא חֲזֵי דְּהָא אִתְּמָר דְּאֲפִילּוּ אִנּוּן בְּנֵי טוֹפָנָא לָא אִתְדָּנוּ אֶלָּא בְּאֶשָׁא וּמַיָּא. מַיָּיא קְרִירָן נַחֲתֵי מִלְּעֵילָא, וּמַיָּיא רְתִיחָן סָלְקֵי מִתַּתָּא כְּאֶשָׁא. וְאִתְדָּנוּ בִּתְרֵי דִינִין, בְּגִין דְּדִינָא דִּלְעֵילָא הָכִי הֲוָה, בְגִין כָּךְ בִּסְדוֹם גָּפְרִית וָאֵשׁ.</p>\n<p>אָמַר לֵיהּ אִי יְקוּמוּן לְיוֹם דִּינָא. אָמַר לֵיהּ הָא אִתְּמָר. אֲבָל אִלֵּין דִּסְדוֹם וַעֲמוֹרָה לָא יְקוּמוּן, וּקְרָא אוֹכַח דִּכְתִיב, (דברים כ״ט:כ״ב) גָּפְרִית וָמֶלַח שְׂרֵפָה כָל אַרְצָהּ לא תִזָּרַע וְלא תַצְמִיחַ וְגו'. אֲשֶׁר הָפַךְ יְיָ בְּאַפּוֹ וּבַחֲמָתוֹ. אֲשֶׁר הָפַךְ יְיָ, בְּעָלְמָא דֵּין. בְּאַפּוֹ, בְּעָלְמָא דְאָתֵי. וּבַחֲמָתוֹ, בְּזִמְנָא דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לַאֲחָיָיא מֵתַיָּיא. אָמַר לֵיהּ תָּא חֲזֵי, כַּמָּה דְּאַרְעָא דִּלְהוֹן אִתְאֲבִיד לְעָלַם וּלְעָלְמֵי עָלְמַיָא, הָכִי נָמֵי אִתְאֲבִידוּ אִנּוּן לְעָלַם וּלְעָלְמֵי עָלְמַיָא.</p>\n<p>וְתָּא חֲזֵי, דִּינָא דְּקוּדְשָׁא בְּרִיךְ הוּא דִּינָא לָקֳבֵל דִּינָא. אִנּוּן לָא הֲוָה תַּיְיבִין נַפְשָׁא דְּמִסְכֵּנָא בְּמֵיכְלָא וּבְמִשְׁתַּיָּא, אוּף הָכִי קוּדְשָׁא בְּרִיךְ הוּא לָא אָתִיב לוֹן נַפְשַׁיְיהוּ לְעָלְמָא דְּאָתֵי.</p>\n<p>וְתָּא חֲזֵי, אִנּוּן אִתְמְנָעוּ מִצְּדָקָה דְּאִקְרֵי חַיִּים, אוּף קוּדְשָׁא בְּרִיךְ הוּא מָנַע מִנַּיְיהוּ חַיִּים בְּעָלְמָא דֵין וּבְעָלְמָא דְּאָתֵי. וְכַמָּה דְּאִנּוּן מָנְעוּ אָרְחִין וּשְׁבִילִין מִבְּנֵי עָלְמָא, הָכִי נָמֵי קוּדְשָׁא בְּרִיךְ הוּא מָנַע מִנַּיְיהוּ אוֹרְחִין וּשְׁבִילִין דְּרַחֲמֵי לְרַחֲמָא עֲלַיְיהוּ בְּעָלְמָא דֵין וּבְעָלְמָא דְּאָתֵי.</p>\n<p>רַבִּי אַבָּא אָמַר כֻּלְהוּ בְּנֵי עָלְמָא יְקוּמוּן, וִיקוּמוּן לְדִינָא וְעֲלַיְיהוּ כְּתִיב, (דניאל י״ב:ב׳) וְאֵלֶּה לַחֲרָפוֹת וּלְדֵרָאוֹן עוֹלָם. וְקוּדְשָׁא בְּרִיךְ הוּא מָארִי דְּרַחֲמִין אִיהוּ, כֵּיוָן דְּדָן לְהוּ בְּהַאי עָלְמָא וְקַבִּילוּ דִּינָא, לָא אִתְדָּנוּ בְּכֻלְהוּ דִּינִין.</p>\n<p>אָמַר רַבִּי חִיָּיא כְּתִיב וַיְשַׁלַּח אֶת לוֹט מִתּוֹךְ הַהֲפֵכָה וְגו'. (קה א) מַהוּ בַּהֲפֹךְ אֶת הֶעָרִים אֲשֶׁר יָשַׁב בָּהֵן לוֹט. אֶלָא בְּכֻלְהוּ עֲבַד דִּיּוּרֵיהּ לוֹט, דִּכְתִיב וְלוֹט יָשַׁב בְּעָרֵי הַכִּכָּר וַיֶּאֱהַל עַד סְדוֹם. (וכתיב אשר ישב בהן לוט. אלא ודאי בכלהו עבד דיוריה) וְלָא קַבִּילוּ לֵיהּ, בַּר דְּמֶלֶךְ סְדוֹם קַבִּיל לֵיהּ <Nonei></i>בִּסְדוֹם בְּגִינֵיהּ דְּאַבְרָהָם:</p>\n<p><Nonei></i><Noneb>סִתְרֵי תּוֹרָה</b> תּוֹסֶפְּתָּא קְטוּרֵי רָמָּאי, הוּרְמְנֵי (עיין סוף הספר סי' ב) דִּבְדוּרֵי. (נ\"א דבורירי ונ\"א דבורייני) חַכִּימִין בְּסֻכְלְתָּנוּ, יִסְתַּכְּלוּן לְמִנְדַע, בְּשַׁעֲתָּא דְּרֵישָׁא חִוָּורָא אַתְּקִין כֻּרְסְיָיא עַל גַּבֵּי סָמְכִין דְּאַבְנִין דְּמַרְגְּלִיטָן טָבָן.</p>\n<p>בֵּין אִנּוּן אַבְנִין אִיתּ חַד מַרְגָּלִיטָא שַׁפִּירָא בְּחֵיזוּ יָאָה בְּרֵיוָא קוּמְטְרָא דְּקַנְטָרָא (נ\"א דקיטרא) דִּמְלַהֲטָא בְּע' גְּוָונִין, אִנּוּן ע' גְּוָונִין מְלַהֲטָן לְכָל סְטַר.</p>\n<p>אִלֵּין ע' מִתְּפָּרְשָׁאן מִגּוֹ ג' גְּוָונִין. אִלֵּין זִיקִין בְּזִיקִין דִּנְצִּיצִּין לְד' סִטְרֵי עָלְמָא, הָכָא אִיתָּא זִיקָא תַּקִּיפָּא דִּסְטַר שְׂמָאלָא דְּאִתְּאַחִיד בִּשְׁמַיָא. אִנּוּן גְּוָונִין שִׁבְעִין (דניאל ז׳:י׳) דִּינָא יָתִּיב וְסִפְּרִין פְּתִּיחוּ.</p>\n<p>מֵהָכָא נָפְּקֵי גִירִין וּסְיָיפִּין וְרוֹמְחִין וְאֶשָׁא דְּקוּסְטְרָא. וְאִתְּאַחִיד אֶשָׁא תַּקִּיפָּא דְּנָפְּקָא מִשָׁמַיִם בֵּיהּ, וְכַד אִתְּאַחַד אשא עִלָּאָה בְּאִלֵּין דִּלְתַּתָּא, לֵיתּ מַאן דְּיָכִיל לְאִתְּבַּר רוּגְזָא <Nonei></i>וְדִינָא.</p>\n<p>עַיְינִין לָהֲטִין כְּטִיסִין דְּנוּרָא, נָחִיתּ בְּהוּ לְעָלְמָא. וַוי מַאן דְּאִעָרַע בֵּיהּ, חֲגִיר חַרְצִּין (ס\"א חרבין), אִיהוּ חַרְבָּא שִׁנְּנָא בִּידֵיהּ, לָא חָיִיס עַל טַב וְעַל בִּישׁ. דְּהָא (ס\"א פסקא) פִּתְּקָא דְּאִנּוּן שִׁבְעִין בִּרְשׁוּ דְּאִתְּאַחִיד הַהוּא סִטְרָא דִשְׁמַיָא נָחִיתּ בִּידָא שְׂמָאלָא בְּכַמָּה דִּינִין,</p>\n<p>אִתְּהַפֵּךָ בְּכַמָּה גְּוָונִין, הֲפּוּךָ בְּכָל יוֹמָא, אִיהוּ אִקְרֵי כְּרֻם זְלֻּתּ דִּמְתַּקְּנָא לְגַבֵּי בְּנֵי אָדָם. כָּל גְּוָונִין דִּכְלֵי זַעֲמוֹ דְּקוּדְשָׁא בְּרִיךָ הוּא בֵּיהּ אִתְּחַזְּיָין. וְאִנּוּן יָתְּבִין בְּרוּמֵי דְּעָלְמָא, וּבְנֵי נָשָׁא בְּסִכְלוּתָּא דִלְהוֹן לָא מַשְׁגְּחֵי בְּהוֹן.</p>\n<p>גָּפְּרִיתּ וָאֵשׁ הִתּוּכָא דְּמַיָא וְאֶשָׁא דְּמִתְּהַתְּכֵי מִן שְׁמַיָא אִתְּאַחֲדוּ דָּא בְּדָא וּנְחַתּ עַל סְדוֹם. וַוי לְחַיָּיבַיָא דּלא מַשְׁגִּיחִין עַל יְקָרָא דְמָארֵיהוֹן:</p>\n<p>א. עֲשָׂרָה שְׁמָהָן גְּלִיפָּן בְּהוּרְמְנוּתָּא דְמַלְכָּא. (פירוש השם במלואו עשר אותיות יו\"ד ה\"א וי\"ו ה\"א). ב. עשר אִנּוּן וְסָלְקִין לְחוּשְׁבַּן סַגֵּי. (פי' יוד עולה כ', יוד הא עולה כ\"ו, יוד (נ\"ל הה וו) הא ויו עולה מ\"ב, י' יד' יד' ידוד' עולה ע\"ב). ג. שִׁבְעִין (הם ע\"ב ונקראים ד' מחנות שכינה והם למטה ממלכות). גַּוְונָן מְלַהֲטֵי לְכָל סְטַר. נַפְּקֵי מִגּוֹ שְׁמָהָן דְּאִגְלִיף רָזָא דְּע' שְׁמָהָן דְּמַלְאָכַיָיא. דְּאִנּוּן בְּרָזָא דִשְׁמַיָא.</p>\n<p>וְאִנּוּן מיכאל גּבריאל רפּאל נוריאל. קמ\"ץ \"קדומיאל \"מלכיאל \"צּדקיאל. פּתּ\"ח \"פּדאל \"תּומיאל \"חשדיאל. צּר\"י \"צּדקיאל \"רזיאל \"יופּיאל. סגו\"ל \"סטוטריה \"גזריאל \"ותּריאל נ\"א ורדיא\"ל \"למואל. חר\"ק \"רהטיאל \"חזקיאל \"קדשיאל. שׁב\"א \"שמעאל \"ברכיאל (נ\"א שכניאל ונ\"א ברקיא\"ל) \"אהיאל. חל\"ם חניא\"ל \"להדיאל \"מחניאל. (נ\"א ח\"ניאל ל\"עדיאל מ\"לכיאל). \"עניאל ענאל אהניאל רחמיאל עזריאל (נ\"א ש\"בנאל ר\"ומיאל ק\"דומיאל. שר\"ק. חכמיאל רמיאל קרשיאל. חר\"ק)</p>\n<p>סנניה ודרגזיה רסיסיאל דומיאל</p>\n<p>חוניאל \"זכריאל \"ואריאל \"ה\"ינאל ד\"נדאל ג\"דיאל ב\"דאל א\"נפּיאל ועדי\"אל, <Nonei></i>אדנ\"י עַל כֻּלְהוּ. ד (פירוש כשע\"ב מלאכים מתחברין במלכות אז נקרא מלכות הוא ובית דינו בלשון וה').</p>\n<p>כַּד מִתְּחַבְּרָן כֻּלְהוּ כְּחֲדָא בְּרָזָא חָדָא בְּחֵילָא עִלָּאָה, כְּדֵין אִקְרֵי וידוד כֹּלָּא בִּכְלָלָא חָדָא. מֵאֵתּ יְיָ מִן הַשָׁמַיִם, שְׁמָא קַדִּישָׁא דְּאִתְּגְּלַף בְּע' שְׁמָהָן אָחֳרָנִין רָזָא דְּשָׁמָיִם. ואִלֵּין אִנּוּן שִׁבְעִין דְּשָׁלְטִין עַל אִלֵּין ע' דִּינִין רָזָא דְּיהו\"ה, ואִלֵּין שִׁבְעִין שְׁמָהָן בִּקְדוּשָׁה יהו\"ה שָׁמָיִם. ה (פירוש שם של ע\"ב גשרים היוצא מפסוק ויסע ויבא ויט אלו הם נקראים שמים, ואותם ע\"ב מלאכים של מטה במלכו\"ת מקבלים מע\"ב של מעלה, ונוטלין מהן).</p>\n<p>אִלֵּין נָטְלִין מֵאִלֵּין וְידוד. ו (פירוש מלכות מתפארת). נָטִיל מֵאֵתּ ידוד דָּא מִן דָּא. ז (פירוש סוד של אותן ע\"ב שמות הוא שם ידוד, והוא הרוכב עליהן כנשמה לגוף). ואִלֵּין תַּלְיָין מֵאִלֵּין, תַּתָּאִין בְּעִלָּאִין, וְכלָּא קִשׁוּרָא חָדָא. וּבְהַאי קוּדְשָׁא בְּרִיךָ הוּא אִשְׁתְּמוֹדָע בִּיקָרֵיהּ. ח (פירוש ע\"ב מלאכים של מטה מתחבים בע\"ב שמות של מעלה הנקראים שמים). שָׁמַיִם דְּאִנּוּן ע' רָזָא ידוד, דָּא אִיהוּ בְּרָזָא דְּשִׁבְעִין וּתְּרֵין שְׁמָהָן ואִלֵּין אִנּוּן דְּנָפְּקֵי מִן וַיִּסַּע וַיָּבֹא וַיֵּט.</p>\n<p>וה\"ו יל\"י סי\"ט על\"ם מה\"ש לל\"ה אכ\"א כה\"תּ הז\"י אל\"ד לא\"ו הה\"ע. חֵלֶק רִאשׁוֹן בָּרוּךָ שֵׁם כְּבוֹד מַלְכוּתּוֹ לְעוֹלָם וָעֶד יז\"ל מב\"ה הר\"י הק\"ם לא\"ו כל\"י לו\"ו פּה\"ל נל\"ךָ יי\"י מל\"ה חה\"ו. חֵלֶק שֵׁנִי בָּרוּךָ שֵׁם כְּבוֹד מַלְכוּתּוֹ לְעוֹלָם וָעֶד נתּ\"ה הא\"א יר\"תּ שא\"ה רי\"י או\"ם לכ\"ב וש\"ר יה\"ו לה\"ח כו\"ק מנ\"ד. חֵלֶק שְׁלִישִׁי בָּרוּךָ שֵׁם כְּבוֹד מַלְכוּתּוֹ לְעוֹלָם וָעֶד אנ\"י חע\"ם רה\"ע יי\"ז הה\"ה מי\"ךָ וו\"ל יל\"ה סא\"ל ער\"י עש\"ל מי\"ה. חלק רְבִיעִי בָּרוּךָ שֵׁם כְּבוֹד מַלְכוּתּוֹ לְעוֹלָם וָעֶד וה\"ו דנ\"י הח\"ש עמ\"ם ננ\"א ני\"תּ מב\"ה פּו\"י נמ\"מ יי\"ל הר\"ח מצּ\"ר. חֵלֶק חֲמִישִׁי בָּרוּךָ שֵׁם כְּבוֹד מַלְכוּתּוֹ לְעוֹלָם וָעֶד ומ\"ב יה\"ה ענ\"ו מח\"י דמ\"ב מנ\"ק אי\"ע חב\"ו רא\"ה יב\"מ הי\"י מו\"ם, חֵלֶק שִׁשִׁי בָּרוּךָ שֵׁם כְּבוֹד מַלְכוּתּוֹ לְעוֹלָם ועֶד.</p>\n<p>וְאִלֵּין אִנּוּן שִׁבְעִין שְׁמָהָן דְּשָׁלְטִין עַל שִׁבְעִין דַּרְגִּין תַּתָּאִין רָזָא וידוד. אִלֵּין שִׁבְעִין שְׁמָהָן ידוד רָזָא דְאִקְּרֵי שָׁמָיִם. שִׁבְעָא רְקִיעִין אִנּוּן דְּסָלְקִין לְשִׁבְעִין שְׁמָהָן שְׁמָא קַדִּישָׁא, וְדָא אִיהוּ וַידוד הִמְטִיר. מֵאֵתּ ידוד מִן הַשָׁמָיִם.</p>\n<p>סִתְּרָא דְּסִתְּרִין לַחֲכִימִין אִתְּמָסַר. שְׁמָא <Nonei></i>דָּא דְּאִקְּרֵי שָׁמָיִם מִנֵּיהּ אִתְּבְּרֵי סִתְּרָא דְּאִקְּרֵי אָדָם. חָשְׁבָן שַׁיְיפֵּי גוּפָּא דְּאִנּוּן חוּשְׁבַּן מָאתָּן וְאַרְבְּעִין וּתְּמַנְיָא שַׁיְיפִּין.</p>\n<p>חָשְׁבָן אַתְּווֹהִי מָאתָּן וְשִׁיתּ סָרֵי, שְׁמָא דָא דְּאִיהוּ רָזָא וְסִתְּרָא כְּלָלָא דְּכָל אוֹרַיְיתָּא בְּכ\"ב אַתְּוָון וְעֶשֶׂר אֲמִירָן, בְּגִין דְּהָא שְׁמָא דָא מָאתָּן וְשִׁיתּ סָרֵי אַתְּוָון וּתְּלָתִּין וּתְּרֵין שְׁבִילִין דְּאִתְּכְּלִילָן בֵּיהּ, הָא מָאתָּן וְאַרְבָּעִין וּתְּמַנְיָא שַׁיְיפִּין דְּגוּפָּא</p>\n<p>רָזָא דְאִקְרֵי אָדָם דְּשַׁלִּיט על כֻּרְסְיָיא. רָזָא דְּשִׁבְעִין דִּלְתַּתָּא, וְסִתְּרָא דָא דִּכְתִּיב (יחזקאל א׳:כ״ו) וְעַל דְּמוּתּ הַכִּסֵּא דְּמוּתּ כְּמַרְאֵה אָדָם עָלָיו מִלְּמַעְלָה, וְדָא הוּא סִתְּרָא דִּכְתִּיב וַיְיָ הִמְטִיר עַל סְדוֹם וְגו' מֵאֵתּ יְיָ מִן הַשָׁמָיִם. וְכלָּא חַד וּמִלָּה חָדָא, וְסִתְּרָא חָדָא לַחֲכִימֵי לִבָּא אִתְּמָסַר, זַכָּאָה (ד\"א ל\"ג איהו) חוּלַקְהוֹן בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵּי.</p>\n<p>סְדוֹם גְּזַר דִּינָא דִּלְהוֹן על דְּמָנְעוּ צְּדָקָה מִנַּיְיהוּ, כְּמָא דְאַתְּ אָמֵר, (יחזקאל ט״ז:מ״ט) וְיַד עָנִי וְאֶבְיוֹן לא הֶחֱזִיקָה. וּבְגִין כָּךָ דִּינָא לָא הֲוָה אֶלָּא מִן שָׁמַיִם. צְּדָקָה וְשָׁמַיִם כּלָּא חַד וּכְתִּיב, (תהילים ק״ח:ה׳) כִּי גָדוֹל מֵעַל שָׁמַיִם חַסְדֶּךָ, וּבְגִין דְּתַּלְיָא צְּדָקָה בִּשְׁמֵיהּ (נ\"א בשמים) דִּינָא הוּא מִשָׁמַיִם דִּכְתִּיב מאתּ יְיָ מִן הַשָׁמָיִם.</p>\n<p>דִּינָא דְּיִשְׂרָאֵל מֵהַאי אֲתַּר דִּכְתִּיב, (איכה ד׳:ו׳) וַיִּגְדַּל עֲוֹן בַּתּ עַמִּי מֵחַטַאתּ סְדוֹם. וְאִקְרֵי יְרוּשָׁלֵם אֲחוֹתּ לִסְדוֹם כְּמָא דְאַתְּ אָמֵר, (יחזקאל ט״ז:מ״ט) הִנֵּה זְה הָיָה עֲוֹן סְדוֹם אֲחוֹתֵּךָ, וְדִינְהוֹן הֲוָה מִן שְׁמַיָא דִּינָא חָדָא כִּסְדוֹם עַל דְּמָנְעוּ צְּדָקָה מִנַּיְיהוּ. בַּר דְּדָא אִתְּהַפַּךָ וְדָא אִתְּחָרַב, דָּא אִיתּ לָהּ תְּקוּמָה, וְדָא לֵיתּ לָהּ תְּקוּמָה, (ע\"כ סתרי תורה).</p>"],[9520011234,"<p>וַתַּבֵּט אִשְׁתּוֹ מֵאַחֲרָיו, מֵאַחֲרֶיהָ מִבָּעֵי לֵיהּ, אֶלָּא מִבָּתַר שְׁכִינְתָּא. רַבִּי יוֹסֵי אָמַר מִבַּתְרִיהּ דְּלוֹט, דִּמְחַבְּלָא אָזִיל אֲבַתְרֵיהּ, וְכִי אֲבַתְרִיהּ אָזִיל, וְהָא הוּא שַׁדַּר לֵיהּ, אֶלָּא בְּכָל אֲתַר דְּהֲוָה אָזִיל לוֹט אִתְעַכַּב מְחַבְּלָא לְחַבָּלָא, וְכָל אֲתַר דְּאָזִיל כְּבָר וְשָׁבִיק לַאֲחוֹרֵיהּ הֲוָה מְהַפֵּךְ לֵיהּ מְחַבְּלָא.</p>\n<p>וּבְגִין כָּךְ אָמַר לֵיהּ אַל תַּבֵּט אַחֲרֶיךָ דְּהָא אֲנָא אֲחַבֵּל בַּתְרָךְ, וְעַל דָּא כְּתִיב וַתַּבֵּט אִשְׁתּוֹ מֵאַחֲרָיו וְחֲמַת מְחַבְּלָא. כְּדֵין וַתְּהִי נְצִיב מֶלַח. דְּהָא בְּכָל זִמְנָא דִּמְחַבְּלָא לָא חָמֵי אַנְפּוֹי דְּבַר נָשׁ (נ\"א אחמי אנפי לכר נש) לָא מְחַבִּיל לֵיהּ. כֵּיוָן דְּאִתְּתֵיהּ אֲהַדְּרַת אַנְפָּהָא לְאִסְתַּכָּלָא אֲבַתְרִיהּ מִיָּד וַתְּהִי נִצָּב מֶלַח.</p>"],[9520011235,"<p>רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי הֲווּ קָיְימֵי יוֹמָא חַד וְעָסְקֵי בְּהַאי קְרָא, אָמַר רַבִּי אֶלְעָזָר כְּתִיב, (דברים ח׳:ט׳) אֶרֶץ אֲשֶׁר לא בְמִסְכֵּנוּת תֹּאכַל בָּהּ לֶחֶם, לא תֶחְסַר כֹּל בָּהּ. הַאי בָּהּ בָּהּ תְּרִי זִמְנֵי אַמַּאי. אֶלָּא הָא אִתְּמָר דְּקוּדְשָׁא בְּרִיךְ הוּא פָּלִיג כָּל עַמִּין וְאַרְעָאן לִמְמַנָּן שְׁלִיחָן, וְאַרְעָא דְיִשְׂרָאֵל לָא שַׁלִּיט בָּהּ מַלְאָכָא וְלָא מְמַנָּא אָחֳרָא אֶלָּא אִיהוּ בִּלְחוֹדוֹי, בְּגִין כָּךְ אָעִיל לְעַמָּא דְּלָא שַׁלִּיט בְּהוּ אָחֳרָא לְאַרְעָא דְּלָא שָׁלִיט בָּהּ אָחֳרָא.</p>\n<p>תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא יָהִיב מְזוֹנָא תַּמָּן בְּקַדְמִיתָא וּלְבָתַר לְכָל עָלְמָא. כָּל שְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת בְּמִסְכֵּנוּת, וְאַרְעָא דְּיִשְׂרָאֵל לָאו הָכִי, אֶלָּא אֶרֶץ יִשְׂרָאֵל אִתְּזָן בְּקַדְמִיתָא וּלְבָתַר כָּל עָלְמָא.</p>\n<p>וּבְגִין כָּךְ אֶרֶץ אֲשֶׁר לא בְמִסְכֵּנוּת תֹּאכַל בָּהּ לֶחֶם. אֶלָּא בְּעֲתִירוּ בְּסִפּוּקָא דְּכֹלָּא תֹּאכַל בָּהּ וְלָא בְּאֲתַר אָחֳרָא. בָּהּ בִּקְדִּישׁוּ דְּאַרְעָא, בָּהּ שַׁרְיָא מְהֵימְנוּתָא עִלָּאָה. בָּהּ שַׁרְיָא בִּרְכְּתָא דִּלְעֵילָא, וְלָא בְּאֲתַר אָחֳרָא.</p>\n<p>תָּא חֲזֵי כְּתִיב כְּגַן יְיָ כְּאֶרֶץ מִצְרַיִם. עַד הָכָא לָא אִתְיְדַע גַּן יְיָ אִי הוּא אֶרֶץ מִצְרַיִם, וְאִי אִיהוּ אֶרֶץ סְדוֹם, (דף קט ע\"א) וְאִי אִיהוּ גַּן יְיָ דְּאִקְרֵי גַּן עֵדֶן. אֶלָּא כְּגַן יְיָ דְּאִית בֵּיהּ סִפּוּקָא וְעִדּוּנָא דְּכֹלָּא, הָכִי נָמֵי הֲוָה סְדוֹם וְהָכִי נָמֵי מִצְרַיִם. מַה גַּן יְיָ לָא אִצְטְרִיךְ בַּר נָשׁ לְאַשְׁקָאָה לֵיהּ, אוּף מִצְרַיִם לָא אִצְטְרִיךְ אָחֳרָא לְאַשְׁקָאָה לֵיהּ, בְּגִין דְּנִילוּס אִיהוּ אַסִּיק וְאַשְׁקֵי לְכָל אַרְעָא דְמִצְרַיִם.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב, (זכריה י״ד:י״ז) וְהָיָה אֲשֶׁר לא יַעֲלֶה מֵאֵת מִשְׁפְּחוֹת הָאָרֶץ אֶל יְרוּשָׁלֵם וְגו'. דָּא הוּא עוֹנָשָׁא דִלְהוֹן דְּאִתְמְנַע מִנְּהוֹן מִטְרָא, מַה כְּתִיב וְאִם מִשְׁפַּחַת מִצְרַיִם לא תַעֲלֶה וְלא בָאָה וְגו'. חָמֵי דְּלָא כְּתִיב וְלא עֲלֵיהֶם יִהְיֶה הַגֶּשֶׁם, בְּגִין דְּלָא נָחִית מִטְרָא לְמִצְרַיִם וְלָא אִצְטַרְכָן לֵיהּ, אֶלָּא עוֹנָשָׁא דִּלְהוֹן מַה הוּא דִּכְתִיב, (זכריה י״ד:י״ב) וְזֹאת תִּהְיֶה הַמַּגֵּפָה אֲשֶׁר יִגּוֹף יְיָ אֶת כָּל הַגּוֹיִם וְגו'. בְּגִין דְּמִצְרַיִם לָא צְרִיכִין לְמִטְרָא. אוּף סְדוֹם מַה כְּתִיב בֵּיהּ כִּי כֻלָּהּ מַשְׁקֶה, כָּל עִדּוּנִין דְּעָלְמָא הֲווּ בָהּ, וְעַל דָּא לָא בָעָאן דִּבְנֵי נָשָׁא אָחֳרָנִין יִתְעַדְּנוּן בָּהּ.</p>\n<p>רַבִּי חִיָּיא אָמַר אִנּוּן הֲווּ חַיָּיבִין מִגַּרְמַיְיהוּ וּמִמָּמוֹנְהוֹן, דְּכָל בַּר נָשׁ דְּאִיהוּ צָר עֵינָא לְגַבֵּי מִסְכֵּנָא, יָאוֹת הוּא דְּלָא יִתְקַיַּים בְּעָלְמָא. וְלא עוֹד אֶלָּא דְּלֵית לֵיהּ חַיִּים לְעָלְמָא דְּאָתֵי. וְכָל מַאן דְּאִיהוּ וַותְּרָן לְגַבֵּי מִסְכֵּנָא יָאוֹת הוּא דְּיִתְקַיַּים בְּעָלְמָא, וְיִתְקַיַּים עָלְמָא בְּגִינֵיהּ, וְאִית לֵיהּ חַיִּים וְאוֹרְכָּא דְחַיֵּי לְעָלְמָא דְּאָתֵי:</p>"],[9520011236,"<p>וַיַּעַל לוֹט מִצֹּעַר וַיֵּשֶׁב בָּהָר הוּא וּשְׁתֵּי בְנוֹתָיו עִמּוֹ וְגו'. מַאי טַעְמָא. בְּגִין דְּחָמָא דְּהֲוָה קָרִיב לִסְדוֹם וְאִסְתַּלַּק מִתַּמָּן.</p>\n<p>רַבִּי יִצְחָק פָּתַח (איוב ל״ז:י״ב) וְהוּא מְסִיבּוֹת מִתְהַפֵּךְ בְּתַחְבּוּלתָיו לְפָעֳלָם וְגו'. קוּדְשָׁא בְּרִיךְ הוּא מְסַבֵּב סִבּוּבִין דְּעָלְמָא וְאַיְיתֵי קוּמְרִין טְהִירִין לְמֶעְבַּד עוֹבָדוֹי, וּלְבָתַר מְהַפֵּךְ לוֹן וְעָבִיד לוֹן כְּגַוְונָא אָחֳרָא.</p>\n<p>וּבְמָּה, בְּתַחְבּוּלוֹתָיו, עָבִיד תַּחְבּוּלִין וּמְסַבֵּב סִבּוּבִין לַאֲפָכָא לוֹן וְלָאו כְּאִנּוּן קַדְמָאֵי. <Nonei></i>לְפָעֳלָם, בְּגִין פָּעֳלָם דִּבְנֵי נָשָׁא, כְּמָה דְאִנּוּן עָבְדִין עוֹבָדִין הָכִי מְהַפֵּךְ לוֹן. כֹּל אֲשֶׁר יְצַוֵּם עַל פְּנֵי תֵבֵל אָרְצָה. בְּגִין דְּעוֹבָדִין דִּבְנֵי נָשָׁא מְהַפֵּךְ לְאִנּוּן מְסִבּוֹת בְּכָל מַה דְּאִיהוּ פַּקִּיד לוֹן עַל פְּנִי תֵבֵל וְגו'.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר וְהוּא מְסִבּוֹת מִתְהַפֵּךְ. הַקָּדוֹשׁ בָּרוּךְ הוּא מְסַבֵּב סִבּוּבִין וְאַיְיתֵי עוֹבָדִין בְּעָלְמָא לְאִתְקָיְימָא, וּלְבָתַר דְּחֲשִׁיבוּ בְּנֵי נָשָׁא דְּיִתְקָיְימוּן אִנּוּן עוֹבָדִין, קוּדְשָׁא בְּרִיךְ הוּא מְהַפֵּךְ לוֹן לְאִנּוּן עוֹבָדִין מִכְּמָה דְּהֲווּ בְּקַדְמִיתָא.</p>\n<p>בְּתַחְבּוּלוֹתָיו. בְּתַחְבּוּלָתוֹ כְּתִיב כְּהַאי אוֹמָנָא דְּעָבִיד מָאנִין דְּחַרְסָא. בְּעוֹד דְּהַהִיא טִיקְלָא אִסְתַּחֲרַת קַמֵיהּ. חָשִׁיב לְמֶעְבַּד כְּגַוְונָא דָּא עָבִיד. חָשִׁיב לְמֶעְבַּד כְּגַוְונָא אָחֳרָא עָבִיד. מְהַפֵּךְ מָאנָא דָּא לְמָאנָא דָא, בְּגִין דְּהַהוּא טִיקְלָא אִסְתַּחֲרַת קַמֵּיהּ. כָּךְ קוּדְשָׁא בְּרִיךְ הוּא מְהַפֵּךְ עוֹבָדוֹי דְּאִיהוּ עָבִיד.</p>\n<p>בְּתַחְבּוּלֹתָו חָסֵר יו\"ד, וּמַאן אִיהוּ, דָּא בֵּי דִינָא לְתַתָּא דְּאִיהוּ טִקְלָא דְּאִסְתַּחֲרַת קַמֵּיהּ, וְעַל דָּא מְהַפֵּךְ מָאנִין מִמָּאנָא דָא לְמָאנָא אָחֳרָא.</p>\n<p>וְכָל דָּא כְּפִי פָּעֳלָם דִּבְנֵי נָשָׁא, אִי מְטִיבִין בְּנֵי נָשָׁא עוֹבָדֵיהוֹן, הַהוּא טִקְלָא דְּסַחֲרָא אַסְחָרַת לוֹן לְיָמִינָא, וּכְדֵין אִתְעֲבִידוּ עוֹבָדִין בְּעָלְמָא לְאוֹטָבָא לוֹן כְּדְקָא יְאוּת. וְטִיקְלָא אַסְחָרַת תָּדִיר וְלָא שָׁכִיךְ בְּהַהוּא סִטְרָא דְּיָמִינָא וְעָלְמָא מִתְגַּלְגְּלָא בֵּיהּ.</p>\n<p>אָתוּ בְּנֵי נָשָׁא לְאַבְאָשָׁא, <Nonei></i>תַּחְבּוּלָתוֹ דְּאַסְחַר תָּדִיר וְהֲוָה קָיְימָא בְּאַסְחָרוּתָא דְּיָמִינָא, קוּדְשָׁא בְּרִיךְ הוּא אַסְחַר לֵיהּ בְּסִטְרָא דִּשְׂמָאלָא וּמְהַפֵּךְ מְסִבּוֹת וּמָאנִין דְּהֲווּ בְּקַדְמִיתָא לְהַהוּא סְטַר שְׂמָאלָא.</p>\n<p>וּכְדֵין טִקְלָא אַסְחָרָא וְאִתְעֲבִידוּ עוֹבָדִין בְּעָלְמָא לְאַבְאָשָׁא לוֹן לִבְנֵי נָשָׁא. וְטִקְלָא אַסְחַר לְהַהוּא סִטְרָא עַד דִּבְנֵי נָשָׁא תָּיְיבִין לְאוֹטָבָא עוֹבָדֵיהוֹן. וְטִקְלָא קָיְימָא בְּעוֹבָדִין דִּבְנֵי נָשָׁא. וְעַל דָּא בְּתַחְבּוּלָתוֹ לְפָעֳלָם, וְלָא קָיְימָא תָּדִיר.</p>\n<p>תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא גָּרַם סִבּוּבִין וְעוֹבָדִין בְּעָלְמָא בְּגִין לְמֶעְבַּד כֹּלָּא כְּדְקָא יְאוּת. וְכֹלָּא נָפְקָא מֵעִקָּרָא וְשָׁרְשָׁא דִּלְעֵילָא. אַקְרִיב אַבְרָהָם לְגַבֵּיהּ, נָפַק מִנֵּיהּ יִשְׁמָעֵאל דְּלָא הֲוָה אַבְרָהָם גָּזִיר כַּד נָפַק מִנֵּיהּ, בְּגִין דְּאִיהוּ לְתַתָּא וְלָא אִשְׁתְּלִים בְּאָת קְיָימָא קַדִּישָׁא.</p>\n<p>לְבָתַר קוּדְשָׁא בְּרִיךְ הוּא סִבֵּב סִבּוּבִין בְּתַחְבּוּלוֹתָיו וְאִתְגְּזַר אַבְרָהָם וְעָאל בַּבְּרִית וְאִשְׁתְּלִים בִּשְׁמֵיהּ וְאִקְרֵי אַבְרָהָם, וְה' (צו א) עִלָּאָה אַעֲטָרַת לֵיהּ בְּרָזָא דְּמַיִם (לא א) מֵרוּחַ.</p>\n<p>כֵּיוָן דְּרָזָא (דברי הימים א) אִשְׁתְּלִים וְאִתְגְּזַר, נָפַק מִנֵּיהּ יִצְחָק וְהֲוָה זַרְעָא קַדִּישָׁא וְאִתְקַשַּׁר לְעֵילָא בְּרָזָא דְּאֵשׁ מִמַּיִם, וְעַל דָּא כְּתִיב, (ירמיהו ב׳:כ״א) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק כֻּלּה זֶרַע אֱמֶת. וְלָא אִתְקְשַׁר בְּהַהוּא סִטְרָא אָחֳרָא.</p>\n<p>תָּא חֲזֵי, לוֹט נָפְקוּ מִנֵּיהּ וּמִבְּנָתֵיהּ תְּרִין אוּמִין מִתְפָּרְשָׁן, וְאִתְקְשָׁרוּ בְּהַהוּא סִטְרָא דְּאִתְחֲזֵי לוֹן, וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא מְסַבֵּב <Nonei></i>סִבּוּבִין וּמְגַלְגֵּל גִּלְגּוּלִין בְּעָלְמָא דְּיִתְעֲבִיד כֹּלָּא כְּדְקָא יְאוּת וְיִתְקַשַּׁר כֹּלָּא בְּאַתְרֵיהּ.</p>\n<p>תָּא חֲזֵי, יָאוֹת הֲוָה לְלוֹט דְּקוּדְשָׁא בְּרִיךְ הוּא יָפִיק מִנֵּיהּ (ומבנתיה) וּמֵאִתְּתֵיהּ תְּרִין אוּמִין אִלֵּין, אֶלָּא בְּגִין לְאִתְקַשָּׁרָא בְּאַתְרַיְיהוּ דְּאִתְחֲזֵי לְהוּ. וְאִתְעֲבִידוּ מִגּוֹ יֵינָא, וְהַהוּא יֵינָא אִזְדַּמַּן לְהוֹן בַּמְּעַרְתָּא הַהִיא לֵילְיָא, וְדָא הוּא רָזָא דְּאִתְעֲבִידוּ כְּמָה דְּאַתְּ אָמֵר וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וְהָא אִתְּמָר וְאוּקְמוּהָ.</p>\n<p>תָּא חֲזֵי, מוֹאָב וְעַמּוֹן אִנּוּן קָרָאן לוֹן שְׁמָהָן, מוֹאָב מֵאָב. רַבִּי יוֹסֵי אָמַר בְּכִירָה בַּחֲצִיפוּ אָמְרָה מוֹאָב, מֵאַבָּא הוּא. וְהַצְּעִירָה גַּם הִיא יָלְדָה בֵּן וַתִּקְרָא שְׁמוֹ בֶּן עַמִּי. בִּצְנִיעוּ אָמְרָה בֶּן עַמִּי. בַּר עַמִּי, וְלָא אָמְרָה מִמָּאן הֲוָה.</p>\n<p>תָּא חֲזֵי, בְּקַדְמִיתָא כְּתִיב וְלָא יָדַע בְּשִׁכְבָהּ וּבְקוּמָהּ בְּוא\"ו וְנָקוּד עַל וא\"ו, בְּגִין דְּסִיּוּעָא דְּעֵילָא הֲוָה אִשְׁתְּכַח בְּהַהוּא עוֹבָדָא דְּזַמִּין מַלְכָּא מְשִׁיחָא לְנָפְקָא מִנֵּיהּ, וּבְגִין כָּךְ אִשְׁתְּלִים הָכָא בְּוא\"ו. וּבְאָחֳרָא כְּתִיב וּבְקֻמָּהּ חָסֵר וי\"ו, בְּגִין דְּלָא נָפַק מִינָּהּ חוּלְקָא לְקוּדְשָׁא בְּרִיךְ הוּא כְּהַאי אָחֳרָא, וְעַל דָּא כְּתִיב בְּהַאי אָחֳרָא קְשִׁישָׁא וּבְקוּמָהּ בְּוא\"ו מָלֵא וְנָקוּד עֲלָהּ.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, לָא יְדַע דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאוֹקְמָא מִינָהּ דָּוִד מַלְכָּא וּשְׁלֹמֹה וְכָל שְׁאָר מַלְכִין וּמַלְכָּא מְשִׁיחָא. תּוּ וּבְקוּמָהּ, דִּכְתִיב בְּרוּת (רות ג׳:י״ד) וַתָּקָם בְּטֶרְם יַכִּיר אִישׁ אֶת רֵעֵהוּ וְגו'. וּבְהַהוּא יוֹמָא הֲוָה לָהּ קִימָה וַדַּאי <Nonei></i>אִתְחַבַּר עִמָּהּ בֹּעַז לְהָקִים שֵׁם הַמֵּת עַל נַחֲלָתוֹ, וְאִתָּקַם מִנָּהּ כָּל הַנֵּי מַלְכִין וְכָל עִלּוּיָא דְיִשְׂרָאֵל. וְלא יָדַע בְּשִׁכְבָהּ דִּכְתִיב וַתִּשְׁכַּב מַרְגְּלוֹתָיו עַד הַבֹּקֶר. וּבְקוּמָהּ דִּכְתִיב וַתָּקָם בְּטֶרֶם יַכִּיר אִישׁ אֶת רֵעֵהוּ וְגו'. בְּגִין כָּךְ וּבְקוּמָהּ נְקוּד וא\"ו.</p>\n<p>תָּא חֲזֵי, (קה ע\"א) עִנְוְתָנוּתָא דְאַבְרָהָם דְּהָא אֲפִילּוּ בְּקַדְמִיתָא כַּד בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד דִּינָא בִּסְדוֹם לָא בָעָא מִנֵּיהּ רַחֲמֵי עַל לוֹט (דהא), לְבָתַר דִּכְתִיב וַיַּרְא וְהִנֵּה עָלָה קִיטֹר הָאָרֶץ כְּקִיטֹר הַכִּבְשָׁן לָא תָבַע עֲלֵיהּ דְּלוֹט וְלָא אָמַר עֲלֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא כְּלוּם, אוּף הָכִי קוּדְשָׁא בְּרִיךְ הוּא לָא אָמַר לֵיהּ מִידִי, בְּגִין דְּלָא יַחֲשֹׂב אַבְרָהָם דְּקוּדְשָׁא בְּרִיךְ הוּא גָּרַע מִזְכוּתֵיהּ כְּלוּם.</p>\n<p>וְאִי תֵימָא דְּאַבְרָהָם לָא הֲוָה חָשִׁיב לֵיהּ לְלוֹט בְּלִבֵּיהּ כְּלוּם, הָא מָסַר נַפְשֵׁיהּ לְמֵיהַךְ לְאַגָּחָא קְרָבָא בַּחֲמִשָּׁה מְלָכִין תַּקִּיפִין, כְּמָא דְאַתְּ אָמֵר, (בראשית י״ד:י״ד) וַיִּשְׁמַע אַבְרָם כִּי נִשְׁבָּה אָחִיו וְגו'. וּכְתִיב וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה. וּכְתִיב וַיָּשֶׁב אֵת כָּל הָרְכֻשׁ וְגַם אֶת לוֹט אָחִיו וּרְכֻשׁוֹ הֵשִׁיב וְגו'. אֲבָל בִּרְחִימוּתָא דִּרְחִים לְקוּדְשָׁא בְּרִיךְ הוּא וְחָמָא עוֹבָדוֹי דְלוֹט דְּלָא כַשְׁרָן כְּדְקָא יְאוּת, לָא בָעָא אַבְרָהָם דִּבְגִינֵיהּ יִשְׁבּוֹק קוּדְשָׁא בְּרִיךְ הוּא כְּלוּם מִדִּילֵיהּ, וּבְגִינֵי כָךְ לָא תָבַע עֲלֵיהּ רַחֲמֵי לָא בְּקַדְמִיתָא וְלָא בְסוֹפָא:</p>\n<p><Nonei></i><Noneb>מִדְרָשׁ הַנֶּעֱלָם</b> וַיַּעַל לוֹט מִצּוֹעַר וְגו'. אָמַר רַבִּי אַבָּהוּ, בֹּא וּרְאֵה מַה כְּתִיב בַּיֵּצֶּר הָרָע, תֵּדַע לְךָ שֶׁאֵינוֹ מִתְבַּטֵל לְעוֹלָם מִבְּנֵי אָדָם עַד אוֹתוֹ זְמַן דִּכְתִיב, (יחזקאל ל״ו:כ״ו) וַהֲסִרֹתִי אֶת לֵב הָאֶבֶן וגו'. שֶׁאַף עַל פִּי שֶׁרוֹאֶה בְּנֵי אָדָם נִדּוֹנִין בַּגֵּיהִנָּם, הוּא בָּא וְחוֹזֵר לוֹ אֵצֶּל בְּנֵי אָדָם, הֲדָא הוּא דִכְתִיב וַיַּעַל לוֹט מִצּוֹעַר. מִצַּעֲרָהּ שֶׁל גֵּיהִנֹּם מִשָּׁם עוֹלֶה לְפַתּוֹת בְּנֵי אָדָם.</p>\n<p>אָמַר רַבִּי יְהוּדָה שָׁלשׁ הַנְהָגוֹת יִשׁ בָּאָדָם, הַנְהָגַת הַשֵּׂכֶל וְהַחָכְמָה וזוֹ הִיא <Nonei></i>כֹּחַ הַנְּשָׁמָה הַקְּדוֹשָׁה. וְהַנְהָגַת הַתַּאֲוָה שֶׁהִיא מִתְאַוָּה בְּכָל תַּאֲוֹת רָעוֹת, וזֶהוּ כֹּחַ הַתַּאֲוָה. וְהַהַנְהָגָה הַמַנְהֶגֶת לִבְנֵי אָדָם וּמְחַזֶּקֶת הַגּוּף וְהִיא נִקְרֵאת נֶפֶשׁ הַגּוּף, אָמַר רַב דִּימִי זֶהוּ כֹּחַ הַמַּחֲזִיק.</p>\n<p>אָמַר רַבִּי יְהוּדָה בֹּא וּרְאֵה לְעוֹלָם אֵין יֵצֶּר הָרָע שׁוֹלֵט אֶלָּא בְּאֵלּוּ ב' כֹּחוֹת אִלֵּין דְּאֲמָרָן, נֶפֶשׁ הַמִּתְאַוָּה הִיא הָרוֹדֶפֶת אַחַר יִצֶּר הָרָע לְעוֹלָם, מַשְׁמַע דִּכְתִיב וַתֹּאמֶר הַבְּכִירָה אֶל הַצְּעִירָה אָבִינוּ זָקֵן. נֶפֶשׁ הַמִּתְאַוָּה הִיא מְעוֹרֶרֶת אֶת הָאַחֶרֶת וּמְפַתָּה אוֹתָהּ עִם הַגּוּף לְהִדָּבֵק בַּיֵּצֶּר הָרָע, והִיא אוֹמֶרֶת לְכָה נַשְׁקֶה אֶת אָבִינוּ יַיִן וְנִשְׁכְּבָה עִמּוֹ. מַה יִּשׁ לָנוּ בָּעוֹלָם הַבָּא, נֵלֵךְ וְנִרְדֹּף אַחַר יִצֶּר הָרָע וְאַחַר תְּשׁוּקַת חֶמְדַת הָעוֹלָם הַזֶּה. וּמַה עוֹשׂוֹת, שְׁתֵּיהֶן מַסְכִּימוֹת לְהִדָּבֵק בּוֹ, מַה כְּתִיב וַתַּשְׁקֶיןָ אֶת אֲבִיהֶן יַיִן מִתְפַּטְמוֹת לְהִתְעוֹרֵר לְיִּצֶּר הָרָע בַּאֲכִילָה וּבִשְׁתִיָּה.</p>\n<p>וַתָּקָם הַבְּכִירָה וַתִּשְׁכַּב אֶת אָבִיהָ. כְּשֶׁאָדָם שׁוֹכֵב עַל מִטָתוֹ בַּלַּיְלָה, נֶפֶשׁ הַמִתְאַוָּה הִיא הַמְעוֹרֶרֶת לַיִּצֶּר הָרָע, וּמְהַרְהֶרֶת בּוֹ, והוּא דָּבֵק בְּכָל הִרְהוּר רָע עַד שֶׁמִּתְעַבֶּרֶת מְעַט (ס\"א ממנו) (ד\"א ל\"ג על) (נ\"א עד) שֶׁמֵּבִיא בְּלֵב הָאָדָם אוֹתָהּ הַמַּחֲשָׁבָה הָרָעָה וּדְבֵקָה בּוֹ, וַעֲדַיִן יִשׁ בְּלִבּוֹ וְלֹא נִגְמַר לַעֲשׂוֹתָהּ עַד שֶׁזֹּאת הַתַּאֲוָה מְעוֹרֶרֶת לְכֹחַ הַגּוּף כְּמִתְּחִלָּה לְהִדָּבֵק בַּיֵּצֶּר הָרָע ואָז הוּא תַּשְׁלוּם הָרָעָה, הֲדָא הוּא דִכְתִיב וַתַּהֲרֶיןָ שְׁתֵּי בְּנוֹת לוֹט <Nonei></i>מֵאֲבִיהֶן.</p>\n<p>אָמַר רַבִּי יִצְּחָק מֵעוֹלָם אֵין יִצֶּר הָרָע מִתְפַּתֶּה אֶלָּא בַּאֲכִילָה וּשְׁתִיָּה, וּמִתּוֹךְ שִׂמְחַת הַיַּיִן אָז שׁוֹלֵט בָּאָדָם. בַּצַּדִּיק מַה כְּתִיב בֵּיהּ (משלי י״ג:כ״ה) צַּדִּיק אֹכֵל לְשׂבַע נַפְשׁוֹ. ואֵינוֹ מִשְׁתַּכֵּר לְעוֹלָם, דְאָמַר רַבִּי יְהוּדָה הַאי צּוּרְבָא מֵרַבָּנָן דְמַרְוִי, קָרֵינָא עֲלֵיהּ (משלי י״א:כ״ב) נֶזְם זָהָב בְּאַף חֲזִיר. וְלֹא עוֹד אֶלָּא שֶׁמְחַלֵּל שֵׁם שָׁמַיִם. מִנְהַג הָרְשָׁעִים מַהוּ (ישעיהו כ״ב:י״ג) הִנֵּה שָׂשׂוֹן וְשִׂמְחָה. הַיַּיִן אָז שׁוֹלֵט בָּאָדָם, הָרוֹג בָּקָר וְשָׁחוֹט צֹּאן וְגו'. עֲלֵיהֶם אָמַר הַכָּתוּב (משלי ה) הוֹי מַשְׁכִּימֵי בַבֹּקֶר שֵׁכָר יִרְדֹּפוּ וְגו'. כְּדֵי לְעוֹרֵר לַיִּצֶּר הָרָע, שֶׁאֵין יִצֶּר הָרָע מִתְעוֹרֵר אֶלָּא מִתּוֹךְ הַיַּיִן, הֲדָא הוּא דִּכְתִיב וַתַּשְׁקֶיןָ אֶת אֲבִיהֶן יַיִן.</p>\n<p>אָמַר רַבִּי אַבָּהוּ מַה כְּתִיב וְלֹא יָדַע בְּשִׁכְבָהּ וּבְקוּמָהּ. כְּלוֹמַר יֵצֶּר הָרָע אֵינוֹ מַשְׁגִּיחַ בָּהּ בְּשִׁכְבָהּ בָּעוֹלָם הַזֶּה וּבְקוּמָהּ לָעוֹלָם הַבָּא, אֶלָּא מִתְעוֹרֵר עִם כֹּחַ הַגּוּף לַעֲבֹד תַּאֲוָתוֹ בָּעוֹלָם הַזֶּה. דְּאָמַר רַבִּי אַבָּהוּ בְּשָׁעָה שֶׁנִּכְנָסִין הָרְשָׁעִים בַּגֵּיהִנָּם מַכְנִיסִים לַיֵּצֶּר הָרָע לִרְאוֹת בָּהֶן, הֲדָא הוּא דִכְתִיב וְלוֹט בָּא צֹּעֲרָה לְצַּעֲרָהּ שֶׁל גֵּיהִנֹּם, וְנָפַק לֵיהּ מִתַּמָּן לִבְרִיָּיתָא לְנַסּוּתָא כִּדְקָאֲמָרָן. הֲדָא הוּא דִכְתִיב וַיַּעַל לוֹט מִצּוֹעַר מִצַּעֲרָהּ שֶׁל גֵּיהִנֹּם.</p>\n<p>וַיִּשֶׁב בָּהָר, אָמַר רַבִּי יִצְּחָק מַשְׁמַע דִּכְתִיב בָּהָר מְלַמֵּד שֶׁהוּא שָׁם מוֹשָׁבוֹ בְּמָקוֹם הָר. גּוּף שֶׁהוּא חָרֵב כָּהָר דְּלֵית בֵּיהּ טִיבוּתָא. וּשְׁתֵּי בְּנוֹתָיו עִמּוֹ. אֵלּוּ הַב' כֹּחוֹת דְּאֲמָרָן. כִּי <Nonei></i>יָרֵא לָשֶׁבֶת בְּצּוֹעַר, יִרְאָה וַחֲרָדָה נוֹפֶלֶת עָלָיו בְּשָׁעָה שֶׁרוֹאֶה צַּעַר גֵּיהִנֹּם שֶׁמְצַּעֲרִין לָרְשָׁעִים וְחוֹשֵׁב שֶׁשָּׁם יִדּוֹן, כֵּיוָן שֶׁרוֹאֶה שֶׁאֵינוֹ נִדּוֹן שָׁם יוֹצֵּא וְהוֹלֵךְ לְפַתּוֹת בְּנֵי אָדָם אַחֲרָיו.</p>\n<p>רַב הוּנָא כַּד הֲוָה דָּרִישׁ לְאִזְדַּהֲרָא לִבְנֵי אָדָם, הֲוָה אָמַר לְהוּ בָּנַי אִסְתַּמָּרוּ מִשְׁלִיחָא שֶׁל גֵּיהִנֹּם, וּמַאן הוּא זֶהוּ יֵצֶּר הָרָע שֶׁהוּא שָׁלִיחַ שֶׁל גֵּיהִנֹּם.</p>\n<p>רַבִּי אַבָּא אָמַר מַאי דִכְתִיב, (משלי ל׳:ט״ו) לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב. אֵלּוּ שְׁתֵּי בְּנוֹת לוֹט דְּאֲמָרָן, שֶׁהִיא נֶפֶשׁ הַמִּתְאַוּה, וְנֶפֶשׁ הַמִּשְׁתַּתֶּפֶת בַּגּוּף הָרוֹדֶפֶת אַחַר יִצֶּר הָרָע לְעוֹלָם. אָמַר רַבִּי יְהוֹשֻׁעַ כְּתִיב הָכָא בְּלוֹט כִּי יָרֵא לָשֶׁבֶת בְּצּוֹעַר, וּכְתִיב הָתָם לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב. יָרֵ\"א בְּגִימַטְרִיָּא הוּא עֲלוּקָ\"ה. אָמַר רַבִּי יִצְּחָק אִי יָרֵא הוּא לְמַאי אָתֵי לְמִטְעֵי בְּרִיָּיתָא, אֶלָּא כָּךְ דֶּרֶךְ כָּל עוֹשֵׂה עַוְלָה, כְּשֶׁרוֹאֶה הָרָע מִתְיָרֵא לְפִי שָׁעָה, מִיָּד חוֹזֵר לְרִשְׁעָתוֹ ואֵינוֹ חוֹשֵׁשׁ לִכְלוּם, כָּךְ יֵצֶּר הָרָע בְּשָׁעָה שֶׁרוֹאֶה דִּין בָּרְשָׁעִים יָרֵא, כֵּיוָן שֶׁיּוֹצֵּא לַחוּץ (לעשות) אֵינוֹ חוֹשֵׁשׁ כְּלוּם.</p>\n<p>רַבִּי אַבָּא אָמַר מַּהוּ דְּאֲמָּרוּ וַתֹּאמֶר הַבְּכִירָה אֶל הַצְּעִירָה אָבִינוּ זָקֵן. מַאי אָבִינוּ זָקֵן. זֶהוּ יֵצֶּר הָרָע שֶׁנִּקְרָא זָקֵן שֶׁנֶּאֱמַר (קהלת ד׳:י״ג) מֶלֶךְ זָקֵן וּכְסִיל. שֶׁהוּא זָקֵן שֶׁנּוֹלַד עִם הָאָדָם, דְּתָנִינָן אָמַר רַבִּי יְהוּדָה אָמַר רַבִּי יוֹסֵי אוֹתָהּ נֶפֶשׁ הַמִּתְאַוָּה אוֹמֶרֶת לָאַחֶרֶת אָבִינוּ זָקֵן נִרְדֹּף אַחֲרָיו וְנִדְבַּק <Nonei></i>בּוֹ כִּשְׁאָר כָּל הָרְשָׁעִים שֶׁבָּעוֹלָם. ואִישׁ אֵין בָּאָרֶץ לָבֹא עָלֵינוּ, אֵין אִישׁ צַּדִּיק בָּאָרְץ, וְאֵין אִישׁ שַׁלִּיט עַל יִצְּרוֹ, הַרְבֵּה רְשָׁעִים בָּאָרֶץ, לֵית אֲנַן בִּלְחוֹדָנָא חַיָּיבִין, נַעֲשֶׂה כְּדֶרֶךְ כָּל הָאָרֶץ שֶׁהֵם חַיָּיבִים, שֶׁעַד הַיּוֹם דֶּרֶךְ כָּל הָאָרֶץ הוּא. לְכָה נַשְׁקֶה אֶת אָבִינוּ יַיִן, נִשְׂמַח בָּעוֹלָם הַזְּה, נֹאכַל ונִשְׁתֶּה וְנִרְוְה חַמְרָא וְנִדְבַּק בְּאָבִינוּ בַּיִצֶּר הָרָע ונִשְׁכְּבָה עִמּוֹ. וְרוּחַ הַקֹּדֶשׁ צּווַֹחַת וְאוֹמֶרֶת (ישעיהו כ״ח:ז׳) גַּם אֵלֶּה בַּיַּיִן שָׁגוּ וּבַשֵּׁכָר תָּעוּ.</p>\n<p>אָמַר רַבִּי יְהוּדָה תָּא חֲזֵי, מַה כְּתִיב ותַּשְׁקֶיןָ אֶת אֲבִיהֶן יַיִן. דֶּרֶךְ הָרְשָׁעִים לִטְעוֹת אַחֲרֵי הַיַּיִן לְפַנֵּק לַיֵצֶּר הָרָע וּלְעוֹרְרוֹ, ועַד שֶׁהוּא שָׂמֵחַ בְּשִׁכְרוּתוֹ שׁוֹכֵב עַל מִטָתוֹ, מִיָּד וַתָּקָם הַבְּכִירָה וַתִּשְׁכַּב אֶת אָבִיהָ. הִיא מְזְמֶּנֶת עִמּוֹ וּמִתְאַוָּה וּמְהַרְהֶרֶת בְּכָל הִרְהוּרִים רָעִים, ויֵצֶּר הָרָע מִתְחַבֵּר עִמָּהּ וְנִדְבַּק בָּהּ ואֵינוֹ מַשְׁגִּיחַ בָּהּ (ס\"א מההוא זמנא) מַה הוּא מִמֶּנָּהּ. בְּשִׁכְבָהּ וּבְקוּמָהּ. בְּשִׁכְבָהּ בָּעוֹלָם הַזְּה וּבְקוּמָהּ לֶעָתִיד לָבֹא. בְּשִׁכְבָהּ בָּעוֹלָם הַבָּא כְּשֶׁתִּתֵּן דִּין וחֶשְׁבּוֹן. וּבְקוּמָהּ לְיוֹם הַדִּין דִּכְתִיב, (דניאל י״ב:ב׳) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצּוּ וְגו'. בְּשׁוּם עִנְיָן מֵאֵלּוּ אֵין מַשְׁגִּיחַ בָּהּ יִצֶּר הָרָע, אֶלָּא דָּבֵק בָּהּ והִיא נִדְבֶּקֶת בּוֹ, וּלְאַחַר כֵּן מְעוֹרֶרֶת לְאָחֳרָא לְאַחַר שֶׁהַהִרְהוּר גָּדוֹל נִדְבַּק בַּיִּצֶּר הָרָע, בָּאָה הָאַחֶרֶת וְנִדְבֶּקֶת בּוֹ</p>\n<p>וַתַּשְׁקֶיןָ אֶת <Nonei></i>אֲבִיהֶן יָיִן. כְּמוֹ כֵן לְעוֹרֵר לַיִּצֶּר הָרָע וְנִדְבֶּקֶת בּוֹ ואֲזַי תַּשְׁלוּם הָרָעוֹת לַעֲשׂוֹת וּמִתְעַבְּרוֹת שְׁתֵּיהֶן מִיִּצֶּר הָרָע, הֲדָא הוּא דִכְתִיב וַתַּהֲרֶין שְׁתֵּי בְנוֹת לוֹט מֵאֲבֵיהֶן. עַד שֶׁיָּצָּא לַפֹּעַל מַעֲשֵׂיהֶן זוֹ יוֹלֶדֶת רִשְׁעָתָהּ וזוֹ יוֹלֶדֶת רִשְׁעָתָהּ, וְכֵן דַּרְכָּם שֶׁל רְשָׁעִים בְּעִנְיַן זְה עִם יִצֶּר הָרָע, עַד שֶׁהוֹרֵג לָאָדָם וּמוֹלִיכוֹ לַגֵּיהִנֹּם וּמַכְנִיסוֹ שָׁם, וְאַחַר כָּךְ עוֹלֶה מִשָּׁם לְפַתּוֹת לִבְנֵי אָדָם כְּמוֹ כֵן. וּמִי שֶׁמַּכִּיר בּוֹ נִצֹּל מִמֶּנּוּ וְאֵינוֹ מִתְחַבֵּר עִמּוֹ.</p>\n<p>אָמַר רַבִּי יִצְּחָק מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לְכַתְּ לִסְטִים שֶׁהָיוּ אוֹרְבִים בַּדְּרָכִים לִגְזֹל וְלַהֲרֹג לִבְנֵי אָדָם, וּמַפְרִישִׁים מֵהֶם אֶחָד שֶׁיּוֹדֵעַ לְהָסִית לִבְנֵי אָדָם וּלְשׁוֹנוֹ רַךְ, מֶה עָבִיד מַקְדִּים וְהוֹלֵךְ לְקַבְּלָם וְנַעֲשָׂה כְּעֶבֶד לִפְנֵיהֶם עַד שֶׁמַּאֲמִינִים הַטִפְּשִׁים בּוֹ וּבוֹטְחִים בְּאַהֲבָתוֹ וּבְשִׂיחָתוֹ וּשְׂמֵחִים עִמּוֹ, וּמוֹלִיכָם בְּחֵלֶק דְּבָרָיו בְּאוֹתוֹ הַדֶּרֶךְ שֶׁהַלִּסְטִים שָׁם, כֵּיוָן שֶׁמַּגִּיעַ עִמָּהֶם לְשָׁם, הוּא הָרִאשׁוֹן שֶׁהוֹרֵג בָּם, לְאַחַר שֶׁנּוֹתְנָם בְּיַד הַלִּסְטִים לְהָרְגָּם וְלָקַחַת מָמוֹנָם, וְאִנּוּן צָּוְוחִין וְאָמְרִין וַוי דַּאֲצִּיתְנָא לְדֵין וְלִרְכִּיכָא דְּלִישְׁנֵיהּ. לְאַחַר שֶׁהָרְגוּ אֵלֶּה, עוֹלֶה מִשָּׁם וְיוֹצֵּא לְפַתּוֹת לִבְנֵי אָדָם כְּמִתְּחִלָּה. הַפִּקְחִים מָה הֵם עוֹשִׂים כְּשֶׁרוֹאִים לָזֶה יוֹצֵּא לִקְרָאתָם וּמְפַתֶּה לָהֶם, מַכִּירִין בּוֹ שֶׁהוּא צּוֹדֶה אֶת נַפְשָׁם וְהוֹרְגִּים אוֹתוֹ וְהוֹלְכִים בְּדֶרֶךְ אַחֶרֶת. כָּךְ הוּא יִצֶּר הָרָע יוֹצֵּא מִכַּתְ הַלִּסְטִים עוֹלֶה מִגֵּיהִנֹּם לְקָבְלָא דִּבְנֵי נָשָׁא וּלְפַתּוֹת לָהֶם בְּחֵלֶק מֶתֶק דְּבָרָיו, הֲדָא הוּא דִכְתִיב וַיַּעַל לוֹט מִצּוֹעַר וַיִּשֶׁב בָּהָר וגו'. כְּמוֹ לִסְטִים לֶאֱרֹב לִבְנֵי אָדָם, מַה עוֹשֶׂה עוֹבֵר לִפְנֵיהֶם, וְהַטִפְּשִׁים מַאֲמֲינִים בּוֹ וּבְאַהֲבָתוֹ שֶׁהוּא הוֹלֵךְ לְפַתּוֹתָם וְעוֹבֵד לָהֶם כְּעֶבֶד, שֶׁנּוֹתֵן לָהֶם נָשִׁים יָפוֹת אֲסוּרוֹת, נוֹתֵן לָהֶם בְּנֵי אָדָם לְהָרַע, מְפָרֵק מֵהֶם עֹל תּוֹרָה וְעֹל מַלְכוּת שָׁמַיִם. הַטִפְּשִׁים <Nonei></i>רוֹאִים כָּךְ, בּוֹטְחִים בְּאַהֲבָתוֹ, עַד שֶׁהוֹלֵךְ עִמָּהֶם וּמוֹלִיכָם בְּאוֹתוֹ דֶּרֶךְ שֶׁהַלִּסְטִים שָׁם, בְּדֶרֶךְ גֵּיהִנֹּם אֲשֶׁר אֵין דֶּרֶךְ לִנְטוֹת יָמִין וּשְׂמֹאל, כֵּיוָן שֶׁמַּגִּיעַ עִמָּהֶם לְשָׁם, הוּא הָרִאשׁוֹן שֶׁהוֹרֵג לָהֶם, וְנַעֲשָׂה לָהֶם מַלְאַךְ הַמָּוְת וּמַכְנִיסָן לַגֵּיהִנֹּם, וּמוֹרִידִין לְהוֹן מַלְאֲכֵי חַבָּלָה, וְאִנּוּן צָּוְוחִין וְאָמְרִין וַוי דַּאֲצִּיתְנָא לְדֵין, וְלָא מְהַנְיָא לוֹן. לְאַחַר כֵּן עוֹלֶה מִשָּׁם וְיוֹצֵּא לְפַתּוֹת לִבְנֵי אָדָם. הַפִּקְחִין כְּשֶׁרוֹאִין אוֹתוֹ מַכִּירִים אוֹתוֹ וּמִתְגַּבְּרִים עָלָיו עַד שֶׁשּׁוֹלְטִין עָלָיו, וסָאטִין מִזֶּה הַדֶּרֶךְ וְלוֹקְחִין דֶּרֶךְ אַחֶרֶת לְהִנָּצֵּל מִמֶּנּוּ.</p>\n<p>רַב יוֹסֵף כַּד הֲוָה נָחִית לְבָבֶל חָמָא אִנּוּן רַוָּוקַיָא דְּהֲווּ עַיְילֵי וְנָפְקֵי בֵּינִי נַשֵּׁי שַׁפִּירִין ולָא חָטָאן, אָמַר לוֹן לָא מִסְתָּפוּ אִלֵּין מִיִצֶּר הָרָע, אָמְרוּ לֵיהּ לָא מִקּוֹנְדִיטוֹן בִּישָׁא קָאֲתֵינָא, מִקְדוּשָׁתָא דְּקַדִּישָׁא אִתְגַּזַּרְנָא, דְּאָמַר רַב יְהוּדָה אָמַר רַב צָּרִיךְ אָדָם לְקַדֵּשׁ עַצְּמוֹ בִּשְׁעַת תַּשְׁמִישׁ, וְנָפְקֵי מִנִּיהּ בְּנִי קַדִּישֵׁי בְּנִי מַעֲלֵי דְּלָא מִסְתָּפוּ מִיֵצֶּר הָרָע שֶׁנְּאֱמַר (ויקרא כ׳:ז׳) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים.</p>\n<p>רַבִּי אַבָּא אָמַר מַאי דִכְתִיב, (יחזקאל כ׳:כ׳) וְאֶת שַׁבְּתוֹתַי קַדֵּשׁוּ, אֶלָּא אֵין עוֹנָתָן שֶׁל תַּלְמִּידֵּי חֲכָמִים אֶלָּא מִשַּׁבָּת לְשַׁבָּת, וּמַזְהַר לְהוּ דְּהוֹאִיל דְּתַשְׁמִישׁ הַמִּטָה דְּמִצְּוָה הוּא, קַדֵּשׁוּ. כְּלוֹמַר קַדְשׁוּ עַצְּמְכֶם בְּשַׁבְּתוֹתַי בְּהַהוּא תַּשְׁמִישׁ דְּמִצְּוה. אָמַר רַב יְהוּדָה אָמַר רַב הַאי מַאן דְּעָיִיל לְקַרְתָּא וְחָמֵי נַשֵּׁי שַׁפִּירָן, יַרְכִּין עֵינוֹי וְיֵימָא הָכִי, בָּךְ (נ\"א סך) סָפָאן אִיגְזַר אִיגְזַרְנָא (קרדינא) קַרְדִיטָא תְּקִיל פּוּק פּוּק דְּאֲבוֹי קַדִּישָׁא דְּשַׁבַּתָּא הוּא. מַאי טַעְמָא דְּחֲמִימוּת דְּאָרְחָא שָׁלַט בֵּיהּ וְיָכִיל יִצֶּר הָרָע לְשָׁלְטָא עֲלוֹי, (עד כאן מדרש הנעלם)</p>"],[9520011237,"<p><Nonei></i>ויעל לוט מצוער וגו' מגו הורמנותא דמלכא אתפרשא מסטרא דימינא חד התוכא דקטורא דגולפא מתדבקא בגו התוכא דדהבא מסטרא דשמאלא בגו מסאבו (דיצריה) (נ\"א ודיוריה) ואתעביד דקטורא חדא דאילנא</p>\n<p>כד בעא יצחק לאתערא בעלמא בתוקפיה דדינא קשיא אתתקף ופריש דרגין מקיומייהו ואתתקף אברהם ופריש ההוא דקטורא חדא דאילנא מגו ההוא מסאבו,</p>\n<p>ההוא נחש קדמאה עאל באנביה דההוא אילנא ואיהו חמרא דשתא ואוליד תרין דרגין קטירין דא בדא ואינון דרגין דסחרן בסטר מסאבו חד אקרי מלכו\"ם וחד אקרי פעו\"ר</p>\n<p>דא עיטא דאתכסיא ודא עיטא דאתגליא, פעור דאתגליא איהו וכל עובדוי באתגליא, מלכו\"ם דאתכסיא איהו וכל עובדוי באתכסיא מאלין תרין אתפרשן זינין סגיאין לזנייהו <Nonei></i>וסחרן ימא רבא ולכל אלין סטרי מסאבו, וכל חד וחד שף (נ\"א נזף) לדוכתיה,</p>\n<p>כגוונא דא איהו לתתא, לוט אתפרש מאברהם ושוי דיוריה באנשי סדום כד אתער דינא בהו אדכר לאברהם ושלח ליה מתמן ואתפריש מנייהו,</p>\n<p>יין אשקיאו ליה בנתיה ואולידו בהו תרין אומין חד אקרי עמון וחד אקרי מואב, חד באתגליא וחד באתכסיא, עמון דרגא (קעג א) דיליה מלכו\"ם עיטא דאתכסיא, מואב דרגא דיליה פעו\"ר כלא באתגליא</p>\n<p>כגוונא דא בנתיה דא אמרת בן עמי ברא אית לי מעמי ולא אמרת ממאן הוא בגין כך איהו הוה באתכסיא, דא אמרת מואב מאב הוא דנא, מאבא אולידת ליה, דרגא דיליה פעו\"ר מלה באתגליא,</p>\n<p>ובתרין אלין אחיד דוד מלכא לבתר מן מואב אתת רות ונפק מנה דוד מלכא, מן עמון <Nonei></i>אתעטר דוד מלכא בהאי עטרא דאיהי סהדותא לזרעא דדוד דכתיב (מלכים ב י״א:י״ב) ויתן עליו את הנזר ואת העדות והאי הות מן מלכום דרגא דבני עמון דכתיב (שמואל ב י״ב:ל׳) ויקח את עטרת מלכם,</p>\n<p>מלכם דרגא דבני עמון הוא דכתיב ותהי על ראש דוד, ומתמן הוה סהדותא לבנוי לעלמין ובה אשתמודע מאן דאיהו מן בנוי דדוד דאתחזי למלכא ודאי דאמרין מן דוד הוא (הגוף) דאפילו אתיליד בההוא יומא יכיל הוה למסבל ההיא עטרא על רישיה (דהא איהו) דהות משקל ככר זהב ואבן יקרה הות וב\"נ אחרא לא יכיל למסבלא ודא הוא דכתיב ביואש ויתן עליו את הנזר ואת העדות,</p>\n<p>ובתרין דרגין אתאחיד דוד מלכא ואינון תוקפא דמלכותיה לאתתקפא על שאר עמין דאי לא אתכליל בסטרא דלהון לא יכיל לאתתקפא עלייהו כל (גוונין) דרגין דשאר עמין כלילן ביה בדוד לאתגברא ולאתתקפא עלייהו:</p>\n<p>ויעל לוט מצוער <Nonei></i>וישב בהר, כתיב (משלי ל׳:ט״ו) לעלוקה שתי בנות הב הב, אלין שתי בנות דיצר הרע דאינון מתערין ליה (ד\"א ל\"ג בגין) לשלטא בגופא חדא איהי נפש דאתרביאת תדיר בגופא וחדא איהי נפש דכסיפת בתיאובתין בישין (ד\"א ל\"ג דהאי עלמא) ובכל כסופין בישין דהאי עלמא דא איהי בכיר\"ה ודא (ד\"א ואחרא) איהי צעיר\"ה</p>\n<p>ויצה\"ר לא אתחבר תדיר אלא בתרין אלין בגין לפתאה לבני נשא ובגין דיהמנון ליה (א) (ס\"א לאובלא) לאובדא להו לאתר גירין דמותא ויפלחון ליה כמא דאת אמר (שם ז) עד יפלח חץ כבדו,</p>\n<p>ללסטים דמקפחי בטוריא (וכמינו) וטמירו גרמייהו באתר דחיל דטוריא וידעין דהא בני נשא אתטמרן גרמייהו למיהך באינון דוכתי מה עבדי ברירו מנייהו ההוא דחדידא בלישניה מכלא ההוא דידע למפתי בני נשא ויפוק מבינייהו ויתיב באורח מישר דכל בני עלמא עברין תמן כיון דמטא לגבייהו שרי לאתחברא תמן:</p>"],[9520011238,"<p>וַיִּסַּע מִשָּׁם אַבְרָהָם אַרְצָה הַנֶּגֶב. כָּל מַטְלָנוֹי הֲווּ לְסִטְרָא דְּדָרוֹמָא <Nonei></i>יַתִּיר מִסִּטְרָא אָחֳרָא, בְּגִין דְּהָא בְּחָכְמָתָא עֲבַד לְאִתְדַּבְּקָא בְּדָרוֹמָא:</p>\n<p>וַיֹּאמֶר אַבְרָהָם אֶל שָׂרָה אִשְׁתּוֹ אֲחוֹתִי הִיא. תָּנִינָן (כיון) לָא לִיבָּעֵי לֵיהּ לְבַר נָשׁ לְסָמְכָא עַל נִיסָא, וְאִי קוּדְשָׁא בְּרִיךְ הוּא אַרְחִישׁ נִיסָא לְבַּר נָשׁ, לָא אִית לֵיהּ לְסָמְכָא (תדיר) עַל נִיסָא זִמְנָא אָחֳרָא. בְּגִין דְּלָאו בְּכָל שַׁעֲתָא וְשַׁעֲתָא אִתְרְחִישׁ נִיסָא.</p>\n<p>וְאִי יֵיעוּל בַּר נָשׁ גַּרְמֵיהּ בְּאֲתַר דְּנִזְקָא אִשְׁתְּכַח לְעֵינָא, הָא פָּקַע כָּל זְכוּתֵיהּ דְּעֲבַד בְּקַדְמִיתָא וְאוּקְמוּהָ. כְּמָא דְאַתְּ אָמֵר, (בראשית ל״ב:י״א) קָטוֹנְתִּי מִכָּל הַחֲסָדִים וּמִכָּל הָאֱמֶת וְגו'. וְאַבְרָהָם כֵּיוָן דְּסָלִיק מִמִּצְרַיִם וְאִשְׁתְּזִיב זִמְנָא חָדָא, הַשְׁתָּא אַמַּאי אָעִיל גַרְמֵיהּ בְּצַעֲרָא כְּקַדְמִיתָא וְאָמַר אֲחוֹתִי הִיא.</p>\n<p>אֶלָּא אַבְרָהָם לָא סָמִיךְ עַל גַּרְמֵיהּ כְּלוּם, וְחָמָא שְׁכִינְתָּא תָּדִיר בְּדִיּוּרָהּ דְּשָׂרָה וְלָא אַעֲדֵי מִתַּמָּן, וּבְגִין דְּהֲוַת תַּמָּן, אַסְמִיךְ אַבְרָהָם וְאָמַר אֲחוֹתִי הִיא כְּמָה דִכְתִיב (משלי ז׳:ד׳) אֱמֹר לַחָכְמָה אֲחוֹתִי אָתּ. וּבְגִין כָּךְ אָמַר אֲחוֹתִי הִיא (ס\"א את):</p>\n<p>וַיָּבֹא אֱלהִים אֶל אֲבִימֶלֶךְ וְגו'. וְכִי קוּדְשָׁא בְּרִיךְ הוּא אֲתָא לְגַבַּיְיהוּ דְּרַשִּׁיעַיָּא כְּמָה דִכְתִיב, (במדבר כ״ב:ט׳) וַיָּבֹא אֱלהִים אֶל בִּלְעָם. (בראשית ל״א:כ״ד) וַיָּבֹא אֱלהִים אֶל לָבָן. אֶלָּא הַהוּא מְמַנָּא שְׁלִיחָא דְּאִתְפַּקְּדָא עֲלַיְיהוּ הֲוָה, בְּגִין דְּכֻלְהוּ כַּד עָבְדֵי שְׁלִיחוּתָא נַטְלֵי שְׁמָא דָא, וּמִסִּטְרָא דְדִינָא קָא אַתְיָין. וְעַל דָּא וַיָּבֹא אֱלהִים אֶל אֲבִימֶלֶךְ בַּחֲלוֹם הַלַּיְלָה וַיֹּאמֶר לוֹ הִנְךָ מֵת עַל הָאִשָּׁה אֲשֶׁר לָקַחְתָּ וְגו'.</p>\n<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (משלי י״ב:י״ט) שְׂפַת אֱמֶת וְגו'. שְּׂפַת אֱמֶת תִּכּוֹן לָעַד. דָּא אַבְרָהָם, דְּכָל מִלּוֹי בְּקַדְמִיתָא וּבְסוֹפָא הֲווּ בֶּאֱמֶת. וְעַד אַרְגִּיעָה לְשׁוֹן שָׁקֶר. דָּא אֲבִימֶלֶךְ.</p>\n<p>בְּאַבְרָהָם נֶאֱמַר וַיֹּאמֶר אַבְרָהָם אֶל שָׂרָה אִשְׁתּוֹ אֲחוֹתִי הִיא. דָּא בְּקַדְמִיתָא, דְּאָמַר בְּגִין שְׁכִינְתָּא דְּהֲוַת עִמָּהּ דְּשָׂרָה אֲחוֹתִי הִיא, וְאַבְרָהָם בְּחָכְמְתָא עֲבַד.</p>\n<p>מַאי טַעְמָא <Nonei></i>בְּגִין דְּאַבְרָהָם מִסִּטְרָא דְּיָמִינָא אִיהוּ, אָמַר אֲחוֹתִי הִיא, וְרָזָא כְּמָא דְאַתְּ אָמֵר, (שיר השירים ה׳:ב׳) אֲחוֹתִי רַעֲיָתִי יוֹנָתִי תַמָּתִי. וְעַל דָּא אַבְרָהָם קָרָא לָהּ תָּדִיר אֲחוֹתִי, בְּגִין דְּאִתְדָּבַּק בַּהֲדָהּ, וְלָא יִתְעַדּוּן (ויקרא קב דא מן דא לעלמין).</p>\n<p>לְסוֹף מַה כְּתִיב וְגַם אָמְנָה אֲחוֹתִי בַת אָבִי הִיא אַךְ לא בַת אִמִּי. וְכִי הָכִי הֲוָה. אֶלָּא כֹּלָּא בְּגִין שְׁכִינְתָּא קָאֲמַר, אֲחוֹתִי הִיא בְּקַדְמִיתָא, דִּכְתִיב אֱמֹר לַחָכְמָה אֲחוֹתִי אָתְּ. וּלְבָתַר וְגַם אָמְנָה. מַאי וְגַם. לְאִתּוֹסְפָא עַל מַה דְּקָאֲמַר בְּקַדְמִיתָא. אֲחוֹתִי בַת אָבִי הִיא. בְּרַתֵּיהּ דְּחָכְמָה עִלָּאָה, וּבְגִין כָּךְ אִתְקְרֵי אֲחוֹתִי וְאִתְקְרֵי חָכְמָה. אַךְ לֹא בַת אִמִּי. מֵאֲתַר דְּשֵׁירוּתָא דְּכֹלָּא סְתִימָא עִלָּאָה. וְעַל דָּא וַתְּהִי לִי לְאִשָּׁה בְּאַחְוָה בַּחֲבִיבוּתָא דִּכְתִיב, (שיר השירים ב׳:ו׳) וִימִינוֹ תְחַבְּקֵנִי וְכֹלָּא רָזָא דְּחָכְמְתָא אִיהוּ.</p>\n<p>תָּא חֲזֵי, בְּקַדְמִיתָא כַּד נַחְתוּ לְמִצְרַיִם הָכִי קָאֲמַר בְּגִין לְאִתְדַּבְּקָא בְּגוֹ מְהֵימְנוּתָא, וְקָרָא לָהּ אֲחוֹתִי, בְּגִין דְּלָא יִטְעוּן גּוֹ אִנּוּן דַּרְגִּין דִּלְבַר. אוּף הָכָא אֲחוֹתִי, בְּגִין דְּלָא אִתְעֲדֵי מִגּוֹ מְהֵימְנוּתָא כְּדְקָא יְאוּת.</p>\n<p>דְּהָא אֲבִימֶלֶךְ וְכָל אִנּוּן יָתְבֵי אַרְעָא הֲווּ אָזְלֵי בָּתַר פּוּלְחָנָא נוּכְרָאָה, וְאִיהוּ אִתְדָּבַּק גּוֹ מְהֵימְנוּתָא, וּבְגִין כָּךְ עָאל לְתַמָּן וְאָמַר אֲחוֹתִי, מָה אָחוֹת לָא אִתְפְּרַשׁ מֵאָחָא לְעָלְמִין אוּף הָכָא. דְּהָא אִתְּתָא יְכִילַת לְאִתְפְּרָשָׁא אֲבָל אָחוֹת לָא אִתְפְּרַשׁ, דְּהָא תְּרֵין אַחִין לָא יָכְלִין לְאִתְפָּרְשָׁא לְעָלְמִין וּלְעָלְמֵי עָלְמִין.</p>\n<p>וּבְגִין כָּךְ אָמַר אַבְרָהָם אֲחוֹתִי הִיא, דְּהָא כֻּלְהוֹן הֲווּ לְהוּטִין גּוֹ טָהֳרֵי כֹּכְבַיָא וּמַזָּלֵי וּפַלְחֵי לוֹן, וְאַבְרָהָם הֲוָה מִתְדְּבַּק גּוֹ מְהֵימְנוּתָא וְאָמַר אֲחוֹתִי דְּלָא נִתְפְּרַשׁ לְעָלְמִין. וְסִימָנִיךְ (ויקרא כ״א:ג׳) וְלַאֲחוֹתוֹ הַבְּתוּלָה דְּאִתְּמָר לְכֹהֵן, אַתְרָא דְּאַבְרָהָם שַׁרְיָא בֵּיהּ.</p>\n<p>כְּתִיב, (דברים י׳:כ׳-כ״א) אֶת יְיָ אֱלהֶיךָ תִּירָא אוֹתוֹ תַעֲבֹד וּבוֹ תִדְבָּק וּבִשְׁמוֹ תִשָּׁבֵעַ. הַאי קְרָא אוּקְמוּהָ. אֲבָל תָּא חֲזֵי, לַיְיָ אֱלהֶיךָ תִּירָא לָא כְּתִיב, אֶלָּא אֶת <Nonei></i>יְיָ, מַאי אֶת, דָּא דַרְגָּא קַדְמָאָה אֲתַר דַּחֲלָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וּבְגִין כָּךְ כְּתִיב תִּירָא, דְּתַמָּן בָּעֵי בַּר נָשׁ לְדַחֲלָא קַמֵּי מָארֵיהּ (קודשא בריך הוא) בְּגִין דְּאִיהוּ (בי) דִּינָא.</p>\n<p>וְאוֹתוֹ תַּעֲבֹד. דָּא דַּרְגָּא עִלָּאָה דְּקָיְימָא עַל הַאי דַרְגָּא תַּתָּאָה, וְלָא מִתְפָּרְשָׁאן לְעָלְמִין, אֶת וְאוֹתוֹ, דָּא בְּדָא דְּבֵקִין וְלָא אִתְפָּרְשָׁן. מַאי וְאוֹתוֹ. דָּא אֲתַר בְּרִית קַדִּישָׁא אוֹת לְעָלְמִין. דְּהָא פּוּלְחָנָא לָא שַׁרְיָא בְּאֶת וְלָאו אִיהוּ לְמִפְלַח אֶלָּא לְמִדְחַל, אֲבָל פּוּלְחָנָא אִיהוּ (קטו א) לְעֵילָא, וּבְגִין כָּךְ וְאוֹתוֹ תַעֲבֹד.</p>\n<p>וּבוֹ תִדְבָּק. בְּאֲתַר דְּאִיהוּ דְּבֵקוּתָא לְאִתְדַּבְּקָא דְּאִיהוּ גוּפָא דְּשָׁרֵי בְּאֶמְצָעִיתָא. וּבִשְׁמוֹ תִּשָּׁבֵעַ אֲתַר שְׁבִיעָאָה דְּדַרְגִּין. וְסִימָנִיךְ (ירמיהו ל׳:ט׳) וְאֵת דָּוִד מַלְכָּם אֲשֶׁר אָקִים לָהֶם.</p>\n<p>בְּגִין כָךְ אִתְדָּבַּק אַבְרָהָם בִּמְהֵימְנוּתָא כַּד נָחַת לְמִצְרַיִם וְכַד אֲזַל לְאַרְעָא דִּפְלִשְׁתִּים. לְבַּר נָשׁ דְּבָעָא לְנָחֲתָא גּוֹ גּוּבָא עֲמִיקָא. דָּחִיל דְּלָא יָכִיל לְסַלְקָא מִגּוֹ גּוֹבָא, מָה עֲבַד קָשַׁר חַד קִשְׁרָא דְּחֶבֶל לְעֵילָא מִן גּוֹבָא, אָמַר הוֹאִיל דְּקָשִׁירְנָא קִשְׁרָא דָא מִכָּאן וּלְהָלְאָה אִיעוּל תַּמָּן. כָּךְ אַבְרָהָם בְּשַׁעֲתָא דְּבָעָא לְנַחֲתָא לְמִצְרַיִם. עַד לָא יֵיחוּת תַּמָּן קְשַׁר קִשְׁרָא דִּמְהֵימְנוּתָא בְּקַדְמִיתָא לְאִתְתַּקְּפָא בֵּיהּ, וּלְבָתַר נָחַת.</p>\n<p>אוּף הָכִי נָמֵי כַּד עָאל לְאַרְעָא דִּפְלִשְׁתִּים. בְגִין כָּךְ (משלי י״ב:י״ט) שְׂפַת אֱמֶת תִּכּוֹן לָעַד. וְעַד אַרְגִּיעָה לְשׁוֹן שָׁקֶר, דָּא אֲבִימֶלֶךְ דְּאָמַר בְּתוֹם לְבָבִי וּבְנִקְיוֹן כַּפָּי. וְכַד אֲהַדְּרוּ לֵיהּ מַה כְּתִיב גַּם אָנֹכִי יָדַעְתִּי כִּי בְּתָם לְבָבְךָ עָשִׂיתָ זֹאת, וְלָא כְּתִיב נִקְיוֹן כַּפַּיִם:</p>\n<p>וְעַתָּה הָשֵׁב אֵשֶׁת הָאִישׁ כִּי נָבִיא הוּא. רַבִּי יְהוּדָה פָּתַח וְאָמַר (שמואל א ב׳:ט׳) רַגְלֵי חֲסִידָיו יִשְׁמֹר וְגו'. חֲסִידוֹ כְּתִיב חַד, וְדָא אַבְרָהָם דְּקוּדְשָׁא בְּרִיךְ הוּא נָטִיר לֵיהּ תָּדיר וְלָא אַעֲדֵי נְטִירוּ מִנֵּיהּ לְעָלְמִין. וּמַה דְּאָמַר רַגְלֵי, דָּא אִתְּתֵיהּ, דְּקוּדְשָׁא בְּרִיךְ הוּא שַׁדַּר שְׁכִינְתֵּיהּ עִמָּהּ וְנָטַר לָהּ תָּדִיר.</p>\n<p>דָּבָר אַחֵר רַגְלֵי חֲסִידָיו יִשְׁמֹר. חַד, דָּא אַבְרָהָם דְּקוּדְשָׁא בְּרִיךְ הוּא אָזִיל עִמֵּיהּ תָּדִיר בְּגִין דְּלָא יֵיכְלוּן לְנָזְקָא לֵיהּ. וּרְשָׁעִים בַּחשֶׁךְ יִדַּמּוּ. אִלֵּין אִנּוּן מַלְכִין דַּקַטַּל קוּדְשָׁא בְּרִיךְ הוּא בְּהַהוּא לֵילְיָא דְּרָדַף בַּתְרַיְיהוּ.</p>\n<p>הֲדָא הוּא דִכְתִיב בַּחשֶׁךְ יִדַּמּוּ, דָּא לֵילְיָא דְּאִתְקַשַּׁר בַּחֲשׁוֹכָא וְקָטַל לוֹן, וְאַבְרָהָם רָדִיף וְלֵילְיָא קָטִיל לוֹן, הֲדָא הוּא דִכְתִיב וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה הוּא וַעֲבָדָיו וַיַּכֵּם. וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה, דָּא קוּדְשָׁא בְּרִיךְ הוּא דְּפָלִיג רַחֲמֵי מִן דִּינָא בְּגִין לְמֶעְבַּד נוּקְמִין לְאַבְרָהָם, וּבְגִין כָּךְ וּרְשָׁעִים בַּחשֶׁךְ יִדַּמּוּ. וַיַּכֵּם, וַיַּכּוּם מִבָּעֵי לֵיהּ. אֶלָּא דָּא קוּדְשָׁא בְּרִיךְ הוּא. כִּי לֹא בְכֹחַ יִגְבַּר אִישׁ. דְּאִיהוּ וְאֱלִיעֶזֶר הֲווּ בִּלְחוֹדַיְיהוּ.</p>\n<p>רַבִּי יִצְחָק אָמַר וְהָא תָּנִינָן בְּאֲתַר דְּנִזְקָא שְׁכִיחַ לָא יִסְמֹךְ בַּר נָשׁ עַל נִיסָא, וְלָא הֲוָה אֲתַר דְּנִזְקָּא אִשְׁתְּכַח כְּהַאי דְּאַבְרָהָם אָזִיל בָּתַר חֲמִשָּׁה מַלְכִין לְמִרְדַּף בַּתְרַיְיהוּ וְלַאֲגָחָא קְרָבָא. אָמַר רַבִּי יְהוּדָה כַּד אָזִיל אַבְרָהָם לְהַאי לָא אֲזַל לַאֲגָחָא קְרָבָא, וְלָא סָמַךְ עַל נִיסָא, אֶלָּא צַעֲרָא דְלוֹט אַפְקֵיהּ מִבֵּיתֵיהּ, וְנָטִיל מָמוֹנָא לְמִפְרַק לֵיהּ, וְאִי לָאו דִּימוּת בַּהֲדֵיהּ גּוֹ שִׁבְיָהּ. כֵּיוָן דְּנָפַק חָמָא שְׁכִינְתָּא דְּנָהֲרָא קַמֵּיהּ וְכַמָּה חֵילִין סָחֳרָנֵיהּ, בְּהַהִיא שַׁעֲתָא רָדַף בַּתְרַיְיהוּ, וְקוּדְשָׁא בְּרִיךְ הוּא קָטִיל לוֹן, הֲדָא הוּא דִכְתִיב וּרְשָׁעִים בַּחשֶׁךְ יִדַּמּוּ.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר רָזָא אִיהוּ, רַגְלֵי חֲסִידָו יִשְׁמֹר, דָּא אַבְרָהָם. וְכַד נָפַק אִשְׁתַּתַּף יִצְחָק בַּהֲדֵיהּ וְנָפְלוּ קַמֵּיהּ, וְאִי לָאו דְּאִשְׁתַּתַּף יִצְחָק בַּהֲדֵיהּ דְּאַבְרָהָם לָא אִשְׁתֵּצִיאוּ הֲדָא הוּא דִכְתִיב וּרְשָׁעִים בַּחשֶׁךְ יִדַּמּוּ. כִּי לא בְכֹחַ יִגְבַּר אִישׁ. אַף עַל גַּב דְּחֵילָא אִשְׁתְּכַח תָּדִיר בְּיָמִינָא, אִי לָא הֲוָה בְּסִטְרָא דִּשְׂמָאלָא לָא אִתְדַּחְיָין קַמֵּיהּ.</p>\n<p>דָּבָר אַחֵר רַגְלֵי חֲסִידָו יִשְׁמֹר, בְּשַׁעֲתָא דְּבַּר נָשׁ רָחִים לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. קוּדְשָׁא בְּרִיךְ הוּא רָחִים לֵיהּ בְּכָל מַה דְּאִיהוּ עָבִיד וְנָטִיר אָרְחוֹי כְּמָא דְאַתְּ אָמֵר (תהילים קכ״א:ח׳) יְיָ יִשְׁמָר צֵאתְךָ וּבוֹאֶךָ מֵעַתָּה וְעַד עוֹלָם.</p>\n<p>תָּא חֲזֵי, כַּמָּה חֲבִיבוּתֵיהּ דְּאַבְרָהָם לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, דְּבְּכָל אֲתַר דְּהֲוָה אָזִיל לָא הֲוָה חָיִיס עַל דִּילֵיהּ כְּלוּם, <Nonei></i>אֶלָא בְּגִין לְאִתְדַּבְּקָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וּבְגִין כָּךְ רַגְלֵי חֲסִידָיו יִשְׁמֹר. וְדָא הִיא אִתְּתֵיהּ, דִּכְתִיב וַאֲבִימֶלֶךְ לא קָרַב אֵלֶיהָ. וּכְתִיב כִּי עַל כֵּן לא נְתַתִּיךָ לִנְגֹעַ אֵלֶיהָ.</p>\n<p>בְּפַרְעֹה מַה כְּתִיב, (בראשית י״ב:י״ז) וַיְנַגַּע יְיָ אֶת פַּרְעֹה וְגו' עַל דְּבַר. אִיהִי אָמְרָה וְקוּדְשָׁא בְּרִיךְ הוּא הֲוָה מָחֵי, וּבְגִין כָּךְ רַגְלֵי חֲסִידָיו יִשְׁמֹר. וּרְשָׁעִים בַּחשֶׁךְ יִדַּמּוּ, אִלֵּין פַּרְעֹה וְאֲבִימֶלֶךְ, דְּקוּדְשָׁא בְּרִיךְ הוּא עֲבַד בְּהוּ דִּינִין בְּלֵילְיָא. כִּי לא בְּכֹחַ יִגְבַּר אִישׁ. מַאן אִישׁ, דָּא אַבְרָהָם, דִּכְתִיב וְעַתָּה הָשֵׁב אֵשֶׁת הָאִישׁ וְגו':</p>"],[9520011239,"<p>וַיְיָ פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר וְגו'. רַבִּי חִיָּיא פָּתַח וְאָמַר (זכריה ג׳:א׳) וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל עוֹמֵד לִפְנֵי מַלְאַךְ יְיָ וְהַשָּׂטָן עוֹמֵד עַל יְמִינוֹ לְשִׂטְנוֹ. הַאי קְרָא אִית לְאִסְתַּכָּלָא בֵּיהּ. וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל דָּא יְהוֹשֻׁעַ בֶּן יְהוֹצָדָק. עוֹמֵד לִפְנֵי מַלְאַךְ יְיָ, מַאן מַלְאַךְ יְיָ. דָּא אֲתַר צְרוֹרָא (ס\"א דנשמתין דצדיקיא צרירן) דְּנִשְׁמָתֵיהּ דְּצַדִּיק צְרִירָא בֵּיהּ, וְכָל אִנּוּן נִשְׁמָתִין דְּצַדִּיקַיָא קָיְימִין תַּמָּן, וְדָא הוּא מַלְאַךְ יְיָ.</p>\n<p>וְהַשָּׂטָן עוֹמֵד עַל יְמִינוֹ לְשִׂטְנוֹ. דָּא יֵצֶר הָרָע דְּאִיהוּ מְשׁוֹטֵט וְאָזִיל בְּעָלְמָא לְנַטְלָא נִשְׁמָתִין וּלְאַפָּקָא רוּחִין וּלְמִסְטֵי לוֹן לִבְרִיָּיתָא לְעֵילָא וְתַתָּא. וְדָא הוּא בְּשַׁעֲתָא דְּאֲטִיל לֵיהּ נְבוּכַדְנֶצַּר לְאֶשָׁא עִם אִנּוּן נְבִיאֵי הַשֶּׁקֶר, וְהַאי הֲוָה מַסְטִין לְעֵילָא בְּגִין דְּיִתּוֹקַד עִמְּהוֹן.</p>\n<p>דְּהָכִי הוּא אָרְחוֹי דְּלָאו אִיהוּ מְקַטְרֵג אֶלָּא בְּזִמְנָא דְּסַכָּנָה וּבְזִמְנָא דְּצַעֲרָא שָׁרְיָא בְּעָלְמָא, וְאִית לֵיהּ רְשׁוּ לְמִסְטֵי וּלְמֶעְבַּד דִּינָא אֲפִלּוּ בְּלָא דִינָא כְּמָא דְאַתְּ אָמֵר, (משלי י״ג:כ״ג-כ״ד) וְיֵשׁ נִסְפָּה בְּלא מִשְׁפָּט. מַהוּ לְשִׂטְנוֹ, דְּהֲוָה אָמַר אוֹ כֻּלְהוּ יִשְׁתֵּזְבוּן אוֹ כֻּלְהוּ יִתּוֹקְדוּן. דְּהָא בְּשַׁעֲתָא דְּאִתְיְיהִיב רְשׁוּתָא לִמְחַבְּלָא לְחַבָּלָא לָא אִשְׁתְּזִיב זַכָּאָה מִן חַיָּיבַיָא,</p>\n<p>וּבְגִין כָּךְ בְּשַׁעֲתָא דְּדִינָא שָׁרְיָיא בְּמָתָא בָּעֵי בַּר נָשׁ לְעָרְקָא עַד לָא אִתְפַּס תַּמָּן, דְּהָא מְחַבְּלָא כֵּיוָן דְּשָׁרֵי הָכִי נָמֵי עָבִיד לְזַכָּאָה כְּחַיָּיבָא. וְכָל שֶׁכֵּן דְּהֲווּ תְּלָתֵיהוֹן כְּחַד. וְהֲוָה תָּבַע דְּיִתּוֹקְדוּן כֻּלְהוּ אוֹ יִשְׁתֵּזְבוּן כֻּלְהוּ. בְּגִין דְּכַד אִתְעֲבִיד <Nonei></i>נִיסָא לָא אִתְעֲבִיד פַּלְגוּ נִיסָא וּפַלְגוּ דִּינָא, אֶלָּא כֹּלָּא כְּחֲדָא, אוֹ נִיסָא אוֹ דִּינָא.</p>\n<p>אָמַר לוֹ רַבִּי יוֹסֵי, וְלָא, וְהָא בְּזִמְנָא דְּבָקַע קוּדְשָׁא בְּרִיךְ הוּא יַמָּא לְיִשְׂרָאֵל הֲוָה קָרַע יַמָּא לְאִלֵּין וְאָזְלִין בְּיַבֶּשְׁתָּא, וּמַיָּיא הֲווּ תָּבִין מִסִּטְרָא אָחֳרָא וְטָבְעִין לְאִלֵּין וּמֵתִין, וְאִשְׁתְּכַח נִיסָא הָכָא וְדִינָא הָכָא כֹּלָּא כְּחֲדָא.</p>\n<p>אָמַר לֵיהּ וְדָא הוּא דְּקַשְׁיָא קַמֵּיהּ, דְּכַד קוּדְשָׁא בְּרִיךְ הוּא עָבִיד דִּינָא וְנִיסָא כְּחֲדָא, לָאו בְּאֲתַר חָד וְלָא בְּבֵיתָא חָדָא (דאשתכח כלא כחדא), וְאִי אִתְעֲבִיד קַשְׁיָא קַמֵּיהּ, דְּהָא לְעֵילָא לָא אִתְעֲבִיד כֹּלָּא אֶלָּא בִּשְׁלִימוּ כְּחֲדָא אוֹ נִיסָא אוֹ דִּינָא בְּאֲתַר חָד וְלָא בְּפַלְגוּ.</p>\n<p>בְגִין כָּךְ לָא עֲבִיד קוּדְשָׁא בְּרִיךְ הוּא דִּינָא בְּחַיָּיבַיָא עַד דְּאִשְׁתַּלִּימוּ בְּחוֹבַיְיהוּ הֲדָא הוּא דִכְתִיב, (בראשית ט״ו:ט״ז) כִּי לא שָׁלֵם עֲוֹן הָאֱמֹרִי עַד הֵנָּה. וּכְתִיב (ישעיהו כ״ז:ח׳) בְּסַאסְאָה בְּשַׁלְחָהּ תְּרִיבֶנָּה. וְעַל דָּא הֲוָה אַסְטִין לֵיהּ לִיהוֹשֻׁעַ דְּיִתּוֹקַד בְּהוּ, עַד דְּאָמַר לֵיהּ (זכריה ג׳:ב׳) יִגְעַר יְיָ בְּךָ הַשָּׂטָן. מַאן אָמַר לֵיהּ, דָּא מַלְאַךְ יְיָ (ואתמר ויאמר יי אל השטן).</p>\n<p>וְאִי תֵימָא וַיֹּאמֶר יְיָ אֶל הַשָּׂטָן יִגְעַר יְיָ בְּךָ וְגו'. תָּא חֲזֵי, הָכִי נָמֵי לְמשֶׁה בַּסְּנֶה דִּכְתִיב, (שמות ג׳:ב׳) וַיֵּרָא מַלְאַךְ יְיָ אֵלָיו בְּלַבַּת אֵשׁ. וּכְתִיב וַיַּרְא יְיָ כִּי סָר לִרְאוֹת. לְזִמְנִין מַלְאַךְ יְיָ וּלְזִמְנִין מַלְאָךְ וּלְזִמְנִין יְיָ. וּבְגִין כָּךְ אָמַר לֵיהּ יִגְעַר יְיָ בְּךָ הַשָּׂטָן וְלא אָמַר הִנְּנִי גּוֹעֵר בְּךָ.</p>\n<p>תָּא חֲזֵי, כְּגווָֹנָא דָא בְּיוֹמָא דְּאִשְׁתְּכַח דִּינָא בְּעָלְמָא, וְקוּדְשָׁא בְּרִיךְ הוּא יָתִיב עַל כֻּרְסְיָיא דְּדִינָא, כְּדֵין אִשְׁתְּכַח הַאי שָׂטָן דְּאַסְטֵי לְעֵילָא וְתַתָּא, וְאִשְׁתְּכַח אִיהוּ לְחַבָּלָא עָלְמָא וְלִיטֹּל נִשְׁמָתִין.</p>"],[9520011240,"<p>רַבִּי שִׁמְעוֹן הֲוָה יָתִיב וְלָעֵי בְּאוֹרַיְיתָא, וְהֲוָה מִשְׁתַּדֵּל בְּהַאי קְרָא (דברים כ״א:ד׳) וְלָקְחוּ זִ קְנֵי הָעִיר הַהִיא עֶגְלַת בָּקָר וְגו' וְעָרְפוּ שָׁם אֶת הָעֶגְלָה בַּנָּחַל. וְדִינָא אִיהוּ בְּקוּפִיץ לְעָרְפָּא לָהּ. אָמַר לֵיהּ רַבִּי אֶלְעָזָר הַאי לְמַאי אִצְטְרִיךְ.</p>\n<p>בָּכָה רַבִּי שִׁמְעוֹן, וְאָמַר, וַוי לְעָלְמָא דְּאִתְמְשַׁךְ בָּתַר דָּא. דְּהָא מִן הַהוּא יוֹמָא דְּהַהוּא חִוְיָא <Nonei></i>בִּישָׁא דְּאִתְפַּתָּה בֵּיהּ אָדָם שַׁלִיט עַל אָדָם וְשַׁלִּיט עַל בְּנֵי עָלְמָא, אִיהוּ קָאִים לְמִסְטֵי עָלְמָא וְעָלְמָא לָא יָכִיל לְנָפְקָא מֵעָנְשֵׁיהּ עַד דְּיֵיתֵי מַלְכָּא מְשִׁיחָא וְיוֹקִים קוּדְשָׁא בְּרִיךְ הוּא לִדְמִיכֵי עַפְרָא דִּכְתִיב, (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוְת לָנֶצַח וְגו' וּכְתִיב, (זכריה י״ג:ב׳) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ. וְאִיהוּ קָאִים עַל עָלְמָא דָא לְמִיטַל נִשְׁמָתִין דְּכָל בְּנֵי נָשָׁא.</p>\n<p>וְתָא חֲזֵי הָא כְּתִיב (דברים כ״א:א׳) כִּי יִמָּצֵא חָלָל וְגו' תָּא חֲזֵי, כָּל בְּנֵי עָלְמָא עַל יְדֵי מַלְאַךְ הַמָּוְת נָפְקָא נִשְׁמָתַיְיהוּ. אִי תֵימָא דְּבַּר נָשׁ דָּא עַל יְדָא דְּהַהוּא מַלְאַךְ הַמָּוֶת נָפַק נִשְׁמָתֵיהּ, לָאו הָכִי. אֶלָּא מַאן דְּקָטִיל לֵיהּ, אַפִּיק נִשְׁמָתֵיהּ עַד לָא מָטָא זִמְנֵיהּ לְשַׁלְטָאָה בֵּיהּ הַהוּא מַלְאַךְ הַמָּוֶת.</p>\n<p>וּבְגִין כָּךְ וְלָאָרֶץ לא יְכֻפָּר וְגו' וְלָאָרֶץ דִּילָן. וְלָא דַּי לוֹן דְּקָאִים אִיהוּ לְמִסְטֵי עָלְמָא לְמַגָּנָא וּלְקַטְרְגָא תָּדִיר כָל שֶׁכֵּן דְּגָזְלִין מִינֵיהּ מַה דְּאִית לֵיהּ לְנַטְלָא. וְקוּדְשָׁא בְּרִיךְ הוּא חָיִיס עַל בְּנוֹי, וּבְגִין כָּךְ קָרֵבִין עַל הַאי עֶגְלָא, בְּגִין לְתָקָּנָא עִמֵּיהּ מַה דְּאִתְנְטִיל הַהִיא נִשְׁמָתָא דְּבַּר נָשׁ מִנֵּיהּ, וְלָא יִשְׁתְּכַח מְקַטְרְגָא עַל (ד\"א ל\"ג קריבין בהאי) עָלְמָא.</p>\n<p>וְרָזָא עִלָּאָה תָּנִינָן הָכָא: שׁוֹר פָּרָה, עֵגֶל עֶגְלָה, כֻּלְהוּ בְּרָזָא עִלָּאָה אִשְׁתְּכָחוּ, וּבְגִין כָּךְ בְּדָא מְתַקְּנִין לֵיהּ, וְדָא הוּא דִכְתִיב, (דברים כא) יָדֵינוּ לא שָׁפְכֻה אֶת הַדָּם הַזֶּה וְגו' לא שָׁפְכֻה וְלָא גָרִימְנָא מִיתָתֵיהּ, וּבְדָא לָא אִשְׁתְּכַח מְקַטְרְגָא עֲלַיְיהוּ, וּבְכוֹלָּא יָהִיב קוּדְשָׁא בְּרִיךְ עֵיטָא לְעָלְמָא.</p>"],[9520011241,"<p>תָּא חֲזֵי, כְּגווָֹנָא דָא בְּיוֹם רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים דְּדִינָא אִשְׁתְּכַח בְּעָלְמָא, אִיהוּ קָאִים לְקַטְרְגָא וְיִשְׂרָאֵל בָּעְיָין לְאִתְעָרָא בְּשׁוֹפָר, וּלְאַתְעָרָא קוֹל דְּכָלִיל בְּאֶשָׁ\"א וּמַיָ\"א וְרוּחָ\"א וְאִתְעֲבִידוּ חָד, וּלְאַשְׁמָעָא הַהוּא קוֹל מִגּוֹ שׁוֹפָר.</p>\n<p>וְהַהוּא קוֹל סָלְקָא עַד אֲתַר דְּכָרְסְיָא דְדִינָא יָתְבָא וּבָטַשׁ בָּהּ וְסָלְקָא. כֵּיוָן דְּמָטָא הַאי קוֹל מִתַּתָּא, קוֹל דְּיַעֲקֹב אִתְתַּקַּן לְעֵילָא, וְקוּדְשָׁא בְּרִיךְ הוּא <Nonei></i>אִתְעַר רַחֲמֵי, דְּהָא כְּגַוְונָא דְּיִשְׂרָאֵל מִתְעָרֵי לְתַתָּא קוֹל חַד כָּלִיל בְּאֶשָׁ\"א וְרוּחָ\"א וּמַיָ\"א דְּנָפְקֵי כְּחֲדָא מִגּוֹ שׁוֹפָר, הָכִי נָמֵי אִתְעַר לְעֵילָא שׁוֹפָר. וְהַהוּא קוֹל דְּכָלִיל בְּאֶשָׁ\"א וּמַיָ\"א וְרוּחָ\"א אִתְתַּקַּן, וְנָפַק דָּא מִתַּתָּא וְדָא מֵעֵילָא, וְאִתְתַּקַּן עָלְמָא וְרַחֲמֵי אִשְׁתְּכָחוּ.</p>\n<p>וְהַהוּא מְקַטְרְגָא אִעַרְבֵּב דְּחֲשִׁיב לְשַׁלְטָאָה בְּדִינָא וּלְקַטְרְגָא בְּעָלְמָא, וְחָמֵי דְּמִתְעָרֵי רַחֲמֵי, כְּדֵין אִעַרְבָּב וְאִתְּשַׁשׁ חֵילֵיהּ וְלָא יָכִיל לְמֶעְבַּד מִידִי, וְקוּדְשָׁא בְּרִיךְ הוּא דָּאִין עָלְמָא בְּרַחֲמֵי, דְּאִי תֵימָא דְדִינָא אִתְעֲבִיד, לָאו הָכִי, אֶלָּא אִתְחַבָּרוּ רַחֲמֵי בְּדִינָא, וְעָלְמָא אִתְדָּן בְּרַחֲמֵי.</p>\n<p>תָּא חֲזֵי, כְּתִיב, (תהילים פ״א:ד׳) תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ דְּאִתְכַּסְיָא סִיהֲרָא. דְּהָא כְּדֵין שָׁלְטָא הַאי חִיוְיָא בִּישָׁא וְיָכִיל לְנַזְקָא עָלְמָא, וְכַד מִתְעָרֵי רַחֲמֵי, סָלְקָא סִיהֲרָא וְאִתְעֲבָרַת מִתַּמָּן, וְאִיהוּ אִתְעַרְבֵּב וְלָא יָכִיל לְשַׁלְטָאָה, וְאִתְעֲבַר דְּלָא יִתְקְרַב תַּמָּן, וְעַל דָּא בְּיוֹם רֹאשׁ הַשָּׁנָה בָּעֵי לְעַרְבְּבָא לֵיהּ כְּמַאן דְּאִתְעַר מִשְּׁנָתֵיהּ וְלָא יְדַע כְּלוּם.</p>\n<p>בְּיוֹם הַכִּפּוּרִים בָּעֵי לְנַיְיחָא וּלְמֶעְבַּד לֵיהּ נַיְיחָא דְּרוּחָא בְּשָׂעִיר דְּקָרֵבִין לֵיהּ, וּכְדֵין אִתְהַפַּךְ סַנֵּיגוֹרְיָא עֲלַיְיהוּ דְיִשְׂרָאֵל, אֲבָל בְּיוֹמָא דְּרֹאשׁ הַשָּׁנָה אִתְעַרְבָּב דְּלָא יְדַע וְלָא יָכִיל לְמֶעְבַּד כְּלוּם. חָמֵי אִתְעֲרוּתָא דְּרַחֲמֵי סָלְקִין מִתַּתָּא, וְרַחֲמֵי מִלְּעֵילָא וְסִיהֲרָא סָלְקָא בֵּינַיְיהוּ. כְּדֵין אִתְעַרְבָּב וְלָא יְדַע כְּלוּם וְלָא יָכִיל לְשַׁלְטָאָה.</p>\n<p>וְקוּדְשָׁא בְּרִיךְ הוּא דָּן לְהוּ לְיִשְׂרָאֵל בְּרַחֲמֵי, וְחָיִיס עֲלַיְיהוּ וְאִשְׁתְּכַח לְהוּ זִמְנָא כָּל אִנּוּן י' יוֹמִין דְּבֵין רֹאשׁ הַשָּׁנָה לְיוֹם הַכִּפּוּרִים לְקַבְּלָא כָּל אִנּוּן דְּתָיְיבִין קַמֵּיהּ וּלְכַפָּרָא לוֹן מֵחוֹבַיְיהוּ וְסָלִיק לוֹן לְיוֹמָא דְכִפּוּרֵי.</p>\n<p>וְעַל דָּא בְּכוֹלָּא קוּדְשָׁא בְּרִיךְ הוּא פַּקִּיד לוֹן לְיִשְׂרָאֵל לְמֶעְבַּד עוֹבָדָא בְּגִין דְּלָא יִשְׁלוֹט עֲלַיְיהוּ מַאן דְּלָא אִצְטְרִיךְ, וְלָא יִשְׁלוֹט עֲלַיְיהוּ דִינָא, וִיהוֹן כֻּלְהוֹן זַכָּאִין בְּאַרְעָא <Nonei></i>כִּרְחִימוּ דְּאַבָּא עַל בְּנִין, וְכוֹלָּא בְּעוֹבָדָא וּבְמִלִּין תַּלְיָא, וְהָא אוֹקִימְנָא מִלִּין.</p>"],[9520011242,"<p><Noneb>מִדְרָשׁ הַנֶּעֱלָם</b> <Nonei></i>וַיְיָ פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר. רַבִּי יוֹחָנָן פָּתַח בְּהַאי קְרָא (שיר השירים ז׳:ו׳) רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן מֶלֶךְ אָסוּר בָּרְהָטִים. עָשָׂה קוּדְשָׁא בְּרִיךְ הוּא שִׁלְטוֹנִים לְמַעְלָה וְשִׁלְטוֹנִים לְמַטָה. כְּשֶׁנּוֹתֵן קוּדְשָׁא בְּרִיךְ הוּא מַעֲלָה לַשָּׂרִים שֶׁל מַעְלָה נוֹטְלִים מַעֲלָה הַמְּלָכִים שֶׁל מַטָה. נָתַן מַעֲלָה לְשָׂרוֹ שֶׁל בָּבֶל, נָטַל מַעֲלָה נְבוּכַדְנֶצַּר הָרָשָׁע דִּכְתִיב בֵּיהּ (דניאל ב׳:ל״ח) אַנְתְּ הוּא רֵאשָׁה דִּי דַּהֲבָא, והָיוּ כָּל הָעוֹלָם מְשׁוּעְבָּדִים תַּחַת יָדוֹ וּבְנוֹ וּבֶן בְּנוֹ, הֲדָא הוּא דִכְתִיב רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל, זֶהוּ נְבוּכַדְנֶצַּר, הֲדָא הוּא דִכְתִיב, (דניאל ד׳:ט׳) תְּחֹתוֹהִי תַּטְלֵל חֵיוַת בָּרָא. וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן, זְהוּ בֵּלְשַׁצַּר דְּאָמַר (דניאל ה׳:ז׳) אַרְגְּוָונָא יִלְבָּשׁ. מֶלֶךְ אָסוּר בָּרְהָטִים, זֶהוּ אֱוִיל מְרוֹדָךְ שֶׁהָיָה אָסוּר עַד שֶׁמֵּת אָבִיו נְבוּכַדְנֶצַּר וּמָלַךְ תַּחְתָּיו.</p>\n<p>אָמַר רַבִּי יְהוּדָה לְמַאי אֲתָא הַאי טַעַם בְּשִׁיר הַשִּׁירִים. אֶלָּא אָמַר רַבִּי יְהוּדָּה שִׁבְעָה דְבָרִים נִבְרְאוּ קוֹדֶם שֶׁנִּבְרָא הָעוֹלָם, וְאֵלּוּ הֵן וְכוּ', כִּסֵּא הַכָּבוֹד שֶׁנֶּאֱמַר (תהילים צ״ג:ב׳) נָכוֹן כִּסְאֲךָ מֵאָז מֵעוֹלָם אָתָּה וּכְתִיב, (ירמיהו י״ז:י״ב) כִּסֵּא כָבוֹד מָרוֹם מֵרִאשׁוֹן. שֶׁהוּא הָיָה רֹאשׁ הַנִּקְדַּם לַכֹּל, וְנָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַנְּשָׁמָה הַטְהוֹרָה מִכִּסֵּא הַכָּבוֹד לִהְיוֹת מְאִירָה לַגּוּף, הֲדָא הוּא דִכְתִיב רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל, זְהוּ כִּסֵּא הַכָּבוֹד שֶׁהוּא רֹאשׁ עַל הַכֹּל. וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן, זוֹ הִיא הַנְּשָׁמָה הַנִּטֶלֶת מִמֶּנּוּ. מֶלֶךְ אָסוּר בָּרְהָטִים, זְהוּ הַגּוּף שֶׁהוּא אָסוּר בַּקֶּבֶר וְכָלָה בֶּעָפָר וְלֹא נִשְׁאָר מִמֶּנּוּ אֶלָּא כִּמְלֹא תַּרְוָד רֶקֶב. וּמִמֶּנּוּ יִבָּנֶה כָּל הַגּוּף. וּכְשֶׁפּוֹקֵד הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַגּוּף הוּא אוֹמֵר לָאָרֶץ שֶׁתַּפְלִיט אוֹתוֹ לַחוּץ דִּכְתִיב (ישעיהו כ״ו:י״ט) ואֶרְץ רְפָאִים תַּפִּיל.</p>\n<p>אָמַר רַבִּי יוֹחָנָן הַמֵּתִים שֶׁבָּאֶרֶץ הֵם חַיִּים תְּחִלָּה הֲדָא הוּא דִכְתִיב, (ישעיהו כ״ו:י״ט) יִחְיוּ מֵתֶיךָ, נְבֵלָתִי יְקוּמוּן אֵלּוּ שֶׁבְּחוּצָּה לָאָרֶץ. הָקִיצּוּ ורַנְּנוּ <Nonei></i>שׁוֹכְנֵי עָפָר, אֵלּוּ הַמֵּתִים שֶׁבַּמִּדְבָּר. דְּאָמַר רַבִּי יוֹחָנָן לָמָּה מֵת משֶׁה בְּחוּצָּה לָאָרֶץ. לְהַרְאוֹת לְכָל בָּאֵי עוֹלָם, כְּשֵׁם שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת לְמשֶׁה כָּךְ עָתִיד לְהַחֲיוֹת לְדוֹרוֹ (למה) שֶׁהֵם קִבְּלוּ הַתּוֹרָה. (דאמר רבי יוחנן) וְעֲלֵיהֶם נֶאֱמַר (ירמיהו ב׳:ב׳) זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ אַהֲבַת כְּלוּלוֹתָיִךְ לֶכְתֵּךְ אַחֲרַי בַּמִּדְבָּר בְּאֶרֶץ לא זְרוּעָה.</p>\n<p>דָּבָר אַחֵר הָקִיצּוּ ורַנְּנוּ שׁוֹכְנִי עָפָר, אֵלּוּ הֵם הָאָבוֹת. וְהַמֵּתִים בְּחוּצָּה לָאָרֶץ יִבָּנֶה גוּפָם וּמִתְגַּלְגְּלִים תַּחַת הָאָרֶץ עַד אֶרֶץ יִשְׂרָאֵל ושָׁם יְקַבְּלוּ נִשְׁמָתָם וְלֹא בְּחוּצָּה לָאָרֶץ, הֲדָא הוּא דִכְתִיב, (יחזקאל ל״ז:י״ב) לָכֵן הִנָּבֵא וְאָמַרְתָּ אֲלֵיהֶם הִנֵּה אָנֹכִי פּוֹתֵחַ אֶת קִבְרוֹתֵיכֶם וְהַעֲלֵיתִי אֶתְכֶם מִקִּבְרוֹתֵיכֶם עַמִּי וְהֵבֵאתִי אֶתְכֶם אֶל אַדְמַת יִשְׂרָאֵל. מַה כְּתִיב אַחֲרָיו ונָתַתִּי רוּחִי בָכֶם וִחְיִיתֶם.</p>\n<p>רַבִּי פִּנְחָס אָמַר הַנְּשָׁמָה נִטְלָה מִכִּסֵּא הַכָּבוֹד שֶׁהוּא הָרֹאשׁ כִּדְקָאָמַר (שיר השירים ז׳:ו׳) רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל. וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן זוֹ הִיא הַנְּשָׁמָה שֶׁהִיא דַּלַת הָרֹאשׁ. מֶלֶךְ אָסוּר בָּרְהָטִים, הוּא הַגּוּף שֶׁהוּא אָסוּר בַּקְבָרִים. זֶהוּ הַגּוּף וְזֶהוּ שָׂרָה וְזֶהוּ מֶלֶךְ. וְקוּדְשָׁא בְּרִיךְ הוּא פּוֹקְדָהּ לַמּוֹעֵד אֲשֶׁר דִּבֶּר אֵלָיו הֲדָא הוּא דִכְתִיב וַיְיָ פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר. פּוֹקֵד אֶת הַגּוּף לַזְּמַן הַיָּדוּעַ שֶׁבּוֹ יפְקוֹד הַצַּדִּיקִים.</p>\n<p>אָמַר רַבִּי פִּנְחָס עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַפּוֹת לְגוּף הַצַּדִּיקִים לֶעָתִיד לָבֹא כְּיוֹפִי שֶׁל אָדָם הָרִאשׁוֹן כְּשֶׁנִּכְנַס לַגַּן עֵדֶן, שֶׁנְּאֱמַר (ישעיהו נ״ח:י״א) וְנָחֲךָ יְיָ תָּמִיד וְגו' וְהָיִיתָ כְּגַן רָוְה. אָמַר רַבִי לֵוִי הַנְּשָׁמָה בְּעוֹדָהּ בְּמַעֲלָתָהּ נִיזוֹנֶת בְּאוֹר שֶׁל מַעְלָה וּמִתְלַבֶּשֶׁת בּוֹ, וּכְשֶׁתִּכָּנֵס (ונשתרש) לַגוּף לֶעָתִיד לָבֹא בְּאוֹתוֹ הָאוֹר מַמָּשׁ תִּכָּנֵס, וְאֲזַי הַגּוּף יָאִיר כְּזוֹהַר הָרָקִיעַ הֲדָא הוּא דִכְתִיב, (דניאל י״ב:ג׳) וְהַמַּשְׂכִּילִים יַזְהִירוּ כְּזוֹהַר הָרָקִיעַ, וְיַשִּׂיגוּ בְּנִי אָדָם דֵּעָה שְׁלֵימָה שֶׁנְּאֱמַר (ישעיהו י״א:ט׳) כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת יְיָ. מְנָא לָן הָא, מִמַּה דִּכְתִיב וְנָחֲךָ יְיָ תָּמִיד וְהִשְׂבִּיעַ בְּצַּחֲצָּחוֹת נַפְשֶׁךָ. זְה אוֹר שֶׁל <Nonei></i>מַעְלָה. וְעַצְּמוֹתֶיךָ יַחְלִיץ זְה פְּקִידַת הַגּוּף. וְהָיִיתָ כְּגַן רָוְה וּכְמוֹצָּא מַיִם אֲשֶׁר לא יְכַזְבוּ מֵימָיו. זֶהוּ דַעַת הַבּוֹרֵא יִתְבָּרַךְ, וְאֲזַי יֵדְעוּ הַבְּרִיּוֹת שֶׁהַנְּשָׁמָה הַנִּכְנֶסֶת בָּהֶם שֶׁהִיא נִשְׁמַת הַחַיִּים נִשְׁמַת הַתַּעֲנוּגִים שֶׁהִיא קִבְּלָה תַּעֲנוּגִים מִלְּמַעְלָה וּמְעָדֵנֶּת לַגּוּף וְהַכֹּל תְּמֵהִים בָּהּ ואוֹמְרִים (שיר השירים ז׳:ז׳) מַה יָּפִית וּמַה נָּעַמְתְּ אַהֲבָה בַּתַּעֲנוּגִים. זוֹ הִיא הַנְּשָׁמָה לֶעָתִיד לָבֹא.</p>\n<p>אָמַר רַבִּי יְהוּדָה תָּא חֲזֵי, שֶׁכָּךְ הוּא דִּכְתִיב, (שיר השירים ז׳:ז׳) מֶלֶךְ אָסוּר בָּרְהָטִים. וּכְתִיב בַּתְרֵיהּ מַה יָּפִית וּמַה נָּעַמְתְּ. וְאָמַר רַבִּי יְהוּדָה בְּאוֹתוֹ זְמַן עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְשַׂמֵּחַ עוֹלָמוֹ וְלִשְׂמוֹחַ בִּבְרִיּוֹתָיו שֶׁנְּאֱמַר (תהילים ק״ד:ל״א) יִשְׂמַח יְיָ בְּמַעֲשָׂיו. וְאֲזַי יִהְיֶה שְׂחוֹק בָּעוֹלָם מַה שֶּׁאֵין עַכְשָׁיו, דִּכְתִיב, (תהילים קכ״ו:ב׳) אָז יִמָּלֵא שְׂחוֹק פִּינוּ וגו'. הֲדָא הוּא דִכְתִיב וַתֹּאמֶר שָׂרָה צְּחוֹק עָשָׂה לִי אֱלהִים. שֶׁאֲזַי עֲתִידִים בְּנֵי אָדָם לוֹמַר שִׁירָה שֶׁהוּא עֵת שְׂחוֹק. רַבִּי אַבָּא אָמַר הַיּוֹם שֶׁיִּשְׂמַח הַקָּדוֹשׁ בָּרוּךְ הוּא עִם בְּרִיּוֹתָיו לֹא הָיְתָה שִׂמְחָה כְּמוֹתָהּ מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, וְהַצַּדִּיקִים הַנִּשְׁאָרִים בִּירוּשָׁלַיִם לא יָשׁוּבוּ עוֹד לְעַפְרָם דִּכְתִיב, (ישעיהו ד׳:ג׳) והָיָה הַנִּשְׁאָר בְּצִּיּוֹן וְהַנּוֹתָר בִּיְרוּשָׁלַםִ קָדוֹשׁ יֵאָמַר לוֹ. הַנּוֹתָר בְּצִּיּוֹן וּבִיְרוּשָׁלַםִ דַּיְיקָא.</p>\n<p>אָמַר רַבִּי אַחָא אִם כֵּן זְעִירִין אִנּוּן, אֶלָּא כָּל אִנּוּן דְּאִשְׁתְּאָרוּ בְּאַרְעָא קַדִּישָׁא דְיִשְׂרָאֵל דִּינָא דִלְהוֹן כִּיְרוּשָׁלַםִ וּכְצִּיּוֹן לְכָל דָּבָר. מְלַמֵּד דְּכָל אֶרֶץ יִשְׂרָאֵל בִּכְלַל יְרוּשָׁלַםִ הִיא, מִמַּשְׁמַע דִּכְתִיב, (ויקרא י״ט:כ״ג) וכִי תָבֹאוּ אֶל הָאָרֶץ הַכֹּל בִּכְלָל.</p>\n<p>רַבִּי יְהוּדָה בְּרַבִּי אֶלְעָזָר שָׁאַל לְרַבִּי חִזְקִיָּה, אָמַר לוֹ מֵתִים שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹתָם, לָמָּה לָא יָהִיב נִשְׁמַתְהוֹן בְּאֲתַר דְּאִתְקְבָרוּ תַּמָּן וְיֵיתוּן לְאַחֲיָיא בְּאַרְעָא דְיִשְׂרָאֵל. אָמַר לוֹ נִשְׁבַּע הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנוֹת יְרוּשָׁלַםִ וְשֶׁלֹּא תֵּהָרֵס לְעוֹלָמִים, דְּאָמַר רַבִּי יִרְמְיָה עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְחַדֵשׁ עוֹלָמוֹ וְלִבְנוֹת יְרוּשָׁלַםִ וּלְהוֹרִידָהּ בְּנוּיָה מִלְּמַעְלָה (ס\"א בנין) בְּגִין שֶׁלֹּא יִהָרֵס, וְנִשְׁבַּע שֶׁלא תִּגְלֶה עוֹד כְּנֶסֶת יִשְׂרָאֵל, וְנִשְׁבַּע שֶׁלֹּא יֵהָרֵס בִּנְיַן יְרוּשָׁלַ ם, שֶׁנֶּאֱמַר <Nonei></i>(ישעיהו ס״ב:ד׳) לא יִאָמֵר לָךְ עוֹד עֲזוּבָה וּלְאַרְצֵּךְ לֹא יֵאָמֵר עוֹד שְׁמָמָה. וּבְכָל מָקוֹם שֶׁאַתָּה מוֹצֵּא לא לֹא, הִיא שְׁבוּעָה, הֲדָא הוּא דִכְתִיב, (בראשית ט׳:י״א) וְלֹא יִכָּרֵת כָּל בָּשָׂר עוֹד מִמֵּי הַמַּבּוּל ולֹא יִהְיֶה עוֹד מַבּוּל וְגו' וּכְתִיב, (ישעיהו נ״ד:ט׳) אֲשֶׁר נִשְׁבַּעְתִּי מֵעֲבֹר מֵי נֹחַ. מִכָּאן שֶׁלֹּא לֹא, שְׁבוּעָה. וּמִן לָאו אַתָּה שׁוֹמֵעַ הֵן. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְקַיֵּים עוֹלָמוֹ קִיּוּם שֶׁלֹּא תִּגְלֶה כְּנֶסֶת יִשְׂרָאֵל וְלֹא תֵּהָרֵס בִּנְיַן בֵּית הַמִּקְדָּשׁ, לְפִיכָךְ אֵין מְקַבְּלִין נִשְׁמָתָן אֶלָּא בְּמָקוֹם קַיָּים לְעוֹלָמִים, כְּדֵי שֶׁתִּהְיְה הַנְּשָׁמָה קַיֶּימֶת בַּגּוּף לְעוֹלָמִים, ודָא הוּא דִכְתִיב הַנִּשְׁאָר בְּצִּיּוֹן והַנּוֹתָר בִּיְרוּשָׁלַם קָדוֹשׁ יֵאָמֵר לוֹ וגו'.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה מֵהָכָא (מקרא הוא) הוּא קָדוֹשׁ יְרוּשָׁלַם קָדוֹשׁ הַנּוֹתָר בָּהּ קָדוֹשׁ. הוּא קָדוֹשׁ, דִּכְתִיב, (ישעיהו ו׳:ג׳) קָדוֹשׁ יְיָ צְּבָאוֹת. וּכְתִיב, (הושע י״א:ט׳) בְּקִרְבֵּךְ קָדוֹשׁ. יְרוּשָׁלַםִ קָדוֹשׁ, דִּכְתִיב, (קהלת ח׳:י׳) וּמִמָּקוֹם קָדוֹשׁ יְהַלֵּכוּ. הַנּוֹתָר בָּהּ קָדוֹשׁ, דִּכְתִיב, (ישעיהו ד׳:ג׳) והָיָה הַנִּשְׁאָר בְּצִּיּוֹן וְהַנּוֹתָר בִּיְרוּשָׁלַםִ קָדוֹשׁ יֵאָמֵר לוֹ. מַה קָּדוֹשׁ הָרִאשׁוֹן קַיָּים אַף הַשְּׁאָר קָדוֹשׁ קָדוֹשׁ קַיָּים.</p>\n<p>אָמַר רַבִּי יצְּחָק מַאי דִכְתִיב, (זכריה ח׳:ד׳) עוֹד יֵשְׁבוּ זְקֵנִים וּזְקֵנוֹת בִּרְחוֹבוֹת יְרוּשָׁלַם וְאִישׁ מִשְׁעַנְתּוֹ בְּיָדוֹ מֵרוֹב ימִים. מַאי טִיבוּתָא דָא (כדי) לְמֵיזַל כְּדֵין דִּכְתִיב וְאִישׁ מִשְׁעַנְתּוֹ בְּיָדוֹ. אֶלָּא אָמַר רַבִּי יִצְּחָק (קלה א) עֲתִידִים הַצַּדִּיקִים לֶעָתִיד לָבֹא לְהַחֲיוֹת מֵתִים כֶּאֱלִישָׁע הַנָּבִיא, דִּכְתִיב, (מלכים ב ד׳:כ״ט) וְקַח מִשְׁעַנְתִּי בְּיָדְךָ וָלֵךְ. וּכְתִיב וְשַׂמְתָּ מִשְׁעַנְתִּי עַל פְּנֵי הַנַּעַר. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא דָּבָר שֶׁעֲתִידִים לַעֲשׂוֹת הַצַּדִּיקִים לֶעָתִיד לָבֹא אַתָּה רוֹצֶּה עַכְשָׁיו לַעֲשׂוֹת, מַה כְּתִיב וַיָּשֶׂם אֶת הַמִּשְׁעֶנֶת עַל פְּנֵי הַנַּעַר ואֵין קוֹל וְאֵין עוֹנֶה וְאֵין קָשֶׁב. אֲבָל הַצַּדִּיקִים לֶעָתִיד לָבֹא עָלָה בְּיָדָם הַבְטָחָה זוֹ, דִּכְתִיב, (זכריה י) וְאִישׁ מִשְׁעַנְתּוֹ בְּיָדוֹ כְּדֵי לְהַחֲיוֹת בּוֹ אֶת הַמֵּתִים (מה מתים אותם) מֵהַגֵּרִים שֶׁנִּתְגַיְּירוּ מֵאוּמּוֹת הָעוֹלָם דִּכְתִיב בְּהוּ (ישעיהו ס״ה:כ׳) כִּי הַנַּעַר בֶּן <Nonei></i>מֵאָה שָׁנָה יָמוּת וְהַחוֹטֵא בֶּן מֵאָה שָׁנָה יְקוּלָל. אָמַר רַבִּי יִצְּחָק סוֹפֵיהּ דִּקְרָא מוֹכִיחַ דִּכְתִיב מֵרוֹב יָמִים.</p>\n<p>דָּבָר אַחֵר וַתֹּאמֶר שָׂרָה צְּחוֹק עָשָׂה לִי אֱלהִים. כְּתִיב, (ישעיהו ס״ו:י׳) שִׂמְחוּ אֶת יְרוּשָׁלַםִ וְגִילוּ בָהּ כָּל אֹהֲבֶיהָ שִׂישׂוּ אִתָּהּ מָשׂוֹשׂ כָּל הַמִּתְאַבְּלִים עָלֶיהָ. אָמַר רַבִּי יְהוּדָה לא הָיְתָה שִׂמְחָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, כְּאוֹתָהּ שִׂמְחָה שֶׁעָתִיד לִשְׂמוֹחַ עִם הַצַּדִּיקִים לֶעָתִיד לָבוֹא. וְכָל אֶחָד וְאֶחָד מַרְאֶה בָּאֶצְּבַּע ואוֹמֵר (ישעיהו כ״ה:ט׳) הִנֵּה אֱלהֵינוּ זֶה קִוִּינוּ לוֹ וְיוֹשִׁיעֵנוּ זְה יְיָ קִוִּינוּ לוֹ נָגִילָה ונִשְׂמְחָה בִּישׁוּעָתוֹ. וּכְתִיב, (ישעיהו י״ב:ה׳) זַמְּרוּ יְיָ כִּי גֵאוּת עָשָׂה מוּדַעַת זאת בְּכָל הָאָרֶץ.</p>\n<p>רַבִּי יוֹחָנָן אָמַר לֹא חָזִינָן מַאן דְּפָּרִישׁ הַאי מִלָּה כְּדָוִד מַלְכָּא דְּאָמַר (תהילים ק״ד:כ״ט) תַּסְתִּיר פָּנְיךָ יִבָּהֵלוּן וגו'. מִכָּאן שֶׁאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה רָעָה לְשׁוּם אָדָם, אֶלָּא כְּשֶׁאֵינוֹ מַשְׁגִּיחַ בּוֹ הוּא כָּלֶה מֵאֵלָיו, דִּכְתִיב תַּסְתִּיר פָּנֶיךָ יִבָּהֵלוּן תּוֹסֶף רוּחָם יִגְוָעוּן וְגו'. וְאַחַר כָּךְ (תהילים ק״ד:כ״ט) תְּשַׁלַּח רוּחֲךָ יִבְּרֵאוּן וגו'. וְאַחַר כָּךְ (תהילים ק״ד:ל״א) יְהִי כְבוֹד יְיָ לְעוֹלָם יִשְׂמַח יְיָ בְּמַעֲשָׂיו. וְאֲזַי הַשְּׂחוֹק בָּעוֹלָם דִּכְתִיב, (תהילים קכ״ו:ב׳) אָז יִמָּלֵא שְׂחוֹק פִּינוּ וּלְשׁוֹנֵנוּ רִנָּה. הֲדָא הוּא דִכְתִיב ותֹּאמֶר שָׂרָה צְּחֹק עָשָׂה לִי אֱלהִים לִשְׂמוֹחַ בִּישׁוּעָתוֹ.</p>\n<p>רַבִּי חִיָּיא אָמַר תָּא חֲזֵי, עַד שֶׁהַגּוּף עוֹמֵד בָּעוֹלָם הַזְּה הוּא חָסֵר מִן הַתַּשְׁלוּם, לְאַחַר שֶׁהוּא צַּדִּיק וְהוֹלֵךְ בְּדַרְכֵי יוֹשֶׁר וּמֵת בְּיוֹשְׁרוֹ, נִקְרָא שָׂרָה בְּתַשְׁלוּמוֹ, הִגִּיעַ לִתְחִיַּית הַמֵּתִים הוּא שָׂרָה, כְּדֵי שֶׁלֹּא יֹאמְרוּ שֶׁאַחֵר הוּא שֶׁהֶחֱיָה קוּדְשָׁא בְּרִיךְ הוּא. לְאַחַר שֶׁהוּא חַי, וְשָׂמֵחַ עִם הַשְּׁכִינָה וּמַעֲבִיר הַקָּדוֹשׁ בָּרוּךְ הוּא הַיָּגוֹן מִן הָעוֹלָם דִּכְתִיב, (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוֶת לָנֶצַּח וּמָחָה יְיָ אֱלהִים דִּמְעָה מֵעַל כָּל פָּנִים וגו'. אֲזַי נִקְרָא יִצְּחָק, בִּשְׁבִיל הַצְּחוֹק וְהַשִּׂמְחָה שֶׁיִּהְיֶה לַצַּדִּיקִים לֶעָתִיד לָבֹא.</p>\n<p>רַבִּי יְהוּדָה אֲתָא לְהַהוּא אֲתַר דִּכְפַר חָנָן, שָׁדְרוּ לֵיהּ תִּקְרוֹבְתָּא כָּל בְּנֵי מָאתָא, עָאל לְגַבֵּיהּ רַבִּי אַבָּא, אָמַר לֵיהּ אֵימָתַי לֵיזִיל מַר, אָמַר לֵיהּ אֶפְרַע מַה דְּיָהֲבוּ לִי <Nonei></i>בְּנִי מָאתָא וְאֵיזִיל, אָמַר לֵיהּ לָא לֵיחוּשׁ מַר לְהַאי תִּקְרוֹבְתָּא לְאוֹרַיְיתָא הוּא דְּעֲבְדוּ, וְלָא יְקַבְּלוּ מִנָּךְ כְּלוּם, אָמַר לֵיהּ וְלָא מְקַבְּלֵי מִלֵּי דְאוֹרַיְיתָא, אָמַר אִין. אָתוּ כָּל בְּנִי מָאתָא. אָמַר לֵיהּ רַבִּי יְהוּדָה כֻּלְּהוֹן מָארֵי מְתִיבְתָּא, אָמַר לֵיהּ, ואִי אִית מַאן דְּלָא יָאוֹת לְמֵיתַב הָכָא לֵיקוּם וְלֵיזִיל. קָם רַבִּי אַבָּא וְאַבְדִּיל מִנַּיְיהוּ עֲשָׂרָה דִי יְקַבְּלוּן מִנִּיהּ, אָמַר לְהוּ יְתִּיבוּ בַּהֲדֵי גַבְרָא רַבָּא דְּנָא, ואֲנָא ואִנּוּן נְקַבֵּל לְמָחָר וְנְתִיב עִמֵּיהּ. אָזְלוּ. ואִנּוּן עֲשָׂרָה דְּאִשְׁתָּאֲרוּ עִמֵּיהּ יְתִיבוּ (אנון עשרה) וְלָא אָמַר כְּלוּם, אָמְרוּ לֵיהּ אִי רְעוּתֵיהּ דְּמַר נְקַבֵּל אַפֵּי שְׁכִינְתָּא. אָמַר לְהוּ והָא רַבִּי אַבָּא לֵית הָכָא, שָׁדְרוּ בַּהֲדֵיהּ וְאָתָא.</p>\n<p>פָּתַח וְאָמַר וַיְיָ פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר. מַאי שִׁנּוּיָא הֲוָה הָכָא, הֲוָה לֵיהּ לְמֵימַר וַיְיָ זָכָר אֶת שָׂרָה כְּמָה דְּאָמַר (בראשית ל׳:כ״ב) וַיִּזְכֹּר אֱלהִים אֶת רָחֵל. דְּאֵין פְּקִידָה אֶלָּא עַל מַה דְּהֲוָה בְּקַדְמִיתָא. אֶלָּא בְּקַדְמִיתָא הֲוָה, דִּכְתִיב שׁוֹב אָשׁוּב אֵלֶיךָ כָּעֵת חַיָּה, וְעַל אוֹתוֹ עִנְיָן נֶאֱמַר שֶׁפָּקַד עַכְשָׁיו, מַשְׁמַע דִּכְתִיב כַּאֲשֶׁר אָמָר, דְּאִלְמָלֵא לֹא נְאֱמַר כַּאֲשֶׁר אָמָר לֵימָא זְכִירָה, אֲבָל פָּקַד הַהִיא מִלָּה דְּאָמַר לַמּוֹעֵד אָשׁוּב אֵלֶיךָ.</p>\n<p>לְבָתַר אָמַר הָכִי, הַאי צַּדִּיק דְּזָכֵי לְמֵיסַק לְהַהוּא יְקָר עִלָּאָה, דִּיוּקְנֵיהּ מִתְפַּתַּח בְּכָרְסֵי יְקרִיהּ, וכֵן לְכָל צַּדִּיק וְצַּדִּיק דִּיוּקְנֵיהּ לְעֵילָא כַּד הֲוָה לְתַתָּא לְאַבְטָחָא לְהַהִיא נִשְׁמָתָא קַדִּישָׁא.</p>\n<p>וְהַיְינוּ דְּאָמַר רַבִּי יוֹחָנָן, מַאי דִכְתִיב, (חבקוק ג׳:י״א) שֶׁמֶשׁ יָרֵחַ עָמַד זְבֻלָה, דְּזָהֲרָן גּוּפָא וְנִשְׁמָתָא דְּקָיְימִין בְּאִדְרָא קַדִּישָׁא עִלָּאָה דִלְעֵילָא כִּדִיוּקְנָא דְּהֲוָה קָאִים בְּאַרְעָא, והַהִיא דִיוּקְנָא (ס\"א מזונה) מִמְּזוֹנָהּ הֲנָאַת נִשְׁמָתָא, והַהִיא עֲתִידָה לְאִתְלַבַּשׁ בְּהַאי גַרְמָא דְּאִשְׁתָּאַר בְּאַרְעָא, וְאַרְעָא מִתְעֲבַר מִנִּיהּ וטָפַל טִינֵיהּ לְבָרָא, וְדָא הוּא דְּאִתְקְרֵי קְדוּשָׁה.</p>\n<p>וְכַד קָיְימָא דִּיוּקְנָא הַהִיא דִלְעֵילָא, אֲתָא בְּכָל יַרְחָא <Nonei></i>לְסָגְדָא קַמֵּי מַלְכָּא קַדִּישָׁא בְּרִיךְ הוּא דִּכְתִיב, (ישעיהו ס״ו:כ״ג) והָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ. והוּא מְבַשֵּׂר לֵיהּ וְאָמַר לַמּוֹעֵד אָשׁוּב אֵלֶיךָ, לְהַהוּא זְמַן דְּעָתִיד לְאַחֲיָא מֵיתַיָא עַד דְּאִתְפַּקְדַת לְהַהוּא זִמְנָא כְּמָה דְאִתְבַּשַּׂר הֲדָא הוּא דִכְתִיב וַיְיָ פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר. וְהַהוּא יוֹמָא דְּחָדֵי קוּדְשָׁא בְּרִיךְ הוּא בְּעוֹבָדוֹי הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:ל״א) יִשְׂמַח יְיָ בְּמַעֲשָׂיו.</p>\n<p>אָמַר לֵיהּ רַבִּי אַבָּא נֵימָא לָן מַר עַל פָּרָשָׁתָא לְבָתַר, אָמַר יָאוֹת לְכוֹן לְמִפְתַּח פָּרְשָׁתָא דָא. פָּתַח וְאָמַר וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וְהָאֱלהִים נִסָּה אֶת אַבְרָהָם וְגו' וַיֹּאמֶר קַח נָא אֶת בִּנְךָ אֶת יְחִידְךָ אֲשֶׁר אָהַבְתָּ וְגו'. הָכָא אִית לְאִסְתַּכָּלָא הַאי אוּמָנָא דְּאַפִּיק כַּסְפָּא מִמְקוֹרָא דְאַרְעָא, מַאי עֲבַד. בְּקַדְמִיתָא מְעֲיִּיל לֵיהּ בְּנוּר דָּלִיק עַד דְּנָפִיק מִנִּיהּ כָּל זוּהֲמָא דְאַרְעָא, וְהָא אִשְׁתָּאֲרַת כַּסְפָּא אֲבָל לָא כַסְפָּא שְׁלֵימָתָא, לְבָתַר מַאי עָבִיד, מְעֲיִּיל לֵיהּ בְּנוּרָא כִּדְבְקַדְמִיתָא וּמַפִּיק מִנֵּיהּ סְטָיְיפֵי כְּמָא דְאַתְּ אָמֵר, (משלי כ״ה:ד׳) הָגוֹ סִיגִים מִכָּסֶף וְגו' וּכְדֵין הוּא כַּסְפָּא שְׁלֵימָתָא בְּלָא עִרְבּוּבְיָא.</p>\n<p>כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מְעֲיִּיל הַאי גוּפָא תְּחוֹת אַרְעָא עַד דְּמִתְרְקַב כּוּלֵיהּ וְנָפִיק מִנֵּיהּ כָּל זוּהֲמָא בִּישָׁא, ואִשְׁתָּאַר הַהוּא תַּרְוָוד רֶקֶב וְאִתְבְּנֵי גוּפָא מִנִּיהּ, וְעַד כְּעָן הוּא גוּפָא לָא שְׁלִים.</p>\n<p>לְבָתַר הַהוּא יוֹמָא רַבָּא דִּכְתִיב, (זכריה י״ד:ז׳) והָיָה יוֹם אֶחָד הוּא יִוָּדַע לַיְיָ לא יוֹם וְלֹא לַיְלָה, מִתְטַמְּרָן כֻּלְּהוּ בְּעַפְרָא כִּדְבְקַדְמִיתָא מִן קֳדָם דְּחִילוּ ותַקִּיפוּ דְּקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב, (ישעיהו ב׳:י״ט) וּבָאוּ בִּמְעָרוֹת צֻּרִים וּבִמְחִלּוֹת עָפָר מִפְּנֵי פַּחַד יְיָ וּמֵהֲדַר גְּאוֹנוֹ וְגו'. וְנָפִיק נִשְׁמָתַיְיהוּ וּמִתְעַכֵּל הַהוּא תַּרְוָוד רֶקֶב ואִשְׁתָּאַר גּוּפָּא דְּאִתְבְּנֵי תַּמָּן (נ\"א נהורא) דִּילֵיהּ כִּנְהוֹרָא דְשִׁמְשָׁא וּכְזָהֲרָא דִּרְקִיעָא דִּכְתִיב, (דניאל י״ב:ג׳) והַמַּשְׂכִּילִים יַזְהִירוּ כְּזֹהַר הָרָקִיעַ וגו'. וּכְדֵין כַּסְפָּא שְׁלִים, גּוּפָא שְׁלֵימָא בְּלָא עִרְבּוּבְיָא אַחְרָנַיְתָא. (מכאן עד סוף מדרש הנעלם בדף קיח אינו נמצא בז\"ג רק בז\"ק)</p>\n<p>דְּאָמַר רַבִּי יַעֲקֹב <Nonei></i>גּוּפָא דְנָהִיר יִרְמֵי קוּדְשָׁא בְּרִיךְ הוּא מִלְּעֵילָא דִּכְתִיב, (ישעיהו כ״ו:י״ט) כִּי טַל אוֹרוֹת טַלֶּךָ. וּכְתִיב (ישעיהו כ״ב:י״ז) הִנֵּה יְיָ מְטַלְטֶלְךָ וגו'. וּכְדֵין יִתְקְרוּן קַדִּישִׁין עִלָּאִין דִּכְתִיב, (ישעיהו ד׳:ג׳) קָדוֹשׁ יֵאָמֶר לוֹ. וְדָא הוּא דְּאִתְקְרֵי תְּחִיַּית הַמֵּתִים דְּבַתְרַיְיתָא, וְדָא הוּא (כספא שלים גופא שלימא) (נ\"א נסיונא) בַּתְרַיְיתָא וְלָא יִטְעֲמוּן עוֹד טַעֲמָא דְמוֹתָא דִּכְתִיב בִּי נִשְׁבַּעְתִּי נְאֻם יְיָ כִּי יעַן אֲשֶׁר עָשִׂיתָ וְגו' כִּי בָּרֵךְ אֲבָרֶכְךָ וְגו'. וּבְהַהוּא זִמְנָא מַצְּלוּ צַּדִּיקַיָּיא דְּלָא יִתְנַסּוּן בְּדָא יתִּיר.</p>\n<p>מַה כְּתִיב וַיִּשָּׂא אַבְרָהָם אֶת עֵינָיו וַיַּרְא וְהִנֵּה אַיִל וגו'. אִלֵּין שְׁאָר חַיָּיבֵי עַלְמָא דְּאִתְקְרוּן אֵילִים כְּמָא דְאַתְּ אָמֵר, (ישעיהו ס׳:ז׳) אֵילֵי נְבָיוֹת יְשָׁרְתוּנֶךְ וּמְתַרְגְּמִינָן רַבְרְבֵי נְבָיוֹת. אַחַר נֶאֱחַז בַּסְּבַךְ וְגו' כְּמָא דְאַתְּ אָמֵר, (תהילים ע״ה:י״א) וְכָל קַרְנֵי רְשָׁעִים אֲגַדֵּעַ. (וישלח אברהם וגו) וַיִּלֶךְ אַבְרָהָם וַיִּקַּח אֶת הָאַיִל וְגו'. דְּאִנּוּן מְזוּמָנִין לְאִתְנַסָּאָה בְּכָל נִסְיוֹנָא בִּישָׁא, וְיִשְׁתָּאֲרוּן הַצַּדִּיקִים לְעַלְמָא דְאָתֵי כְּמַלְאָכִין עִלָּאִין קַדִּישִׁין לְיַחֲדָא שְׁמֵיהּ, וּבְגִין כָּךְ כְּתִיב, (זכריה י״ד:ט׳) בַּיּוֹם הַהוּא יִהְיְה יְיָ אֶחָד וּשְׁמוֹ אֶחָד וגו'.</p>\n<p>אָמַר לֵיהּ (נ\"א אמר לון) רַבִּי יְהוּדָה מִכָּאן וּלְהָלְאָה אַצְּלָחוּ פִּתְחָא. עָאל יוֹמָא אָחֳרָא עָאלוּ קַמֵּיהּ כָּל בְּנִי מָתָא, אָמְרוּ לֵיהּ לֵימָא לָן מַר מִלַּיָיא דְאוֹרַיְיתָא בְּפָרְשָׁתָא דְּקָרֵינָן בָּהּ יוֹמָא דְשַׁבַּתָּא וַיְיָ פָּקַד אֶת שָׂרָה. קָם בֵּינֵי עַמּוּדֵי, פָּתַח וְאָמַר וַיְיָ פָּקַד אֶת שָׂרָה וְגו'. שָׁלשׁ מַפְתֵּחוֹת בְּיָדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא ולא מְסָרָם לא בְּיַד מַלְאָךְ וְלֹא בְּיַד שָׂרָף. מַפְתֵּחַ שֶׁל חַיָּה וְשֶׁל גְּשָׁמִים וְשֶׁל תְּחִיַּית הַמֵּתִים. בָּא אֵלִיָּהוּ וְנָטַל הַשְּׁנַיִם שֶׁל גְּשָׁמִים וְשֶׁל תְּחִיַּית הַמֵּתִים. וְאָמַר רַבִּי יוֹחָנָן לֹא נִמְסַר בְּיַד אֵלִיָּהוּ אֶלָּא אַחַת. דְּאָמַר רַבִּי יוֹחָנָן כְּשֶׁבִּקֵּשׁ אֵלִיָּהוּ לְהַחֲיוֹת בֶּן הַצָּרְפִית אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, לָא יָאוֹת לָךְ לְמֵיסַב בִּידָךְ שְׁתֵּי מַפְתֵּחוֹת, אֶלָּא תֵּן לִי מַפְתֵּחַ הַגְּשָׁמִים וּתְחַיֶּה הַמֵּת. והַיְינוּ דִכְתִיב, (מלכים א י״ח:א׳) לֵךְ הֵרָאֵה אֶל אַחְאָב וְגו' וְאֶתְּנָה מָטָר. לא אָמַר ותֵן מָטָר אֶלָּא וְאֶתְּנָה.</p>\n<p>וְהָא אֱלִישָׁע הֲווּ <Nonei></i>לֵיהּ. אִין. לְקַיֵּים פִּי שְׁנַיִם בְּרוּחוֹ שֶׁל אֵלִיּהוּ, אֶלָּא שְׁלָשְׁתָּם לא מְסָרָם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיַד שָׁלִיחַ, דְּאָמַר רַבִּי סִימּוֹן בֹּא וּרְאֵה כֹּחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, בְּפַעַם אַחַת מְחַיִּה מֵתִים וּמוֹרִיד שְׁאוֹל וַיָּעַל, מַזְרִיחַ מְאוֹרוֹת וּמוֹרִיד גְּשָׁמִים, מַצְּמִיחַ חָצִּיר, מְדַשֵּׁן יְבוּלִים, פּוֹקֵד עֲקָרוֹת, נוֹתֵן פַּרְנָסוֹת, עוֹזֵר דַּלִּים, סוֹמֵךְ נוֹפְלִים, זוֹקֵף כְּפוּפִים, מְהַעֲדֵא מַלְכִין וּמְהָקֵם מַלְכִין, וְהַכֹּל בִּזְמַן אֶחָד וּבְרֶגַע אֶחָד וּבְבַת אַחַת מַה שֶּׁאֵין שָׁלִיחַ לְעוֹלָם יָכוֹל לַעֲשׂוֹתוֹ.</p>\n<p>תַּנְיָא אָמַר רַבִּי יוֹסֵי כָּל מַה שֶּׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵינוֹ צָּרִיךְ לַעֲשׂוֹת אֶלָּא בְּדִבּוּר, דְּכֵיוָן דְאָמַר מִמְּקוֹם קְדוּשָׁתוֹ יְהֵא כָךְ מִיָּד נַעֲשָׂה. בֹּא וּרְאֵה כֹּחַ גְּבוּרָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא דִּכְתִיב, (תהילים ל״ג:ו׳) בִּדְבַר יְיָ שָׁמַיִם נַעֲשׂוּ. דְּאָמַר רַבִּי יוֹחָנָן (יהודה) מַאי דִכְתִיב, (שמות י״ב:י״ב) וְעָבַרְתִּי בְּאֶרֶץ מִצְּרַיִם אֲנִי וְלֹא מַלְאָךְ וגו'.</p>\n<p>אִי הָכִי יְקָרָא סַגִּיאָה הוּא לְמִצְּרָאֵי, דְּלָא דָמֵי מַאן דְּתָפַשׂ מַלְכָּא לְמַאן דְּתָפַשׂ הֶדְיוֹטָא. וְעוֹד אֵין לְךָ אוּמָה מְזוּהֱמֶת בְּכָל טוּמְאָה כְּמוֹ הַמִּצְּרִים דִּכְתִיב בְּהוּ (יחזקאל כ״ג:כ׳) אֲשֶׁר בְּשַׂר חֲמוֹרִים בְּשָׂרָם וְגו' שֶׁהֵם חֲשׁוּדִים עַל מִשְׁכַּב זָכוּר, וְהֵם בָּאִים מֵחָם שֶׁעָשָׂה מַה שֶּׁעָשָׂה לְאָבִיו וְקִלֵּל אוֹתוֹ וְלִכְנַעַן בְּנוֹ. וְכִי לֹא הָיָה לְהַקָּדוֹשׁ בָּרוּךְ הוּא מַלְאָךְ אוֹ שָׁלִיחַ לְשַׁגֵּר לַעֲשׂוֹת נְקָמָה בְּמִצְּרַיִם כְּמוֹ שֶׁעָשָׂה בְּאַשּׁוּר שֶׁהָיָה בְּנוֹ שֶׁל שֵׁם דִּכְתִיב, (בראשית י׳:כ״ב) וּבְנֵי שֵׁם עֵילָם וְאַשּׁוּר. ושֵׁם הָיָה כֹּהֵן גָּדוֹל וְנִתְבָּרֵךְ שֶׁנְּאֱמַר (בראשית ט׳:כ״ו) בָּרוּךְ יְיָ אֱלהֵי שֵׁם. וְהָיָה לְשֵׁם הַגְּדוּלָּה וְהַבְּרָכָה עַל אֶחָיו. וּכְתִיב בָּם (ישעיהו ל״ז:ל״ו) וַיִּצֵּא מַלְאַךְ יְיָ וַיַּכֶּה בְּמַחֲנֶה אַשּׁוּר. וְעַל יְדֵי שָׁלִיחַ נַעֲשָׂה, כָל שֶׁכֵּן הַמִּצְּרִים שֶׁהֵם מְזוּהָמִים יוֹתֵר מִכָּל אוּמָה, ואָמַר אֲנִי וְלֹא מַלְאָךְ.</p>\n<p>אֶלָּא אָמַר רַבִּי יְהוּדָה מִכָּאן לָמַדְנוּ כֹּחַ גְּבוּרָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּמַעֲלָתוֹ שֶׁהוּא גָּבוֹהַּ עַל הַכֹּל. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא אוּמָה זוֹ שֶׁל מִצְּרַיִם מְזוּהֱמֶת וּמְטוּנֶפֶת, ואֵין רָאוּי לְשַׁגֵּר מַלְאָךְ ולא שָׂרָף, דָּבָר קָדוֹשׁ בֵּין רְשָׁעִים אֲרוּרִים מְטוּנָפִים, אֶלָּא אֲנִי <Nonei></i>עוֹשֶׂה מַה שֶּׁאֵין יָכוֹל לַעֲשׂוֹת מַלְאָךְ וְלֹא שָׂרָף ולא שָׁלִיחַ. שֶׁאֲנִי אוֹמֵר מִמְּקוֹם קְדוּשָּׁתִי יְהֵא כָךְ וּמִיָּד נַעֲשָׂה, מַה שֶּׁאֵין הַמַּלְאָךְ יָכוֹל לַעֲשׂוֹתוֹ. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא, מִמְּקוֹם קְדוּשָּׁתוֹ אוֹמֵר יְהֵא כָךְ וּמִיָּד נַעֲשָׂה מַה שֶּׁהוּא רוֹצֶּה לַעֲשׂוֹת. וּלְפִיכָךְ לא נַעֲשֵׂית נְקָמָה זוֹ עַל יְדֵי מַלְאָךְ וְשָׁלִיחַ, בִּשְׁבִיל קְלוֹן הַמִּצְּרִים, וּלְהַרְאוֹת גְּדוּלָּתוֹ שֶׁל מָקוֹם שֶׁלֹּא רָצָּה שֶׁיִּכָּנְסוּ בֵּינֵיהֶם דָּבָר קָדוֹשׁ, וְעַל הַדֶּרֶךְ הַזֶּה נֶאֱמַר אֲנִי וְלֹא מַלְאָךְ. אֲנִי יָכוֹל לַעֲשׂוֹתוֹ וְלֹא מַלְאָךְ.</p>\n<p>כַּיּוֹצֵּא בּוֹ אָמַר רַבִּי יְהוּדָה מַאי דִכְתִיב, (יונה ב׳:י״א) וַיֹּאמֶר יְיָ לַדָּג. וְכַמָּה צַּדִּיקִים וַחֲסִידִים מִיִּשְׂרָאֵל שֶׁלֹּא דִּבֵּר עִמָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבָא לְדַבֵּר עִם הַדָּג דָּבָר שֶׁאֵינוֹ מַכִּיר וְיוֹדֵעַ. אֶלָּא אָמַר רַבִּי יְהוּדָה כֵּיוָן שֶׁעָלְתָה תְּפִלָּתוֹ שֶׁל יוֹנָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, מִמְּקוֹם קְדוּשָּׁתוֹ אָמַר בִּשְׁבִיל שֶׁיָּקִיא הַדָּג אֶת יוֹנָה אֶל הַיַּבָּשָׁה. למ\"ד לַדָּג כְּמוֹ בִּשְׁבִיל, כְּלוֹמַר וַיֹּאמֶר יְיָ בִּשְׁבִיל הַדָּג שֶׁיָּקִיא אֶת יוֹנָה אֶל הַיַּבָּשָׁה. מִמְּקוֹם קְדוּשָּׁתוֹ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, יְהֵא כָךְ וּמִיָּד נַעֲשָׂה, מַה שֶׁאֵין שָׁלִיחַ יָכוֹל לַעֲשׂוֹתוֹ.</p>\n<p>תַּנְיָא אָמַר רַבִּי שִׁמְעוֹן מַפְתֵּחַ שֶׁל חַיָה בְּיָדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, הִיא, וּבְעוֹד שֶׁהִיא יוֹשֶׁבֶת עַל הַמַּשְׁבֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא מְעַיֵּין בְּאוֹתוֹ הַוְּלַד אִם רָאוּי הוּא לָצֵּאת לָעוֹלָם (יוצא ו) פּוֹתֵחַ דַּלְתוֹת בִּטְנָהּ וְיוֹצֵּא, וְאִם לָאו סוֹגֵר דַּלְתוֹתֶיהָ וּמֵתוּ שְׁנֵיהֶם. אִי הָכִי לא יִצֵּא רָשָׁע לָעוֹלָם. אֶלָּא הָכִי תָּנִינָן עַל שָׁלשׁ עֲבֵירוֹת נָשִׁים מֵתוֹת וְכוּ' (אמר רבי שמעון והא) וְאָמַר רַבִּי יִצְּחָק לָמָּה אִשָּׁה מַפֶּלֶת פְּרִי בִטְנָהּ. אֶלָּא אָמַר רַבִּי יִצְּחָק הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה אוֹתוֹ הָעוּבָּר שֶׁאֵינוֹ רָאוּי לָצֵּאת לָעוֹלָם וּמַקְדִּים לַהֲמִיתוֹ בִּמְעֵי אִמּוֹ שֶׁנֶּאֱמַר (בראשית ו׳:ד׳) הַנְּפִילִים הָיוּ בָּאָרֶץ בַּיָּמִים הָהֵם. הַנְּפִלִים כְּתִיב בְּלֹא יוּד רִאשׁוֹנָה. וְלָמָּה, בִּשְׁבִיל שֶׁאַחֲרֵי כֵן בָּאוּ בְּנֵי הָאֱלהִים אֶל בְּנוֹת הָאָדָם וְיָלְדוּ לָהֶם בִּזְנוּת וַיִּרְבּוּ <Nonei></i>מַמְזֵרִים בָּעוֹלָם.</p>\n<p>הֵמָּה הַגִּבּוֹרִים אֲשֶׁר מֵעוֹלָם. שֶׁאֵין גִּבּוֹר וּפָרִיץ ועָרִיץ כְּמוֹ הַמַּמְזִר. אַנְשֵׁי הַשֵּׁם, שֶׁהַכֹּל יַכִּירוּ לִקְרוֹתוֹ הַשֵּׁם הַיָּדוּעַ מַמְזִר, דְּכֵיוָן שֶׁרוֹאִים מַעֲשָׂיו שֶׁהוּא פָּרִיץ וְעָרִיץ וְגִבּוֹר הַכֹּל יִקְרְאוּהוּ אוֹתוֹ שֵׁם. וּמַה דְאָמַר רַבִּי שִׁמְעוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא מְעַיֵּין בְּאוֹתוֹ הַוְּלַד. אֵין לְךָ רָשָׁע בָּעוֹלָם מֵאוֹתָם הָרְשָׁעִים הַיּוֹצְּאִים לָעוֹלָם שֶׁאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא מְעַיֵּין בּוֹ ורוֹאֶה אִם אוֹתוֹ הַגּוּף יַנִּיחַ בֵּן צַּדִּיק וְכָשֵׁר, אוֹ שֶׁיַּצִּיל לְאָדָם מִיִּשְׂרָאֵל מִמִּיתָה מְשׁוּנָּה, אוֹ שֶׁיַּעֲשֶׂה טוֹבָה אַחַת, וּבִשְׁבִיל כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹצִּיאוֹ לָעוֹלָם.</p>\n<p>בְּיוֹמוֹי דְרַבִּי יוֹסֵי הֲווּ אִנּוּן פְּרִיצֵּי דְּהֲווּ מְשַׁדְּדֵי בְּטוּרַיָּיא עִם פְּרִיצֵּי אוּמּוֹת הָעוֹלָם, וְכַד מַשְׁכְּחֵי בַּר נָשׁ וְתָפְשֵׂי לֵיהּ לְקָטְלֵיהּ, הֲווּ אָמְרִין לֵיהּ מַה שְּׁמָךְ, אִי הֲוָה יוּדָאי הֲווּ אָזְלִין עִמֵּיהּ וּמַפְקִין לֵיהּ מִן טוּרַיָּיא, וְאִי הֲוָה בַּר נָשׁ אַחֲרִינָא קָטְלֵי לֵיהּ. (והא) והֲוָה אָמַר רַבִּי יוֹסֵי אִתְחֲזוּן אִנּוּן בְּכל הַאי לְמֵיעַל לְעַלְמָא דְאָתֵי.</p>\n<p>תָּנוּ רַבָּנָן ג' דְּבָרִים הַלָּלוּ אֵינָן בָּאִן לָעוֹלָם אֶלָּא בְּקוֹלוֹת, קוֹל חַיָּה דִּכְתִיב, (בראשית ג׳:ט״ז) בְּעֶצֶּב תֵּלְדִי בָּנִים וּכְתִיב, (בראשית ל׳:כ״ב) וַיִּשְׁמַע אֵלֶיהָ אֱלֹהִים. קוֹל גְּשָׁמִים דִּכְתִיב, (תהילים כ״ט:ג׳) קוֹל יְיָ עַל הַמָּיִם וּכְתִיב, (מלכים א י״ח:מ״א) כִּי קוֹל הֲמוֹן הַגָּשֶׁם. קוֹל תְּחִיַּית הַמֵּתִים דִּכְתִיב, (ישעיהו מ׳:ג׳) קוֹל קוֹרֵא בַּמִּדְבָּר. מַאי בָּעֵי הָכָא קָלָא בְּמַדְבְּרָא. אֶלָּא אָמַר רַבִּי זְרִיקָא אִלֵּין אִנּוּן קָלַיָיא לְאַתְעָרָא מֵתֵי מִדְבָּר, וּמִכָּאן דְּהוּא הַדִּין לְכָל הָעוֹלָם. אָמַר רַבִּי יוֹחָנָן הָא תְּנַן כְּשֶׁנִּכְנַס אָדָם לַקֶּבֶר נִכְנַס בְּקוֹלוֹת. כְּשֶׁיָּקוּמוּ בִּתְחִיַּית הַמֵּתִים אֵינוֹ דִּין שֶׁיָּקוּמוּ בְּקוֹלֵי קוֹלוֹת.</p>\n<p>אָמַר רַבִּי יעֲקֹב עֲתִידָה בַּת קוֹל לִהְיוֹת מִתְפּוֹצֶּצֶּת בְּבָתֵּי קְבָרוֹת וְאוֹמֶרֶת (ישעיהו כ״ו:י״ט) הָקִיצּוּ ורַנְּנוּ שׁוֹכְנִי עָפָר, וַעֲתִידִים לִחְיוֹת בְּטַל שֶׁל אוֹר גָּדוֹל שֶׁל מַעְלָה דִּכְתִיב, (ישעיהו כ״ו:י״ט) כִּי טַל אוֹרוֹת טַלֶּךָ וְאֶרֶץ רְפָאִים תַּפִּיל. אכי\"ר, (ע\"כ מדרש הנעלם).</p>\n<p><Nonei></i>וַיְיָ פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר, דִּכְתִיב לַמּוֹעֵד אָשׁוּב אֵלֶיךָ כָּעֵת חַיָּה וּלְשָׂרָה בֵן. וְתָנִינָן פָּקַד אֶת שָׂרָה, פְּקִידָה לְנוּקְבָא, זְכִירָה לִדְכוּרָא, וּבְגִין כָּךְ וַיְיָ פָּקַד אֶת שָׂרָה, כַּאֲשֶׁר אָמַר, דִּכְתִיב שׁוֹב אָשׁוּב אֵלֶיךָ כָּעֵת חַיָּה וְגו', מֵהָכָא מַשְׁמַע דְּאָמַר (קב ב) וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךָ, וַיֹּאמֶר סְתָם, דְּאִיהוּ הֲוָה וְלָא שְׁלִיחָא אָחֳרָא:</p>"],[9520011243,"<p>וַיַּעַשׂ יְיָ לְשָׂרָה וְגו'. כֵּיוָן דְּאָמַר וַיְיָ פָּקַד אֶת שָׂרָה, מַהוּ וַיַּעַשׂ יְיָ לְשָׂרָה. אֶלָּא הָכִי תָּנִינָן דְּאִיבָּא דְּעוֹבָדוֹי דְקוּדְשָׁא בְּרִיךְ הוּא מֵהַהוּא נָהָר דְּנָגִיד וְנָפִיק מֵעֵדֶן אִיהוּ, וְאִיהוּ נִשְׁמַתְהוֹן דְּצַדִּיקַיָּיא, וְאִיהוּ מַזָּלָא דְּכָל בִּרְכָאן טָבָאן וְגִשְׁמֵי בִּרְכָאן נָזְלֵי מִנֵּיהּ וּמִתַּמָּן נָפְקֵי, דִּכְתִיב לְהַשְׁקוֹת אֶת הַגָּן, דְּאִיהוּ מַזִּיל וּמַשְׁקֶה מֵעֵילָא לְתַתָּא, בְּגִין דְּבָנֵי (נשא) בְּהַאי (קפא א) מַזָּלָא תַּלְיָין וְלָא בְּאֲתַר אָחֳרָא. וְעַל דָּא כְּתִיב וַיְיָ פָּקַד אֶת שָׂרָה פְּקִידָה בִּלְחוֹדוֹי.</p>\n<p>וַיַּעַשׂ יְיָ לְשָׂרָה. עֲשִׂיָּיה אִיהוּ לְעֵילָא מֵהַאי דַרְגָא (קיב ב) כְּמָה דְאִתְּמָר דְּהָא בְּמַזְּלָא תַּלְיָיא, וְעַל דָּא כָּאן פְּקִידָה וְכָאן עֲשִׂיָּיה. וּבְגִין כָּךְ אָמַר יְיָ וַיְיָ וְכֹלָּא חַד.</p>\n<p>רַבִּי אֶלְעָזָר פָּתַח וְאָמַר (תהילים קכ״ז:ג׳) הִנֵּה נַחֲלַת יְיָ בָּנִים שָׂכָר פְּרִי הַבָּטֶן. הִנֵּה נַחֲלַת יְיָ, אַחְסַנְתָּא לְאִתְאַחֲדָא בַּיְיָ דְּלָא יִתְעֲבַר מִינָהּ לְעָלְמִין, דְּבַר נָשׁ דְּזָכֵי לִבְנִין בְּהַאי עַלְמָא זָכֵי בְּהוּ לְמֵיעַל לְפַרְגּוֹדָא בְּעַלְמָא דְאָתֵי. בְּגִין דְּהַהוּא בְּרָא דְּשָׁבִיק בַּר נָשׁ וְזָכֵי בֵּיהּ בְּעַלְמָא דָא, אִיהוּ יִזְכֵּי לֵיהּ לְעַלְמָא דְאָתֵי, וְזָכֵי לְאַעָלָא בֵּיהּ לְנַחֲלַת יְיָ. מַאן נַחֲלַת יְיָ, דָּא אֶרֶץ הַחַיִּים. וְהָכִי קָרָא לָהּ לְאֶרֶץ יִשְׂרָאֵל דְּאִיהִי אֶרֶץ הַחַיִּים.</p>\n<p>דָּוִד מַלְכָּא (קרא ליה) נַחֲלַת יְיָ דִּכְתִיב, (שמואל א כ״ו:י״ט) כִּי גֵּרְשׁוּנִי הַיּוֹם מֵהִסְתַּפֵּחַ בְּנַחֲלַת יְיָ לֵאמֹר לֵךְ עֲבֹד אֱלהִים אֲחֵרִים, וּבְגִין כָּךְ הִנֵּה נַחֲלַת יְיָ <Nonei></i>בָּנִים. מַאן אַזְכֵּי לֵיהּ לְבַר נָשׁ. בְּנִין. אִי זָכֵי בְּהוּ בְּהַאי עַלְמָא, שָׂכָר פְּרִי הַבָּטֶן, אַגְרָא וְחוּלָקָא טָבָא בְּהַהִיא עַלְמָא, בְּהַהוּא אִיבָּא דְּמֵעוֹי אִיהוּ דְּזָכֵי בַּר נָשׁ בְּהַהוּא עַלְמָא בְּהוּ.</p>\n<p>תָּא חֲזֵי, הִנֵּה נַחֲלַת יְיָ בָּנִים. יְרוּתָא וְאַחְסַנְתָּא דְּאִיבִּין דְּעוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא מִלְּעֵילָא אִיהוּ מֵאִילָנָא דְחַיֵּי, דְּהָא מִתַּמָּן זָכֵי בַּר נָשׁ לִבְנִין כְּמָא דְאַתְּ אָמֵר, (הושע י״ד:ט׳) מִמֶּנִּי פֶּרְיְךָ נִמְצָא. מַה כְּתִיב, (תהילים קכ״ז:ה׳) אַשְׁרֵי הַגֶּבֶר אֲשֶׁר מִלֵּא אֶת אַשְׁפָּתוֹ מֵהֶם לא יֵבוֹשׁוּ וְגו'. אַשְׁרֵי בְּעַלְמָא דֵין וְאַשְׁרֵי בְּעַלְמָא דְאָתֵי.</p>\n<p>לֹא יֵבוֹשׁוּ כִּי יְדַבְּרוּ אֶת אוֹיְבִים בַּשָּׁעַר. מַאן אוֹיְבִים בַּשָּׁעַר. אִלֵּין מָארִיהוֹן דְּדִינִין, דְּכַד נִשְׁמָתָא נָפְקַת מֵהַאי עַלְמָא, כַּמָּה אִנּוּן מָרֵיהוֹן דְּדִינִין דְּזַמִּינִין קַמֵּיהּ, עַד לָא יֵיעוּל לְדוּכְתֵּיהּ בַּשָּׁעַר בְּהַהוּא תַּרְעָא דְּיֵיעוּל תַּמָּן, בְּגִין דְּמַשְׁכּוֹנִין שָׁבִיק בְּהַאי עַלְמָא וּבְגִינֵיהוֹן יִזְכֵּי בְּהַהוּא עַלְמָא וְעַל דָּא לא יֵבוֹשׁוּ כִּי יְדַבְּרוּ אֶת אוֹיְבִים בַּשָּׁעַר.</p>\n<p>רַבִּי יְהוּדָה וְרַבִּי יוֹסֵי הֲווּ אָזְלֵי בְּאָרְחָא. אָמַר לֵיהּ רַבִּי יְהוּדָה לְרַבִּי יוֹסֵי פְּתַח פּוּמָךְ וְלָעֵי בְּאוֹרַיְיתָא דְּהָא שְׁכִינְתָּא אִשְׁתַּכְּחַת גַּבָּךְ, דְּכָל זְמַן דִּבְמִלֵּי דְאוֹרַיְיתָא לָעָאן שְׁכִינְתָּא אַתְיָא וּמִתְחַבְּרָא, וְכָל שֶׁכֵּן בְּאוֹרְחָא (עט ב דשכינתא קדמא ואתיא ואזלא קמייהו דבני נשא דזכאן במהימנותא דקודשא בריך הוא.)</p>"],[9520011244,"<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר. (תהלים קכז) אֶשְׁתְּךָ כְּגֶפֶן פֹּרִיָּה בְּיַרְכְּתֵי בֵיתֶךָ בָּנֶיךָ כִּשְׁתִילֵי זֵיתִים סָבִיב לְשֻׁלְחָנְךָ. אֶשְׁתְּךָ כְּגֶפֶן פֹּרִיָּה, כָּל זִמְנָא דְּאִתְּתָא בְּיַרְכְּתֵי בֵיתָא וְלָא נָפְקָא לְבַר, הִיא צְנוּעָה וְאִתְחֲזֵי לְאוֹלָדָא בְּנִין דְּכָשְׁרָן. כְּגֶפֶן, מַה גֶּפֶן לָא אִתְנַטְעָא אלָּא בְּזִינָהּ וְלָא בְּזִינָא אָחֳרָא. כָּךְ אִתְּתָא דְכָשְׁרָא לָא תֶעֱבַד נְטִיעָן בְּבַר נָשׁ אָחֳרָא. מַה גֶּפֶן לָא אִית בֵּיהּ רְכִיבָה מֵאִילָנָא אָחֳרָא, אוּף הָכִי אִתְּתָא דְּכָשְׁרָא הָכִי נָמֵי.</p>\n<p>חֲמֵי מָה אַגְרָהּ, <Nonei></i>בָּנֶיךָ כִּשְׁתִילֵי זֵיתִים. מַה זֵיתִים לָא נָפְלֵי טַרְפַּיְיהוּ כָּל יוֹמֵי שַׁתָּא וְכֻלְּהוּ קְשׁוּרִין (נ\"א בסירי) תָּדִיר, אוּף הָכִי בָּנֶיךָ כִּשְׁתִילֵי זֵיתִים סָבִיב לְשֻׁלְחָנֶךָ.</p>\n<p>מַה כְּתִיב בַּתְרֵיהּ הִנֵּה כִי כֵן יְבֹרַךְ גָּבֶר יְרֵא יְיָ. מַאי הִנֵּה כִי כֵן יְבֹרַךְ גָּבֶר. הִנֵּה כֵן מִבָּעֵי לֵיהּ. אֶלָּא לְאַסְגָּאָה מִלָּה אָחֳרָא דְּאוֹלִיפְנָא דָּא מִינָּהּ, דְּכָל זִמְנָא דִּשְׁכִינְתָּא הֲוָה צְנִיעָא בְּאַתְרָהּ כְּדְקָא חָזֵי לָהּ כִּבְיָכוֹל בָּנֶיךָ כִּשְׁתִילֵי זֵיתִים אִלֵּין יִשְׂרָאֵל כַּד שָׁרָאן בְּאַרְעָא. סָבִיב לְשֻׁלְחָנְךָ. דְּאָכְלֵי וְשָׁתָאן וּקְרֵבִין קָרְבָּנִין וְחָדָאן קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וּמִתְבָּרְכָן עִלָּאִין וְתַתָּאִין בְּגִינַיְיהוּ.</p>\n<p>לְבָתַר דִּשְׁכִינְתָּא נָפְקַת, אִתְגָּלוּ יִשְׂרָאֵל מֵעַל פְּתוֹרָא דְּאֲבוּהוֹן וְהֲווּ בֵּינֵי עַמָּמַיָא וְצָוְוחִין כָּל יוֹמָא וְלֵית דְּאַשְׁגַּח בְּהוּ בַּר קוּדְשָׁא בְּרִיךְ הוּא דִּכְתִיב (ויקרא כ״ו:מ״ד) וְאַף גַּם זֹאת בִּהְיוֹתָם בְּאֶרֶץ אוֹיְבֵיהֶם וְגו'. וְחָמִינָן כַּמָּה קַדִּישִׁין עִלָּאִין מִיתוּ בִּגְזֵרִין תַּקִּיפִין, וְכָל דָּא בְּגִין עוֹנָשָׁא דְאוֹרַיְיתָא דְּלָא קִיְימוּ יִשְׂרָאֵל כַּד הֲווּ שָׁרָאן בְּאַרְעָא קַדִּישָׁא.</p>\n<p>חֲמֵי מַה כְּתִיב, (דברים כ״ח:מ״ז) תַּחַת אֲשֶׁר לא עָבַדְתָּ אֶת יְיָ אֱלהֶיךָ בְּשִׂמְחָה וּבְטוּב לֵבָב מֵרֹב כֹּל. הַאי קְרָא אִיהוּ רָזָא, תַּחַת אֲשֶׁר לא עָבַדְתָּ בְּשִׂמְחָה, בִּזְמַן דְּכֹהֲנֵי הֲווּ קְרֵבִין קָרְבָּנִין וַעֲלָוָון וְדָא הִיא בְּשִׂמְחָה. וּבְטוּב לֵבָב, אִלֵּין לֵיוָאֵי. מֵרוֹב כֹּל, אֵלּוּ יִשְׂרָאֵל דְּהֲווּ אֶמְצָעִיִּים בֵּינַיְיהוּ וְנָטְלֵי בִּרְכָאן מִכָּל סִטְרִין.</p>\n<p>דִּכְתִיב, (ישעיהו ט׳:ב׳) הִרְבִּיתָ הַגּוֹי לוֹ הִגְדַּלְתָּ הַשִּׂמְחָה. אִלֵּין כַּהֲנֵי. שָׂמְחוּ לְפָנֶיךָ כְּשִׂמְחַת בַּקָּצִיר, אֵלּוּ יִשְׂרָאֵל דְּקוּדְשָׁא בְּרִיךְ הוּא בָּרִיךְ לוֹן עִבּוּרָא דְחַקְלָא וְיַהֲבֵי מַעַשְׂרָא מִכֹּלָּא. כַּאֲשֶׁר יָגִילוּ בְּחַלְּקָם שָׁלָל. אִלֵּין לֵיוָאֵי דְּנָטְלָא מַעַשְׂרָא מִגּוֹ אִדְרָא.</p>\n<p>דָּבָר אַחֵר הִרְבִּיתָ הַגּוֹי. אִלֵּין יִשְׂרָאֵל דִּמְהֵימְנוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא עֲלַיְיהוּ כְּדְקָא חָזֵי. לוֹ הִגְדַלְתָּ הַשִּׂמְחָה, דָּא אִיהוּ דַרְגָּא רֵישָׁא עִלָּאָה דְּאַבְרָהָם דְּאִתְדָּבַּק בָּהּ, דְּאִיהוּ גָּדוֹל וְחֶדְוָה בֵּיהּ אִשְׁתַּכַּח.</p>\n<p>שָׂמְחוּ לְפָנֶיךָ, <Nonei></i>בְּשַׁעֲתָא דְּסָלְקִין לְאִתְדַבְּקָא בָּךְ. כְּשִׂמְחַת בַּקָּצִיר, דָּא כְּנֶסֶת יִשְׂרָאֵל דְּשִׂמְחַת בַּקָּצִיר דִּילֵיהּ הֲוָה. כַּאֲשֶׁר יָגִילוּ בְּחַלְּקָם שָׁלָל. כַּאֲשֶׁר יָגִילוּ, אִלֵּין שְׁאָר חֵילִין וּרְתִיכִין לְתַתָּא בְּזִמְנָא דִּמְחַלְּקֵי שָׁלָל וְטַרְפֵי טַרְפָא בְּרֵאשִׁיתָא דְכֹלָּא.</p>"],[9520011245,"<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהילים קי״ט:קכ״ו) עֵת לַעֲשׂוֹת לַיְיָ הֵפֵרוּ תוֹרָתֶךָ. עֵת לַעֲשׂוֹת לַיְיָ מַהוּ. אֶלָּא הָא אוּקְמוּהָ. אֲבָל עֵת, דָּא כְּנֶסֶת יִשְׂרָאֵל דְּאִקְרֵי עֵת. כְּמָה דְאַתְּ אָמֵר, (ויקרא ט״ז:ב׳) וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ. מַאי וְאַל יָבֹא בְכָל עֵת. כְּמָה דְאַתְּ אָמֵר, (משלי ז׳:ה׳) לִשְׁמָרְךָ מֵאִשָּׁה זָרָה. וְדָא הוּא (ויקרא י׳:א׳) וַיַּק1ְריבוּ לִפְנֵי יְיָ אֵשׁ זָרָה וְגו'. מַאי טַעְמָא עֵת. בְּגִין דְּאִית לָהּ עֵת וּזְמַן לְכֹלָּא לְקָרְבָא לְאִתְנַהֲרָא לְאִתְחַבְּרָא כְּדְקָא יְאוּת. כְּמָא דְאַתְּ אָמֵר, (תהילים ס״ט:י״ד) וַאֲנִי תְפִלָּתִי לְךָ יְיָ עֵת רָצוֹן.</p>\n<p>לַעֲשׂוֹת לַיְיָ כְּמָה דִכְתִיב, (שמואל ב ח׳:י״ג) וַיַּעַשׂ דָּוִד שֵׁם. דְּכָל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא כְּאִילוּ עָבִיד וְתַקֵּן הַאי עֵת לְחַבְּרָא לָהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. וְכָל כָּךְ לָמָּה בְּגִין דְּהֵפֵרוּ תוֹרָתֶךָ, דְּאִילוּ לא הֵפֵרוּ תוֹרָתֶךָ לָא אִשְׁתַּכַּח פִּירוּדָא דְּקוּדְשָׁא בְּרִיךְ הוּא מִיִּשְׂרָאֵל לְעָלְמִין.</p>\n<p>אָמַר רַבִּי יוֹסֵי כְּגַוְּונָא דָא כְּתִיב, (ישעיהו ס׳:כ״ב) אֲנִי יְיָ בְּעִתָּהּ אֲחִישֶׁנָּה. מַהוּ בְּעִתָּהּ. בְּעֵת ה'. דְּתָקוּם מֵעַפְרָא כְּדֵין אֲחִישֶׁנָּה.</p>\n<p>אָמַר רַבִּי יוֹסֵי וְעִם כָּל דָּא יוֹמָא חַד נֶאֱלַמְתִּי דוּמִיָּ\"ה, בְּגִין דְּאִסְתַּלַּק וא\"ו מִן ה\"א, וְקוֹל לָא אִשְׁתַּכַּח, כְּדֵין דִּבּוּר אִתְאַלָּם.</p>\n<p>וּבְגִין כָּךְ הִיא שְׁכִיבַת בְּעַפְרָא כָּל הַהוּא יוֹמָא (דנא) דְּה\"א. וּמַאן אִיהוּ אֶלֶף חֲמִשָּׁאָה, וְאַף עַל גַּב דְּאַקְדִימַת בְּגָלוּתָא עַד לָא יֵיעוּל הַהוּא אֶלֶף חֲמִשָּׁאָה רָזָא דְּה\"א,</p>\n<p>וְכַד יֵיתֵי אֶלֶף שְׁתִיתָאָה דְּאִיהוּ רָזָא <Nonei></i>דְּוא\"ו, כְּדֵין וא\"ו יוֹקִים לְה\"א. בְּזִמְנָא (שמות ט ב) שִׁית זִמְנִין עֶשֶׂר שִׁתִּין נֶפֶשׁ, כְּדֵין שְׁלִימוּ וא\"ו עֶשֶׂר זִמְנִין, וא\"ו שִׁית זִמְנִין עֶשֶׂר, (דוא\"ו) וא\"ו סָלְקָא (בעשר) בְּי', וא\"ו נָחֲתָא בְּה\"א.</p>\n<p>אִשְׁתְּלִים וא\"ו גּוֹ עֶשֶׂר שִׁית זִמְנִין, כְּדֵין הֲווּ שִׁתִּין לְאָקְמָא מֵעַפְרָא, וּבְכָל שִׁתִּין וְשִׁתִּין מֵהַהוּא אֶלֶף שְׁתִיתָאָה אִתְתַּקַּף ה\"א וְסַלְקָא בְּדַרְגּוֹי לְאִתְתַּקְּפָא. וּבְשִׁית מְאָה שְׁנִין לִשְׁתִיתָאָה יִתְפַּתְּחוּן תַּרְעֵי דְחָכְמְתָא לְעֵילָא וּמַבּוּעֵי דְחָכְמְתָא לְתַתָּא, וְיִתְתַּקַּן עַלְמָא לְאָעֳלָא בִּשְׁבִיעָאָה. כְּבַר נָשׁ דְּמִתְתַּקַּן בְּיוֹמָא שְׁתִיתָאָה מֵכִי עָרַב שִׁמְשָׁא לְאֲעָלָא בְּשַׁבַּתָּא. אוּף הָכִי נָמֵי. וְסִימָנִיךְ (בראשית ז׳:י״א) בִּשְׁנַת שֵׁשׁ מֵאוֹת שָׁנָה לְחַיֵּי נֹחַ וְגו' נִבְקְעוּ כָּל מַעְיְינוֹת תְּהוֹם רַבָּה.</p>\n<p>אָמַר לֵיהּ רַבִּי יוֹסֵי כָּל דָּא אֲרִיכוּ זִמְנָא יַתִּיר מִכְּמָה דְאוּקְמוּהָ חַבְרַיָיא דְּאִיהוּ יוֹמָא חַד גָּלוּתָא דִּכְנֶסֶת יִשְׂרָאֵל וְלָא יַתִּיר דִּכְתִיב, (איכה א׳:י״ג) נְתָנַנִי שׁוֹמֵמָה כָּל הַיּוֹם דָּוָה. אָמַר לֵיהּ הָכִי אוֹלִיפְנָא מֵאַבָּא בְּרָזִין דְּאַתְוָון דִּשְׁמָא קַדִּישָׁא וּבְיוֹמֵי דִּשְׁנֵי עַלְמָא וּבְיוֹמֵי דִבְרֵאשִׁית וְכֹלָּא רָזָא חָדָא אִיהוּ.</p>\n<p>וּכְדֵין יִתְחֲזֵי קַשְׁתָּא בַּעֲנָנָא בִּגְוָונֵי (עב ב) נְהִירִין כְּאִתְּתָא דְמִתְקַשְּׁטָא לְבַעֲלָהּ דִּכְתִיב, (בראשית ט׳:ט״ז) וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם וְהָא אוּקְמוּהָ וְשַׁפִּיר הוּא. וּרְאִיתִיהָ, בִּגְוָונִין נְהִירִין כְּדְקָא יְאוּת.</p>\n<p>וּכְדֵין לִזְכֹּר בְּרִית עוֹלָם. מַאן בְּרִית עוֹלָם. דָּא כְּנֶסֶת יִשְׂרָאֵל, וְיִתְחַבַּר וא\"ו בְּה\"א, וְיֵיקִים לָהּ מֵעַפְרָא, כְּמָא דְאַתְּ אָמֵר וַיִּזְכֹּר אֱלהִים אֶת בְּרִיתוֹ. דָּא כְּנֶסֶת יִשְׂרָאֵל דְּאִיהִי בְּרִית, כְּמָא דְאַתְּ אָמֵר וְהָיְתָה לְאוֹת בְּרִית וְגו'.</p>\n<p>כַּד יִתְעַר וא\"ו לְגַבֵּי ה\"א, כְּדֵין אָתִין עִלָּאִין יִתְעָרוּן בְּעָלְמָא (רלו א) וּבְנוֹי דִרְאוּבֵן זְמִינִין דְּיִתְעָרוּן, קְרָבִין בְּכָל עַלְמָא, וּכְנֶסֶת יִשְׂרָאֵל יוֹקִים לָהּ מֵעַפְרָא וְיִדְכַּר לָהּ קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וְיִשְׁתַּכַּח קוּדְשָׁא בְּרִיךְ הוּא לְגַבָּהּ גּוֹ גָּלוּתָא כְּחוּשְׁבַּן וא\"ו שִׁית זִמְנִין י' (עשר). עֶשֶׂר זִמְנִין שִׁית שְׁנִין, וּכְדֵין תֵּיקוּם וְיִתְפַּקַד עַלְמָא לְמֶעְבַּד נוּקְמִין, וּמַאן דְּאִיהוּ מָאִיךְ יִתְרְמֵי.</p>\n<p>אָמַר לֵיהּ רַבִּי יוֹסֵי שַׁפִּיר קָאֲמַרְתְּ בְּגִין <Nonei></i>דְּאִיהוּ גּוֹ רָזָא דְּאַתְוָון. וְלֵית לָן לְאַתְעָרָא חוּשְׁבַּן וְקִצִּין אָחֳרָנִין, דְּהָא בְּסִפְרָא דְּרַב יֵיבָא סָבָא אַשְׁכְּחָן חוּשְׁבַּן דָּא דִּכְתִיב, (ויקרא כ״ו:ל״ד) אָז תִּרְצֶה הָאָרֶץ. וְהוּא רָזָא דְּוא\"ו דִּכְתִיב, (ויקרא כ״ו:מ״ב) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב וְדָא הוּא וא\"ו כֹּלָּא כְּחֲדָא, וְעַל דָּא אֶזְכּוֹר, וּלְבָתַר וְהָאָרֶץ אֶזְכּוֹר, דָּא כְּנֶסֶת יִשְׂרָאֵל. תִּרְצֶה. תִּתְרְעֵי אַרְעָא לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>אֲבָל יוֹמָא חַד דְּאָמְרוּ חַבְרַיָיא וַדַּאי כֹּלָּא הוּא גָּנִיז קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְכֹלָּא אִשְׁתְּכַח בְּרָזָא דְאַתְוָון דִּשְׁמָא קַדִּישָׁא, דְּהָא גָלוּתָא בְּאִנּוּן אַתְוָון גָּלֵי לוֹן רַבִּי יֵיסָא הָכָא, וְהַשְׁתָּא בְּאִנּוּן אַתְוָון אִתְגַּלְּיָין וְגָלֵי לוֹן.</p>\n<p>אָמַר לֵיהּ תָּא חֲזֵי, דְּאָפִילּוּ כַּד אִתְפַּקְּדָא שָׂרָה, מֵהַאי דַרְגָא לָא פַּקִּיד לָהּ, אֶלָּא בְּרָזָא דְוא\"ו, דִּכְתִיב וַיְיָ פָּקַד אֶת שָׂרָה וְגו'. בְּגִין דְּכֹלָּא בְּרָזָא דְוא\"ו אִיהוּ, וּבְהָא כָּלִיל כֹּלָּא, וּבֵיהּ אִתְגַּלְּיָא כֹּלָּא, בְּגִין דְּכָל מִלָּה דְּאִיהִי סְתִימָא אִיהִי גַּלֵּי כָּל סָתִים. וְלָא אָתֵי מַאן דְּאִיהוּ בְּאִתְגַלְּיָא וִיגַלֵּי מַה דְּאִיהוּ סָתִים.</p>\n<p>אָמַר רַבִּי יוֹסֵי כַּמָּה אִית לָן לְאִתְמַשְּׁכָא גּוֹ גָּלוּתָא עַד הַהוּא זִמְנָא, וְכֹלָּא תָּלֵי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא כַּד יְתוּבוּן בִּתְיוּבְתָּא. אִי יִזְכּוּ וְאִי לָא יִזְכּוּ, כְּמָה דְאִתְמָּר בְּהַאי קְרָא דִּכְתִיב אֲנִי יְיָ בְּעִתָּהּ אֲחִישֶׁנָּה. זָכוּ אֲחִישֶׁנָּה לא זָכוּ בְּעִתָּהּ.</p>\n<p>אֲזְלוּ, עַד דְּהֲווּ אָזְלֵי, אָמַר רַבִּי יוֹסֵי אַדְכַּרְנָא הַשְׁתָּא דְּהָא בְּאֲתַר דָּא יָתִיבְנָא יוֹמָא חַד עִם אַבָּא, וְאָמַר לִי בְּרִי זַמִּין אַנְתְּ כַּד מָטוּן יוֹמָךְ לְשִׁיתִּין שְׁנִין לְאַשְׁכָּחָא בְּהַאי אֲתַר סִימָא דְּחָכְמְתָא עִלָּאָה, וְהָא זָכִינָא לְאִנּוּן יוֹמִין וְלָא אַשְׁכַּחְנָא, וְלָא יְדַעְנָא אִי הַנֵּי מִלִּין דְּקָאֲמָרָן אוֹ הַהִיא חָכְמְתָא דְּאִיהוּ אָמַר.</p>\n<p>וְאָמַר לִי כַּד יִמְטוּן קוּלְפִין דְּנוּרָא גּוֹ טְהִירֵי יְדָךְ אִתְאֲבִיד מִינָךְ. אֲמִינָא לֵיהּ אַבָּא בַּמֶּה יְדַעְתְּ. אָמַר לִי בְּהַנֵּי תְּרֵין צִפּוֹרִין דְּאַעֲבָרוּ עַל רֵישָׁךְ יְדַעְנָא.</p>\n<p>אַדְּהָכִי אִתְפְּרַשׁ רַבִּי יוֹסֵי וְעָאל גּוֹ מְעַרְתָּא <Nonei></i>חָדָא וְאַשְׁכַּח סִפְרָא חַד דְּהֲוָה נָעִיץ גּוֹ נוּקְבָא דְּטִנָּרָא בִּסְיָיפֵי מְעַרְתָּא, נָפַק בֵּיהּ.</p>\n<p>כֵּיוָן דְּפָתַח לֵיהּ חָמָא שִׁבְעִין וּתְרֵין גְּלִיפִין דְּאַתְוָון דְּאִתְמְסָרוּ לְאָדָם הָרִאשׁוֹן וּבְהוּ הֲוָה יָדַע כָּל חָכְמְתָא דְּעִלָּאִין קַדִּישִׁין וְכָל אִנּוּן דְּבָתַר רֵיחַיָא דְּמִתְגַּלְגְּלָן בָּתַר פָּרוּכְתָּא גּוֹ טְהִירִין עִלָּאִין וְכָל אִנּוּן מִלִּין דְּזַמִּינִין לְמֵיתֵי לְעָלְמָא, עַד יוֹמָא דְּיֵקוּם עֲנָנָא דְּבִסְטַר מַעֲרָב וְיַחְשִׁיךְ עָלְמָא.</p>\n<p>קָרָא לְרַבִּי יְהוּדָה וְשָׁרוּ לְמִלְעֵי בְּהַהוּא סִפְרָא, לָא סְפִיקוּ לְמִלְעֵי תְּרֵי אוֹ תְּלָתָא סִטְרִין דְּאִנּוּן אַתְוָון עַד דְּהֲווּ מִסְתַּכְּלִין בְּהַהִיא חָכְמָה עִלָּאָה, כֵּיוָן דְּמָטוּ לְמִלְעֵי בִּסְתִירוּ דְּסִפְרָא וּמִשְׁתָּעוּ דָּא עִם דָּא, נָפַק שְׁבִיבָא דְּאֶשָׁא וְעִלְעוּלָא דְּרוּחָא וּבָטַשׁ בִּידֵיהוֹן וְאִתְאֲבִיד מִנַּיְיהוּ. בָּכָה רַבִּי יוֹסֵי וְאָמַר דִּילְמָא חַס וְשָׁלוֹם חוֹבָה אִיהוּ גַּבָּן אוֹ דְּלָאו אֲנַן זַכִּין לְמִנְדַע לֵיהּ.</p>\n<p>כַּד אָתוּן לְגַבֵּי דְרַבִּי שִׁמְעוֹן אִשְׁתָּעוּ לֵיהּ עוֹבָדָא דָא, אָמַר לוֹן דִּילְמָא בְּקֵץ מְשִׁיחָא דְּאִנּוּן אַתְוָון הֲוֵיתוּן מִשְׁתַּדְּלֵי, אָמְרוּ לֵיהּ דָּא לָא יַדְעִינָן דְּהָא כֹּלָּא אִתְנְשֵׁי מִינָן. אָמַר לוֹן רַבִּי שִׁמְעוֹן לֵית רְעוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא בְּדָא דְּיִתְגְּלֵי כָּל כָּךְ לְעַלְמָא, וְכַד יְהֵא קָרִיב לְיוֹמֵי מְשִׁיחָא אֲפִילּוּ רַבְיֵי דְעַלְמָא זְמִינִין לְאַשְׁכָּחָא טְמִירִין דְּחָכְמְתָא וּלְמִנְדַע בֵּיהּ קִצִּין וְחוּשְׁבְּנִין, וּבְהַהוּא זִמְנָא אִתְגַּלְּיָא לְכֹלָּא הֲדָא הוּא דִכְתִיב (צפניה ג׳:ט׳) כִּי אָז אֶהְפֹּךְ אֶל עַמִּים וְגו'. מַהוּ אָז. בְּזִמְנָא דְּתֵיקוּם כְּנֶסֶת יִשְׂרָאֵל מֵעַפְרָא וְיוֹקִים לָהּ קוּדְשָׁא בְּרִיךְ הוּא כְּדֵין אֶהְפֹּךְ אֶל עַמִּים שָׂפָה בְרוּרָה לִקְרֹא כֻלָּם בְּשֵׁם יְיָ וּלְעָבְדוֹ שְׁכֶם אֶחָד.</p>\n<p>תָּא חֲזֵי, אַף עַל גַּב דְּאַבְרָהָם כְּתִיב בֵּיהּ וַיִּסַּע אַבְרָם הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה. וְכָל מַטְלָנוֹי הֲווּ לְדָרוֹמָא וְאִתְקַשַּׁר בֵּיהּ, לָא סָלִיק לְדוּכְתֵּיהּ כְּדְקָא יְאוּת עַד דְּאִתְיְלִיד יִצְחָק, כֵּיוָן דְּאִתְיְלִיד יִצְחָק אִסְתַּלַּק לְאַתְרֵיהּ וְאִיהוּ אִשְׁתַּתַּף בַּהֲדֵיהּ וְאִתְקַשְּׁרוּ <Nonei></i>דָּא בְּדָא.</p>\n<p>בְגִין כָּךְ אִיהוּ קָרֵי לֵיהּ יִצְחָק וְלָא אָחֳרָא, בְּגִין לְשַׁתְּפָא מַיָא בְּאֶשָׁא, דִּכְתִיב וַיִּקְרָא אַבְרָהָם אֶת שֵׁם בְּנוֹ הַנּוֹלַד לוֹ אֲשֶׁר יָלְדָה לוֹ שָׂרָה יִצְחָק. מַאן הַנּוֹלַד לוֹ, אֵשׁ מִמַּיִם:</p>"],[9520011246,"<p>וַתֵּרֶא שָׂרָה אֶת בֶּן הָגָר הַמִּצְרִית אֲשֶׁר יָלְדָה לְאַבְרָהָם מְצַחֵק. אָמַר רַבִּי חִיָּיא, מִיּוֹמָא דְּאִתְיְלִיד יִצְחָק וְהֲוָה יִשְׁמָעֵאל בְּבֵיתָא דְאַבְרָהָם, לָא אִסְתַּלַּק יִשְׁמָעֵאל בִּשְׁמָא, בְּאֲתַר דְּדַהֲבָא שַׁרְיָא סוֹסְפִיתָא לָא אִדְכַּר קַמֵּיהּ, וּבְגִין כָּךְ אֶת בֶּן הָגָר הַמִּצְרִית, גְּבַר דְּלָא יִתְחֲזֵי לְאַדְכָּרָא קַמֵּיהּ דְּיִצְחָק.</p>\n<p>אָמַר רַבִּי יִצְחָק וַתֵּרֶא שָׂרָה, בְּעֵינָא דִקְלָנָא חָמַאת לֵיהּ שָׂרָה, דְּלָא חָמַאת לֵיהּ בְּעֵינָא דְּאִיהוּ בְּרָא דְּאַבְרָהָם, אֶלָּא דְּאִיהוּ בְּרָא דְּהָגָר הַמִּצְרִית, וּבְגִין כָּךְ וַתֵּרֶא שָׂרָה. דְּשָׂרָה חָמַאת לֵיהּ בְּעֵינָא דָא וְלֹא אַבְרָהָם, דְּאִילוּ בְּאַבְרָהָם לֹא כְּתִיב אֶת בֶּן הָגָר אֶלָּא אֶת בְּנוֹ.</p>\n<p>תָּא חֲזֵי, לְבָתַר מַה כְּתִיב וַיֵּרַע הַדָּבָר מְאֹד בְּעֵינִי אַבְרָהָם עַל אוֹדוֹת בְּנוֹ. וְלָא כְּתִיב עַל אוֹדוֹת בֶּן הָגָר הַמִּצְרִית. בְגִין כָּךְ וַתֵּרֶא שָׂרָה אֶת בֶּן הָגָר הַמִּצְרִית. וְלָא חָמַאת דְּאִיהוּ בְּרִיהּ דְּאַבְרָהָם.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר הַאי קְרָא תּוּשְׁבַּחְתָּא דְשָׂרָה אִיהוּ, בְּגִין דְּחָמַאת לֵיהּ דְּקָא מְצַחֵק לְכּוֹכָבִים וּמַזָּלוֹת, אָמְרָה, וַדַּאי לַאו בְּרָא דָא בְּרָא דְאַבְרָהָם לְמֶעֱבַד עוֹבָדוֹי דְאַבְרָהָם, אֶלָּא בְּרָא דְּהָגָר הַמִּצְרִית אִיהוּ אֲהַדַּר לְחוּלָקָא דְּאִמֵּיהּ, בְגִין כָּךְ וַתֹּאמֶר לְאַבְרָהָם גָּרֵשׁ הָאָמָה הַזֹּאת וְאֶת בְּנָהּ, כִּי לֹא יִירַשׁ בֶּן הָאָמָה הַזֹּאת עִם בְּנִי עִם יִצְחָק.</p>\n<p>וְכִי סַלְקָא דַעְתָּךְ דְּקַנֵּי לָהּ שָׂרָה אוֹ לִבְרָהּ, אִי הָכִי לא אוֹדֵי קוּדְשָׁא בְּרִיךְ הוּא עִמָּהּ, דִּכְתִיב כֹּל אֲשֶׁר תֹּאמַר אֵלֶיךָ שָׂרָה שְׁמַע בְּקוֹלָהּ. אֶלָּא בְּגִין דְּחָמַאת לֵיהּ בְּכּוֹכָבִים וּמַזָּלוֹת וְאִמֵּיהּ אוּלְפָא לֵיהּ נִמּוּסֵי דְּכּוֹכָבִים וּמַזָּלוֹת, בְּגִין כָּךְ אֲמְרַת שָׂרָה כִּי לֹא יִירַשׁ בֶּן הָאָמָה הַזֹּאת, אֲנָא יָדַעְנָא דְּלָא יָרִית לְעָלְמִין חוּלָקָא דִמְהֵימְנוּתָא, וְלָא יְהֵא לֵיהּ עִם בְּרִי חוּלָקָא לָא בְּעַלְמָא דֵין וְלָא בְּעַלְמָא דְאָתֵי, וּבְגִין כָךְ אוֹדֵי עִמָּהּ קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וְקוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְאַפְרָשָׁא בִּלְחוֹדוֹי זַרְעָא קַדִּישָׁא כְּדְקָא יְאוּת, דִּבְגִין כָּךְ בָּרָא עַלְמָא דְּהָא יִשְׂרָאֵל סָלִיק בִּרְעוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא עַד לָא יִבְרֵי עַלְמָא, וּבְגִין כָּךְ נָפַק אַבְרָהָם לְעַלְמָא וְעַלְמָא מִתְקַיֵּים בְּגִינֵיהּ, וְאַבְרָהָם וְיִצְחָק (לא) קָיְימוּ וְלָא אִתְיַישְׁבוּ בְּדוּכְתַּיְיהוּ עַד דְּנָפַק יַעֲקֹב לְעָלְמָא.</p>\n<p>כֵּיוָן דְּנָפַק יַעֲקֹב לְעַלְמָא אִתְקָיְימוּ אַבְרָהָם וְיִצְחָק וְאִתְקְיַּים כָּל עַלְמָא, וּמִתַּמָּן נָפַק עַמָּא קַדִּישָׁא לְעַלְמָא, וְאִתְקְיַּים כֹּלָּא כְּגַוְונָא קַדִּישָׁא כְּדְקָא יְאוּת, וּבְגִין כָּךְ אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, כֹּל אֲשֶׁר תֹּאמַר אֵלֶיךָ שָׂרָה שְׁמַע בְּקוֹלָהּ כִּי בְיִצְחָק יִקָּרֵא לְךָ זָרַע, וְלֹא בְּיִשְׁמָעֵאל. מַה כְּתִיב לְבָתַר וַתֵּלֶךְ וַתֵּתַע בְּמִדְבַּר בְּאֵר שָׁבַע.</p>\n<p>כְּתִיב הָכָא וַתֵּתַע וּכְתִיב הָתָם (ירמיהו י׳:ט״ו) הֶבֶל הֵמָּה מַעֲשֵׂה תַּעְתּוּעִים. וְקוּדְשָׁא בְּרִיךְ הוּא בְּגִינֵיהּ דְּאַבְרָהָם לָא שָׁבִיק. לָהּ וְלִבְרָהּ.</p>\n<p>תָּא חֲזֵי, בְּקַדְמִיתָא כַד אָזְלַת מִקַּמָּהּ דְּשָׂרָה מַה כְּתִיב כִּי שָׁמַע יְיָ אֶל עָנְיֵיךְ. וְהַשְׁתָּא דְּטָעַאת בָּתַר כּוֹכָבִים וּמַזָּלוֹת אַף עַל גַּב דִּכְתִיב וַתִּשָּׂא אֶת קוֹלָהּ וַתֵּבְךָ. מַה כְּתִיב כִּי שָׁמַע אֱלֹהִים אֶל קוֹל הַנַּעַר. וְלָא כְּתִיב כִּי שָׁמַע אֱלהִים אֶת קוֹלֵךְ.</p>\n<p>בַּאֲשֶׁר הוּא שָׁם. הָא אוּקְמוּהָ דְּלָאו בַּר עוֹנָשָׁא הוּא לְגַבֵּי בֵּי דִינָא דִּלְעֵילָא, דְּהָא בֵּי דִינָא דִלְתַתָּא עָנְשִׁין מִתְּלֵיסַר שְׁנִין וּלְעֵילָא, וּבֵי דִינָא דִלְעֵילָא מֵעֶשְׂרִים שְׁנִין וּלְהָלְאָה. וְאַף עַל גַּב דְּחַיָּיבָא הֲוָה, לָאו בַּר עוֹנָשָׁא אִיהוּ. וְהָא אוּקְמוּהָ, וְדָא הוּא דִכְתִיב בַּאֲשֶׁר הוּא שָׁם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר אִי הָכִי מַאן דְּאִסְתַּלַּק מֵעַלְמָא עָד לָא מָטוּן יוֹמוֹי לְעֶשְׂרִין שְׁנִין, מֵאָן אֲתַר אִתְעַנָּשׁ, בְּגִין דְּהָא מִתְּלֵיסַר שְׁנִין וּלְתַתָּא לָאו בַּר עוֹנָשָׁא אִיהוּ אֶלָא בְּחֶטְאוֹי דְּאֲבוֹי. אֲבָל מִתְּלֵיסַר שְׁנִין וּלְעֵילָא מַהוּ, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא חָס עֲלֵיהּ דְּלֵימוּת זַכַּאי (ולא לימות חייב) וְיָהִיב לֵיהּ אֲגַר טַב בְּהַהוּא עָלְמָא, וְלָא לֵימוּת חַיָּיב דְּיִתְעַנָּשׁ בְּהַהוּא עָלְמָא וְאוּקְמוּהָ.</p>\n<p>אָמַר לֵיהּ אִי חַיָּיבָא הוּא וְלָא מָטוּן יוֹמוֹי <Nonei></i>לְעֶשְׂרִין שְׁנִין מַהוּ כֵּיוָן דְּאִסְתַּלַּק מֵעַלְמָא בְּמַאי הוּא עוֹנְשֵׁיהּ. אָמַר לֵיהּ בְּדָא אִתְקְיַּים (משלי י״ג:כ״ג) וְיֵשׁ נִסְפָּה בְּלא מִשְׁפָּט. דְּכַד עוֹנָשָׁא נָחִית לְעַלְמָא אִיהוּ (דינא) אַעֲרַע בְּלָא כַּוָּנָה לְעֵילָא וְתַתָּא בְּהַהוּא מְחַבְּלָא וְיִתְעַנַּשׁ כַּד לָא אַשְׁגָּחוּ עֲלֵיהּ מִלְעֵילָא.</p>\n<p>וְעֲלֵיהּ כְּתִיב, (משלי ה׳:כ״ב) עֲווֹנוֹתָיו יִלְכְּדֻנוֹ אֶת הָרָשָׁע. א\"ת לְאַסְגָּאָה מַאן דְּלָא מָטוּן יוֹמוֹי לְאִתְעֲנָשָׁא. עֲווֹנוֹתָיו יִלְכְּדֻנוֹ (את הרשע) וְלָא בֵּי דִינָא דִלְעֵילָא, וּבְחַבְלֵי חַטָּאתוֹ יִתָּמֵךְ וְלָא בֵּי דִינָא דִלְתַתָּא. בְּגִין כָּךְ כְּתִיב כִּי שָׁמַע אֱלהִים אֶל קוֹל הַנַּעַר בַּאֲשֶׁר הוּא שָׁם.</p>"],[9520011247,"<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (ויקרא כ״ו:מ״ב) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב מָלֵא בְּוא\"ו אַמַּאי. אֶלָּא בִּתְרֵין סִטְרִין אִיהוּ (אנון). רָזָא דְחָכְמְתָא חָדָא. דְּאִיהוּ רָזָא דַרְגָּא דְחָכְמְתָא. אֲתַר דְּשָׁרֵי בֵּיהּ יַעֲקֹב. אֲבָל הַאי קְרָא עַל גָּלוּתָא דְיִשְׂרָאֵל אִתְּמָר, דְּכַד אִנּוּן גּוֹ גָּלוּתָא, הַהוּא זִמְנָא דְּיִתְפַּקְדוּן (ביה יעקב) יִתְפַּקְדוּן בְּרָזָא דְּוא\"ו. וְאִיהוּ בְּאֶלֶף שְׁתִיתָאָה.</p>\n<p>(ואתחנן ער א) וּפְקִידָה בְּרָזָא דְוא\"ו שִׁית רִגְעֵי וּפְלַג עִידָן. וּבְזִמְנָא דְּשִׁתִּין שְׁנִין לְעִבּוּרָא דְדַשָּׁא בְּאֶלֶף שְׁתִיתָאָה יָקִים אֱלָהּ שְׁמַיָא פְּקִידוּ לִבְרַתֵּיהּ דְּיַעֲקֹב. וּמֵהַהוּא זִמְנָא עַד דִּיְהֵא לָהּ זְכִירָה שִׁית שְׁנִין וּפַלְגָא. וּמֵהַהוּא זִמְנָא שִׁית שְׁנִין אָחֳרָנִין וְאִנּוּן שִׁבְעִין (ותלת) וּתְרֵין וּפַּלְגָא.</p>\n<p>בְּשִׁיתִּין וְשִׁית יִתְגְּלֵי מַלְכָּא מְשִׁיחָא בְּאַרְעָא (שמות ז ב, ט ב) דְגָלִיל, וְכַד כֹּכָבָא דְּבִסְטַר מִזְרָח יִבְלַע שֶׁבַע כֹּכְבַיָא מִסְטַר צָפוֹן, וְשַׁלְהוֹבָא דְּאֶשָׁא אוּכְמָא תְּהֵא תַּלְיָא בִּרְקִיעָא שִׁיתִּין יוֹמִין, וּקְרָבִין יִתְעָרוּן בְּעַלְמָא לִסְטַר צָפוֹן, וּתְרִין מַלְכִין יִפְּלוּן בְּאִנּוּן קְרָבִין.</p>\n<p>וְיִזְדַּוְּוגוּן כֻּלְּהוֹן עַמְּמַיָא עַל בְּרַתֵּיהּ דְּיַעֲקֹב לְאִדַחְיָיא לָהּ (לון) מֵעָלְמָא. וְעַל הַהוּא זִמְנָא כְּתִיב (והיתה) (ירמיהו ל׳:ז׳) וְעֵת צָרָה הִיא לְיַעֲקֹב וּמִמֶּנָּהּ יִוָּשֵׁעַ וּכְדֵין יִסְתַּיְּימוּן נַפְשִׁין מִגּוּפָא וּבָעְיָין לְאִתְחַדְּשָׁא, וְסִימָנִיךְ (כל הנפש לבית יעקב הבאה מצרימה שבעים וכתיב) (בראשית מ״ו:כ״ז) כָּל הַנֶּפֶשׁ הַבָּאָה לְיַעֲקֹב מִצְרַיְמָה וְגו' כָּל נֶפֶשׁ שִׁשִּׁים וָשֵׁשׁ.</p>\n<p>בְּשִׁבְעִין וּתְלַת כָּל מַלְכֵי עַלְמָא יִתְכַּנְּשׁוּן לְגוֹ קַרְתָּא רַבְּתָא דְּרוֹמִי, וְקוּדְשָׁא בְּרִיךְ הוּא יִתְעַר עֲלַיְיהוּ אֶשָׁא וּבַרְדָא וְאַבְנֵי אַלְגָבִישׁ וְיִתְאַבְּדוּן מֵעַלְמָא, בַּר אִנּוּן מְלָכִין דְּלָא יִמְטוּן לְתַמָּן וִיהַדְּרוּן לְאַגָּחָא קְרָבִין אָחֳרָנִין. וּמֵהַהוּא זִמְנָא מַלְכָּא מְשִׁיחָא יִתְעַר בְּכָל עַלְמָא, וְיִתְכַּנְּשׁוּן עִמֵּיהּ כַּמָּה עַמִּין וְכַמָּה חַיָּילִין מִכָּל סְיָיפֵי עַלְמָא, וְכָל בְּנֵי יִשְׂרָאֵל יִתְכַּנְּשׁוּן בְּכָל אִנּוּן אַתְרֵי.</p>\n<p>עַד דְּאִשְׁתַּלִּימוּ אִנּוּן שְׁנִין לְמֵאָה, כְּדֵין וא\"ו יִתְחַבַּר בְּה\"א, וּכְדֵין (ישעיהו ס״ו:כ׳) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם מִכָּל הַגּוֹיִם מִנְחָה לַיְיָ וְגו'. וּבְנֵי יִשְׁמָעֵאל (ישראל) זְמִינִין בְּהַהוּא זִמְנָא לְאַתְעָרָא (עליהון) עִם כָּל עַמִּין דְּעַלְמָא לְמֵיתֵי עַל יְרוּשָׁלֵם דִּכְתִיב, (זכריה י״ד:ב׳) וְאָסַפְתִּי אֶת כָּל הַגּוֹיִם אֶל יְרוּשָׁלַ ם לַמִלְחָמָה וְגו'. וּכְתִיב, (תהילים ב׳:ב׳) יִתְיַצְּבוּ מַלְכֵי אֶרֶץ וְרוֹזְנִים נוֹסְדוּ יָחַד עַל יְיָ וְעַל מְשִׁיחוֹ. וּכְתִיב יוֹשֵׁב בַּשָּׁמַיִם יִשְׂחָק יְיָ יִלְעַג לָמוֹ.</p>\n<p>לְבָתַר וא\"ו זְעִירָא יִתְעָר לְאִתְחַבָּרָא וּלְחַדְּשָׁא נִשְׁמָתִין דְּהֲווּ עַתִּיקִין בְּגִין לְחַדְתָּא עַלְמָא כְּמָה דִכְתִיב, (שם קד) יִשְׂמַח יְיָ בְּמַעֲשָׂיו וּכְתִיב יְהִי כְבוֹד יְיָ לְעוֹלָם לְאִתְחַבָּרָא כְּדְקָא יְאוּת. יִשְׂמַח יְיָ בְּמַעֲשָׂיו לְנַחֲתָא לוֹן לְעָלְמָא וּלְמֶהֱוֵי כֻּלְּהוֹן בְּרִיָין חַדְתִּין לְחַבְּרָא עַלְמִין כֻּלְּהוּ כְּחַד.</p>\n<p>זַכָּאִין אִנּוּן כָּל אִנּוּן דְּיִשְׁתָּאֲרוּן בְּעַלְמָא בִּסְיָיפֵי אֶלֶף שְׁתִיתָאָה לְמֵיעַל בְּשַׁבַּתָּא, דְּהָא כְּדֵין אִיהוּ יוֹמָא חַד לְקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי לְאִזְדַּוְּוגָא כְּדְקָא יְאוּת וּלְמִלְקַט נִשְׁמָתִין חַדְתִּין לְמֶהֱוֵי בְּעַלְמָא עִם אִנּוּן דְּאִשְׁתָּאֲרוּ בְּקַדְמִיתָא דִּכְתִיב, (ישעיהו ד׳:ג׳) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּיְרוּשָׁלַם קָדוֹשׁ יֵאָמֵר לוֹ כָּל הַכָּתוּב לְחַיִּים בִּיְרוּשָׁלַ ם:</p>"],[9520011248,"<p>וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וְהָאֱלהִים נִסָּה אֶת אַבְרָהָם וַיֹּאמֶר אֵלָיו אַבְרָהָם וַיֹּאמֶר הִנִּנִי. רַבִּי יְהוּדָה פָּתַח וְאָמַר (תהלים מה) אַתָּה הוּא מַלְכִּי וְגו'. דָּא הוּא שְׁלִימוּ דְּכָל דַּרְגִּין כְּחֲדָא דָּא בְּדָא.</p>\n<p>צַוֵּה יְשׁוּעוֹת יַעֲקֹב, כָּל אִנּוּן שְׁלִיחָן דְּעַבְדֵּי שְׁלִיחוּתָא <Nonei></i>בְּעַלְמָא דְלֶיהוֵי כֻּלְּהוּ מִסִּטְרָא דְרַחֲמֵי וְלָא לֶהווֹ מִסִּטְרָא דְדִינָא, בְּגִין דְּאִית מָארֵי שְׁלִיחָן מִסִּטְרָא דְרַחֲמֵי וּמִסִּטְרָא דְדִינָא קַשְׁיָא. אִנּוּן שְׁלִיחָן דְּאַתְיָין מִסִּטְרָא דְרַחֲמֵי לָא עַבְדֵי שְׁלִיחוּתָא דְדִינָא בְּעַלְמָא כְּלָל.</p>\n<p>וְאִי תֵימָא הָא מַלְאָכָא דְּאִתְגְּלֵי לֵיהּ לְבִלְעָם הָא תָּנִינָן שְׁלִיחָא דְּרַחֲמֵי הֲוָה וְאִתְהַפַּךְ לְדִינָא. לָא. לְעוֹלָם לָא אִשְׁתַּנֵּי, אֶלָּא שְׁלִיחָא דְרַחֲמֵי הֲוָה לַאֲגָנָא עֲלַיְיהוּ דְיִשְׂרָאֵל וּלְמֶהֱוֵי סַנֵּיגוֹרְיָא עֲלַיְיהוּ, וּלְקֳבְלֵיהּ הוּא דִינָא, וְכָךְ אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, כַּד אוֹטִיב לְדָא הַהוּא טִיבוּ דִּינָא לְדָא. כָּךְ הָא שְׁלִיחָא דְרַחֲמֵי הֲוָה לְהוּ לְיִשְׂרָאֵל וּלְבִלְעָם אִתְהַפַּךְ לְדִינָא. בְגִין כָּךְ צַוֵּה יְשׁוּעוֹת יַעֲקֹב, אָמַר דָוִד, פַּקִּיד עַל עַלְמָא כַּד יִשְׁתַּלְּחוּן שְׁלִיחָאָה דִּי לֶהֶוְיָן מִסִּטְרָא דְרַחֲמֵי.</p>\n<p>רַבִּי אַבָּא אָמַר צַוֵּה יְשׁוּעוֹת יַעֲקֹב דְּאִנּוּן גּוֹ גַלְוָותָא וְיִשְׁתַּכַּח פּוּרְקָנָא לְהוֹן גּוֹ גָּלוּתְהוֹן. תָּא חֲזֵי, תּוּשְׁבְּחָן דְּאֲבָהָן יַעֲקֹב הֲוָה, וְאִלְמָלֵא יִצְחָק לָא אֲתָא יַעֲקֹב לְעַלְמָא, וּבְגִין כָּךְ צַוִּה יְשׁוּעוֹת יַעֲקֹב דָּא יִצְחָק, דְּכֵיוָן דְּאִשְׁתְּזִיב יִצְחָק יְשׁועוֹת יַעֲקֹב הֲווּ.</p>\n<p>וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה. רַבִּי שִׁמְעוֹן אָמַר הָא תָּנִינָן וַיְהִי בִּימֵי עַל צַעֲרָא אִתְּמָר, וַיְהִי אַף עַל גַּב דְּלָא כְּתִיב בִּימֵי טַפְסֵי דְצַעֲרָא אִית בֵּיהּ. וַיְהִי אַחַר, בָּתַר דַּרְגָּא תַּתָּאָה דְּכָל דַּרְגִּין עִלָּאִין, וּמַאן אִיהוּ דְּבָרִים, כְּמָא דְאַתְּ אָמֵר (שמות ד׳:י׳) לא אִישׁ דְּבָרִים אָנֹכִי.</p>\n<p>וּמַאן הֲוָה בָּתַר דַּרְגָּא דָא, וְהָאֱלהִים נִסָּה אֶת אַבְרָהָם דְּאַתְיָא יֵצֶר הָרָע לְקַטְרְגָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. הָכָא אִית לְאִסְתַּכָּלָא וְהָאֱלהִים נִסָּה אֶת אַבְרָהָם. אֶת יִצְחָק מִבָּעֵי לֵיהּ. דְּהָא יִצְחָק בַּר תְּלָתִין וְשֶׁבַע שְׁנִין הֲוָה וְהָא אֲבוֹי לָאו בַּר עוֹנָשָׁא דִילֵיהּ הֲוָה, דְּאִלְמָלֵא אָמַר יִצְחָק לָא בָעֵינָא לָא אִתְעֲנַשׁ אֲבוֹי עֲלֵיהּ. מַאי טַעְמָא וְהָאֱלהִים נִסָּה אֶת אַבְרָהָם וְלָא כְּתִיב נִסָּה אֶת יִצְחָק.</p>\n<p>אֶלָּא אֶת אַבְרָהָם וַדַּאי דְּבָעֵי לְאִתְכְּלָלָא בְּדִינָא, דְּהָא אַבְרָהָם לָא הֲוָה בֵּיהּ דִּינָא כְּלַל מִקַּדְמַת דְּנָא, וְהַשְׁתָּא אִתְכְּלִיל מַיָי\"א בְּאֶשָׁ\"א. וְאַבְרָהָם לָא הֲוָה שְׁלִים עַד הַשְׁתָּא דְּאִתְעַטַּר לְמֶעְבַּד דִּינָא וּלְאַתְקָנָא לֵיהּ בְּאַתְרֵיהּ.</p>\n<p>וְכָל יוֹמוֹי לָא הֲוָה שְׁלִים עַד הַשְׁתָּא דְּאִתְכְּלִיל מַיָ\"א בְּאֶשָׁ\"א וְאֶשָׁ\"א בְּמַיָ\"א, וּבְגִין כָּךְ וְהָאֱלהִים נִסָּה אֶת אַבְרָהָם וְלא אֶת יִצְחָק, דְּאַזְמִין אַבְרָהָם לְאִתְכְּלָלָא בְּדִינָא, וְכַד עָבִיד דָּא, עָאל (קלג ב) אֶשָׁ\"א בְּמַיָ\"א וְאִשְׁתְּלִים דָּא עִם דָּא. וְדָא עָבִיד דִּינָא לְאִתְכְּלָלָא דָּא בְּדָא. וּכְדֵין יֵצֶר הָרָע אֲתָא לְקַטְרְגָא עֲלֵיהּ דְּאַבְרָהָם דְּלָא אִשְׁתְּלִים כְּדְקָא יְאוּת עַד דְּיַעֲבִיד דִּינָא בְּיִצְחָק. דְּיֵצֶר הָרָע אַחַר הַדְּבָרִים אִיהוּ וְאָתָא לְקַטְרְגָא.</p>\n<p>וְתָא חֲזֵי רָזָא דְמִלָּה, אַף עַל גַּב דְּקָאֲמָרָן דְּאַבְרָהָם כְּתִיב וְלָא יִצְחָק, יִצְחָק נָמֵי אִתְכְּלִיל בֵּיהּ בְּהַאי קְרָא, רָזָא דִכְתִיב וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם. נִסָּה לְאַבְרָהָם לָא כְּתִיב אֶלָּא אֶת אַבְרָהָם אֶת דַּיְיקָא וְדָא יִצְחָק. דְּהָא בְּהַהִיא שַׁעֲתָא בִּגְבוּרָ\"ה תַּתָּאָה שַׁרְיָא, כֵּיוָן דְּאִתְעַקַּד וְאִזְדַּמַּן בְּדִינָא עַל יְדָא דְּאַבְרָהָם כְּדְקָא יְאוּת, כְּדֵין אִתְעַטַּר בְּאַתְרֵיהּ בַּהֲדֵיהּ דְּאַבְרָהָם וְאִתְכְּלִילוּ אֶשָׁ\"א בְּמַיָ\"א וּסְלִיקוּ לְעֵילָא, וּכְדֵין אִשְׁתַּכַּח מַחְלוֹקֶת כְּדְקָא יְאוּת מַיָא בְּאֶשָׁא.</p>\n<p>מַאן (עבד) חָמָא אַבָּא רַחֲמָנָא דְּאִתְעֲבִיד אַכְזָר. אֶלָּא בְּגִין לְאִשְׁתַּכָּחָא מַחְלוֹקֶת מַיָא בְּאֶשָׁא וּלְאִתְעַטְּרָא בְּאַתְרַייהוּ (ד\"א ל\"ג כדקא יאות), עַד דְּאָתָא יַעֲקֹב וְאִתְתַּקַּן כֹּלָּא כְּדְקָא יְאוּת וְאִתְעֲבִידוּ תְּלָתָא אַבָּהָן שְׁלֵמִין וְאִתְתַּקָנוּ עִלָּאֵי וְתַתָּאֵי:</p>\n<p>וַיֹּאמֶר קַח נָא אֶת בִּנְךָ. וְכִי הֵיאַךְ יָכִיל אַבְרָהָם דְּאִיהוּ סָבָא. אִי תֵימָא בְּגִין דְּיִצְחָק לָא נָפִיק מֵרְשׁוּתֵיהּ כְּלַל, יָאוֹת, אֲבָל כְּמָא דְאַתְּ אָמֵר, (במדבר כ׳:כ״ה) קַח אֶת אַהֲרֹן וְאֶת אֶלְעָזָר בְּנוֹ אֶלָּא בְּגִין לְאַמְשָׁכָא לוֹן בְּמִלִּין וּלְאַדְבָּרָא לוֹן לִרְעוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, אוּף הָכָא קַח בְּמִלִּין. אֶת בִּנְךָ אֶת יְחִידְךָ אֲשֶׁר אָהַבְתָּ הָא <Nonei></i>אוּקְמוּהָ. וְלֶךְ לְךָ אֶל אֶרֶץ הַמּוֹרִיָּה כְּמָא דְאַתְּ אָמֵר (שיר השירים ד׳:ו׳) אֵלֵךְ לִי אֶל הַר הַמּוֹר. לְאַתְקָנָא בְּאַתְרָא דְּיִתְחֲזֵי:</p>"],[9520011249,"<p>בַּיּוֹם הַשְּׁלִישִׁי וַיִּשָּׂ\"א אַבְרָהָ\"ם אֶ\"ת עֵינָיו וַיַּרְא אֶת הַמָּקוֹם מֵרָחוֹק. בַּיּוֹם הַשְּׁלִישִׁי הָא אוּקְמוּהָ, אֶלָּא כֵּיוָן דְּאִתְּמָר וַיָּקָם וַיֵּלֶךְ אֶל הַמָּקוֹם אֲשֶׁר אָמַר לוֹ הָאֱלהִים מַאי טַעְמָא בַּיּוֹם הַשְּׁלִישִׁי וַיַּרְא אֶת הַמָּקוֹם מֵרָחוֹק. אֶלָּא בְּגִין דִּכְתִיב כִּי בְיִצְחָק יִקָּרֵא לְךָ זָרַע וְדָא הוּא יַעֲקֹב דְּנָפַק מִנֵּיהּ וְהַאי הוּא בַּיּוֹם הַשְּׁלִישִׁי. וַיַּרְא אֶת הַמָּקוֹם מֵרָחוֹק כְּמָא דְאַתְּ אָמֵר (ירמיהו ל״א:ג׳) מֵרָחוֹק יְיָ נִרְאָה לִי.</p>\n<p>וַיַּרְא אֶת הַמָּקוֹם. דָּא הוּא יַעֲקֹב דִּכְתִיב, (בראשית כ״ח:י״א) וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם. אִסְתַּכַּל אַבְרָהָם בַּיּוֹם הַשְּׁלִישִׁי דְּאִיהוּ דַרְגָּא תְּלִיתָאָה וְחָמָא לֵיהּ לְיַעֲקֹב דְּזַמִּין לְמֵיפַק מִנֵּיהּ. מֵרָחוֹק כְּמָה דְאֲמָרָן מֵרָחוֹק וְלָא לִזְמַן קָרִיב.</p>\n<p>אָמַר לֵיהּ רִבִּי אֶלְעָזָר מַאי שְׁבָחָא אִיהוּ לְאַבְרָהָם כַּד אִסְתַּכַּל וְחָמָא דְּזַמִּין לְמֵיפַק מִנִּיהּ יַעֲקֹב. דְּהָא כַּד אָזִיל לְמֶיעֱקַד לֵיהּ לְיִצְחָק, לָאו שְׁבָחָא כָּל כָּךְ אִיהוּ דִילֵיהּ.</p>\n<p>אָמַר לֵיהּ וַדַּאי (והא) חָמָא לֵיהּ לְיַעֲקֹב דְּהָא מִקַּדְמַת דְּנָא יָדַע אַבְרָהָם חָכְמְתָא, וְאִסְתַּכַּל הַשְׁתָּא בַּיּוֹם הַשְּׁלִישִׁי דְּאִיהוּ דַרְגָּא תְּלִיתָאָה לְמֶעְבַּד שְׁלִימוּ וּכְדֵין חָמָא לֵיהּ לְיַעֲקֹב דִּכְתִיב וַיַּרְא אֶת הַמָּקוֹם. אֲבָל הַשְׁתָּא קַיְימָא לֵיהּ מִלָּה מֵרָחוֹק בְּגִין דְּאָזִיל לְמֶיעֱקַד לֵיהּ לְיִצְחָק וְלָא בָּעָא לְהַרְהֵר אֲבַתְרֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>מֵרָחוֹק חָמָא לֵיהּ גּוֹ אַסְפַּקְלַרְיָאה דְּלָא נָהֲרָא בִּלְחוֹדוֹי, וּבְגִין כָּךְ חָמָא לֵיהּ וְלָא אִתְגְּלִי כֹּלָּא, דְּאִלּוּ אַסְפַּקְלַרְיָאה דְנַהֲרָא הֲוָה שְׁכִיחַ עַל הַאי אַסְפַּקְלַרְיָאה דְּלָא נַהֲרָא אִתְקְיַּים עֲלֵיהּ אַבְרָהָם כְּדְקָא יָאוֹת, אֲבָל מֵרָחוֹק, בִּלְחוֹדוֹי הֲוָה, מֵרָחוֹק.</p>\n<p>מַאי טַעְמָא אִסְתַּלַּק מֵהַאי מִלָּה אַסְפַּקְלַרְיָאה דְּנַהֲרָא בְּגִין דְּהַאי דַּרְגָּא דְּיַעֲקֹב הֲוָה. וּבְגִין דְּיַעֲקֹב עַד לָא אִתְיְילִיד לָא אִשְׁתַּכַּח הַשְׁתָּא עַל הַאי דַרְגָא. וְתוּ בְּגִין דִּיהַךְ וִיקַבֵּל אַגְרָא. וַיַּרְא אֶת הַמָּקוֹם מֵרָחוֹק דָּא יַעֲקֹב כְּמָה דְאִתְּמָר מֵרָחוֹק דְּלָא זָכָה בֵּיהּ.</p>\n<p>(ראייה בעינוי בהאי עלמא אלא מרחוק מגו האי דרגא דהא כד אתא יעקב הכא דאף על גב דאתו לההוא ראייה וחמא ליעקב, אמר אברהם ודאי קודשא בריך הוא ידע בגוונא אחרא דאתחזי, מיד ויבן שם אברהם את המזבח וגו'.</p>\n<p>מה כתיב לעילא ויאמר יצחק אל אברהם אביו ויאמר אבי, הא אוקמוה. אבל מאי טעמא לא אתיב ליה (מדי)) מִיָּד. אֶלָא בְּגִין דְּהָא אִסְתַּלַּק מֵרַחֲמֵי דְאַבָּא עַל בְּרָא וּבְגִין כָּךְ כְּתִיב הִנְּנִּי בְנִי, הִנְּנִּי דְאִסְתַּלָּקוּ רַחֲמֵי וְאִתְהַפַּךְ לְדִינָא:</p>\n<p>וַיֹּאמֶר אַבְרָהָם, וְלָא כְּתִיב וַיֹּאמֶר אָבִיו, דְּהָא לָא קָאִים עֲלֵיהּ כְּאַבָּא אֶלָּא בַּעַל מַחְלוֹקֶת הֲוָה בֵּיהּ. אֱלהִים יִרְאֶה לוֹ הַשֶּׂה. יִרְאֶה לָנוּ מִבָּעֵי לֵיהּ, מַאי יִרְאֶה לוֹ. אֶלָּא אָמַר לֵיהּ אֱלֹהִים יִרְאֶה לוֹ לְגַרְמֵיהּ, כַּד אִיהוּ יִצְטְרִיךְ. אֲבָל הַשְׁתָּא בְּנִי וְלָא אִמְרָא. מִיָּד וַיֵּלְכוּ שְׁנֵיהֶם יַחְדָּו.</p>\n<p>רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר (ישעיהו ל״ג:ז׳) הֵן אֶרְאֶלָם צָעֲקוּ חוּצָה מַלְאֲכֵי שָׁלוֹם מַר יִבְכָּיוּן. הֵן אֶרְאֶלָם אִלֵּין מַלְאֲכֵי עִלָּאֵי. צָעֲקוּ בְּהַהִיא שַׁעֲתָא וּבָעוּ לְקַיְימָא עַל הַהִיא מִלָּה דִּכְתִיב, (בראשית ט״ו:ה׳) וַיּוֹצֵא אוֹתוֹ הַחוּצָה. בְּגִין כָּךְ צָעֲקוּ חוּצָה.</p>\n<p>מַלְאֲכֵי שָׁלוֹם. אִלֵּין אִנּוּן מַלְאָכִין אָחֳרָנִין דְּהֲווּ זְמִינִין לְמֵיהַךְ קַמֵּיהּ דְּיַעֲקֹב וּבְגִינֵיהּ דְּיַעֲקֹב אַבְטַח לוֹן שְׁלִימוּ, קוּדְשָׁא בְּרִיךְ הוּא. דִּכְתִיב, (בראשית ל״ב:ב׳) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בּוֹ מַלְאֲכֵי אֱלהִים. וְאִלֵּין אִקְרוּן מַלְאֲכֵי שָׁלוֹם, כֻּלְּהוּ בָּכוּ כַּד חָמוּ לֵיהּ לְאַבְרָהָם דְּעָקִיד לֵיהּ לְיִצְחָק, וְאִזְדַּעְזְעוּ עִלָּאֵי וְתַתָּאֵי וְכֻלְּהוּ עֲלֵיהּ דְּיִצְחָק:</p>"],[9520011250,"<p>וַיִּקְרָא אֵלָיו מַלְאַךְ יְיָ וְגו', פָּסִיק טַעְמָא בְּגַוַּויְהוּ, דְּלָאו אַבְרָהָם בַּתְרָאָה כְּקַדְמָאָה. בַּתְרָאָה <Nonei></i>שְׁלִים (נשא קלח א) קַדְמָאָה לָא שְׁלִים. כְּגַוְונָא דָא שְׁמוּאֵל שְׁמוּאֵל, בַּתְרָאָה שְׁלִים, קַדְמָאָה לָא שְׁלִים. בַּתְרָאָה נָבִיא, קַדְמָאָה לָא נָבִיא. אֲבָל משֶׁה משֶׁה, לָא פָּסִיק, בְּגִין דְּמִיּוֹמָא דְּאִתְיְילִיד לָא אַעֲדֵי מִנֵּיהּ שְׁכִינְתָּא. אַבְרָהָם אַבְרָהָם. רַבִּי חִיָּיא אָמַר בְּגִין לְאַתְעָרָא לֵיהּ בְּרוּחָא אָחֳרָא בְּעוֹבָדָא אָחֳרָא בְּלִבָּא אָחֳרָא.</p>\n<p>רַבִּי יְהוּדָה אָמַר אִתְבְּרִיר יִצְחָק וְאִסְתַּלִּיק בִּרְעוּתָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא כְּרֵיחָא דִקְטוֹרֶת בּוּסְמִין דְּקָרְבִין כָּהֲנַיָּיא קַמֵּיהּ, תְּרֵין זִמְנִין בְּיוֹמָא וְאִשְׁתְּלִים קָרְבָּנָא. דְּהָא צַעֲרָא דְאַבְרָהָם הֲוָה בְּשַׁעֲתָא דְּאִתְּמָר לֵיהּ אַל תִּשְׁלַח יָדְךָ אֶל הַנַּעַר וְאַל תַּעַשׂ לוֹ מְאוּמָה. חָשִׁיב דְּקָרְבָּנֵיהּ לָא אִשְׁתְּלִים וּלְמַגָּנָא עָבַד וְסִדֵּר כֹּלָּא וּבְנָה מִזְבֵּחַ. מִיָּד. וַיִּשָּׂא אַבְרָהָם אֶת עֵינָיו וַיַּרְא וְהִנִּה אַיִל אַחַר וְגו'</p>\n<p>הָא תָּנִינָן הוּא אַיִל דְּאִתְבְּרֵי בֵּין הַשְּׁמָשׁוֹת הֲוָה, וּבֶן שְׁנָתוֹ הָיָה כְּמָא דְאַתְּ אָמֵר, (במדבר ז׳:ט״ו) כֶּבֶשׂ אֶחָד בֶּן שְׁנָתוֹ וְהָכִי אִצְטְרִיךְ (נ\"א ואת אמרת בין השמשות. ותו והא יצחק לא הוה בעלמא, אלא אתפקיד וכו') (והא יצחק לא הוה בעלמא) וְאַתְּ אֲמַרְתְּ בֵּין הַשְּׁמָשׁוֹת. אֶלָּא אִתְפַּקַּד חֵילָא לְאִזְדַּמְּנָא הַהוּא אִימְרָא בְּשַׁעֲתָא דְּאִצְטְרִיךְ לֵיהּ לְאַבְרָהָם. כְּמָה דְּכָל אִנּוּן מִלִּין דְּהֲווּ בֵּין הַשְּׁמָשׁוֹת אִתְמַנָּא חֵילָא לְאִזְדַּמְּנָא הַהוּא מִלָּה (לההוא זמנא) בְּשַׁעֲתָא דְּאִצְטְרִיךְ לֵיהּ. הָכִי נָמֵי הַאי אַיִל דְּאִתְקְרִיב תְּחוֹתֵיהּ דְּיִצְחָק.</p>"],[9520011251,"<p>פָּתַח וְאָמַר, (ישעיהו ס״ג:ט׳) בְּכָל צָרָתָם לֹא צָר וּמַלְאַךְ פָּנָיו הוֹשִׁיעָם וְגו'. תָּא חֲזֵי, בְּכָל צָרָתָם דְּיִשְׂרָאֵל כַּד אִזְדַּמַּן לוֹן עָאקָן, כְּתִיב לֹא בְּאל\"ף וּקְרִי בְּוא\"ו, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא עִמְּהוֹן בְּעָקוּ. לא בְּאל\"ף, אֲתַר עִלָּאָה יַתִּיר, אַף עַל גַּב דְּלָאו בְּהַהוּא אֲתַר רוּגְזָא וְעָקוּ, לְהָתָם לְעֵילָא מָטָא עַקְתָא דְיִשְׂרָאֵל. לא בְּאל\"ף כְּמָא דְאַתְּ אָמֵר, (תהלים ק) הוּא עָשָׂנוּ וְלֹא אֲנַחְנוּ. כְּתִיב בְּאל\"ף וּקְרִי בְּוא\"ו.</p>\n<p>וּמַלְאַךָ פָּנָיו הוֹשִׁיעָם. וְהָא אִיהוּ עִמְהוֹן בְּהַהוּא עָקוּ, וְאַתְּ אֲמַרְתְּ הוֹשִׁיעָם. אֶלָּא מוֹשִׁיעָם לֹא כְּתִיב, אֶלָּא הוֹשִׁיעָם מִקַּדְמַת דְּנָא דְּאִיהוּ זַמִּין בְּהַהוּא עָקוּ לְמִסְבַּל עִמְּהוֹן. תָּא חֲזֵי, בְּכָל זִמְנָא דְיִשְׂרָאֵל אִנּוּן בְּגָלוּתָא, שְׁכִינְתָּא עִמְּהוֹן בְּגָלוּתָא, וְהָא אוּקְמוּהָ, דִּכְתִיב (דברים ל׳:ג׳) וְשָׁב יְיָ אֱלהֶיךָ אֶת שְׁבוּתְךָ וְרִחַמְךָ וְגו'.</p>\n<p>דָּבָר אַחֵר וּמַלְאַךְ פָּנָיו הוֹשִׁיעָם, דָּא שְׁכִינְתָּא. דְּאִיהִי עִמְּהוֹן בְּגָלוּתָא וְאַתְּ אֲמַרְתְּ דְּאִיהוּ הוֹשִׁיעָם. אֶלָּא הָכִי הוּא וַדַּאי, דְּאִלֵּין אִנּוּן מִשְׁכְּנוֹתָיו דְּקוּדְשָׁא בְּרִיךְ הוּא בְּגָלוּתָא, וּבְגִין דִּשְׁכִינְתָּא עִמְּהוֹן קוּדְשָׁא בְּרִיךְ הוּא אַדְכַּר לוֹן לְאוֹטָבָא לוֹן וְלְאֲפָקָא לוֹן מִן גָּלוּתָא, דִּכְתִיב, (שמות ו׳:ה׳) וָאֶזְכֹּר אֶת בְּרִיתִי בְּקַדְמִיתָא, וּלְבָתַר וְעַתָּה הִנֵּה צַעֲקַת בְּנֵי יִשְׂרָאֵל בָּאָה אֵלַי.</p>\n<p>וְגַם רָאִיתִי. לְאַסְגָּאָה רְאִיָה אָחֳרָא דְּאִיהוּ קַדְמָאָה דְּכֹלָּא, וּכְתִיב, (שמות ב׳:כ״ד) וַיִּזְכֹּר אֱלהִים אֶת בְּרִיתוֹ דָּא שְׁכִינְתָּא. אֶת אַבְרָהָם לְאַבְרָהָם מִבָּעֵי לֵיהּ, אֶלָּא אֶת אַבְרָהָם דָּא הוּא חַבְרוּתָא וְזִוּוּגָא דִילָהּ בַּאֲבָהָן. אֶת אַבְרָהָם (במדבר קכ א) דָּא הוּא מַעֲרָבִית דְּרוֹמִית. אֶת יִצְחָק דָּא הוּא צְפוֹנִית מַעֲרָבִית. וְאֶת יַעֲקֹב דָּא הוּא זִוּוּגָא חָדָא, כְּלָלָא חָדָא, זִוּוּגָא שְׁלִים כְּדְקָא יָאוֹת.</p>\n<p>כְּגַוְונָא דָא אֶת הַשָּׁמַיִם דָּא הוּא כְּלָלָא מִדַּת לַיְלָה בַּיּוֹם. וְאֶת הָאָרֶץ דָּא מִדַּת יוֹם בְּלַיְלָה כְּחֲדָא. אוּף הָכָא בְּכֻלְּהוּ אֶת, וּבְיַעֲקֹב וְאֶת, לְמֶהֱוֵי כֹּלָּא זִוּוּגָא חָדָא דְּלָא מִתְפַּרְשִׁין דְּכַר וְנוּקְבָא לְעָלְמִין. וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַכְרָזָא בְּכָל עַלְמָא וּלְאַשְׁמָעָא קָל דְּיֵימָא (ישעיהו ס״ג:ח׳-ט׳) וַיֹּאמֶר אַךְ עַמִּי הֵמָּה בָּנִים לֹא יְשַׁקֵּרוּ ויְהִי לָהֶם לְמוֹשִׁיעַ. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן: (עד כאן פרשת וירא)</p>"],[9520011252,"<p><Nonei></i>וַיִּהְיוּ חַיִּי שָׂרָה מֵאָה שָׁנָה ועֶשְׂרִים שָׁנָה ושֶׁבַע שָׁנִים, רַבִּי יוֹסֵי פָּתַח וְאָמַר, (יונה א׳:ט״ו) ויִּשְׂאוּ אֶת יוֹנָה ויְטִלֻהוּ אֶל הַיָּם ויַּעֲמֹד הַיָּם מִזַּעְפּוֹ. הָכָא אִית לְאִסְתַּכָּלָא, מַאי טַעְמָא אַרְעִישַׁת יַמָּא עֲלֵיהּ דְּיוֹנָה, ולָא אַרְעִישַׁת עֲלֵיהּ אַרְעָא, כֵּיוָן דְּהֲוָה אָזִיל בְּגִין דְּלָא תִשְׁרֵי עֲלֵיהּ שְׁכִינְתָּא, יַמָּא (עלאה) אַמַּאי אָחִיד בֵּיהּ כַּד הֲוָה אָזִיל.</p>\n<p>אֶלָא וַדַּאי מִלָּה בְּאַתְרֵיהּ הֲוָה. יַם, תְּנַן יַם דַּמְיָא לְרָקִיעַ וְרָקִיעַ לְכִסֵּא הַכָּבוֹד, וּבְגִין כָּךְ יַמָּא אָחִיד בֵּיהּ וְנְטַל לֵיהּ (בגין דהוה עריק) מִקַּמֵּי יַמָא עָרַק (נ\"א ומקמי ימא ביה שרא יראה בדוכתיה), שָׁדֵי יַמָּא יְדָא בֵּיהּ בְּדוּכְתָּהָא (נ\"א תשרי ידא בדוכתהא).</p>\n<p>וַיִּשְׂאוּ אֶת יוֹנָה וַיְטִלֻהוּ אֶל הַיָּם. אוֹלִיפְנָא כַּד הֲווּ נָטְלֵי לֵיהּ וְטָבְעֵי יַרְכוֹי בְּיַמָּא, הֲוָה יַמָּא שָׁכִיךְ, זָקְפִין לֵיהּ, אִתְרְעִישׁ יַמָּא, כָּל מַה דְּטָבְעֵי לֵיהּ הָכִי אִשְׁתְּכִיךְ יַמָּא, עַד דְּאִיהוּ אָמַר שָׂאוּנִי וַהֲטִילוּנִי אֶל הַיָּם, מִיָּד וַיִּשְׂאוּ אֶת יוֹנָה וַיְּטִלוּהוּ אֶל הַיָּם.</p>\n<p>כֵּיוָן דְּאִתְרַמֵּי בַּיָּם פָּרְחָה מִנֵּיהּ נִשְׁמָתֵיהּ, וְסָלְקָא עַד כֻּרְסְיָיא דְמַלְכָּא, וְאִתְדָּנַת קַמֵּיהּ, וְאַהֲדָרַת לֵיהּ נִשְׁמָתֵיהּ, וְעָאל בְּפוּמָא דְהַהוּא נוּנָא, וּמִית נוּנָא, לְבָתַר אִתְקְיַּים הַהוּא נוּנָא, וְאוּקְמוּהָ.</p>\n<p><Nonei></i>תָּא חֲזֵי, בְּשַׁעְתָּא דְּבַר נָשׁ סָלִיק בְּעַרְסֵיהּ כָּל לֵילְיָא וְלֵילְיָא, נִשְׁמָתֵיהּ נָפְקַת מִנֵּיהּ וְאִתְדָּנַת קַמֵּי בֵּי דִינָא דְמַלְכָּא, אִי זַכָּאָה לְאִתְקָיְימָא, אִתְהַדָּרַת לְהַאי עַלְמָא.</p>\n<p>וְדִינָא הוּא בִּתְרֵין גְּוָונִין, דְּהָא לָא דָיְינִין לֵיהּ לְבַר נָשׁ עַל בִּישִׁין דְּאִיהוּ עָתִיד וְזַמִּין לְמֶעְבַּד דִּכְתִיב (בראשית כ״א:י״ז) כִּי שָׁמַע אֱלהִים וְגו' בַּאֲשֶׁר הוּא שָׁם. וְלָא תֵימָא דְּדָנִין לֵיהּ עַל טָבִין דְּעָבִיד לְחוּד, אֶלָּא לְאוֹטָבָא לֵיהּ עַל אִינוּן טָבִין דְּהַשְׁתָּא כְּמָה דְאִתְּמָר, וְדָנִין לֵיהּ עַל זָכְיָין דְּאִיהוּ זַמִּין לְמֶעְבַּד, וּבְגִינַיְיהוּ אִשְׁתְּזִיב אַף עַל גַּב דְּאִיהוּ הַשְׁתָּא חַיָּיבָא. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד טִיבוּ עִם כָּל בִּרְיָין וְכָל אָרְחוֹי דְאִיהוּ עָבִיד לְאוֹטָבָא לְכֹלָּא, וְלָא דָאִין לְבַר נָשׁ עַל בִּישִׁין דְּאִיהוּ זַמִּין לְמֶעְבַּד, וּבְגִין כָּךְ אִתְדָּן בַּר נָשׁ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>תָּא חֲזֵי, כֵּיוָן דְּאַטִּילוּ לֵיהּ לְיוֹנָה בְּיַמָּא, מַה כְּתִיב, וַיַּעֲמֹד הַיָּם מִזַּעְפּוֹ. הַיָּם עִלָּאָה, מַאי וַיַּעֲמֹד, דְּקָאִים בְּקִיּוּמֵיהּ כְּדְקָא יְאוּת, בַּעֲמִידָה אִיהוּ כַּד רוּגְזָא שָׁכִיךְ, בְּשַׁעְתָּא דְּדִינָא שַׁרְיָא בְּעַלְמָא, הַהוּא בֵּי דִינָא אִיהוּ כְּאִתְּתָא דְּמִתְעַבְּרָא, וְקַשְׁיָא לְאוֹלָדָא, וְכַד אוֹלִידַת שְׁכִיךְ רוּגְזָא. הָכִי נָמֵי כַּד דִּינָא שַׁרְיָא בְּעַלְמָא, לָא שָׁכִיךְ וְלָא נָח עַד דְּאִתְעֲבִיד דִּינָא בְּחַיָּיבַיָא, כְּדֵין הוּא נַיְיחָא דִילֵיהּ, לְמֵיקַם בְּדוּכְתָּא שְׁלִים, וּלְמֵיקַם בְּקִיּוּמֵיהּ, הֲדָא הוּא דִכְתִיב, (משלי י״א:י׳) וּבַאֲבֹד רְשָׁעִים רִנָּה. וְהָא אוֹקִימְנָא.</p>\n<p>בַּאֲבֹד רְשָׁעִים רִנָּה. וְהָכְתִיב (יחזקאל י״ח:כ״ג) הֶחָפֹץ אֶחְפֹּץ מוֹת רָשָׁע וְהָא לֵית נַיְיחָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא כַּד אִתְעֲבִיד דִּינָא בְּרַשִּׁיעַיָּיא. אֶלָּא כָּאן קוֹדֶם דְּאִשְׁתְּלִים קִיסְטָא, כָּאן לְבָתַר דְּאִשְׁתְּלִים קִיסְטָא (אית ליה נייחא):</p>"],[9520011253,"<p><Nonei></i><Noneb>תוספתא</b> וְיִהְיוּ חַיֵּי שָׂרָה, גּוּפָא דְּמַתְנִיתִין אֲנַן קְרֵיבִין הֲוֵינָא שְׁמַעְנָא קָלָא מִתְהַפֵּךְ מִלְּעִילָּא לְתַתָּא אֶתְפַּשְּׁטַת בְּעָלְמָא קַל מִתְּבַר טוּרֵין וּמְתַבַּר טִנָּרִין תַּקִּיפִין עִלְעוּלִין רַבְרְבִין סָלְקִין אוּדְנַנָא פְּתִיחָן</p>\n<p>הֲוָה אָמַר בִּמְטַלְּנוֹי קוֹץ קוֹצִיתָא דְּמִיכָן דְּמִיְּמִין שִׁינְתָּא בְּחוּרֵיהוֹן קַיָּימִין בִּקְיוֹמֵיהוּן מַלְכָּא דְּמִמְּלָל (וְלָא אִעַבַּרוּ אִשְׁתְּכַחוּ) נָטְרֵי תַּרְעִין שֶׁלִּיטָא דְּחִילִין סַגִּיאִין קָם בְּקִיּוּמֶיהָ</p>\n<p>כֻּלְּהוּ לָא מַרְגְּשָׁן וְלָא יָדְעִי דְּסָפְרָא פָּתִיחַ וּבִשְׁמָא אֶכְתּוֹב וְדוֹמֶה קָאֵים וְנָטֵיל בְּחוּשְׁבָּנָא וְדָיְירִי עַפְרָא תַּיְיבִין לְבַר וְקָרִיב טָב לְאִתְמְנְאָה בְּהוּ לָא תְּאֵיבִין גִּלְגּוֹלָא וַהֲפוֹךְ</p>\n<p>נָפְלִין וְלָא קָיְימִין אִתְמְחוּן חַיָּיבִין מִסִּפְרָא דְּדוֹמֶה מַאן יִתְבַּע לוֹן וּמַאן יָתֵיב בְּחוּשְׁבָּנְהוֹן וָוֵי לוֹן וָוֵי לִחְיָיְהוֹן וַוי לרגשׁיהון (ס\"א לְנַפְשִׁיהוֹן) בְּגִינְהוּן אִתַּקַּרִי (תהילים ס״ט:כ״ט) יִמְחוּ מִסְפַּר חַיִּים וְגוֹ':</p>"],[9520011254,"<p>וַיִּהְיוּ חַיֵּי שָׂרָה. מַאי שְׁנָא הָכָא שָׂרָה דִּכְתִיב מִיתָתָה בְּאוֹרַיְיתָא מִכָּל נְשֵׁי דְעַלְמָא דְּלָא כְּתִיב הָכִי מִיתַתְהוֹן בְּאוֹרַיְיתָא. אָמַר רַבִּי חִיָיא וְלָאו, וְהָכְתִיב (בראשית ל״ה:י״ט) וַתָּמָת רָחֵל וַתִּקָּבֵר בְּדֶרֶךְ אֶפְרָתָה. וּכְּתִיב, (במדבר כ׳:א׳) וַתָּמָת שָׁם מִרְיָם וְגו'. וּכְתִיב, (בראשית ל״ה:י״ט) וַתָּמָת דְּבוֹרָה <Nonei></i>מֵינֶקֶת רִבְקָה. וּכְתִיב, (בראשית ל״ח:י״ב) וַתָּמָת בַּת שׁוּעַ אֵשֶׁת יְהוּדָה.</p>\n<p>אָמַר רַבִּי יוֹסֵי בְּכֻלְּהוּ לָא כְּתִיב כְּמָה דִכְתִיב בְּשָׂרָה דְּאִתְּמָר וַיִּהְיוּ חַיֵּי שָׂרָה מֵאָה שָׁנָה וְעֶשְׂרִים שָׁנָה וְשֶׁבַע שָׁנִים שְׁנֵי חַיֵּי שָׂרָה. דְּהָא בְּכֻלְּהוּ לָא אִתְמָנוּן יוֹמִין וּשְׁנִין כְּמוֹ לְשָׂרָה. בְּכֻלְּהוּ לָא כְּתִיב פָּרְשָׁתָא חָדָא בִּלְחוּדָהָא כְּמוֹ לְשָׂרָה. אֶלָּא רָזָא אִיהוּ בְּגִין הַהוּא דַרְגָּא דְּכָל יוֹמִין וּשְׁנִין דְּבַר נָשׁ בֵּיהּ תַּלְיָין (דדא היא ה\"א בתראה).</p>\n<p>פָּתַח וְאָמַר, (קהלת ה׳:ח׳) וְיִתְרוֹן אֶרֶץ בַּכֹּל הִיא מֶלֶךְ לְשָׂדֶה נֶעֱבָד. וְיִתְרוֹן אֶרֶץ בַּכֹּל הִיא וַדַּאי דְּהָא מִתַּמָּן נָפְקִין רוּחִין וְנִשְׁמָתִין וְתוֹעַלְתָּא לְעַלְמָא. מֶלֶךְ לְשָׂדֶה נֶעֱבָד, מַאן מֶלֶךְ דָּא קוּדְשָׁא בְּרִיךְ הוּא. לְשָׂדֶה נֶעֱבָד כַּד אִיהוּ (עז ב אתתקן כדקא יאות. ומלך, דא, מלך עלאה דאתחבר לשדה כד איהו נעבד. מאן שדה, דא שדה אשר ברכו יי. דכתיב, (בראשית כ״ז:כ״ז)) כְּרִיחַ שָׂדֶה אֲשֶׁר בֵּרַכוֹ יְיָ. דְּכַד אִיהוּ (אתעבד) נֶעֱבַד וְאִתְתַּקַּן בְּכָל מַה דְּאִצְטְרִיךְ לֵיהּ כְּדְקָא יָאוֹת, כְּדֵין מֶלֶךְ עִלָּאָה אִתְחַבַּר עִמֵּיהּ.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, מֶלֶךְ לְשָׂדֶה נֶעֱבָד. כַּמָּה גַוְונֵי רָזִין עִלָּאִין הָכָא. מֶלֶךְ. דָּא (עזב) שְׁכִינְתָּא דְּלָא שַׁרְיָא בְּבֵיתָא לְאִתְתַּקָּנָא בָהּ אֶלָּא בְּזִמְנָא דְּאִתְנָסִיב בַּר נָשׁ וְאִזְדַּוַּוג בְּאִנְתְּתֵיהּ לְאוֹלָדָא וּלְמֶעְבַּד אִיבִּין, וְאִיהִי אֲפִיקַת נִשְׁמָתִין לְאַשְׁרָאָה בָהּ, וּבְגִין כָּךְ לְשָׂדֶה נֶעֱבָד וְלָא לְאָחֳרָא.</p>\n<p>דָּבָר אַחֵר מֶלֶךְ דָּא אִשָּׁה יִרְאַת יְיָ כְּמָא דְאַתְּ אָמֵר, (משלי ל״א:ל׳) אִשָּׁה יִרְאַת יְיָ הִיא תִתְהַלָּל. לְשָׂדֶה נֶעֱבָד דָּא אִשָּׁה זָרָה כְּמָא דְאַתְּ אָמֵר, (משלי ז׳:ה׳) לִשְׁמָרְךָ מֵאִשָּׁה זָרָה. בְּגִין דְּאִית שָׂדֶה וְאִית שָׂדֶה. אִית שָׂדֶה דְּכָל בִּרְכָאָן וְקִדּוּשִׁין בֵּיהּ שַׁרְיָין כְּמָה דְאַתְּ אָמֵר כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרַכוֹ יְיָ. וְאִית שָׂדֶה דְּכָל חִירוּב וּמְסָאֲבוּ וְשֵׁיצָאָה וְקָטוֹלִין וּקְרָבִין בֵּיהּ שָׁרְיָין. וְהַאי מֶלֶךְ זִמְנִין דְּאִיהוּ נֶעֱבַד לְהַאי שָׂדֶה דִּכְתִיב, (משלי ל׳:כ״ב) תַּחַת שָׁלשׁ רָגְזָה אֶרֶץ <Nonei></i>וְגו', תַּחַת עֶבֶד כִּי יִמְלוֹךְ וְגו' וְשִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ. וְהַאי מֶלֶךְ אִתְכַּסְּיָא נְהוֹרֵיהּ וְאִתְחַשָּׁךְ עַד דְּאִתְדַּכֵּי וְאִתְחַבַּר לְעֵילָא.</p>\n<p>וּבְגִין כָּךְ שָׂעִיר דְּרֹאשׁ חוֹדֶשׁ, בְּגִין דְּאִתְפְּרַשׁ הַהוּא שָׂדֶה מִמַּלְכָּא קַדִּישָׁא וְלָא שַׁרְיָין בְּהַאי שָׂדֶה בִּרְכָאָן מֵהַאי מֶלֶךְ. וְכַד אִיהוּ נֶעֱבַד לְהַאי שָׂדֶה כְּדֵין כְּתִיב, (דברים כ״ב:כ״ז) כִּי בַשָּׂדֶה מְצָאָהּ וְגו'. כִּי בַּשָּׂדֶה כְּמָה דְאִתְּמָר.</p>\n<p>תָּא חֲזֵי, אָתַת חַוָּה לְעַלְמָא אִתְדַּבְּקַת בְּהַאי חִוְּיָא וְאַטִּיל בָהּ זוּהֲמָא. וְגָרְמָא מוֹתָא לְעַלְמָא וּלְבַעֲלָהּ. אָתַת שָׂרָה וְנָחֲתַת וְסָלְקַת וְלָא אִתְדַּבְּקַת בֵּיהּ כְּמָא דְאַתְּ אָמֵר, (בראשית י״ג:א׳) וַיַּעַל אַבְרָם מִמִּצְרַיִם הוּא וְאִשְׁתּוֹ וְכָל אֲשֶׁר לוֹ. אֲתָא נֹחַ לְעַלְמָא מַה כְּתִיב (בראשית ט׳:כ״א) וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגָּל וְגו'.</p>\n<p>וּבְגִין דְּאַבְרָהָם וְשָׂרָה לָא אִתְדַּבָּקוּ בֵּיהּ, בְגִין כָּךְ שָׂרָה זָכְתָה לְחַיִּין עִלָּאִין לָהּ וּלְבַעֲלָהּ וְלִבְנָהָא בַּתְרָאָה הֲדָא הוּא דִכְתִיב (ישעיהו נ״א:א׳) הַבִּיטוּ אֶל צוּר חוּצַבְתֶּם וְאֶל מַקֶּבֶת בּוֹר נוּקַרְתֶּם. וְעַל דָּא וַיִּהְיוּ חַיֵּי שָׂרָה דְּזָכְתָה בְּהוּ בְּכֻלְּהוּ, וְלָא כְּתִיב בְּכֻלְּהוּ נַשֵּׁי וַיִּהְיוּ חַיֵּי חַוָּה, וְכֵן בְּכֹלָּא, הִיא אִתְדַּבְּקַת בַּחַיִּין, וְעַל דָּא דִילָהּ הֲווּ חַיִּין:</p>"],[9520011255,"<p><Noneb>תּוֹסֶפְתָּא</b> זַכָּאָה אִיהוּ מַאן דְּאַזְעִיר גַּרְמֵיהּ בְּהַאי עַלְמָא. כַּמָּה אִיהוּ רַב וְעִלָּאָה בְּהַהוּא עַלְמָא. וְהָכִי פָּתַּח רַב מְתִּיבְתָּא מַאן דְּאִיהוּ זְעֵיר אִיהוּ רַב. מַאן דְּאִיהוּ רַב אִיהוּ זְעֵיר. דִּכְתִּיב וַיִּהְיוּ חַיֵּי שָׂרָה וְגו' מֵאָה דְּאִיהוּ חוּשְׁבַּן רַב כְּתִּיב בֵּיהּ שָׁנָה, זְעִירוּ דִשְׁנִין חַד אַזְעִיר לֵיהּ. שֶׁבַע דְּאִיהוּ חוּשְׁבַּן זָעִיר אַסְגֵּי לֵיהּ ורַבֵּי לֵיהּ דִּכְתִּיב שָׁנִים. תָּא חֲזֵי, דְּלָא רַבֵּי קוּדְשָׁא בְּרִיךָ הוּא אֶלָּא לִדְאַזְעִיר, ולָא אַזְעִיר אֶלָּא לִדְרַבֵּי. זַכָּאָה אִיהוּ מַאן דְּאַזְעִיר גַּרְמֵיהּ בְּהַאי עַלְמָא, כַּמָּה אִיהוּ רַב בְּעִלּוּיָא לְהַהוּא עַלְמָא. עַד כָּאן.</p>\n<p>מַאן דְּפָּסַק יִתְּפַּסַק. מַאן דְּקָצַּר יִתְּקַצַּר. מַאן דְּקָצַּר יִתְּאָרַךָ. רְצּוֹנוֹ לוֹמַר מַאן דְּפָּסַק מִלִּין דְּאוֹרַיְיתָּא על מִלִּין בְּטֵלִין יִתְּפַּסְקוּן חַיּוֹהִי מֵהַאי עַלְמָא וְדִינִיהּ קָיְימָא בְּהַהוּא עָלְמָא. מַאן דְּקָצַּר אָמֵן ולָא מַאֲרִיךָ גּוֹ נַיְיחָא יִתְּקַצַּר מֵחַיִּין דְּהַאי עָלְמָא. מַאן דְּאָמַר אֶחָד אִצְּטְרִיךָ לְחָטְפָּא אָלֶ\"ף וּלְקַצֵּר קַרְנָא דִילֵיהּ ולָא יְעַכֵּב בְּהַאי אוֹתּ כְּלָל, וּמַאן דְּיַעֲבִיד דָּא יִתְּאָרְכוּן חַיָּיו. (אלו הם חדושים שהגידו לרבי שמעון בר יוחאי בישיבה של מעלה), (עד כאן התוספתא השייך לדף קכב ע\"ב)</p>"],[9520011256,"<p>וַיִּהְיוּ חַיֵּי שָׂרָה. אִינוּן חַיִּין כֻּלְּהוּ לְעֵילָא, מֵאָה שָׁנָה לְעֵילָא. וְעֶשְׂרִים שָׁנָה לְעֵילָא, וְשֶׁבַע שָׁנִים לְעֵילָא, כֻּלְּהוּ הֲווּ כְּדְקָא יְאוּת. אָמַר רַבִּי שִׁמְעוֹן <Nonei></i>תָּא חֲזֵי רָזָא דְמִלָּה, מַאי שְׁנָא בְּכֻלְּהוּ דְּאָמַר שָׁנָה שָׁנָה, וּבְאִינוּן שֶׁבַע דְּאָמַר שָׁנִים. דִּכְתִיב מֵאָה שָׁנָה וְעֶשְׂרִים שָׁנָה, וּלְבָתַר שֶׁבַע שָׁנִים.</p>\n<p>אֶלָּא כֹּלָּא חֲד. מֵאָה שָׁנָה כְּלָלָא דְכֹלָּא (נ\"א כלא כחדא ברזא דמאה ברכאן בכל יומא. וכן עשרים שנה דאתכליל עלאה סתימא דכל סתימין, ובגין כך כתיב שנה רזא דיחודא). קוּדְשָׁא בְּרִיךְ הוּא דְּאִתְכְּלִיל מֵאֲתַר עִלָּאָה סְתִימָא דְכָל סְתִימִין בְּמֵאָה בְּרָזָא דְמֵאָה בִּרְכָאָן דְּכָל יוֹמָא, וְכֵן עֶשְׂרִים שָׁנָה, וּבְגִין כָּךְ כְּתִיב שָׁנָה רָזָא דְּיִחוּדָא דְּלָא אִתְפְּרַשׁ (צא ב) מַחֲשָׁבָה וְיוֹבְלָא לְעָלְמִין.</p>\n<p>שֶׁבַע שָׁנִים אִלֵּין אִתְפָּרְשָׁן וְנָפְקָאן מִכְּלָלָא סְתִימָאָה דִלְעֵילָא. וְאַף עַל גַּב דְּכֹלָּא יִחוּדָא חָדָא, אֲבָל מִתְפָּרְשָׁן בְּדִינָא וְרַחֲמֵי בְּכַמָּה סִטְרִין וְאוֹרְחִין מַה דְּלָא הֲוִי הָכִי לְעֵילָא. וּבְגִין כָּךְ כְּתִיב שָׁנָה רָזָא דְּיִחוּדָא דְּלָא אִתְפְּרַשׁ לְעָלְמִין. שֶׁבַע שָׁנִים אִלֵּין אִתְפָּרְשָׁאן בְּדִינָא וְרַחֲמֵי בְּכַמָּה סִטְרִין וְאוֹרְחִין מַה דְּלָא הֲוֵי הָכִי לְעֵילָא. וּבְגִין כָּךְ בְּאִלֵּין שֶׁבַע שָׁנִים כְּתִיב בְּהוּ שָׁנִים וְלָא שָׁנָה, וְכֻלְּהוּ אִקְרוּן חַיִּים. וַיִּהְיוּ חַיֵּי שָׂרָה, דְּהֲווּ מַמָּשׁ דְּאִתְבְּרִיאוּ וְאִתְקַיְּימוּ לְעֵילָא.</p>\n<p>אָמַר רַבִּי חִיָּיא הָא אוּקְמוּהָ דְהָא כַּד אִתְעַקַּד יִצְחָק בַּר תְּלָתִין וְשֶׁבַע שָׁנִים הֲוָה, וְכֵיוָן דְּאִתְעַקַּד יִצְחָק מִיתַת שָׂרָה, דִּכְתִיב וַיָּבֹא אַבְרָהָם לִסְפֹּד לְשָׂרָה וְלִבְכֹּתָהּ. מֵאַיִן בָּא, מֵהַר הַמּוֹרִיָּה בָּא מִלְּמֶעֱקַד לֵיהּ לְיִצְחָק, וְאִינוּן תְּלָתִין וְשֶׁבַע שְׁנִין מִיּוֹמָא דְּאִתְיְילִיד יִצְחָק עַד שַׁעְתָּא דְּאִתְעַקַּד אִינוּן הֲווּ חַיֵּי שָׂרָה וַדַּאי כְּחוּשְׁבַּן וַיִּהְי\"וּ בְּגִימַטְרִיָּ\"א תְּלָתִין וּשְׁבַע שְׁנִין הֲווּ כְּמָה דְּאִתְּמָר מִדְּאִתְיְלִיד יִצְחָק עַד דְּאִתְעַקַּד.</p>"],[9520011257,"<p>רַבִּי יוֹסֵי פָּתַח וְאֲמַר, (תהילים צ״ח:א׳) מִזְמוֹר שִׁירוּ לַיְיָ שִׁיר חָדָשׁ כִּי נִפְלָאוֹת עָשָׂה הוֹשִׁיעָה לוֹ יְמִינוֹ וּזְרוֹעַ קָדְשׁוֹ. הַאי קְרָא אוּקְמוּהָ חַבְרַיָא, דְּפָרוֹת אֲמְרוּהָ. כְּמָה דִכְתִיב, (שמואל א ו׳:י״ב) וַיִּשַּׁרְנָה הַפָּרוֹת בַּדֶּרֶךְ. מַאי וַיִּשַּׁרְנָה, דְּהֲווּ אָמְרֵי שִׁירָתָא חַדְתָּא. וּמַאי שִׁירָה אָמְרוּ. מִזְמוֹר שִׁירוּ לַיְיָ שִׁיר חָדָשׁ כִּי נִפְלָאוֹת עָשָׂה.</p>\n<p>הָכָא אִית לְאִסְתַּכָּלָא, דְּכָל מַה דְּבָרָא קוּדְשָׁא בְּרִיךְ הוּא בְּעַלְמָא כֻּלְּהוּ אָמְרִי תּוּשְׁבְּחָן וְשִׁירָתָא קַמֵּיהּ בֵּין לְעֵילָא בֵּין לְתַתָּא, וְאִי תֵימָא דְּאִינְהוּ מִגַּרְמַיְיהוּ (ד\"א ל\"ג הוו) אָמְרֵי שִׁירָתָא דָא, הָכִי הוּא וַדַּאי דְּרָזָא עִלָּאָה אִיהוּ, אֲבָל הַנֵּי, אֲרוֹנָא הֲוָה עַל גַּבַּיְיהוּ, וְכֵיוָן דַּאֲרוֹנָא אִשְׁתְּקִיל עֲלַיְיהוּ וְשַׁוְיוּהָ לְעֵילָא אִינוּן שְׁרִירוּ (נ\"א לא שכיבו מ) שִׁירָתָא, דְּהָא כֵּיוָן דְּאִתְנְטִיל מִנַּיְיהוּ אֲרוֹנָא הֲווּ גָעָאן כְּאוֹרַח שְׁאָר פָּרוֹת דְּעַלְמָא וְלָא אָמְרוּ שִׁירָתָא. וַדַּאי אֲרוֹנָא <Nonei></i>דְּעַל גַּבַּיְיהוּ עָבִיד לוֹן לְזַמְּרָא.</p>\n<p>מִזְמוֹר. הָא אוֹקִימְנָא, וְאִתְּמָר בְּכֹלָּא כְּתִיב מִזְמוֹר לְדָוִד אוֹ לְדָוִד מִזְמוֹר. וְהָכָא לָא אָמַר דָּוִד כְּלָל. אֶלָּא מִזְמוֹר דְּרוּחַ קוּדְשָׁא זַמִּין לְזַמְּרָא לֵיהּ לְזִמְנָא דְיוֹקִים קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל מֵעַפְרָא. וּכְדֵין שִׁירוּ לַיְיָ שִׁיר חָדָשׁ, כְּדֵין אִיהוּ חָדָשׁ, דְּהָא שִׁירָתָא כְּהַאי לָא אִתְּמָר מִיּוֹמָּא דְאִתְבְּרֵי עָלְמָא.</p>\n<p>אָמַר רַבִּי חִיָּיא כְּתִיב, (קהלת א׳:ט׳) אֵין כָּל חָדָשׁ תַּחַת הַשֶּׁמֶשׁ. וְהָכָא שִׁירָתָא דָא אִיהִי חָדָשׁ וְאִיהִי תַּחַת הַשֶּׁמֶשׁ, דְּהָא תְּחוֹת שִׁמְשָׁא לֶהוֵי. וּמַאי אִיהוּ דָּא סִיהֲרָא, וּכְדֵין הֲוִי חָדָשׁ תַּחַת הַשֶּׁמֶשׁ. מַאי טַעְמָא בְּגִין כִּי נִפְלָאוֹת עָשָׂה. וּמַאן אִינוּן נִפְלָאוֹת, הַאי דִכְתִיב הוֹשִׁיעָה לוֹ יְמִינוֹ וּזְרוֹעַ קָדְשׁוֹ. הוֹשִׁיעָה לוֹ. לְמַאן <Nonei></i>לְהַהוּא דַרְגָּא דְּאָמַר שִׁירָתָא דָא, בְּגִין דְּבְּהוּ אִסְתַּמִּיךְ בִּימִינָא וּבִשְׂמָאלָא. הוֹשִׁיעָה לוֹ יְמִינוֹ, וַדַּאי לְהַהוּא דַרְגָּא דְּהַאי מִזְמוֹר, אֵימָתַי בְּזִמְנָא דִּיקוּמוּן מֵתֵי עַלְמָא וְיִתְעָרוּן מֵעַפְרָא, כְּדֵין יְהֵא חָדָשׁ מַה דְּלָא אִתְעֲבִיד בְּהַאי עָלְמָא.</p>\n<p>רַבִּי יוֹסֵי אָמַר בְּזִמְנָא דְּיַעֲבִיד קוּדְשָׁא בְּרִיךְ הוּא נוּקְמִין בְּעָלְמָא בְּגִינַיְיהוּ דְיִשְׂרָאֵל, כְּדֵין יִתְאֲמַר שִׁירָתָא, דְּהָא לְבָתַר יִתְעָרוּן מֵעַפְרָא מֵתֵי עַלְמָא וְיִתְחַדֵּשׁ עַלְמָא בְּקִיּוּם שְׁלִים דְּלָא לֶיהוֵי (כקדמיתא דשליט מותא בעלמא בגין דחויא) (נ\"א כרת ומיתה בעלמא ויתעבר חויא מעלמא דגרים) גָּרִים מוֹתָא בְּעַלְמָא לְכֹלָּא וְאִסְתָּאַב עַלְמָא וְאִתְחֲשִׁיךְ אַנְפּוֹי.</p>"],[9520011258,"<p>תָּא חֲזֵי, כְּתִיב, (בראשית ג׳:ט״ו) וְאֵיבָה אָשִׁית בֵּינְךָ וּבֵין הָאִשָּׁה. מַאי וְאֵיבָה כְּדִכְתִיב (איוב ט׳:כ״ו) חָלְפוּ עִם אֳנִיּוֹת אֵבֶה. דְּהָא כַּמָּה אַרְבִין שָׁטָאן גּוֹ יַמָּא רַבָּא, וְאִית אַרְבִין וּסְפִינָן מִתְפָּרְשָׁן דָּא מִן דָּא. וְאִינוּן אַרְבִין דְּהַאי נָחָשׁ שָׁאט בְּגַוַּויְיהוּ אִקְרוּן אֳנִיּוֹת אֵבָה.</p>\n<p>בֵּינְךָ וּבֵין הָאִשָּׁה. דָּא אִשָּׁה יִרְאַת יְיָ. וּבֵין זַרְעֶךָ, אִלֵּין שְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וּבֵין זַרְעָהּ, אִלֵּין יִשְׂרָאֵל. הוּא יְשׁוּפְךָ רֹאשׁ, דָּא קוּדְשָׁא בְּרִיךְ הוּא דְּזַמִּין לְבַעֲרָא לֵיהּ מֵעַלְמָא דִּכְתִיב, (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוְת לָנֶצַח. וּכְתִיב, (זכריה י״ג:ב׳) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ.</p>\n<p>רֹאשׁ, דָּא לְזִמְנָא דְאָתֵי דְיִתְעָרוּן מֵתַיָא. דְּהָא כְּדֵין לֶהֱוֵי עַלְמָא רֹא\"שׁ, דְּיִתְקַיַּים בָּרֹא\"שׁ דְּאִיהוּ עַלְמָא עִלָּאָה. וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב. דָּא בְּהַאי עַלְמָא הַשְׁתָּא דְאִיהוּ עָקֵב וְלָאו אִיהוּ בְּקִיּוּמָא וְהַהוּא חִוְיָא נָשִׁיךְ לְעַלְמָא וְאַחְשִׁיךְ אַנְפּוֹי בִּרְיָין.</p>\n<p>תָּא חֲזֵי, יוֹמִין דְּבַר נָשׁ אִתְבְּרִיאוּ וְקָיְימוּ בְּאִינוּן דַּרְגִּין עִלָּאִין, כֵּיוָן דִּמְסַיְימוּ לְאִתְקַיְימָא בְּאִינוּן דַּרְגִּין דִּכְתִיב, (תהילים צ׳:י׳) יְמֵי שְׁנוֹתֵינוּ בָּהֶם שִׁבְעִים שָׁנָה וְגו', מִכָּאן וּלְהָלְאָה לֵית דַּרְגָא לְאִתְקַיְּימָא. וּבְגִין כָּךְ וְרָהְבָּ\"ם עָמָל וָאָוֶן. וְאִינוּן כְּלָא הֲווּ.</p>\n<p>אֲבָל אִינוּן יוֹמִין דְּצַדִּיקַיָא <Nonei></i>הֲווּ וְאִתְקָיְימוּ כְּמָא דְאַתְּ אָמֵר וַיִּהְיוּ חַיֵּי שָׂרָה. וְכֵן וְאֵלֶּה יְמֵי שְׁנֵי חַיֵּי אַבְרָהָם. וְאִי תֵימָא הָכִי נָמֵי כְּתִיב בְּיִשְׁמָעֵאל דִּכְתִיב, (בראשית כ״ה:ז׳) שְׁנֵי חַיֵּי יִשְׁמָעֵאל. אֶלָּא בִּתְשׁוּבָה אַהֲדַר, וְעַל דָּא קָרֵי (ביומוי) וַיִּהְיוּ:</p>"],[9520011259,"<p><Nonei></i><Noneb>מִדְרָשׁ הַנֶּעֱלָם</b> וַיִּהְיוּ. רַבָּנָן פָּתְחֵי בְּהַאי קְרָא, (שיר השירים ז׳:י״ב) לְכָה דוֹדִי נֵצֵּא הַשָּׂדֶה נָלִינָה בַּכְּפָרִים. תָּנוּ רַבָּנָן הַיּוֹצֵּא לַדֶּרֶךְ יִתְפַּלֵּל שָׁלשׁ תְּפִלּוֹת, תְּפִלָּה שֶׁהִיא חוֹבָה שֶׁל יוֹם. וּתְפִלַּת הַדֶּרֶךְ עַל הַדֶּרֶךְ שֶׁהוּא עוֹשֶׂה. וּתְפִלָּה שֶׁיַּחְזוֹר לְבֵיתוֹ לְשָׁלוֹם. וְלֵימָא לְהוּ לְהַנֵּי שְׁלשָׁה, אֲפִילּוּ בְּאֶחָד יָכִיל לְמֶעְבְּדֵיהּ, דְּתָנִינָן כָּל שְׁאֵלוֹתָיו שֶׁל אָדָם יָכִיל לְמִכְלְלִינְהוּ בְּשׁוֹמֵעַ תְּפִלָּה.</p>\n<p>אָמַר רַבִּי יְהוּדָה כָּל עוֹבָדוֹי דְּבַר נָשׁ כְּתִיבִין בְּסִפְרָא, הֵן טַב הֵן בִּישׁ, וְעַל כֻּלְּהוֹן עָתִיד לְמִיתַּן דִּינָא, דְּתָנִינָן אָמַר רַב יְהוּדָה אָמַר רַב, מַאי דִכְתִיב, (תהילים קל״ט:ט״ז) גָּלְמִי רָאוּ עֵינֶיךָ, אוֹתָם הַדְּבָרִים שֶׁעָשָׂה הַגּוֹלֶם שֶׁאֵינוֹ מַשְׁגִּיחַ בָּעוֹלָם הַבָּא, כּוּלָּם רָאוּ עֵינֶיךָ שֶׁעִיַּינְתָּ בָּהֶם. וְעַל סִפְרְךָ כּוּלָּם יִכָּתֵבוּ, לִיתֵּן עֲלֵיהֶם דִּין וחֶשְׁבּוֹן לָעוֹלָם הַבָּא, הִלְכָּךְ יַקְדִּים אָדָם תְּפִלָּתוֹ תָּמִיד וְיוֹעִיל לֵיהּ.</p>\n<p>אָמַר רַבִּי יִצְּחָק אֵין אָדָם עוֹשֶׂה עֲבֵירוֹת אֶלָּא מִי שֶׁהוּא גּוֹלֶם ולֹא אָדָם, וְהַיְינוּ הַהוּא דְּלָא מִסְתַּכַּל בְּנִשְׁמָתָא קַדִּישָׁא, אֶלָּא כָּל עוֹבָדוֹי כְּהַאי בְּעִירָא דְּלָא מַשְׁגַּחַת וְלָא יָדְעַת. אָמַר רַבִּי בּוֹ, וְכִי גוֹלֶם מִתְקְרֵי דָוד דְּאָמַר הַאי פְּסוּקָא. אָמַר לוֹ רַבִּי יִצְּחָק אָדָם הָרִאשׁוֹן אֲמָרוֹ, גָּלְמִי <Nonei></i>רָאוּ עֵינֶיךָ, קוֹדֶם שֶׁזָּרַקְתָּ בִּי נְשָׁמָה, רָאוּ עֵינֶיךָ לְמֶעְבַּד בִּדְיוֹקְנִי בְּנֵי נָשָׁא דְדָמוּ לִי. וְעַל סִפְרְךָ כֻּלָּם יִכָּתֵבוּ, מַאן אִינוּן. יָמִים יוּצָּרוּ, כְּהַאי צּוּרָה דִידִי. וְלֹא אֶחָד בָּהֶם דְּלָא אִשְׁתָּאַר חַד מִנְּהוֹן.</p>\n<p>אָמַר רַבִּי בּוֹ, לָמָּה. אָמַר לֵיהּ תָּא חֲזֵי, כֻּלְּהוּ דְדָמוּ לֵיהּ אוֹ בִּרְמִיזָא דִילֵיהּ, לָא מֵתוּ בְּמִיתַת נַפְשְׁהוֹן, וְכֻלְּהוּ לָקוּ בְּהַהוּא עִנְיָינָא מַמָּשׁ. תָּא חֲזֵי, אָמַר רַבִּי יְהוּדָה דִּיוּקְנֵיהּ דְּאָדָם הָרִאשׁוֹן וְשַׁפִּירוּתֵיהּ הֲוָה כְּזָהֲרָא דִּרְקִיעָא עִלָּאָה דְּעַל גַּבֵּי שְׁאָר רְקִיעֵי, וּכְהַהוּא נְהוֹרָא דְּגָנִיז קוּדְשָׁא בְּרִיךְ הוּא לְצַּדִּיקַיָּיא לְעַלְמָא דְאָתֵי, וְכָל אִינוּן דְּהֲווּ רְמִיזָא בֵּיהּ מִדִיוּקְנֵיהּ דְּאָדָם הָרִאשׁוֹן בֵּיהּ לָקוּ וּמִיתוּ.</p>\n<p>דְּכָךְ אוֹרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא, יָהִיב עוּתְרָא לְבַר אִינִישׁ, לָמָּה, לְמֵיזַן עֲנָיִין וּלְמֶעְבַּד פִּקּוּדוֹי. לָא עָבִיד הַאי ואִתְגָאֵי (ואי אתגליא ביה) בְּהַהוּא עוּתְרָא, בֵּיהּ יִלְקֵי דִּכְתִיב, (קהלת ה׳:י״ב) עשֶׁר שָׁמוּר לִבְעָלָיו לְרָעָתוֹ. יָהִיב לֵיהּ בְּנִין, לָמָּה, לְמֵילַף לְהוּ אוֹרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא, וּלְמִיטַר פִּקּוּדוֹי כִּדְאָמוּר בְּאַבְרָהָם (בראשית י״ח:י״ט) כִּי יְדַעְתִּיו לְמַעַן אֲשֶׁר יְצַּוְּה אֶת בָּנָיו וְאֶת בֵּיתוֹ אַחֲרָיו וְשָׁמְרוּ דֶרֶךְ יְיָ לַעֲשׂוֹת צְּדָקָה וְגו'. לָא עָבִיד הַאי וּמִתְגָּאֶה בְּהוּ, בְּהוּ לָקֵי דִּכְתִיב, (איוב י״ח:י״ט) לֹא נִין לוֹ וְלֹא נֶכֶד בְּעַמּוֹ וְגו'. וְכֵן כְּהַאי גַוונָא כַּד יָהִיב קוּדְשָׁא בְּרִיךְ הוּא מִשַׁפִּירוּתָא טָבָא עִלָּאָה דְאָדָם הָרִאשׁוֹן לְהוּ, לָמָּה, בְּגִין לְמִיטַר פִּקּוּדוֹי וּלְמֶעְבַּד רְעוּתֵיהּ, לָא עָבְדוּ כְּדֵין אֶלָּא אִתְגָּאוּ בֵּיהּ. בֵּיהּ לָקוּ בְּהַאי שַׁפִּירוּתָא.</p>\n<p>אָמַר רַב יְהוּדָה, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא אָדָם הָרִאשׁוֹן, הֲוָה גוֹלֶם עַד לָא זָרִיק בֵּיהּ נִשְׁמָתָא, וְקָרָא לְהַהוּא מַלְאָכָא דְּהוּא מְמוּנֶּה עַל דִּיוּקְנָא דִּבְנֵי נָשָׁא, וְאָמַר לוֹ עַיֵּין וְצֹּר בְּדִיוּקְנָא דְדֵין שִׁיתָּא בְּנִי נְשָׁא, הֲדָא הוּא דִכְתִיב, (בראשית ה׳:ג׳) וַיּוֹלֶּד בִּדְמוּתוֹ כְּצַּלְמוֹ וַיִּקְרָא אֶת שְׁמוֹ שֵׁת, כְּלוֹמַר שִׁיתָּא.</p>\n<p>אָמַר רַבִּי יִצְּחָק מֵהַהוּא עַפְרָא מַמָּשׁ דְּאִתְבְּרֵי אָדָם הָרִאשׁוֹן נָסִיב קוּדְשָׁא בְּרִיךְ הוּא לְאִתְבְּרָאָה אִלֵּין שִׁיתָּא, וְקָרָא לֵיהּ שֵׁת, שִׁיתָּא, הֲדָא הוּא דִכְתִיב <Nonei></i>וַיּוֹלֶד בִּדְמוּתוֹ כְּצַּלְּמוֹ מֵאוֹתָהּ הָעִיסָה שֶׁנִּבְרָא הַגּוֹלֶם שֶׁלּוֹ, וְעַל כָּךְ נֶאֱמַר גָּלְמִי רָאוּ עֵינְיךָ וְעִיַינְת בּוֹ לַעֲשׂוֹת (ד\"א ל\"ג בו) דְּדָאמוּ לֵיהּ. וְעַל סִפְרְךָ כֻּלָּם יִכָּתֵבוּ, מַאן אִינוּן, כֻּלְּהוּ דְּלָא נָטְרוּ מַאי דְּיָהַב קוּדְשָׁא בְּרִיךְ הוּא לוֹן וְאִתְטָרְדוּ מִן עַלְמָא (ואתדנו בההוא דינא).</p>\n<p>תְּנַן הָתָם אָמַר רַב יְהוּדָה אָמַר רַב אַשְׁכַּחְנָא דִּתְלַת מִטְרָן הֲוִי לֵילְיָא, וְכָל חַד וְחַד אִית עִנְיָינָא דְּקוּדְשָׁא בְּרִיךְ הוּא בְּבַר נָשׁ. כַּד נָפִיק נִשְׁמָתֵיהּ מִינֵּיהּ ואִשְׁתָּאַר הַהוּא גּוֹלְמָא נָאִים עַל עַרְסֵיהּ, וְנִשְׁמָתֵיהּ סָלְקָא בְּכָל לֵילְיָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, אָמַר רַבִּי יִצְּחָק אִי זַכָּאָה הִיא חָדָאן עִמַּהּ, וְאִי לָא דַּחְיָין לָהּ לְבַר. אָמַר רַב יְהוּדָה אָמַר רַב מַאי דִכְתִיב, (שיר השירים ה׳:ח׳) הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלַםִ אִם תִּמְצְּאוּ אֶת דּוֹדִי מַה תַּגִּידוּ לוֹ שֶׁחוֹלַת אַהֲבָה אָנִי.</p>\n<p>אָמַר רַבִּי פִּנְחָס אָמַר רַבִּי יְהוּדָה הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלַם, הַנְּשָׁמָה אוֹמֶרֶת לְאוֹתָם הַנְּשָׁמוֹת הַזּוֹכוֹת לִיכָּנֵס לִירוּשָׁלַם שֶׁל מַעְלָה, והֵם הַנִּקְרָאוֹת בְּנוֹת יְרוּשָׁלַםִ עַל שֶׁזּוֹכוֹת לִיכָּנֵס שָׁם, וּלְפִיכָךְ הַנְּשָׁמָה אוֹמֶרֶת לָהֶם הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלַםִ אִם תִּמְצְּאוּ אֶת דּוֹדִי דָּא קוּדְשָׁא בְּרִיךְ הוּא. רַב אָמַר זֶה זִיו אַסְפַּקְלַרְיָאה שֶׁל מַעְלָה. מַה תַּגִּידוּ לוֹ שֶׁחוֹלַת אַהֲבָה אָנִי, לֵיהָנוֹת מִזִּיו שֶׁלּוֹ וּלְהִסְתּוֹפֵף בְּצִּלּוֹ. רַב הוּנָא אָמַר שֶׁחוֹלַת אַהֲבָה אָנִי, אוֹתָהּ הַתְּשׁוּקָה וְהַכִּסּוּף שֶׁכָּסַפְתִּי בָּעוֹלָם עַל הַכֹּל לְפִיכָךְ אֲנִי חוֹלָה. רַבִּי יְהוּדָה אָמַר זוֹ אַהֲבָה שֶׁאוֹהֶבֶת הַנְּשָׁמָה לַגּוּף, דְּכֵיון שֶׁנִּשְׁלַם קִצּוֹ שֶׁל גּוּף אוֹתָם הַיָּמִים שֶׁנִּגְזְרוּ עָלָיו כְּמָה דְאַתְּ אָמֵר וַיִּהְיוּ חַיֵּי שָׂרָה, מַה כְּתִיב וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ וְגו'.</p>\n<p>אָמַר רַב יְהוּדָה אָמַר רַב מַה כְּתִיב בַּפָּסוּק קוֹדֶם זְה דִּכְתִיב וַתָּמָת שָׂרָה בְּקִרְיַת אַרְבַּע הִיא חֶבְרוֹן בְּאֶרֶץ כְּנַעַן.</p>\n<p>רַבִּי יִצְּחָק אָמַר רַבִּי יוֹחָנָן בָּרָא <Nonei></i>קוּדְשָׁא בְּרִיךְ הוּא לָאָדָם וְהִכְנִיס בּוֹ אַרְבָּעָה דְבָרִים הַנֶּחֱלָקִים בַּגּוּף. אָמַר רַבִּי יְהוּדָה הַמְחוּבָּרִים בַּגּוּף. רַבִּי יִצְּחָק אָמַר הַנֶּחלָקִים בַּגּוּף שֶׁהֵם חוֹלְקִים לְהִתְפָּרֵשׁ כָּל אֶחָד לִיסוֹדוֹ כְּשֶׁיּוֹצֵּא הָאָדָם מִן הָעוֹלָם הַזְּה. רַבִּי יְהוּדָה אָמַר הַמְחוּבָּרִים בַּגּוּף בְּחַיָּיו, מַשְׁמַע מִקְרָא דִכְתִיב וַתָּמָת שָׂרָה, זֶה הַגּוּף. בְּקִרְיַת אַרְבַּע, אֵלּוּ הָאַרְבַּע יְסוֹדוֹת. הִיא חֶבְרוֹן, שֶׁהָיוּ מְחוּבָּרִים בְּגוּפוֹ בְּחַיָּיו. בְּאֶרֶץ כְּנַעַן, בָּעוֹלָם הַזְּה הַבּוֹחֵר אָדָם בִּזְמַן מוּעָט:</p>"],[9520011260,"<p>וַיָּבֹא אַבְרָהָם לִסְפֹּד לְשָׂרָה ולִבְכֹּתָהּ. הַיְינוּ (דכתיב) דִתְנַן כָּל שִׁבְעַת הַיָּמִים נַפְשׁוֹ שֶׁל אָדָם פּוֹקֶדֶת לְגוּפוֹ וּמִתְאַבֶּלֶת עָלָיו, הֲדָא הוּא דִכְתִיב, (איוב י״ד:כ״ב) אַךְ בְּשָׂרוֹ עָלָיו יִכְאָב וְנַפְשׁוֹ עָלָיו תֶּאֱבָל. כְּהַאי גַוְונָא וַיָּבֹא אַבְרָהָם לִסְפֹּד לְשָׂרָה וְלִבְכֹּתָהּ. וַיָּבֹא אַבְרָהָם, זוֹ הִיא הַנְּשָׁמָה. לִסְפֹּד לְשָׂרָה, זְה הַגּוּף.</p>\n<p>אָמַר רַבִּי יִצְּחָק בְּשָׁעָה שֶׁהַנְּשָׁמָה זוֹכָה וְעוֹלָה לִמְקוֹם מַעֲלָתָהּ, הַגּוּף שׁוֹכֵב בְּשָׁלוֹם וְיָנוּחַ עַל מִשְׁכָּבוֹ הֲדָא הוּא דִכְתִיב, (איוב נז) יָבֹא שָׁלוֹם יָנוּחוּ עַל מִשְׁכְּבוֹתָם, הֹלֵךְ נְכֹחֹה. מַאי הוֹלֵךְ נְכֹחֹה. אָמַר רַבִּי יִצְּחָק הַנְּשָׁמָה הוֹלֵךְ נְכֹחֹה לִמְקוֹם הָעֵדֶן הַגָּנוּז לָהּ. מַאי מַשְׁמַע. אָמַר רַבִּי יְהוּדָה מֵהַאי מַשְׁמַע, נְכֹחֹה כְּתִיב, (לפנינו כ' בואו ועי' לעיל פג ב בדרך אמת אות ג) בְּה\"א. וּבְשָׁעָה שֶׁאֵינָהּ זוֹכָה וְהִיא רְאוּיָה לְקַבֵּל <Nonei></i>עוֹנְשָׁהּ הוֹלֶכֶת מְשׁוֹמֶמֶת וּמְבַקֶּרֶת בְּכָל יוֹם לַגּוּף וְלַקֶּבֶר.</p>\n<p>אָמַר רַבִּי יוֹסֵי הַאי קוּלִיתָא דְקַרְדִינוּתָא, כַּד אָזִיל בִּסְרִיחוּתָא לְכָאן וּלְכָאן אָזַל וּמְבַקֵּר לָהּ לְאַתְרָהּ תְּרֵיסַר יַרְחֵי. כָּךְ נִשְׁמָתָא הַהִיא דְּאִתְחַזְּיָא לְקַבְּלָא עָנְשָׁא, אָזְלָה לְבַר בְּעַלְמָא וּמַפְקֶדֶת לָה לְאַתְרָהּ תְּרֵיסַר יַרְחֵי בְּבָתֵּי קִבְרֵי וּבְעַלְמָא.</p>\n<p>אָמַר רַבִּי יְהוּדָה תָּא חֲזֵי, דִּכְתִיב וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ וגו', אָמַר רַבִּי אַבָּא וְהָא תְּנַן דְּכַד נִשְׁמָתָא הִיא בְּתַשְׁלוּמָא עִלָּאָה, נִיתּוֹסַף בָּהּ ה' וְנִקְרֵאת אַבְרָהָם בְּתַשְׁלוּמָא עִלָּאָה. וְהָכָא אַתְּ אָמֵר דְּכַד לֵיתָא זַכָּאָה כָּל כָּךְ דִּכְתִיב וַיָּקָם אַבְרָהָם. עָבְדַת מַאן דְּיָתִיב בְּכֻּרְסְיָיא נָחִית בְּגוֹ זוּטָר תַּתָּאָה.</p>\n<p>אֶלָּא הָכִי גַּזַּרְנָא וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ, דְּאָמַר רַבִּי בּוֹ אָמַר רַבִּי זְרִיקָא כְּשֶׁהַנְּשָׁמָה רְאוּיָה לַעֲלוֹת לִמְקוֹם עִדְנָּה, קוֹדֶם מְגִינָה עַל הַגּוּף הַקָּדוֹשׁ שֶׁיּוֹצֵּאת מִשָּׁם וְאַחַר כָּךְ עוֹלָה לִמְקוֹם מַעֲלָתָהּ, הֲדָא הוּא דִכְתִיב וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ זְהוּ הַגּוּף.</p>\n<p>וַיְדַבֵּר אֶל בְּנֵי חֵת אֵלּוּ שְׁאָר גּוּפוֹת הַצַּדִּיקִים שֶׁהֵם (ד\"א ל\"ג בני) חַתְּחַתִּים וְנְהֱלָמִים בָּעוֹלָם לְמַעַן יִרְאַת קוֹנָם, חָתִּים עַל שֶׁהֵם שׁוֹכְנֵי עָפָר, וְאַמַּאי צְּרִיכָה לְהוּ אָמַר רַבִּי יְהוּדָה כֹּלָּא בְּמִנְיָינָא כְּתִיבִין, וְעַל (דהוי ד\"א דא הוי ההוא) גוּפָא בְּמִנְיָינָא עִמְּהוֹן.</p>\n<p>וּמַה אָמַר לְהוּ בְּדֶרֶךְ פִּיּוּס וּבְדֶרֶךְ כָּבוֹד. <Nonei></i>גֵּר וְתוֹשָׁב אָנֹכִי עִמָּכֶם וְגו' דְּהַאי גּוּפָא יֶהֱוִי בְּמִנְיָינָא חַד עִמְּכוֹן בְּחִבּוּרָא דָא. אָמַר רַבִּי רְאֵה מַה כְּתִיב וַיַּעֲנוּ בְּנֵי חֵת אֶת אַבְרָהָם וְגו'. כְּמוֹ כֵן בְּדֶרֶךְ כָּבוֹד בְּדֶרֶךְ פִּיּוּס, הֲדָא הוּא דִכְתִיב שְׁמָעֵנוּ אֲדוֹנִי נְשִׂיא אֱלֹהִים אַתָּה בְּתוֹכֵנוּ.</p>"],[9520011261,"<p>מַאי נְשִׂיא אֱלֹהִים אַתָּה. אָמַר רַבִּי פִּנְחָס קוֹדֶם שֶׁיִּצֵּא הַצַּדִּיק מִן הָעוֹלָם, בַּת קוֹל יוֹצֵּאת בְּכָל יוֹם עַל אוֹתָם הַצַּדִּיקִים בְּגַן עֵדֶן הָכִינוּ מָקוֹם לִפְלוֹנִי שֶׁיָּבֹא לְכָאן. וְעַל כֵּן הֵם אוֹמְרִים מֵאֵת אֱלהִים מִלְּמַעְלָה אַתָּה נָשִׂיא בְּכָל יוֹם בְּתוֹכֵנוּ, בְּמִבְחַר קְבָרֵינוּ בְּמִבְחַר הַצַּדִּיקִים הַצַּדִּיקִים בַּחֲבוּרַת הַמּוּבְחָרִים מְנֵה אוֹתוֹ הַכְנִיסֵהוּ בְּחֶשְׁבּוֹן עִמָּנוּ, וְאִישׁ מִמֶּנּוּ לֹא יִמְנַע אֶת הַמִּנְיָן כִּי כוּלָּנוּ שְׂמֵחִים בּוֹ וּמַקְדִּימִים לוֹ שָׁלוֹם.</p>\n<p>אָמַר רַבִּי יוֹסֵי בֶּן <Nonei></i>פַּזִּי תָּא חֲזֵי, כֵּיוָן שֶׁהַנְּשָׁמָה פּוֹגַעַת בָּהֶם (ותדון), לְאַחַר כָּךְ פּוֹגַעַת לְאוֹתוֹ הַמַּלְאָךְ הַמְמוּנֶּה עֲלֵיהֶם דִּתְנַן מַלְאָךְ מְמוּנֶּה עַל בָּתֵּי קִבְרֵי וְדוּמָה שְׁמוֹ, והוּא מַכְרִיז בֵּינֵיהֶם בְּכָל יוֹם עַל הַצַּדִּיקִים הָעֲתִידִים לִיכָּנֵס בֵּינֵיהֶם, וּמִיָּד פּוֹגַעַת בּוֹ כְּדֵי לְשַׁכֵּן הַגּוּף בְּהַשְׁקֵט וּבְבִטְחָה וּבִמְנוּחָה וּבַהֲנָאָה, (עלאה) הֲדָא הוּא דִכְתִיב וַיְדַבֵּר אֶל עֶפְרוֹן.</p>\n<p>אָמַר רַבִּי יִיסָא זֶה הַמַּלְאָךְ הַנִּקְרָא דּוּמָה, וְלָמָּה נִתְכַּנֶּה שְׁמוֹ עֶפְרוֹן, עַל שֶׁהוּא מְמוּנֶּה עַל שׁוֹכְנֵי עָפָר. וְהוּפְקְדוּ בְּיָדוֹ כָּל פִּנְקְסֵי הַצַּדִּיקִים וַחֲבוּרוֹת הַחֲסִידִים הַשּׁוֹכְנִים בֶּעָפָר, וְהוּא עָתִיד לְהוֹצִּיאָם בְּחֶשְׁבּוֹן.</p>\n<p>וְתָאנָא אָמַר רַבִּי אֶלְעָזָר, לֶעָתִיד לָבֹא כְּשֶׁיִּפְקוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת הַמֵּתִים, יִקְרָא לַמַּלְאָךְ הַמְּמוּנֶּה עַל הַקְּבָרוֹת, וְדוּמָה שְׁמוֹ, וְיִתְּבַע מִמֶּנּוּ מִנְיַן כָּל הַמֵּתִים הַצַּדִּיקִים וְהַחֲסִידִים וְאוֹתָם גֵּרֵי הַצֶּדֶק וְשֶׁנֶּהֶרְגוּ עַל שְׁמוֹ, וְהוּא מוֹצִּיאָם בְּחֶשְׁבּוֹן כְּמוֹ שֶׁנְּטָלָם (שמות צז ב) בְּחֶשְׁבּוֹן, הֲדָא הוּא דִכְתִיב (ישעיהו מ׳:כ״ו) הַמּוֹצִּיא בְּמִסְפַּר צְּבָאָם וְגו' אִישׁ לא נֶעְדָר.</p>\n<p>וְתָאנָא אָמַר רַבִּי שְׁמוּאֵל בְּרַבִּי יַעֲקֹב, נְפָשׁוֹת הָרְשָׁעִים נְתוּנוֹת בְּיָדוֹ שֶׁל מַלְאָךְ זֶה שֶׁשְּׁמוֹ דוּמָה, לְהַכְנִיסָם בַּגֵּיהִנָּם ולָדוּן שָׁם, וְכֵיוָן שֶׁנִּמְסָרוֹת בְּיָדוֹ, שׁוּב אֵינָן חוֹזְרוֹת עַד שֶׁיִּכָּנְסוּ לַגֵּיהִנֹּם, וְזְה יִרְאַת דָּוִד שֶׁנִּתְיָירֵא כְּשֶׁעָשָׂה אוֹתוֹ עָוֹן שֶׁנְּאֱמַר (תהילים צ״ד:י״ז) לוּלֵי יְיָ עֶזְרָתָה לִי כִּמְעַט שָׁכְנָה דוּמָה נַפְשִׁי. אָמַר רַבִּי יִיסָא הַנְּשָׁמָה פּוֹגַעַת לוֹ לְהַכְנִיס אוֹתוֹ גּוּף עִם שְׁאָר גּוּפוֹת הַצַּדִּיקִים בְּחֶשְׁבּוֹנָם הֲדָא הוּא דִכְתִיב וַיְדַבֵּר אֶל עֶפְרוֹן וְגו'.</p>\n<p>אָמַר רַבִּי תַּנְחוּם הַמַּלְאָךְ קוֹדֵם וְאוֹמֵר לוֹ. רְאֵה מַה כְּתִיב לְמַעְלָה וְעֶפְרוֹן יוֹשֵׁב בְּתוֹךְ בְּנֵי חֵת, שִׁחֲתוֹ לִשְׁכּוֹן בֶּעָפָר. והוּא מַקְדִּים וְאוֹמֵר לוֹ לְהַכְנִיס אוֹתוֹ הַגּוּף בְּחֶשְׁבּוֹן הַצַּדִּיקִים, הֲדָא הוּא דִכְתִיב וַיַּעַן עֶפְרוֹן הַחִתִּי אֶת אַבְרָהָם בְּאָזְנֵי בְנֵי חֵת לְכֹל בָּאֵי שַׁעַר עִירוֹ לֵאמֹר. מַאי לְכֹל בָּאֵי שַׁעַר עִירוֹ. רַב נַחְמָן אָמַר אִינוּן <Nonei></i>דְּעָאלוּ בִּכְתַב חוּשְׁבַּן פִּנְקָסֵיהּ, דְּאָמַר רַב נַחְמָן וְהָכִי אִתְגְּזַר (על) חֶשְׁבּוֹן, עַל יְדוֹי דְדוּמָה עָאלִין בְּבָתֵּי קִבְרֵי וּבְחוּשְׁבַּן פִּתְקָא זַמִּין לְאֲפָקָא לוֹן וְהוּא מְמוּנֶּה עַל דַּיְירֵי עַפְרָא.</p>\n<p>מַהוּ הַשָּׂדֶה נָתַתִּי לָךְ וְהַמְּעָרָה אֲשֶׁר בּוֹ. אָמַר רַבִּי יוֹסֵי הַפְקָדָא דְּשַׁלְּוָה וּמְנוּחָה רַבָּה. אָמַר רַבִּי שָׁלוֹם בַּר מִנְיוּמֵי אֵין לְךָ כָּל צַּדִּיק וְצַּדִּיק מֵאוֹתָם הָעוֹסְקִים בַּתּוֹרָה שֶׁאֵין לוֹ מָאתַיִם עוֹלָמוֹת וְכִסּוּפִין בִּשְׁבִיל הַתּוֹרָה הֲדָא הוּא דִכְתִיב, (שיר השירים ח׳:י״ב) וּמָאתַיִם לַנּוֹטְרִים אֶת פִּרְיוֹ, וּמָאתַיִם עַל שֶׁמּוֹסְרִים עַצְּמָם בְּכָל יוֹם כְּאִילּוּ נֶהֶרְגוּ עַל קְדוּשַׁת שְׁמוֹ, נִצְּחוֹ כְּהַאי פְּסוּקָא (נ\"א וכך אמרו בהאי פסוקא) דִכְתִיב וְאָהַבְתָּ אֵת יְיָ וְגו'. וְתָאנָא כָּל הַמְכַוִין לִבּוֹ בְּהַאי פְּסוּקָא כְּדֵי לִמְסוֹר נַפְשׁוֹ עַל קְדוּשַׁת שְׁמוֹ מַעֲלֶה עָלָיו הַכָּתוּב כְּאִלּוּ נֶהֱרַג בְּכָל יוֹם עָלָיו, הֲדָא הוּא דִכְתִיב, (תהלים מה) כִּי עָלֶיךָ הוֹרַגְנוּ כָּל הַיּוֹם. אָמַר רַב נַחְמָן כָּל הַמּוֹסֵר נַפְשׁוֹ בְּהַאי פְּסוּקָא נוֹחֵל אַרְבַּע מֵאוֹת עוֹלָמוֹת לָעוֹלָם הַבָּא. אָמַר רַב יוֹסֵף וְהָא תְּנַן מָאתַיִם. אָמַר רַב נַחְמָן מָאתַיִם עַל הַתּוֹרָה, וּמָאתַיִם עַל שֶׁמָּסַר עַצְּמוֹ בְּכָל יוֹם עַל קְדוּשַׁת שְׁמוֹ,</p>"],[9520011262,"<p>וַתָּמָת שָׂרָה בְּקִרְיַת אַרְבַּע. רַבִּי אַבָּא אָמַר כְּגַוְונָא דָא לָא הֲווּ בְּכָל נְשֵׁי עַלְמָא דְּהָא אִתְּמָר חוּשְׁבַּן יוֹמָהָא וּשְׁנָהָא וְקִיּוּמָהָא בְּעָלְמָא וְהַהוּא אֲתַר דְּאִתְקַבְרַת בֵּיהּ. אֶלָּא לְאַחֲזָאָה דְּלָא הֲוָה כְּשָׂרָה בְּכָל נְשֵׁי עָלְמָא.</p>\n<p>וְאִי תֵימָא הָא מִרְיָם דִּכְתִיב (במדבר כ׳:א׳) וַתָּמָת שָׁם מִרְיָם וַתִּקָּבֵר שָׁם. בְּגִין לְאַחֲזָאָה סָרְחָנָא דְיִשְׂרָאֵל קָא אֲתָא, דְּהָא מַיָיא לָא אָזְלֵי לְהוּ בְּיִשְׂרָאֵל אֶלָּא בִּזְכוּתָא דְמִרְיָם. אֲבָל לָא אִתְּמָר בְּמִיתָתָהּ כְּמָה דְאִתְּמָר בְּשָׂרָה.</p>\n<p>רַבִּי יְהוּדָה פָּתַח (קהלת י׳:י״ז) אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִין וְשָׂרַיִךְ בָּעֵת יאכֵלוּ. הַאי קְרָא (צה ב) אוּקְמוּהָ חַבְרַיָיא, אֲבָל אִית לָן לְאִסְתַּכָּלָא בֵּיהּ, דְּזַכָּאִין אִינוּן יִשְׂרָאֵל דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב לוֹן אוֹרַיְיתָא לְמִנְדַע כָּל אוֹרְחִין סְתִימִין וּלְאִתְגַּלְּיָיא לוֹן רָזִין עִלָּאִין וְהָא אִתְּמָר.</p>\n<p>אַשְׁרֵיךָ אֶרֶץ, דָּא אֶרֶץ הַחַיִּים, בְּגִין דְּמַלְכָּא דִילָהּ אַזְמִין לָהּ כָּל בִּרְכָאן דְּאִתְבָּרְכָא מֵאֲבָהָן עִלָּאִין, רָזָא דְוא\"ו דְּאִיהוּ קַיְימָא לְאַרְקָא עֲלָהּ בִּרְכָאן תָּדִיר, וְאִיהוּ בֶּן חוֹרִין בֶּן יוֹבֵלָא דְּאַפִּיק עַבְדִּין לְחֵירוּ, בְּרָא דְּעַלְמָא עִלָּאָה דְּאַפִּיק תָּדִיר כָּל חַיִּין וְכָל נְהִירוּ וְכָל מְשַׁח רְבוּת, וְכֹלָּא אָעִיד (נ\"א אנגיד) הַאי בְּרָא בּוּכְרָא לְהַאי אֶרֶץ כְּמָא דְאַתְּ אָמֵר (שמות ד) בְּנִי בְּכֹרִי יִשְׂרָאֵל, וּבְגִין כָּךְ אַשְׁ\"רֵיךְ אֶרֶץ.</p>\n<p>וּמַה דְּאִתְּמָר אִי לָךְ אֶרֶץ שֶׁמַּלְכֵּךְ נַעַר כְּמָה דְאוּקְמוּהָ, דְּהַאי אֶרֶץ תַּתָּאָה וְעַלְמָא תַּתָּאָה לָא יָנְקָא אֶלָּא מִגּוֹ שָׁלְטָנוּתָא (דעילא) דְּעָרְלָה. וְכֹלָּא מֵהַהוּא מַלְכָּא דְּאִקְרֵי נַעַר כְּמָה דְאוּקְמוּהָ. וַוי לְאַרְעָא דְּאִצְטְרִיךְ לִינָקָא הָכִי.</p>\n<p>תָּא חֲזֵי, הַאי נַעַר <Nonei></i>לֵית לֵיהּ מִגַרְמֵיהּ כְּלוּם בַּר כַּד נָטִיל בִּרְכָאן לְזִמְנִין יְדִיעָן, וְכָל זִמְנִין דְּאִתְמְנָעוּ מִנֵּיהּ וְאִתְפְּגִים סִיהֲרָא וְאִתְחֲשָׁךְ וּבִרְכָאן אִתְמְנָעוּ מִנֵּיהּ, וַוי לְעַלְמָא דְּאִצְטְרִיךְ לִינָקָא בְּהַהִיא שַׁעְתָּא. וְעוֹד בְּכַמָּה דִינִין אִתְדָן הַאי עַלְמָא עַד לָא יָנְקָא מִנֵּיהּ, דְּכוֹלָּא בְּדִינָא אִתְקַיָּים וְאִתְעֲבַד וְאוּקְמוּהָ (הכי).</p>\n<p>תָּא חֲזֵי, וַתָּמָת שָׂרָה בְּקִרְיַת אַרְבַּע. רָזָא אִיהוּ, בְּגִין דְּלָא הֲוָה מִיתָתָהּ עַל יְדָא דְּהַהוּא נָחָשׁ עֲקִימָאָה, וְלָא שָׁלַט בָּהּ כִּשְׁאָר בְּנֵי עָלְמָא דְּאִיהוּ שַׁלִּיט בְּהוּ. וְעַל יָדֵיהּ מֵתוּ בְּנֵי עָלְמָא מִיּוֹמָא דְּגָרִים לוֹן אָדָם בַּר משֶׁ\"ה וְאַהֲרֹ\"ן וּמִרְיָ\"ם דִּכְתִיב בְּהוּ עַל פִּי יְיָ. וּבְגִין יְקָרָא דִּשְׁכִינְתָּא לָא כְּתִיב בְּמִרְיָם עַל פִּי יְיָ.</p>\n<p>אֲבָל בְּשָׂרָה כְּתִיב בְּקִרְיַת אַרְבַּע, רָזָא דְּקִרְיַת אַרְבַּע בְּרָזָא עִלָּאָה, וְלָא עַל יְדָא אָחֳרָא. בְּקִרְיַת אַרְבַּע, וְלא בְּנָחָשׁ. בְּקִרְיַת אַרְבַּע הִיא חֶבְרוֹן, דְּאִתְחַבַּר דָּוִד מַלְכָּא בַּאֲבָהָן, וְעַל דָּא לָא הֲוָה מִיתָתָהּ בִּידָא אָחֳרָא אֶלָּא בְּקִרְיַת אַרְבַּע.</p>\n<p>תָּא חֲזֵי, כַּד יוֹמִין דְּבַר נָשׁ אִתְקַיְימוּ בְּדַרְגִּין עִלָּאִין, אִתְקָיָּים בַּר נָשׁ בְּעַלְמָא. כֵּיוָן דְּלָא אִתְקַיָּים בְּדַרְגִּין עִלָּאִין, נָפְקֵי וְנָחֲתֵי לְתַתָּא עַד דִּקְרִיבוּ לְהַאי דַרְגָּא דְּמוֹתָא שַׁרְיָא בֵּיהּ, וּכְדֵין נָטִיל רְשׁוּ לְאַפִּיק נִשְׁמָתָא וְטָאס עַלְמָא בְּזִמְנָא חָדָא וְנָטִיל נִשְׁמָתָא וְסָאִיב לֵיהּ לְגוּפָא וְאִשְׁתָּאַר מְסָאֲבָא. זַכָּאִין אִינוּן צַדִּיקַיָּא דְּלָא אִסְתָּאֲבוּ וְלָא אִשְׁתָּאַר בְּהוּ מְסָאֲבוּתָא.</p>"],[9520011263,"<p>וְתָא חֲזֵי בְּאֶמְצָעוּת דִּרְקִיעָא אִתְקַטַּר חַד אוֹרְחָא קַסְטְרִירָא וְאִיהוּ חִוְיָא דִּרְקִיעָא דְּכָל כֹּכָבִין דַּקִּיקִין כֻּלְהוּ קְטִירִין בֵּיהּ וְקָיְימֵי בֵּיהּ תִּלֵּי תִּלִּין, וְאִינוּן מְמַנָּן בִּסְתִירוּ (ס\"א בסטירו) עוֹבָדֵי בְּנֵי עָלְמָא.</p>\n<p>כְּגַוְונָא דָא כַּמָּה חֲבִילֵי טְהִירִין נָפְקֵי לְעַלְמָא מֵהַאי חִוְיָא עִלָּאָה קַדְמָאָה דְּאִתְפַּתָּא בֵּיהּ אָדָם, וְכֻלְהוּ מְמַנָּן בִּסְתִירוּ עוֹבָדֵי <Nonei></i>עַלְמָא, וּבְגִין כָּךְ אָתֵי בַּר נָשׁ לְאִתְדַּכָּאָה, מְסַיְיעִין לֵיהּ מִלְּעֵילָא, וְסִיּוּעָא דְּמָארֵיהּ סַחֲרָא לֵיהּ וְאִסְתַּמַּר וְאִקְרֵי קָדוֹשׁ.</p>\n<p>אָתֵי בַּר נָשׁ לְאִסְתָּאֲבָא, כַּמָּה חֲבִילִין טְהִירִין אִזְדַּמְּנוּ לֵיהּ. וְכֻלְהוּ (סחרן) שַׁרְיָין בֵּיהּ וּמְסַחֲרִין לֵיהּ וּמְסָאֲבִין לֵיהּ וְאִקְרֵי טָמֵא, וְכֻלְּהוּ אָזְלֵי וּמַכְרְזֵי קַמֵּי, טָמֵא טָמֵא כְּמָה דְאַתְּ אָמֵר, (ויקרא י״ג:מ״ה-מ״ו) וְטָמֵא טָמֵא יִקְרָא. וְכֻלְּהוּ קְטִירִין בְּהַהוּא חִיוְיָא קַדְמָאָה וּסְתִירִין בְּכַמָּה עוֹבָדֵי עָלְמָא.</p>\n<p>רַבִּי יִצְחָק וְרִבִּי יוֹסֵי הֲווּ אָזְלֵי מִטְּבֶרְיָא לְלוֹד. אָמַר רַבִּי יִצְחָק תְּוַוהֲנָא עַל הַהוּא רָשָׁע דְּבִלְעָם דְּכָל עוֹבָדוֹי דְהַהוּא רָשָׁע הֲווּ מִסִּטְרָא דִּמְסָאֲבָא. וְהָכָא אוֹלִיפְנָא רָזָא חָדָא, דְּכָל זִינֵי נְחָשַׁיָּא דְּעַלְמָא כֻּלְּהוֹן מִתְקַטְּרָן וְנָפְקִין מֵהַהוּא נָחָשׁ קַדְמוֹנִי דְּאִיהוּ רוּחַ מְסָאֲבָא מְזוּהֲמָא, וּבְגִין כָּךְ כָּל חָרָשִׁין דְּעַלְמָא אִקְרוּן עַל שְׁמָא דָא נְחָשִׁים (ועקרבים) וְכֻלְּהוּ מֵהַאי סִטְרָא נָפְקֵי. וּמַאן דְּאִתְמְשַׁךְ בְּהַאי, הָא אִסְתָּאַב.</p>\n<p>וְלָא עוֹד אֶלָּא דְּבָעֵי לְאִסְתָּאֲבָא בְּגִין לְאַמְשָׁכָא עֲלֵיהּ הַהוּא סִטְרָא דְּרוּחַ מְסָאֲבָא. דְּהָא תָּנִינָן כְּגַוְונָא דְאִתְעַר בַּר נָשׁ הָכִי נָמֵי אַמְשִׁיךְ עֲלֵיהּ מִלְּעֵילָא, אִי אִיהוּ אִתְעַר בְּסִטְרָא דִקְדוּשָּׁה אַמְשִׁיךְ עֲלֵיהּ קְדוּשָּׁה מִלְּעֵילָא וְאִתְקַדַּשׁ. וְאִי אִיהוּ אִתְעַר בְּסִטְרָא דִּמְסָאֲבָא הָכִי אַמְשִׁיךְ עֲלֵיהּ רוּחַ מְסָאֲבָא וְאִסְתָּאַב. דְּהָא אִתְּמָר עַל מַה דְּתָנִינָן אָתֵי בַּר נָשׁ לְאִסְתָּאֲבָא מְסָאֲבִין לֵיהּ.</p>\n<p>בְּגִין כָּךְ הַהוּא רָשָׁע דְּבִלְעָם, בְּגִין לְאַמְשָׁכָא עֲלֵיהּ רוּחַ מְסָאֲבָא מֵהַהוּא נָחָשׁ עִלָּאָה, הֲוָה אִסְתָּאַב בְּכָל לֵילְיָא בַּאֲתָנֵיהּ, וְהֲוָה עָבִיד עִמַּהּ עוֹבָדֵי אִישׁוּת בְּגִין לְאִסְתָּאֲבָא וּלְאַמְשָׁכָא עֲלֵיהּ רוּחַ מְסָאֲבָא, וּכְדֵין עֲבִיד חֳרָשׁוֹי וְעוֹבָדוֹי.</p>\n<p>וְשֵׁירוּתָא דְּעוֹבָדוֹי הֲוֵי נָטִיל נָחָשׁ מֵאִינוּן חִוְיָין וְקָטִיר לֵיהּ קַמֵּיהּ וּבָזַע <Nonei></i>רֵישֵׁיהּ וְאַפִּיק לִישָׁנֵיהּ וְנָטִיל עִשְׂבִּין יְדִיעָן וְאוֹקִיד כֹּלָּא וְעֲבִיד מִנֵּיהּ קְטַרְתָּא חָדָא, לְבָתַר נָטִיל רֵישָׁא דְהַהוּא חִוְיָא וּבְזַע לֵיהּ לְאַרְבַּע סִטְרִין וְעֲבִיד מִנֵּיהּ קְטַרְתָּא אָחֳרָא.</p>\n<p>וְעֲבִיד עִגּוּלָא חַד, וְהֲוָה אָמַר מִלִּין וְעֲבִיד עוֹבָדִין אָחֳרָנִין, עַד דְּאַמְשִׁיךְ עֲלֵיהּ רוּחִין מְסָאֲבִין, וְאוֹדִיעִין לֵיהּ מַה דְּאִצְטְרִיךְ, וְעֲבִיד בְּהוּ עוֹבָדוֹי כְּפוּם מַה דְּאִינוּן יָדְעֵי מִסִּטְרָא דְהַהוּא חִוְיָא דִּרְקִיעָא. מִתַּמָּן אִתְמַשַּׁךְ בְּעוֹבָדוֹי וְחָרָשׁוֹי עַד דְּאַמְשִׁיךְ עֲלֵיהּ רוּחַ מֵהַהוּא נָחָשׁ קַדְמָאָה.</p>\n<p>וּמֵהָכָא הֲוָה יָדַע יְדִיעָן וָחֳרָשִׁין וְקוֹסְמִין. וּבְגִין כָּךְ כְּתִיב וְלא הָלַךְ כְּפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים, נְחָשִׁים וַדַּאי, וְעִקְּרָא וְשָׁרְשָׁא בִּמְסָאֲבוּתָא אִיהוּ כְּמָה דְאִתְּמָר, וּלְבָתַר שֵׁירוּתָא דְּכֹלָּא לָאו אִיהוּ אֶלָּא בְּנָחָשׁ.</p>"],[9520011264,"<p>אָמַר רַבִּי יוֹסֵי אַמַּאי כָּל זַיְינֵי חֳרָשִׁין וְקוֹסְמִין לָא אִשְׁתַּכָּחוּ אֶלָּא בִּנְשַׁיָּיא. אָמַר לֵיהּ הָכִי אוֹלִיפְנָא מִדַּאֲתָא נָחָשׁ עַל חַוָּה הִטִּיל בָּהּ זוּהֲמָא, בָּהּ אַטִּיל וְלָא בְּבַעֲלָהּ. אָמַר הָכִי הוּא וַדַּאי, אֲתָא רַבִּי יוֹסֵי וּנְשָׁקֵיהּ לְרַבִּי יִצְחָק, אָמַר כַּמָּה זִמְנִין שָׁאִילְנָא הַאי מִלָּה וְלָא זָכִינָא בָּהּ אֶלָּא הַשְׁתָּא.</p>\n<p>אָמַר לֵיהּ כָּל הַנֵּי עוֹבָדִין וְכָל מַה דְּיָדַע בִּלְעָם מֵאָן אֲתַר אוֹלִיף לֵיהּ. אָמַר לֵיהּ מֵאֲבוֹי. אֲבָל בְּאִינוּן הַרְרֵי קֶדֶם דְּאִיהוּ אֶרֶץ קֶדֶם אוֹלִיף כָּל חֳרָשִׁין וְכָל זִינֵי קוֹסְמִין. (שמות קיב) בְּגִין דִּבְאִינוּן טוִּרִי אִינוּן מַלְאֲכֵי עֲזָ\"א וַעֲזָאֵ\"ל, דְּאַפִּיל לוֹן קוּדְשָׁא בְּרִיךְ הוּא מִן שְׁמַיָא וְאִינוּן קְטִירִין בְּשַׁלְשְׁלָאֵי דְפַרְזְלָא וְאוֹדִיעִין חֳרָשִׁין לִבְנֵי נָשָׁא, וּמִתַּמָּן הֲוָה יָדַע בִּלְעָם כְּמָה דְאַתְּ אָמֵר מִן אֲרָם יַנְחֵנִי בָלָק מֶלֶךְ מוֹאָב מֵהַרְרֵי קֶדֶם.</p>\n<p>אָמַר לֵיהּ וְהָא כְּתִיב וְלא הָלַךְ כְּפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים וַיָּשֶׁת אֶל הַמִּדְבָּר פָּנָיו. אָמַר לֵיהּ, סִטְרָא תַּתָּאָה דְּאַתְיָא מֵרוּחַ מְסָאֲבָא דִלְעֵילָא, הוּא רוּחַ מְסָאֲבָא דְּשַׁלִּיט בְּמַדְבְּרָא כַּד עָבְדוּ בְּנֵי יִשְׂרָאֵל יַת עֶגְלָא בְּגִין לְאִסְתָּאֲבָא בַּהֲדֵיהּ דְּאִיהוּ תַּתָּאָה, וּבְכֹלָּא <Nonei></i>עֲבַד חֳרָשׁוֹי בְּגִין דְּיֵכוּל לְאַעֲקָרָא לוֹן לְיִשְׂרָאֵל וְלָא יָכִיל.</p>\n<p>אָמַר רִבִּי יוֹסֵי הַאי דְאָמַרְתְּ בְּקַדְמִיתָא דְּכַד נָחָשׁ אֲתָא עַל חַוָּה אַטִיל בָּהּ זוּהֲמָא שַׁפִּיר, אֲבָל הָא תָּנִינָן דְּכַד קָאִימוּ יִשְׂרָאֵל עַל טוּרָא דְסִינַי פָּסַק מִנַּיְיהוּ זוּהֲמָא. יִשְׂרָאֵל דְּקַבִּילוּ אוֹרַיְיתָא פָּסַק מִנַּיְיהוּ זוּהֲמָא, אֲבָל שְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת דְּלָא קַבִּילוּ אוֹרַיְיתָא לָא פָּסְקָא זוּהֲמָא מִנַּיְיהוּ.</p>\n<p>אָמַר לֵיהּ שַׁפִּיר קָאֲמַרְתְּ, אֲבָל תָּא חֲזֵי, אוֹרַיְיתָא לָא אִתְיְיהִיבַת אֶלָּא לִדְכוּרֵי דִּכְתִיב, (דברים ד׳:מ״ד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם משֶׁה לִפְנֵי בְּנֵי יִשְׂרָאֵל. דְּהָא נַשֵּׁי פְּטִירִין מִפִּקּוּדֵי אוֹרַיְיתָא.</p>\n<p>וְעוֹד דְּאַהֲדָרוּ כֻּלְּהוּ לְזוּהֲמָתָן כְּקַדְמִיתָא בָּתַר דְּחָטוּ, וְאִתְּתָא קַשְׁיָא לְאִתְפְּרָשָׁא זוּהֲמָא מִנָּהּ יַתִּיר מִגַּבְרָא. וּבְגִין כָּךְ אִשְׁתַּכָּחוּ נָשִׁין בַּחֲרָשַׁיָא וּבְזוּהֲמָא דָא יַתִּיר מִגּוּבְרִין. דְּהָא נְשַׁיָא מִסִּטְרָא דִשְׂמָאלָא קָא אַתְיָין וְאִתְדַּבָּקוּ בְּדִינָא קַשְׁיָא, וְסִטְרָא דָא אִתְדָּבַּק בְּהוּ יַתִּיר מִגּוּבְרִין כְּמָה דְאִתְּמַר בְּגִין דְּאַתְיָא מִסִּטְרָא דְדִינָא קַשְׁיָא, וְכֹלָּא אִתְדָּבַּק וְאָזִיל בָּתַר זִינֵיהּ.</p>\n<p>תָּא חֲזֵי, דְּהָכִי הוּא כְּמָה דַאֲמִינָא, דְּבִלְעָם הֲוָה אִסְתָּאַב בְּקַדְמִיתָא בְּגִין לְאַמְשָׁכָא עֲלֵיהּ רוּחָא מְסָאֲבָא. כְּגַוְונָא דָא אִתְּתָא בְּיוֹמֵי דִּמְסָאֲבוּ דִילָהּ אִית לֵיהּ לְבַר נָשׁ לְאִסְתַּמְּרָא מִנָּהּ, בְּגִין דִּבְרוּחַ מְסָאֲבָא אִתְדַּבְּקַת וּבְהַהוּא זִמְנָא אִי אִיהִי תַּעֲבִיד חֳרָשִׁין אַצְלָחוּ בִּידָהָא יַתִּיר מִזִּמְנָא אָחֳרָא, דְּהָא רוּחַ מְסָאֲבָא שַׁרְיָא עִמַּהּ, וְעַל דָּא בְּכָל מַה דְּקָרִיבַת אִסְתָּאַב, כָּל שֶׁכֵּן מַאן דְּקָרִיב בַּהֲדָהּ. זַכָּאִין אִינוּן יִשְׂרָאֵל דְּקוּדְשָׁא בְּרִיךְ הוּא יָהִיב לוֹן אוֹרַיְיתָא וְאָמַר לוֹן (ויקרא י״ח:י״ט) וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לא תִקְרַב לְגַלּוֹת עֶרְוָתָהּ אֲנִי יְיָ.</p>\n<p>אָמַר לֵיהּ הַאי מַאן דְּאִסְתַּכַּל בְּצִפְצוּפוֹי דְּעוֹפֵי אַמַּאי אִקְרֵי נָחָשׁ. אָמַר לוֹ דְּהָא מֵהַהוּא סִטְרָא קָאָתֵי דְּרוּחַ מְסָאֲבָא שַׁרְיָא עַל הַהוּא עוֹפָא <Nonei></i>וְאוֹדַע מִלִּין בְּעַלְמָא. וְכָל רוּחַ מְסָאֲבָא בְּנָחָשׁ אִתְדַּבָּקוּ וְאַתְיָין לְעַלְמָא וְלֵית מַאן דְּיִשְׁתְּזִיב מִנֵּיהּ בְּעַלְמָא, דְּהָא אִיהוּ אִשְׁתַּכַּח עִם כֹּלָּא, עַד זִמְנָא דְּזָמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַעֲבָרָא לֵיהּ מֵעַלְמָא כְּמָה דְאִתְּמָר דִּכְתִיב, (ישעיהו כ״ה:ח׳) בִּלַע הַמָּוֶת לָנֶצַח וּמָחָה יְיָ אֱלהִים דִּמְעָה מֵעַל כָּל פָּנִים וְגו'. וּכְתִיב, (זכריה י״ג:ב׳) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ וְגו'.</p>"],[9520011265,"<p>רִבִּי יְהוּדָה אָמַר, אַבְרָהָם יָדַע בְּהַהִיא מְעַרְתָּא סִימָנָא, וְלִבֵּיהּ וּרְעוּתֵיהּ תַּמָּן הֲוָה, בְּגִין דְּמִקַדְּמַת דְּנָא עָאל לְתַמָּן וְחָמָא לְאָדָם וְחַוָּה טְמִירִין תַּמָּן. וּמְנָא הֲוָה יָדַע דְּאִינוּן הֲווּ. אֶלָּא חָמָא דִּיוּקְנֵיהּ, וְאִסְתַּכַּל וְאִתְפַּתַּח לֵיהּ חַד פִּתְחָא דְּגִנְתָּא דְעֵדֶן תַּמָּן וְהַהוּא דִּיוּקְנָא דְאָדָם הֲוָה קָאִים לְגַבֵּיהּ.</p>\n<p>וְתָא חֲזֵי כָּל מַאן דְּאִסְתַּכַּל בְּדִיוּקְנָא דְּאָדָם לָא אִשְׁתְּזִיב לְעָלְמִין מִמִּיתָה, בְּגִין דְּהָא בְּשַׁעְתָּא דְּבַר נָשׁ אִסְתַּלַּק מֵעַלְמָא חָמֵי לֵיהּ לְאָדָם וּבְהַהוּא זִמְנָא מִית. אֲבָל אַבְרָהָם אִסְתַּכַּל בֵּיהּ וְחָמָא דִיוּקְנֵיהּ וְאִתְקְיַּים, וְחָמָא נְהוֹרָא דְּנָהִיר בִּמְעַרְתָּא וְחַד שְׁרַגָּא דָּלִיק, כְּדֵין תָּאִיב אַבְרָהָם דִּיּוּרֵיהּ בְּהַהוּא אֲתַר, וְלִבֵּיהּ וּרְעוּתֵיהּ הֲוָה תָּדִיר בִּמְעַרְתָּא.</p>\n<p>תָּא חֲזֵי, הַשְׁתָּא אַבְרָהָם בְּחָכְמְתָא עֲבַד בְּזִמְנָא דְּתָבַע קִבְרָא לְשָׂרָה, דְּהָא כַּד תָּבַע לָא תָבַע לִמְעַרְתָּא בְּהַהוּא זִמְנָא, וְלָא אָמַר דְּבָעֵי לְאִתְפָּרְשָׁא מִנַּיְיהוּ. אֶלָּא אָמַר, תְּנוּ לִי אֲחוּזַת קֶבֶר עִמָּכֶם וְאֶקְבְּרָה מֵתִי מִלְּפָנַי. וְאִי תֵימָא דְלָא הֲוָה עֶפְרוֹן תַּמָּן. תַּמָּן הֲוָה, דִּכְתִיב וְעֶפְרוֹן יוֹשֵׁב בְּתוֹךְ בְּנֵי חֵת, וְאַבְרָהָם לָא אָמַר לֵיהּ בְּהַהִיא שַׁעְתָּא כְּלוּם.</p>\n<p>אֶלָּא מַה דְּאָמַר לוֹן, אָמַר כְּמָה דִכְתִיב וַיְדַבֵּר אֶל בְּנֵי חֵת וְגו'. וְכִי סָלְקָא דַעְתָּךְ דְּאַבְרָהָם בָּעָא לְאִתְקְבְרָא בֵּינַיְיהוּ בֵּין מְסָאֳבִין אוֹ דְּתִאוּבְתֵּיהּ הֲוָה עִמְּהוֹן, אֶלָּא בְּחָכְמָה עֲבַד.</p>\n<p>וְיַלְפִינָן <Nonei></i>אוֹרַח אַרְעָא הָכָא בְּמָּה דְעֲבַד אַבְרָהָם, דְּהָא בְּגִין דְּתִאוּבְתֵּיהּ וּרְעוּתֵיהּ הֲוָה בְּהַהִיא מְעַרְתָּא, אַף עַל גַּב דְּהֲוָה תַּמָּן, לָא בָּעָא לְמִשְׁאַל לֵיהּ מִיָּד הַהוּא רְעוּתָא דְּהֲוָה לֵיהּ בִּמְעַרְתָּא, וְשָׁאִיל בְּקַדְמִיתָא מַה דְּלָא אִצְטְרִיךְ לֵיהּ לְאִינוּן אָחֳרָנִין וְלָא לְעֶפְרוֹן.</p>\n<p>כֵּיוָן דְּאָמְרוּ לֵיהּ קַמֵּי עֶפְרוֹן שְׁמָעֵנוּ אֲדֹנִי נְשִׂיא אֱלהִים אַתָּה בְּתוֹכֵנוּ וְגו'. מַה כְּתִיב וְעֶפְרוֹן ישֵׁב בְּתוֹךְ בְּנֵי חֵת. יָשַׁב כְּתִיב, מִשֵּׁירוּתָא דְּמִלִּין דְּאָמַר אַבְרָהָם תַּמָּן הֲוָה. כְּדֵין אָמַר שְׁמָעוּנִי וּפִגְעוּ לִי בְּעֶפְרוֹן בֶּן צֹחַר וְיִתֶּן לִי אֶת מְעָרַת הַמַּכְפֵּלָה אֲשֶׁר לוֹ וְגו'. וְאִי תֵימָא בְּגִין יְקָרָא דִּילִי יַתִּיר מִנַּיְיכוּ אֲנָא עָבִיד דְּלָא רָעֵינָא בְּכוּ. בְּתוֹכְכֶם, בְּגִין לְאִתְקְבָרָא בֵּינַיְיכוּ דְּרָעֵינָא בְּכוּ בְּגִין דְּלָא אִתְפְּרַשׁ מִנַּיְיכוּ.</p>"]]});
